-- AP&E glossary — Machine B batch 1 — PASTE FILE 4 of 6
-- Paste this whole file into the Supabase SQL editor and Run. Order between files does not matter.
-- Idempotent: safe to re-run. Backup already exists (glossary_backup_mb_batch1_20260721).
BEGIN;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"d8068124-e307-4b3b-8ec8-45297bdf67e0": {"definition": "ADR blend is the process of matching re-recorded dialogue (ADR) to the surrounding production sound so the replaced lines sit seamlessly in the scene. It involves matching level, perspective, equalization, room tone, and reverb, and often adding matching background ambience so the studio-recorded line does not stand out from the location dialogue.", "plain_english": "ADR is dialogue an actor re-records in a studio to replace noisy location lines. Blending it means making that clean studio line match the real scene's sound. It is like patching a photo so the new piece matches the lighting and grain of the original.", "purpose_function": "It exists so replaced lines feel like they were spoken on set, keeping dialogue consistent and the edit invisible to the audience. Without blending, a clean ADR line would jump out against the location recording.", "practical_application": "A dialogue editor matches the ADR's EQ and reverb to nearby production lines, then layers in room tone so the swap is unnoticeable. On the stage, the re-recording mixer fine-tunes level and perspective to seat the ADR in the scene.", "category": "Dialogue Editing", "related_terms": ["ADR", "Room tone", "Production sound", "Reverb matching", "Dialogue editing", "Perspective"], "common_mistakes": ["Matching only level while ignoring room tone, so the ADR sounds too clean against the scene.", "Skipping perspective and reverb matching, so the line's space does not fit the shot.", "Recording ADR too dry or too dead, leaving nothing that matches the original acoustic."], "scenario_contexts": ["Replacing a line ruined by traffic noise and blending it into the location dialogue.", "Seating a studio-recorded line into a reverberant room scene.", "Adding matching room tone so an ADR insert disappears within a sequence."]}, "2ea5e963-8e27-4e1e-945c-391294723daa": {"definition": "A Foley performance style in which everyday sync sound effects — footsteps, cloth, and prop handling — are performed with heightened force and energy so they read louder, sharper, and more physically emphatic against the picture.", "plain_english": "Foley is when an artist makes body and prop sounds in time with the picture. Aggressive Foley just means playing those sounds hard and loud, so a punch or a stomp feels big and forceful.", "purpose_function": "It exists to give action physical weight and impact, so hits, footsteps, and movement feel powerful and believable instead of soft or lost in the background.", "practical_application": "A Foley artist uses it on fights, chases, and horror beats — stomping harder and striking props firmly — and the mixer then rides the level to match the on-screen energy.", "category": "Foley", "related_terms": ["Foley", "Sound effects", "Room tone", "Sync", "Backgrounds", "Sound design"], "common_mistakes": ["Trying to fake it by only raising the fader in the mix instead of actually performing the movement with more force.", "Overplaying every action so quiet scenes lose contrast and the track becomes tiring to listen to.", "Not matching the performance to the character's weight, surface, and footwear seen on screen."], "scenario_contexts": ["Cutting Foley for a hand-to-hand fight so each punch and body fall lands hard.", "Building footsteps for a heavy, angry character storming through a room.", "Adding forceful cloth and prop sounds to a tense action beat."]}, "211615a2-1e43-4294-80dc-3bb630762a5d": {"definition": "The subtle, low-level sound of moving air — drafts, ventilation, wind, or the wash created by a body or object passing the camera — added to a soundtrack to convey open space, motion, or a living environment rather than dead silence.", "plain_english": "Air movement is the soft sound of air on the move, like a breeze, a vent, or the wind when someone runs past. Editors add it so a scene feels alive and open, not empty and dead.", "purpose_function": "It exists to give a scene a sense of space and presence and to smooth over gaps, so quiet moments still feel natural instead of unnaturally silent.", "practical_application": "An editor lays a faint air or wind bed under exteriors and large spaces, or drops in a small air whoosh as a character or object sweeps past frame.", "category": "Ambience", "related_terms": ["Room tone", "Ambience", "Backgrounds", "Whoosh", "Wind", "Sound design"], "common_mistakes": ["Setting the level too high so the air bed pulls attention away from dialogue.", "Using a looped air sound with an obvious repeat or audible seam.", "Confusing air movement with room tone, which is the still, steady sound of a specific interior."], "scenario_contexts": ["Adding a faint breeze bed under a wide outdoor shot.", "Placing an air whoosh as a car speeds past frame.", "Filling a large hall with a soft moving-air presence."]}, "9f1692b9-eb31-48e9-b2f4-e72147fb2c9f": {"definition": "A dialogue or performance edit in which a word, line, or phrase from a different recorded take is cut in to replace or improve the matching moment in the chosen take, blended to match its timing, tone, and background.", "plain_english": "Actors usually record a line many times. An alternate-take edit means swapping in a word or line from one of those other tries to get a cleaner read, then blending it so no one hears the join.", "purpose_function": "It exists to fix problem words — noise, flubs, or weak reads — without re-recording, by borrowing the best moments from other takes of the same performance.", "practical_application": "A dialogue editor auditions the alternate takes, finds a clean version of a troublesome word, cuts it into the main take, and smooths the edit with matching room tone and crossfades.", "category": "Dialogue editing", "related_terms": ["Dialogue editing", "ADR", "Room tone", "Crossfade", "Production sound", "Take"], "common_mistakes": ["Cutting in an alternate take whose background or mic tone does not match, so the join is audible.", "Ignoring lip sync when the alternate word has different timing than the picture.", "Forgetting to fill the edit with matching room tone, leaving a hole in the sound."], "scenario_contexts": ["Replacing a word ruined by a cough with the same word from another take.", "Swapping in a stronger read of a key line without calling the actor back for ADR.", "Fixing a plosive or noise on a single word using a clean alternate."]}, "1d1b0b5f-ac79-45ef-bd77-0e0ccc112bca": {"definition": "A defined region of a scene or space assigned its own ambient sound bed, so that as the picture or listener moves between areas the background changes to match each location's character.", "plain_english": "An ambience zone is an area given its own background sound. Move from a busy street into a quiet shop, and the ambience zone changes the background so each place sounds right.", "purpose_function": "It exists to keep backgrounds believable across a scene, giving each space its own sonic identity and smooth transitions as the story moves between areas.", "practical_application": "An editor maps different ambiences to zones — a lobby, a kitchen, an alley — and crossfades between them as the camera or character crosses from one to the next.", "category": "Ambience", "related_terms": ["Ambience", "Backgrounds", "Room tone", "Crossfade", "Perspective", "Sound design"], "common_mistakes": ["Cutting hard between zones instead of crossfading, so the change sounds abrupt.", "Making every zone equally loud, which loses the contrast between spaces.", "Forgetting to shift the ambience when the picture clearly changes location."], "scenario_contexts": ["Changing background sound as a character walks from a party into a bathroom.", "Assigning distinct ambiences to rooms in a house for a walk-through scene.", "Transitioning from interior to exterior ambience through a doorway."]}, "20a75a4d-b73b-4c39-8a5f-1f5f81f78575": {"definition": "A section of ambient or background recording edited to repeat seamlessly, used to sustain a continuous environmental sound over a duration longer than the original recording.", "plain_english": "An ambient loop is a background sound, like rain or a busy room, edited so it can play over and over with no gap. It lets a short recording fill a long scene without you hearing it restart.", "purpose_function": "It exists to provide continuous, gap-free background for a scene of any length from a limited recording, saving time and keeping the environment consistent.", "practical_application": "An editor finds matching in and out points, crossfades the ends, and loops the clip across the whole scene, checking that no click or obvious repeat gives the loop away.", "category": "Ambience", "related_terms": ["Ambience", "Backgrounds", "Room tone", "Crossfade", "Loop point", "Sound design"], "common_mistakes": ["Choosing a clip with a unique sound, such as a car horn, that gives away the repeat.", "Leaving a click or level jump at the loop point.", "Making the loop too short, so the repeating pattern becomes obvious."], "scenario_contexts": ["Looping a short rain recording to cover a long dialogue scene.", "Sustaining crowd ambience under an entire restaurant sequence.", "Filling a forest exterior with a seamless nature bed."]}, "7b262d92-97bd-4d37-b975-00144f0630bf": {"definition": "A defined relationship showing how a signal's level is reduced as a function of another variable — most often distance in spatial audio, or frequency in a filter — expressed as a curve rather than a single fixed amount.", "plain_english": "An attenuation curve is a graph of how much a sound gets quieter as something changes, like how a sound fades the farther away it is. It sets the rule for how fast the level drops.", "purpose_function": "It exists to control level change in a smooth, predictable way, so sounds fall off naturally with distance or a filter rolls off gently across frequency.", "practical_application": "In spatial or game audio, an editor shapes the distance attenuation curve so a source fades realistically as it moves away; in an EQ, the curve describes how much each frequency is cut.", "category": "Signal processing", "related_terms": ["Attenuation", "Distance attenuation", "Panning", "Filter", "Fade", "Spatial audio"], "common_mistakes": ["Confusing attenuation, which reduces level, with gain, which raises it.", "Using a curve that drops too fast, so sources vanish unnaturally quickly.", "Assuming attenuation only means volume and ignoring filtering across frequency."], "scenario_contexts": ["Setting how a sound source fades with distance in an immersive mix.", "Shaping a filter's roll-off across frequency.", "Adjusting a fall-off curve so a passing vehicle recedes smoothly."]}, "e3332f99-3619-4639-b138-178f530cddd6": {"definition": "Any discrete piece of audio content — a recording, sound effect, music cue, or edited clip — managed as a named, reusable file within a project, media library, or deliverable package.", "plain_english": "An audio asset is any single piece of sound in a project, like one sound effect, a music track, or a recorded line. Each one is a file you can name, store, and reuse.", "purpose_function": "It exists to treat sound as organised, trackable items, so material can be found, shared, versioned, and delivered reliably across a production.", "practical_application": "An editor imports, labels, and organises assets in the session and media pool, then hands off the required assets as part of the final deliverable package.", "category": "Media management", "related_terms": ["Session", "Deliverables", "Stems", "Metadata", "Sound library", "Consolidate"], "common_mistakes": ["Leaving assets with default or unclear names, making them hard to find later.", "Delivering a session that points to assets that were never included or consolidated.", "Forgetting to keep metadata with the asset, which loses key information about it."], "scenario_contexts": ["Organising sound effects in a library for a project.", "Consolidating every clip so the session's assets travel with the deliverable.", "Tracking versions of a music cue as separate assets."]}, "8bcc1905-775f-4ca8-9725-c13259ad1b16": {"definition": "An audio implementer is the person who integrates finished sound assets into a game or interactive project, connecting them to events, parameters, and logic in audio middleware or a game engine so they play back correctly at runtime.", "plain_english": "An audio implementer is the person who puts sounds into a video game. They connect each sound to the actions that should make it play, so the right sound happens at the right time.", "purpose_function": "The role exists to bridge sound design and code, making sure recorded or designed assets behave interactively by triggering, mixing, and adapting to gameplay rather than just sitting as files.", "practical_application": "An implementer builds events, containers, and parameter links in tools like Wwise or FMOD, then tests them in the engine to confirm footsteps, weapons, and ambience trigger and mix correctly.", "category": "Audio Roles", "related_terms": ["Audio programmer", "Audio trigger", "Audio parameter", "Audio state", "Audio-editing suite"], "common_mistakes": ["Confusing the implementer with the sound designer, when implementation is about integration and behavior, not creating the raw sounds", "Assuming implementation is only file placement, when it also covers mixing, parameter mapping, and runtime logic", "Skipping testing in the actual engine, so problems only surface at runtime"], "scenario_contexts": ["Wiring a gunfire event in middleware so pulling the trigger plays layered shot, mechanism, and tail sounds", "Mapping engine RPM to a real-time parameter that changes a vehicle's sound", "Setting up footstep switches so the surface type selects the correct footstep sample set"]}, "ab287e1a-8730-48d6-ba11-bfb535d56d90": {"definition": "In spatial and interactive audio, the listener is a virtual reference point in 3D space representing the position and orientation of the receiver (the 'ears'), against which the engine calculates panning, distance attenuation, and Doppler for every sound source.", "plain_english": "The listener is a virtual pair of ears placed inside a 3D scene. The game measures where each sound sits compared to those ears, so sounds seem to come from the right direction and get quieter as they move away.", "purpose_function": "It gives the audio engine a single frame of reference so 3D sound sources can be positioned, attenuated, and Doppler-shifted realistically as the player or camera moves.", "practical_application": "A technician usually binds the listener to the player's camera or head, and in split-screen or VR may manage more than one listener so each viewpoint hears correct spatialization.", "category": "Interactive Audio", "related_terms": ["Audio zone", "Audio trigger", "Audio parameter", "Audio implementer"], "common_mistakes": ["Forgetting to update the listener's orientation, so left/right panning stays fixed while the camera turns", "Attaching the listener to the wrong object, such as the body instead of the camera, causing mismatched direction cues", "Assuming one listener is always correct, when split-screen needs several"], "scenario_contexts": ["Binding the listener to a first-person camera so gunfire pans as the player looks around", "Managing two listeners in local split-screen multiplayer", "Positioning the listener at the camera in a third-person game to balance world audio"]}, "8ee4724e-e91e-4698-8250-a1cdde6a34e4": {"definition": "An audio parameter is a named, continuously adjustable value that controls one or more audio properties, such as volume, pitch, filter cutoff, or effect send, and can be updated in real time, often driven by game or system state.", "plain_english": "An audio parameter is a control knob for sound that a program can turn by itself. For example, as a car speeds up, a 'speed' parameter can smoothly raise the engine's pitch.", "purpose_function": "Parameters let sound respond continuously to changing conditions, so audio can adapt smoothly instead of only switching between fixed states.", "practical_application": "An implementer maps a parameter such as RPM, health, or distance to a property like pitch or filter cutoff, then tunes the response curve so the change sounds natural.", "category": "Interactive Audio", "related_terms": ["Audio state", "Audio trigger", "Audio implementer", "Audio listener"], "common_mistakes": ["Confusing continuous parameters with discrete states, since parameters vary smoothly while states switch in steps", "Setting parameter ranges that do not match the game values feeding them, so the effect maxes out or never moves", "Using steep response curves that make changes sound abrupt or unnatural"], "scenario_contexts": ["Mapping vehicle speed to engine pitch and volume", "Driving a low-pass filter from player health to muffle audio when hurt", "Using distance to control the reverb send on a sound source"]}, "6a744424-87dd-4bec-9bb1-12cd0dfeaf66": {"definition": "An audio programmer is a software developer who designs and writes the code behind audio playback, including engine integration, DSP, mixing, streaming, and middleware hooks, so that sound systems run efficiently and correctly at runtime.", "plain_english": "An audio programmer writes the code that makes sound work inside a game or app. They build the systems that play, mix, and process audio, and make sure it runs fast without glitches.", "purpose_function": "The role exists to build and maintain the technical foundation, such as DSP, memory and CPU budgets, and engine tools, that sound designers and implementers rely on for reliable playback.", "practical_application": "An audio programmer might optimize voice limits and streaming, write a custom DSP effect, or fix a bug where sounds drop out under heavy CPU load.", "category": "Audio Roles", "related_terms": ["Audio implementer", "Audio parameter", "Audio state", "Audio-editing suite"], "common_mistakes": ["Confusing the audio programmer with the implementer, since programmers build the systems and implementers use them to place and wire sounds", "Assuming any general programmer can cover audio, when DSP and real-time timing are specialized skills", "Overlooking CPU and memory budgets, causing audio dropouts on target hardware"], "scenario_contexts": ["Writing a custom reverb DSP effect for a game engine", "Optimizing voice management so too many simultaneous sounds do not overload the CPU", "Integrating middleware like Wwise or FMOD into a proprietary game engine"]}, "19ec3121-e527-4c21-858a-6cbeafe804c2": {"definition": "An audio state is a discrete, named global condition, one of a mutually exclusive set, that tells the audio system how to behave or mix, such as switching to a muffled 'underwater' or 'paused' state that applies across many sounds at once.", "plain_english": "An audio state is a named mode for the whole soundtrack, like 'underwater' or 'paused.' When the game switches state, many sounds change together, for example all becoming muffled at once.", "purpose_function": "States let a project change the overall sound in one step, keeping large groups of sounds consistent instead of adjusting each one on its own.", "practical_application": "An implementer defines states such as Exploration, Combat, and Menu, then sets how volumes, effects, and music respond when the game switches between them.", "category": "Interactive Audio", "related_terms": ["Audio parameter", "Audio trigger", "Audio zone", "Audio implementer"], "common_mistakes": ["Confusing states, which are discrete and global, with parameters, which are continuous values", "Creating overlapping states that fight each other because they are not mutually exclusive within a group", "Forgetting to set transition times, causing abrupt jumps when the state changes"], "scenario_contexts": ["Switching to an 'underwater' state that low-pass filters everything when the player submerges", "Ducking ambience and effects when a 'pause menu' state is active", "Changing the music mix between 'exploration' and 'combat' states"]}, "9cbef41d-0988-45db-a1b6-e06d22ef0673": {"definition": "An audio trigger is an event or condition that tells the audio system to start, stop, or change a sound, such as a gameplay action, animation marker, or timeline cue that fires a corresponding audio event.", "plain_english": "An audio trigger is the thing that makes a sound play. When the player jumps or a door opens, that action acts as a trigger and fires the matching sound.", "purpose_function": "Triggers connect events in the game, animation, or timeline to sound, so audio happens at exactly the right moment in response to what is occurring.", "practical_application": "An implementer places triggers on animation markers, collision events, or timeline cues so footsteps, impacts, and effects fire in sync with the action.", "category": "Interactive Audio", "related_terms": ["Audio state", "Audio parameter", "Audio implementer", "Audio zone"], "common_mistakes": ["Placing a trigger on the wrong frame, so sound and action are out of sync", "Letting rapid re-triggering stack copies of a sound, causing buildup or distortion", "Confusing a trigger, the event that starts sound, with the sound asset itself"], "scenario_contexts": ["Firing a footstep sound from an animation marker at each foot plant", "Triggering an impact sound on a collision event", "Using a timeline cue to trigger a sound effect in a cutscene"]}, "920312d0-c191-48cd-9fe8-9eb3c09b319d": {"definition": "An audio zone is a defined region of 3D space within which specific audio behavior applies, such as a reverb setting, ambient bed, or attenuation rule, that takes effect when the listener or a source enters or leaves the region.", "plain_english": "An audio zone is an invisible area in the game world with its own sound rules. Walk into a cave zone and the game adds echo; walk out and the echo stops.", "purpose_function": "Zones let audio change automatically based on location, so environments like caves, rooms, or crowds sound right without manually cueing each change.", "practical_application": "An implementer draws zone volumes around spaces and assigns each a reverb, ambience, or filter that activates when the listener crosses the boundary.", "category": "Interactive Audio", "related_terms": ["Audio listener", "Audio state", "Audio trigger", "Audio parameter"], "common_mistakes": ["Creating hard zone boundaries with no blend, so reverb or ambience pops abruptly at the edge", "Overlapping zones without priority rules, so it is unclear which one applies", "Sizing zones to the visual space instead of how sound actually travels"], "scenario_contexts": ["Adding a cave reverb zone that turns on when the player enters", "Placing an ambience zone that fades in market-crowd sound near a bazaar", "Using a zone to muffle outside sounds when the player steps indoors"]}, "9720f43d-a953-4b8d-b07e-596b603c42ed": {"definition": "An audio-editing suite is a software application or integrated set of tools for recording, editing, arranging, and processing audio, covering tasks like cutting, fading, noise reduction, effects, and mixdown, and often overlapping with a digital audio workstation (DAW).", "plain_english": "An audio-editing suite is a program for working with sound on a computer. You use it to cut, clean up, add effects to, and combine recordings, like a word processor but for audio.", "purpose_function": "It provides, in one place, the tools a technician needs to turn raw recordings into finished audio, from trimming and cleanup to effects and final export.", "practical_application": "A technician uses a suite such as Pro Tools, Nuendo, or a wave editor to clean dialogue, tighten edits, apply processing, and export deliverables in the required format.", "category": "Audio Software", "related_terms": ["Audio implementer", "Audio programmer", "Audio parameter"], "common_mistakes": ["Editing on the only copy of a recording instead of working non-destructively or keeping a backup", "Exporting at the wrong sample rate or bit depth for the deliverable spec", "Confusing a simple two-track editor with a full multitrack DAW when the job needs multitracking"], "scenario_contexts": ["Cleaning up and trimming a dialogue recording before a mix", "Applying noise reduction and EQ to a location sound file", "Exporting a finished stereo file to the delivery format and level spec"]}, "4494a084-f7ae-4985-8041-6aff6283cb63": {"definition": "An avoid-repeat setting is a randomization option in a sound container that prevents the same sample, or the last few samples played, from being selected again immediately, so repeated triggers draw fresh variations and avoid audible repetition.", "plain_english": "An avoid-repeat setting stops a game from playing the exact same sound twice in a row. When several versions of a sound exist, it picks a different one each time so footsteps or gunshots do not sound fake.", "purpose_function": "It keeps randomized sounds feeling natural by ensuring variety, preventing the obvious, robotic 'machine-gun' effect that happens when the same clip repeats back to back.", "practical_application": "An implementer turns it on for a random container of footstep or weapon variations and sets how many recent samples to skip, balancing variety against the size of the sample pool.", "category": "Interactive Audio", "related_terms": ["Audio trigger", "Audio parameter", "Audio implementer", "Audio state"], "common_mistakes": ["Setting the avoid count too high for a small sample pool, leaving too few choices or forcing a fixed order", "Assuming plain random already avoids repeats, when without this setting the same clip can repeat by chance", "Forgetting to enable it, so rapid-fire sounds reveal the loop"], "scenario_contexts": ["Enabling it on a footstep container so consecutive steps use different samples", "Using it on gunfire variations to avoid a repetitive machine-gun sound", "Applying it to impact or UI-click variations for natural variety"]}, "a5232f7a-214a-4ccc-a61c-17755479487c": {"definition": "A continuous, non-specific ambient sound layer that establishes the environment or location of a scene, such as room tone, traffic, wind, or a distant crowd. Commonly called backgrounds (BGs) or ambiences, these tracks sit beneath dialogue and hard effects to create a believable sense of place.", "plain_english": "A steady sound that tells you where a scene takes place, like traffic outside a window or birds in a park. It sits quietly under the voices so the scene feels real and is never dead silent.", "purpose_function": "Creates a believable sense of place and keeps the soundscape continuous, hiding edits and preventing the unnatural dead silence that would otherwise make a scene feel empty.", "practical_application": "A sound editor lays continuous background loops under each scene, matches them to the location on screen, and crossfades between them at scene changes so the ambience never cuts out.", "category": "Sound Effects", "related_terms": ["Ambience", "Room tone", "Hard sound effect", "Foley", "Dialogue editing"], "common_mistakes": ["Letting backgrounds get loud enough to compete with or mask the dialogue instead of sitting beneath it", "Using an obviously short loop so the repeat becomes noticeable", "Failing to change or crossfade the background when the scene's location changes", "Confusing a background (continuous ambience) with a hard effect (a specific sync sound)"], "scenario_contexts": ["Adding city traffic and distant sirens under an outdoor dialogue scene", "Filling a quiet interior with soft room tone so cuts are seamless", "Crossfading from a forest ambience to a cave ambience as a character walks inside"]}, "64e7e9e9-0a4e-4d11-98a7-c130ae63c068": {"definition": "A movement sound effect capturing the noises a worn backpack makes as a character moves — the creak of straps, shift of fabric, and clink of buckles or contents. It belongs to the movement (or moves) category of Foley and sound effects tied to a character's motion.", "plain_english": "The rustle, creak, and jingle a backpack makes as someone walks or turns. It helps a character feel like they are really carrying gear on their back.", "purpose_function": "Adds weight and realism to a character's motion, reinforcing that they carry equipment and helping match or cover their on-screen movement.", "practical_application": "A Foley artist performs backpack sounds in sync with the actor, or an editor cuts library moves under a character to match their pace and how heavy the pack looks.", "category": "Foley", "related_terms": ["Foley", "Cloth pass", "Footsteps", "Movement effects", "Prop effects"], "common_mistakes": ["Placing the sounds out of sync with the actor's steps and gestures", "Making the backpack too loud so it distracts from dialogue", "Reusing the same clip so identical creaks become noticeable", "Ignoring the pack's apparent weight and contents when choosing the sound"], "scenario_contexts": ["Foleying a hiker's loaded pack as they climb a trail", "Adding strap creaks to a soldier moving through a scene", "A student running for a bus with a heavy school bag"]}, "895194bc-8609-4f45-b39a-679663c32f5c": {"definition": "Aligning or re-syncing recorded audio or edits to a project's musical bar-and-beat (tempo) grid rather than to timecode, so that events fall on their intended bars and beats. It is used when material must follow a tempo map, as in music editing and scoring to picture.", "plain_english": "Lining up recorded music or edits so they land on the right bars and beats, not just a clock time. It is like snapping notes onto a song's beat grid so everything stays in time.", "purpose_function": "Keeps musical material locked to the tempo grid so edits, overdubs, and cues stay rhythmically in time even as the tempo changes.", "practical_application": "A music editor sets the session's tempo map, then conforms takes or a cue to the bars and beats so new edits fall cleanly on the grid.", "category": "Music Editing", "related_terms": ["Bar-and-beat display", "Tempo map", "Beat-level edit", "Quantize", "Conform"], "common_mistakes": ["Confusing a bar-and-beat conform with a timecode conform to picture changes", "Conforming before a correct tempo map is set, so events land off the grid", "Assuming the conform fixes performance feel when it only aligns events to bars and beats"], "scenario_contexts": ["Aligning a recorded cue to a tempo map before editing", "Re-syncing music edits to the beat grid after a tempo change", "Fitting overdubs to the bars and beats of a click-based session"]}, "773a7286-23e0-4ed6-85b5-9a42ebcfb1ec": {"definition": "A DAW timeline ruler or counter that shows position in musical units — bars, beats, and ticks — rather than in timecode or minutes and seconds. In Pro Tools this is the Bars|Beats ruler, driven by the session's tempo and meter.", "plain_english": "A way of showing your place in a song by bar and beat number instead of by clock time. It is like counting \"measure 4, beat 2\" instead of \"12 seconds in.\"", "purpose_function": "Lets editors and composers navigate and edit in musical time, so positions and grid snapping follow the tempo instead of the clock.", "practical_application": "An editor switches the ruler to Bars|Beats to snap edits to the grid, place cues on downbeats, and follow the click track.", "category": "Music Editing", "related_terms": ["Timecode", "Tempo map", "Bar-and-beat conform", "Grid mode", "Meter"], "common_mistakes": ["Expecting bar-and-beat positions to stay fixed when the tempo map changes", "Confusing bars and beats with timecode when reading delivery specs", "Setting the wrong meter so the beats per bar are counted incorrectly"], "scenario_contexts": ["Editing music to a click by snapping to the bar grid", "Placing a musical hit on a specific downbeat to match picture", "Reading a composer's session in musical time"]}, "1dec3edf-1e8a-4d09-bff7-bf197a3b43c9": {"definition": "An edit made at the resolution of a whole musical bar, where cuts, moves, and selections snap to bar boundaries on a bars-and-beats grid. It is a coarse musical edit granularity, as opposed to finer beat-level or sample-level edits.", "plain_english": "An edit that lines up to whole measures, so you cut or move music one full bar at a time. It is like rearranging a song block by block instead of note by note.", "purpose_function": "Keeps musical structure intact by editing in complete bars, which preserves phrasing and downbeats when rearranging, looping, or shortening a piece.", "practical_application": "An editor sets the grid to bars and trims or moves a section by whole bars to loop or shorten a cue without breaking its timing.", "category": "Music Editing", "related_terms": ["Beat-level edit", "Bar-and-beat display", "Grid mode", "Looping", "Tempo map"], "common_mistakes": ["Editing at the bar when a finer beat-level edit is needed for a tight cut", "Not snapping to the grid, so bars drift out of time", "Assuming every phrase is a whole number of bars"], "scenario_contexts": ["Looping a four-bar section to extend a cue", "Removing a full bar to shorten music to picture", "Rearranging song sections one bar at a time"]}, "965ff27e-9925-430c-b25a-89a4b3474c0d": {"definition": "An edit made at the resolution of individual beats or sub-beats, where cuts, moves, and quantizing snap to the beat grid within a bar. It is a finer musical edit granularity than a bar-level edit.", "plain_english": "An edit that lines up to single beats, so you can cut or nudge music beat by beat. It is like fixing a song one tap of the foot at a time.", "purpose_function": "Allows precise rhythmic edits and timing fixes within a bar without disturbing the surrounding bars.", "practical_application": "An editor snaps to beats to tighten a fill, fix a timing slip, or move a hit onto the correct beat.", "category": "Music Editing", "related_terms": ["Bar-level edit", "Bar-and-beat display", "Quantize", "Grid mode", "Tempo map"], "common_mistakes": ["Snapping to the wrong beat because the meter is set incorrectly", "Making beat-level cuts that break the musical phrase", "Over-quantizing so the performance loses its natural feel"], "scenario_contexts": ["Nudging a drum hit onto the correct beat", "Tightening a musical fill within one bar", "Moving a downbeat accent by a single beat to match picture"]}, "987d9f3a-68d6-4846-8813-683c771b76dc": {"definition": "Game audio rendered for headphone playback using head-related transfer functions (HRTFs) to place sounds in three dimensions around the listener, including height and behind-the-head cues. It recreates how real ears sense direction and distance, giving accurate spatial localization over two channels.", "plain_english": "Game sound made for headphones that seems to come from all around you, even above or behind. It copies how your ears sense direction so you can tell where a sound is coming from.", "purpose_function": "Delivers convincing 3D spatial cues over ordinary headphones, boosting immersion and letting players locate sounds like footsteps or gunfire by ear.", "practical_application": "A game audio designer enables an HRTF-based binaural renderer, such as a spatializer plugin in the audio engine, so 3D sources are folded down to two channels for headphones.", "category": "Spatial Audio", "related_terms": ["HRTF", "Spatial audio", "Binaural production suite", "Ambisonics", "Head tracking"], "common_mistakes": ["Expecting the 3D effect to hold up on loudspeakers instead of headphones", "Using a generic HRTF that fits some listeners poorly", "Confusing binaural rendering with plain stereo panning"], "scenario_contexts": ["Letting a player hear enemy footsteps behind them in a shooter", "Rendering a VR scene so sounds track head movement", "Mixing a horror game for headphone players"]}, "20e6143c-7dc7-47c4-9198-738cb47f0729": {"definition": "An integrated set of software tools or plugins for authoring binaural audio, typically providing HRTF-based spatial encoding, panning, and monitoring so a mix can be positioned in 3D for headphone playback. Suites may add head-tracking, reverb, and room modeling.", "plain_english": "A bundle of tools for making 3D headphone sound in one place. It lets you place sounds all around a listener and hear the result as you work.", "purpose_function": "Gives producers a complete workflow to place, process, and monitor sounds in three dimensions for binaural delivery, instead of stitching together separate tools.", "practical_application": "A producer loads the suite's spatial panner on each track and its monitoring plugin on the master to build and check a binaural mix for headphones.", "category": "Spatial Audio", "related_terms": ["Binaural game audio", "HRTF", "Spatial audio", "Ambisonics", "Head tracking"], "common_mistakes": ["Judging the binaural mix on speakers rather than headphones", "Leaving the monitoring or decoder plugin engaged in the final render", "Assuming one HRTF profile works equally well for every listener"], "scenario_contexts": ["Mixing a binaural music track for headphone release", "Producing spatial audio for a VR experience", "Creating an immersive 3D podcast or ASMR piece"]}, "8bed6755-cf68-4bcd-a73e-c12fce2379b1": {"definition": "In Audiokinetic Wwise, a container object that groups child objects into one or more blend tracks, playing them together and crossfading between them along a Game Parameter (RTPC) or as a continuous layered blend. It lets multiple sounds combine or morph based on a game value such as speed or engine RPM.", "plain_english": "A Wwise tool that plays several sounds together and smoothly mixes between them as a game value changes, like an engine getting louder and rougher as a car speeds up. It blends layers instead of picking just one.", "purpose_function": "Combines or crossfades layered sounds driven by live game data, so audio reacts smoothly to continuous changes like speed, load, or intensity.", "practical_application": "A game sound designer builds a Blend Container for engine layers and maps them to an RPM parameter so the sound morphs as the car accelerates.", "category": "Game Audio", "related_terms": ["RTPC", "Switch container", "Random container", "Sequence container", "Game parameter"], "common_mistakes": ["Confusing a Blend Container (plays layers together) with a Switch or Random Container (picks one child)", "Forgetting to assign an RTPC or Game Parameter so crossfades never trigger", "Setting overlapping crossfade ranges poorly so layers pop or double", "Placing objects in the wrong blend track"], "scenario_contexts": ["Crossfading engine layers by RPM in a driving game", "Layering wind and intensity beds that change with player speed", "Blending calm and combat music stems by a tension parameter"]}, "949485d9-f468-4f71-8abd-6cb62f46f267": {"definition": "The Foley recording of the sounds a book makes when handled on screen — picking it up, setting it down, opening and closing the covers, and turning or riffling pages — performed with a matching book in sync with the picture.", "plain_english": "Book handling is the Foley sound of someone using a book. A Foley artist opens, closes, and flips the pages of a real book in time with the picture. This makes the book on screen sound real.", "purpose_function": "It exists to give on-screen books believable, synced sound that the camera mic often misses, adding realism and small detail to a scene.", "practical_application": "A Foley artist performs page turns and cover movements with a similar book while watching the picture, and the editor syncs each sound to the actor's hands.", "category": "Foley", "related_terms": ["Foley", "Sound effects", "Prop handling", "Sync", "Cloth pass", "Sound design"], "common_mistakes": ["Using the wrong kind of book, such as a stiff hardcover where the scene shows a soft paperback.", "Turning pages too fast or too slow to match the actor's hands on screen.", "Playing the handling too loud so it distracts from the dialogue."], "scenario_contexts": ["Adding page turns for a character reading at a desk.", "Covering a book being slammed shut in a tense moment.", "Filling in the sound of someone flipping through a photo album."]}, "3ac36805-9902-4697-a5bb-dab99c236170": {"definition": "A dialogue mixing technique in which the boom microphone and the lavalier (body) microphone recordings of the same line are combined — the boom supplying natural, open timbre and the lav supplying close, intelligible detail — and matched so the two sources read as one voice.", "plain_english": "Actors are often recorded by two mics at once: a boom overhead and a tiny lav on the body. A boom-and-lav blend mixes both together. The boom sounds natural and the lav sounds clear, so you get the best of each.", "purpose_function": "It exists to get dialogue that is both natural-sounding and clearly intelligible, letting the editor lean on whichever mic solves a problem in a given moment.", "practical_application": "A dialogue editor lines up the boom and lav tracks, checks their timing and phase, and rides the balance between them line by line to fix noise, clothing rustle, or dull tone.", "category": "Dialogue editing", "related_terms": ["Boom-track priority", "Lavalier microphone", "Dialogue editing", "Production sound", "Phase", "ADR"], "common_mistakes": ["Blending the two mics without checking phase, causing hollow or thin comb-filtered sound.", "Keeping both mics up at equal level when one is clearly much cleaner than the other.", "Forgetting that boom and lav have different tone, so an unmatched blend sounds odd."], "scenario_contexts": ["Mixing a wide shot where the boom is distant but the lav sits close.", "Using the lav to cover a word the boom lost under noise.", "Blending mics to smooth a scene shot from several angles."]}, "7c681f77-cce0-4031-b362-26ad26615dc6": {"definition": "An editorial and mixing preference for using the boom microphone as the primary dialogue source, treating the lavalier as a backup drawn on only when the boom is unusable, because the boom generally gives the most natural sound of the room, with the truest sense of perspective.", "plain_english": "In dialogue editing, the boom mic usually sounds the most natural. Boom-track priority means the editor uses the boom first by default. The lav mic is only used when the boom has a problem, like noise or a bad angle.", "purpose_function": "It exists to keep dialogue sounding consistent and natural across a scene by defaulting to the mic that best matches how the room really sounds.", "practical_application": "A dialogue editor builds the scene on the boom track first, then patches in lav only where the boom is blocked, noisy, or off-mic, keeping the two matched in tone.", "category": "Dialogue editing", "related_terms": ["Boom-and-lavalier blend", "Boom microphone", "Lavalier microphone", "Dialogue editing", "Production sound", "Perspective"], "common_mistakes": ["Cutting to the lav for a whole scene when only one line of boom is bad.", "Treating the rule as absolute and ignoring lines where the lav is clearly better.", "Failing to match tone when switching between the boom and the lav."], "scenario_contexts": ["Editing a dialogue scene where the boom captures the room well.", "Choosing the boom for a two-shot with clean overhead coverage.", "Reserving the lav for moments the boom cannot reach."]}, "05870dfe-88cc-4c33-9104-c4a6b523433d": {"definition": "Footstep Foley performed while wearing boots, recorded to match a character seen in boots — capturing the heavier weight, harder heel strike, and distinct leather-and-sole character that boots produce on a given surface.", "plain_english": "Boot Foley is the sound of footsteps made in boots. A Foley artist wears boots and walks in time with the picture. This makes a character in boots sound heavy and solid on the floor.", "purpose_function": "It exists to give booted characters believable, weighty footsteps that match their footwear and the surface they walk on.", "practical_application": "A Foley artist picks the right boots, walks the step pattern in sync on a matching floor surface in the Foley pit, and the editor tightens each step to the picture.", "category": "Foley", "related_terms": ["Foley", "Footsteps", "Foley pit", "Carpet footsteps", "Surfaces", "Sync"], "common_mistakes": ["Using boots whose heel sounds nothing like the pair on screen.", "Walking on the wrong surface, such as concrete for a wooden floor.", "Performing the steps out of sync with the actor's feet."], "scenario_contexts": ["Adding heavy footsteps for a soldier marching in boots.", "Covering a cowboy walking across a wooden porch.", "Building steps for a detective pacing a tiled hallway."]}, "c70d0b48-e22e-45fb-81f5-935af64c6175": {"definition": "The Foley recording of sounds made when bottles are handled on screen — lifting, setting down, gripping, clinking, and pouring — performed with matching bottles in sync with the picture.", "plain_english": "Bottle handling is the Foley sound of someone using bottles. A Foley artist picks up, sets down, and clinks real bottles in time with the picture. This makes a bar or kitchen scene sound real.", "purpose_function": "It exists to add believable, synced bottle sounds that the camera mic often misses, giving detail to bar, kitchen, and drinking scenes.", "practical_application": "A Foley artist chooses glass or plastic bottles to match what is on screen, performs the pickups and set-downs in sync, and the editor places each sound to the actor's hands.", "category": "Foley", "related_terms": ["Foley", "Prop handling", "Book handling", "Sound effects", "Sync", "Sound design"], "common_mistakes": ["Using a glass bottle where the picture clearly shows plastic, or the reverse.", "Making handling clinks too loud so they pull focus from the dialogue.", "Missing the exact frame where the bottle touches down."], "scenario_contexts": ["Adding clinks and set-downs to a bar scene.", "Covering a character grabbing a water bottle mid-scene.", "Filling in the sound of bottles moved on a shelf."]}, "aafd8f30-bd2e-4a85-956f-334483236377": {"definition": "A short, emphatic, conclusive ending to a musical cue or piece — typically a final accented chord or hit that lands squarely and stops — giving a clear, definite sense of finish rather than fading or trailing off.", "plain_english": "A button ending is a sharp, final chord that ends a piece of music with a bang. It lands hard and stops, so you know for sure the music is done. It is like the firm dot at the end of a sentence.", "purpose_function": "It exists to close a cue cleanly and decisively, marking a strong end point that can be cut to picture or landed on a specific moment on screen.", "practical_application": "A composer or music editor writes or trims a cue so it finishes on a firm final hit, often timed to land on an action, a cut, or the end of a scene.", "category": "Music editing", "related_terms": ["Cue", "Music editing", "Sting", "Hit point", "Scoring", "Sound design"], "common_mistakes": ["Confusing a button, which stops firmly, with a fade-out that trails away.", "Placing the button so it lands off the intended picture moment.", "Making the button too soft, so the ending feels unfinished."], "scenario_contexts": ["Ending a comedy scene on a crisp musical button.", "Landing a final chord exactly on a hard cut to black.", "Trimming a library cue so it stops on a firm hit."]}, "2bf772a7-c934-4b8f-8dec-dfb59546c674": {"definition": "A Foley or hard sound-effect element covering the opening, closing, and latching of a cabinet or cupboard door — including hinge movement, the knock of the door against the frame, and the click of the catch — synced to the picture.", "plain_english": "A cabinet door effect is the sound of a cupboard door opening and closing. It includes the hinge, the bump of the door, and the click of the latch. Editors add it so a kitchen or cupboard scene sounds real.", "purpose_function": "It exists to give on-screen cabinets and cupboards believable, synced movement sound that the camera mic often does not capture cleanly.", "practical_application": "An editor or Foley artist matches the effect to the type of door on screen and syncs the open, close, and latch to the exact frames the door moves.", "category": "Sound effects", "related_terms": ["Foley", "Sound effects", "Prop handling", "Hard effects", "Sync", "Sound design"], "common_mistakes": ["Using a heavy wooden-door sound for a light, thin cabinet door.", "Missing the latch click, so the close sounds incomplete.", "Placing the close a frame or two off from the picture."], "scenario_contexts": ["Adding open and close sounds to a kitchen cabinet in a scene.", "Covering a character grabbing something from a cupboard.", "Syncing a medicine-cabinet door in a bathroom shot."]}, "e8bc7d5b-cb5c-4fac-9422-605c042eb5e7": {"definition": "Footstep Foley performed on a carpeted surface, producing the soft, muffled, low-frequency steps characteristic of walking on carpet, recorded in sync to match a character moving across a carpeted floor on screen.", "plain_english": "Carpet footsteps are the soft, quiet steps you hear when someone walks on a carpet. A Foley artist walks on a piece of carpet in time with the picture. The steps sound muffled and gentle, not sharp.", "purpose_function": "It exists to match a character's footsteps to a carpeted floor, giving the soft, dull step sound that surface produces instead of a hard, bright one.", "practical_application": "A Foley artist walks the step pattern on a carpet section in the Foley pit while watching picture, and the editor syncs each muffled step to the actor's feet.", "category": "Foley", "related_terms": ["Foley", "Footsteps", "Boot Foley", "Foley pit", "Surfaces", "Sync"], "common_mistakes": ["Making carpet steps too loud or too sharp, so they sound like a hard floor.", "Using the wrong surface, so a hard footstep plays over carpet on screen.", "Letting the steps drift out of sync with the actor's feet."], "scenario_contexts": ["Adding soft steps for a character crossing a carpeted living room.", "Covering someone creeping over a hotel-hallway carpet.", "Building quiet footsteps for a bedroom scene."]}, "68ce0155-3c98-46d3-bc23-4ee25b14bad6": {"definition": "In multichannel film and television mixing, the practice of routing the principal spoken dialogue to the dedicated center loudspeaker channel of a surround format (e.g., 5.1 or 7.1), anchoring speech to the screen independently of the left/right music and effects channels.", "plain_english": "In surround sound, the actors' voices are sent to the middle speaker behind the screen. This keeps the talking tied to the picture so every seat in the room hears it clearly.", "purpose_function": "It anchors dialogue to the picture and keeps speech intelligible and stable across a wide seating area, separating voices from music and effects that live in the other channels.", "practical_application": "A re-recording mixer routes edited dialogue and ADR to the center channel and rides its level against music and effects to hold intelligibility, then checks how it folds down to stereo.", "category": "Surround Mixing", "related_terms": ["5.1 surround", "Re-recording mix", "Dialogue stem", "Downmix", "ADR"], "common_mistakes": ["Confusing the discrete center channel with a phantom center created by the left and right speakers", "Crowding the center with music or effects so dialogue loses clarity", "Not checking the stereo or LtRt downmix, where center-channel dialogue can shift in level"], "scenario_contexts": ["Mixing a 5.1 theatrical soundtrack where all principal dialogue sits in the center", "Creating a broadcast television mix that must stay intelligible on a single center speaker", "Checking a stereo downmix to confirm dialogue level after collapsing the surround mix"]}, "75dab70e-4f00-4a86-8bb5-511cea1fb41d": {"definition": "A hard-effects or Foley element reproducing the sharp, bright, often brittle sounds of ceramic objects — such as plates, mugs, or tile — striking a surface or shattering, recorded or drawn from a library to match on-screen action.", "plain_english": "This is the clink or crash a ceramic thing like a plate or mug makes when it hits something or breaks. Sound editors add it to match objects on screen.", "purpose_function": "It supplies realistic hard-surface impact and breakage sounds so on-screen ceramic objects read as solid, heavy, and believable.", "practical_application": "A sound-effects or Foley editor syncs a ceramic impact from a Foley pass or library to a mug set down hard or a plate smashing on the floor.", "category": "Sound Effects", "related_terms": ["Foley", "Hard effects", "Prop sound", "Impact", "Sound library"], "common_mistakes": ["Using a glass or metal impact where the material should clearly read as ceramic", "Placing the impact slightly off the frame of contact so it feels disconnected from the picture", "Forgetting to add debris or settle sounds after a ceramic object shatters"], "scenario_contexts": ["Syncing a plate smashing during a kitchen argument", "Adding the clink of a ceramic mug being set on a table in a dialogue scene", "Building a breakage effect for a fight where dishes are knocked to the floor"]}, "9d4f9894-bddf-4fa5-9faa-43bd7a705be6": {"definition": "A Foley or sound-effects element reproducing the sounds of a chair being moved, scraped, shifted, or sat in, performed or edited to match a character's interaction with the chair on screen.", "plain_english": "These are the sounds of a chair being pushed, scraped, or sat in. A Foley artist makes them so the chair on screen sounds real.", "purpose_function": "It adds physical realism to scenes where characters use furniture, grounding the action and supporting continuity when production sound is missing or unusable.", "practical_application": "A Foley artist performs a chair scrape or sit to picture, and the editor trims it to hit the exact frame the character stands, sits, or drags the chair.", "category": "Foley", "related_terms": ["Foley", "Prop sound", "Footsteps", "Cloth pass", "Sound effects editing"], "common_mistakes": ["Using a chair sound that is the wrong material, such as metal legs on carpet where wood on tile is needed", "Missing the sync frame so the scrape lands before or after the visible move", "Overplaying the movement so subtle shifts sound exaggerated"], "scenario_contexts": ["Foleying a character dragging a chair back from a table before sitting", "Covering an interrogation scene where a chair scrapes on a hard floor", "Replacing noisy production sound of a chair creak during a quiet dialogue moment"]}, "881b1c71-73e3-4ab0-b9b2-fcaec76ecb37": {"definition": "In dialogue editing and ADR workflow, the practice of grouping and labeling recorded lines by the character who speaks them, so each character's dialogue sits on its own track or is clearly identified for editing, mixing, and localization.", "plain_english": "This means sorting each recorded line by the person who says it. Editors put each character's lines on their own track so they are easy to find and mix.", "purpose_function": "It organizes dialogue so a mixer can process and balance each character consistently, and so lines can be tracked cleanly through ADR, dubbing, and delivery.", "practical_application": "A dialogue editor splits a scene so each character occupies a separate track, letting the re-recording mixer apply steady EQ and level moves per voice.", "category": "Dialogue Editing", "related_terms": ["Dialogue editing", "ADR", "Track layout", "Dubbing", "Dialogue stem"], "common_mistakes": ["Leaving two characters on one track, which forces conflicting EQ and level moves", "Mislabeling tracks so ADR and localization teams cue the wrong character", "Splitting inconsistently between scenes, breaking the mixer's track layout"], "scenario_contexts": ["Laying out a dialogue scene so each speaking character has a dedicated track", "Preparing an ADR cue sheet organized by character for a session", "Building split tracks for a dubbing house working in another language"]}, "fcecbec0-256a-46e6-8e7f-9d59af1906b6": {"definition": "Foley and sound-effects elements that represent the sounds a character makes while moving — footsteps, cloth rustle, and body movement — created and edited to match the actor's motion on screen.", "plain_english": "These are the sounds a person makes while moving, like footsteps and clothes rustling. Foley artists make them to match the actor on screen.", "purpose_function": "It gives characters physical presence and weight, filling gaps where production sound is missing and supporting continuity across cuts and angles.", "practical_application": "A Foley team performs footsteps and cloth to picture, and the editor syncs the passes so a character's walk, turn, and gestures sound natural.", "category": "Foley", "related_terms": ["Foley", "Footsteps", "Cloth pass", "Prop sound", "Sound effects editing"], "common_mistakes": ["Matching footsteps to the wrong surface or shoe type", "Forgetting the cloth pass, so movement feels thin and unnatural", "Letting steps drift out of sync during long walking shots"], "scenario_contexts": ["Foleying footsteps and cloth for a character walking down a hallway", "Covering body movement for a fight scene lacking usable production sound", "Adding subtle cloth and shifts for a character fidgeting during dialogue"]}, "d465c6be-4bf4-4b0c-b3fa-e9a2f8c934b4": {"definition": "The process of matching a re-recorded or substitute voice — from ADR, dubbing, or a voice double — to an established character's vocal timbre, tone, and delivery so the replacement lines blend seamlessly with the original production dialogue.", "plain_english": "This is making a new recorded voice sound like the character's real voice. The goal is for the new lines to blend in and not stand out.", "purpose_function": "It preserves a character's consistent identity when lines must be replaced or translated, so the audience never notices the substitution.", "practical_application": "An ADR editor or dubbing supervisor selects and coaches a voice, then matches mic, tone, and level so the new take sits invisibly against the production track.", "category": "Dialogue Editing", "related_terms": ["ADR", "Dubbing", "Dialogue editing", "Voice double", "Lip sync"], "common_mistakes": ["Matching timbre but ignoring the room tone and mic character of the original", "Casting a voice whose age or accent does not fit the established character", "Letting the replacement level or brightness stand out from surrounding lines"], "scenario_contexts": ["Recording ADR that must match an actor's on-set delivery", "Casting a dubbing actor to match a character's voice in another language", "Using a voice double to cover lines the original actor cannot re-record"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"4decb662-da60-4f2c-97ff-ae330a401904": {"definition": "A designed impact sound — a short, powerful, low-heavy stinger or 'hit' — used to punctuate a cut, title, reveal, or dramatic moment in film and trailer sound design.", "plain_english": "A cinematic hit is a big, punchy boom used to mark a strong moment. You often hear it on a title card or a sharp cut in a trailer.", "purpose_function": "It adds weight and emphasis at a key beat, directing the audience's attention and heightening dramatic impact.", "practical_application": "A sound designer layers a low boom with a transient attack and tail, then syncs it to a title card, hard cut, or reveal for punch.", "category": "Sound Design", "related_terms": ["Sound design", "Stinger", "Impact", "Riser", "Sweetener"], "common_mistakes": ["Making the hit so loud or low that it swamps dialogue or overloads the mix", "Overusing hits until they lose impact", "Mistiming the transient so the punch lands off the visual cut"], "scenario_contexts": ["Punctuating a title card in a trailer with a heavy boom", "Emphasizing a dramatic reveal at a hard cut", "Layering a hit under a logo sting at the start of a film"]}, "b364a73c-e973-4711-a6c9-1d179029fec2": {"definition": "A designed sound element — such as a whoosh, riser, sweep, or reverse effect — used to bridge or smooth a cut or scene change, carrying the audience between shots or sequences.", "plain_english": "This is a sound like a whoosh or sweep used to move between two scenes. It helps carry the viewer smoothly from one shot to the next.", "purpose_function": "It links two moments so a cut feels intentional and fluid, and it can build or release tension as the picture changes.", "practical_application": "A sound designer places a rising whoosh across a cut, aligning its peak with the new shot so the change feels driven by the sound.", "category": "Sound Design", "related_terms": ["Sound design", "Whoosh", "Riser", "Sweetener", "Scene change"], "common_mistakes": ["Peaking the transition on the wrong frame so it fights the picture cut", "Reusing the same whoosh so often it becomes noticeable", "Letting the transition cover important dialogue at the scene change"], "scenario_contexts": ["Bridging a flashback with a reverse sweep into the new scene", "Driving a fast montage with rising whooshes between shots", "Smoothing a hard cut between two locations in a trailer"]}, "d6f645e2-e485-4a3d-a0e1-ca138757af98": {"definition": "Unwanted leakage of a metronome or click track from performers' headphones into open microphones, appearing as a faint rhythmic ticking in the captured audio, most often on a scoring stage or in music recording.", "plain_english": "Players often wear headphones with a click, a steady beat like a metronome. That tick can leak into the mics and show up as a faint ticking in the recording that you do not want.", "purpose_function": "As an unwanted artifact, it signals a monitoring or isolation problem; recognizing it lets editors and mixers remove or avoid ticking that would otherwise intrude on the final mix.", "practical_application": "An editor spots faint click bleed in a quiet passage and either muffs the guilty mic, lowers the headphone click, or notch-edits the ticks out during cleanup.", "category": "Recording Artifact", "related_terms": ["Click track", "Headphone bleed", "Scoring stage", "Isolation", "Spill"], "common_mistakes": ["Assuming the click is inaudible when it surfaces during quiet or exposed passages", "Running the headphone click far louder than needed, increasing spill", "Using open-back headphones on the stage instead of closed-back", "Discovering the bleed only at the mix, after the session has wrapped"], "scenario_contexts": ["Detecting a faint tick in a quiet solo passage on a scoring stage", "Reviewing tracked stems and hearing click leak from a vocalist's headphones", "Setting headphone levels before a session to keep the click from spilling into mics"]}, "5d5335c5-240b-4a52-adb0-36167553296a": {"definition": "A section of a film-score cue performed and recorded without a metronome click track, letting the conductor and players follow tempo freely rather than a fixed beat. Sync to picture is guided instead by visual cues such as streamers and punches, and the passage may sit between click-driven sections of the same cue.", "plain_english": "A part of the music played with no ticking click track. The players follow the conductor and the film freely instead of a set beat.", "purpose_function": "It gives music a natural, expressive feel where a rigid tempo would sound mechanical, while still allowing the cue to line up with the picture through visual guides. This lets a scoring session mix strict-tempo and free-tempo playing within one piece.", "practical_application": "A scoring mixer or recordist notes where the click drops out so the click feed is muted for that passage, and the conductor uses streamers and punches to catch key hit points.", "category": "Music Scoring", "related_terms": ["Click-track cue mix", "Click-track level", "Streamers and punches", "Timecode", "Scoring stage"], "common_mistakes": ["Assuming every scored cue must run to a click, when free-timing passages are common", "Leaving the click audible during a free passage so it bleeds into open microphones", "Forgetting to plan visual sync points, leaving the conductor with no way to hit picture in a click-free section"], "scenario_contexts": ["An orchestral scoring session where an emotional cue is played rubato without a click", "A hybrid cue that starts on a click, drops to free timing, then returns to click", "Recording a solo instrument to picture using streamers instead of a click"]}, "a334f1a7-ace3-4442-8127-b35d58b494ee": {"definition": "The custom headphone (foldback) monitor mix sent to scoring musicians that carries the metronome click track alongside music and reference guides, so performers can play in time with the picture. It is a monitoring feed only and is kept out of the recorded music stems.", "plain_english": "The sound in the players' headphones that has the ticking click in it. It helps them stay in time with the film while they record.", "purpose_function": "It gives performers a steady tempo reference plus guide material so their take locks to timecode and to on-screen hit points. Delivering it only to headphones keeps the click from contaminating the recording.", "practical_application": "A scoring mixer or Pro Tools operator builds and balances this mix, setting how loud the click sits against the music in each player's headphones.", "category": "Music Scoring", "related_terms": ["Click-track level", "Click-track routing", "Click-free passage", "Foldback", "Timecode"], "common_mistakes": ["Setting the click so loud it bleeds through headphones into open microphones", "Sending the same generic mix to everyone instead of tailoring the balance to each player", "Accidentally routing the click into the recorded stems along with the cue mix"], "scenario_contexts": ["An orchestral scoring session recording to picture", "A composer overdubbing live players against a programmed mockup", "A songwriter cutting a song to a locked picture edit"]}, "0fc4a648-6012-4b9b-80ed-ecd6f701e1f3": {"definition": "The volume at which the metronome click is set within a performer's headphone cue mix — loud enough to follow reliably but low enough to avoid leaking into open microphones. It is balanced per player against the surrounding music.", "plain_english": "How loud the ticking click is set in the mix. It has to be easy to hear but soft enough not to leak into the mics.", "purpose_function": "A correct level keeps players locked to tempo while protecting the recording from audible click bleed. Too low and the beat is lost; too high and the click prints onto the tracks.", "practical_application": "A scoring or tracking engineer trims the click fader while checking talkback with players, raising it for busy passages and lowering it once the tempo is felt.", "category": "Music Scoring", "related_terms": ["Click-track cue mix", "Click-track routing", "Foldback", "Microphone bleed", "Click-free passage"], "common_mistakes": ["Pushing the click loud enough that it bleeds into vocal or acoustic microphones", "Setting it so low that players drift off tempo", "Using one click level for the whole session instead of adjusting per player and per cue"], "scenario_contexts": ["Balancing the click in a lead vocalist's headphones during a scoring take", "Raising click level for a fast, dense passage a drummer must nail", "Reducing click level so it does not print through an open room microphone"]}, "a14a7190-8692-43b8-9988-a36579202afb": {"definition": "The signal-path setup that sends the metronome click only to performers' headphone foldback and deliberately excludes it from the recorded music stems and the program deliverable. It isolates the click as a monitoring-only signal.", "plain_english": "The path that sends the click only to the players' headphones. It keeps the click out of the final recorded sound.", "purpose_function": "It ensures musicians hear the tempo reference while guaranteeing the click never appears in printed tracks or the finished mix, which must be click-free. Proper routing separates monitoring feeds from record and program buses.", "practical_application": "An engineer patches or buses the click to the cue/foldback outputs only, then confirms by soloing the record path that no click is present before printing.", "category": "Music Scoring", "related_terms": ["Click-track cue mix", "Click-track level", "Foldback", "Bus", "Stem"], "common_mistakes": ["Routing the click to the record bus so it prints into the delivered stems", "Not verifying the record path is click-free before committing a take", "Confusing the monitor/foldback bus with the main program bus when assigning the click"], "scenario_contexts": ["Configuring a scoring session so the click feeds headphones but not the mix", "Checking stems before delivery to confirm no click bleed remains", "Setting up foldback sends on a console for a tracking date"]}, "94a97ddf-dd15-4a3c-ac4a-c4a87249faaa": {"definition": "One of the three core Foley categories (with footsteps and props), covering the subtle sounds of a performer's clothing and fabric shifting as the body moves. Foley artists perform these 'moves' by manipulating garments in sync with the picture to add physical realism.", "plain_english": "The soft rustle of clothes as an actor moves. A Foley artist makes these sounds by moving fabric in time with the picture.", "purpose_function": "It restores the quiet fabric sounds that are usually missing or too weak in the production dialogue track, grounding characters in a believable physical space. These moves knit footsteps and prop handling together into natural human motion.", "practical_application": "A Foley artist watches the scene and moves matching clothing (a jacket, denim, or leather) at a Foley pit microphone, laying a continuous 'cloth pass' that a Foley mixer records and edits to picture.", "category": "Foley", "related_terms": ["Clothing rustle", "Cloth synchronization", "Footsteps", "Foley pit", "Props"], "common_mistakes": ["Performing cloth so loudly it competes with dialogue instead of supporting the action", "Using the wrong fabric so the texture does not match the costume on screen", "Neglecting cloth moves, leaving characters feeling flat and lifeless"], "scenario_contexts": ["Adding fabric moves under a character walking across a room", "Covering a fight scene where jackets and shirts scuff and stretch", "Laying subtle cloth under a seated actor gesturing during dialogue"]}, "7dcb0503-31b8-4e3a-a11c-4862b755eff3": {"definition": "The process of performing and aligning cloth (clothing) Foley so the fabric-movement sounds match the on-screen actor's body movements frame-accurately. It applies picture-sync discipline specifically to the cloth pass.", "plain_english": "Lining up the cloth rustle sounds so they match the actor's moves on screen. The fabric sound has to hit at the same moment we see the body move.", "purpose_function": "Accurate sync makes the added fabric sounds read as coming from the character rather than as unrelated noise, preserving the illusion of real motion. Misaligned cloth breaks immersion even when the recording sounds good.", "practical_application": "A Foley artist and mixer perform and then nudge the cloth takes in the DAW so each rustle lands on the matching frame, checking against the picture at edit points.", "category": "Foley", "related_terms": ["Cloth movement", "Clothing rustle", "Footsteps", "Frame accuracy", "Timecode"], "common_mistakes": ["Leaving cloth a few frames early or late so it feels detached from the action", "Syncing only the big moves and ignoring small in-between shifts", "Trusting the performance take without checking it against picture at key frames"], "scenario_contexts": ["Nudging a recorded cloth pass to hit an actor's sudden turn", "Aligning jacket rustle to a character standing up", "Fixing sync on cloth that drifted during a long walking shot"]}, "47e427df-ce99-4855-bc82-b5ef267646d8": {"definition": "The frictional, swishing noise produced by fabric moving against itself or the body. In post it is recreated deliberately as cloth Foley, and in production sound it is an unwanted contaminant when a garment couples into a hidden lavalier or body microphone.", "plain_english": "The swishy, scratchy sound clothes make when they rub. It can be added on purpose as Foley, or it can be unwanted noise on a hidden mic.", "purpose_function": "As Foley it adds lifelike texture to a character's movement; as production noise it is a problem to prevent or clean up because it masks dialogue. Understanding both sides lets a technician add it where wanted and remove it where not.", "practical_application": "A Foley artist performs it with matching fabric for realism, while a production or dialogue editor mounts lav mics carefully and uses spectral repair tools to reduce rustle on recorded dialogue.", "category": "Foley", "related_terms": ["Cloth movement", "Cloth synchronization", "Lavalier microphone", "Dialogue editing", "Foley pit"], "common_mistakes": ["Mounting a lavalier where costume fabric rubs it, printing rustle onto the dialogue", "Assuming heavy rustle can always be removed cleanly in post rather than preventing it at the source", "Performing Foley rustle with fabric that does not match the on-screen costume"], "scenario_contexts": ["Hiding a lav under a stiff jacket and taming rustle with mounts and tape", "Adding cloth Foley to a scene shot silent or with a boom only", "Cleaning rustle from a lav track during dialogue editing"]}, "a132518c-9dd6-4621-8bc3-bc432051a430": {"definition": "A Foley 'specifics'/prop sound: the clink, jingle, and rattle of coins being handled, counted, dropped, or carried, performed in sync with on-screen action. It is one of many prop-based Foley effects used to add small, character-driven detail.", "plain_english": "The clink and jingle of coins being handled or dropped. A Foley artist shakes or drops coins in time with the action on screen.", "purpose_function": "It gives weight and reality to small hand actions that the picture shows but the dialogue track did not capture, telling the audience money is present and being handled. Such prop details make scenes feel tactile.", "practical_application": "A Foley artist uses real coins on a matching surface at the Foley stage, shaking a pocketful or dropping them onto a counter in sync with the actor's hands.", "category": "Foley", "related_terms": ["Props", "Cloth movement", "Footsteps", "Foley pit", "Spot effects"], "common_mistakes": ["Using the wrong number or size of coins so the jingle does not match what is on screen", "Performing the handling off-sync with the actor's hand movements", "Recording coins too loud so they jump out of the scene's perspective"], "scenario_contexts": ["Covering a character paying with change at a counter", "Adding a pocketful of coins jingling as someone runs", "Foleying coins being counted onto a table"]}, "fc7973d1-2b0b-4544-b994-435505b75071": {"definition": "The impact sound created when two objects strike each other, built as a Foley or hard sound effect and synced to the moment of on-screen contact. It typically combines an initial transient with body and debris elements to convey mass and material.", "plain_english": "The bang or crash when two things hit each other. In film this hit is added as an effect, timed to the moment they touch.", "purpose_function": "It sells the force, weight, and material of an impact the picture shows, giving physical consequence to an action that would otherwise feel weightless. The right transient and body tell the audience how hard and how heavy the hit was.", "practical_application": "A Foley artist or sound effects editor performs or layers impacts — matching materials and adding low-end or debris — and aligns the transient to the exact contact frame in the DAW.", "category": "Sound Effects", "related_terms": ["Hard effects", "Foley", "Transient", "Layering", "Frame accuracy"], "common_mistakes": ["Placing the impact a frame or two off the visible contact so it feels disconnected", "Using a thin single sample that lacks the weight the object should have", "Reusing an obviously mismatched impact whose material does not fit the objects on screen"], "scenario_contexts": ["Timing a car-crash impact to the frame of contact", "Building a punch or body impact in a fight scene", "Layering a heavy object falling and striking the floor"]}, "e799bcab-44c8-4b5c-bcb4-26fbd5284999": {"definition": "A darkened, calibrated screening room fitted with a reference projector or display and a color-grading control surface, in which a colorist adjusts the color, contrast and brightness of a film or program to a defined viewing standard. It is where the picture's final look (the digital intermediate) is created, mirroring the audio dubbing/mix stage on the sound side of post.", "plain_english": "A dark room with a big, carefully set up screen. An artist there tweaks the colors and brightness of a movie, a bit like editing a photo, but for the whole film and on a cinema-sized screen.", "purpose_function": "It gives the colorist a controlled, standards-matched space so the color choices they make look the same in real cinemas. It exists to finish the picture's look in a consistent, repeatable way.", "practical_application": "Sound teams coordinate with the grading theater because the final graded picture must match the version used for the mix and share the same timecode and reel structure for conform and deliverables.", "category": "Post-Production Facility", "related_terms": ["Digital intermediate", "Dubbing stage", "Reference monitor", "Conform", "Timecode", "Deliverables"], "common_mistakes": ["Confusing the color-grading theater with the audio dubbing stage; they are separate rooms for picture and sound.", "Assuming any dark room works, when grading needs calibrated displays and controlled lighting to a viewing standard.", "Treating grading changes as cosmetic, when a reframe or speed change can force the sound team to re-conform."], "scenario_contexts": ["A colorist finalizes a feature's look in the grading theater before the graded picture goes to the mix stage.", "A change made in the grading theater shifts a cut point, so the re-recording mixer updates the sound conform.", "A studio checks that the grading theater and the dubbing stage reference the same picture version for deliverables."]}, "c0ac50df-cde0-4fcf-bcef-1e9d26be93bf": {"definition": "In interactive (game) audio, a game state or control value that flags when gameplay has entered combat, read by the audio engine or middleware to switch or blend music, ambience and mix settings to suit fighting. It is typically one value in a set of mutually exclusive states such as explore, combat and victory that drive adaptive audio.", "plain_english": "A signal inside a video game that says 'a fight is happening now.' The game uses it to bring in tense battle music and pull back other sounds, like a mood switch that flips when danger starts.", "purpose_function": "It lets a game change its music and mix on its own as the action changes, with no person mixing live. It exists so audio can react to gameplay in real time.", "practical_application": "A game-audio technician sets up the combat state in middleware such as Wwise or FMOD and maps it to music switches and mix snapshots so the score intensifies the moment combat begins.", "category": "Interactive Audio", "related_terms": ["Adaptive music", "Real-time parameter control (RTPC)", "Audio middleware", "Mix snapshot", "State (game audio)", "Interactive music"], "common_mistakes": ["Confusing a state (a discrete condition like combat) with a continuous parameter that varies over a range.", "Leaving no transition or crossfade, so music snaps harshly when combat starts or ends.", "Forgetting to define the exit or return state, so combat music keeps playing after the fight is over."], "scenario_contexts": ["A player is ambushed and the combat state triggers, swapping calm exploration music for a driving battle cue.", "When the enemies are defeated, the state returns to explore and the music eases back.", "A sound designer tunes the fade time on the combat state so the music shift feels smooth."]}, "ac4d025f-6649-405d-accb-e40a400f2b3f": {"definition": "In Foley, footstep sounds performed and recorded to match a character walking or running on a concrete or hard stone surface, using suitable footwear on a matching floor or Foley pit. They form part of the footstep 'moves' layer of a film or program's sound effects.", "plain_english": "The sound of shoes hitting a hard concrete floor, made and recorded on purpose to match what you see on screen. A Foley artist wears the right shoes and steps on real concrete so each step lines up with the actor.", "purpose_function": "They replace or reinforce footstep sounds the location recording missed, so a character's walk sounds solid and real on a hard surface. They exist to make movement believable and to give mixers clean, separate footstep tracks.", "practical_application": "A Foley artist watches the picture and walks in time with the actor on a concrete surface, choosing shoes and stepping style to match the pace, weight and mood of the shot.", "category": "Foley", "related_terms": ["Foley", "Foley pit", "Footsteps", "Sound effects editing", "M&E stem", "Spotting"], "common_mistakes": ["Recording footsteps out of sync with the picture so they do not land with the actor's feet.", "Using the wrong shoes or surface, making concrete steps sound hollow or like wood.", "Forgetting that footsteps must also live in the M&E stem for foreign-language versions."], "scenario_contexts": ["A detective walks down a concrete alley and the Foley team performs matching footsteps.", "Location dialogue is clean but has no footsteps, so Foley adds concrete steps to sell the walk.", "Footsteps are recorded separately so they can be balanced and delivered in the effects stem."]}, "16d04a9a-e5a3-43da-8169-3a313bd83d54": {"definition": "Playback of audio or media that occurs only when defined conditions or logic are satisfied — such as a game state, a user action, a sensor input or a branching rule — rather than playing linearly. It is a core behavior of interactive and installation media systems and of branching or adaptive audio.", "plain_english": "Sound that plays only when certain things are true, instead of playing straight through. It is like a doorbell that rings only when someone presses the button, or game music that starts only when you enter a room.", "purpose_function": "It lets a system respond to what is happening so the right sound plays at the right moment. It exists to make audio interactive and aware of context instead of fixed.", "practical_application": "A technician builds conditional playback in middleware or a show-control or AV system, setting rules so cues fire only when a trigger, state or input meets the set condition.", "category": "Interactive Audio", "related_terms": ["Interactive audio", "Trigger", "Show control", "Adaptive music", "State (game audio)", "Cue"], "common_mistakes": ["Not covering every condition, leaving gaps where no sound plays when it should.", "Overlapping conditions that let two cues fire at once and clash.", "Testing only the expected path and missing edge cases where the trigger never resolves."], "scenario_contexts": ["In a museum exhibit, narration plays only when a visitor stands on a sensor pad.", "In a game, a stinger plays only if the player's health drops below a set point.", "A show-control system plays a backup cue only if the primary source fails."]}, "21aa63aa-893b-416e-b2b6-878f1eccab73": {"definition": "On a scoring stage, a dedicated headphone (cue) mix sent to the conductor that combines the click track (metronome tempo reference) with a chosen balance of pre-recorded elements, playback and live orchestra needed to conduct in sync with picture. It is one of several individually tailored click/cue mixes distributed to the podium and players.", "plain_english": "A special headphone mix made just for the conductor while a film score is recorded. It blends a click, like a steady metronome beep, with the music so the conductor can lead the orchestra exactly in time with the movie.", "purpose_function": "It keeps the conductor locked to the film's tempo and timing so the recorded music lines up with the picture. It exists because the orchestra must play to precise sync points, not just by feel.", "practical_application": "A scoring mixer or music tech builds the conductor's click mix at the console or click system, setting click level, subdivisions and count-in so the conductor hears the beat clearly over the orchestra.", "category": "Music Scoring", "related_terms": ["Click track", "Scoring stage", "Streamers and punches", "Conductor video monitor", "Cue (music)", "Pre-roll"], "common_mistakes": ["Setting the click too low so the conductor loses the beat under a loud orchestra.", "Sending everyone the same mix instead of tailoring the conductor's balance.", "Leaving out the count-in, so the downbeat is missed."], "scenario_contexts": ["A composer conducts to picture while the click mix keeps the orchestra on tempo.", "During a tricky hit, the conductor relies on the click mix to land the sync point.", "The mixer adds click subdivisions in the conductor's mix for a fast passage."]}, "d358b835-558f-47d6-9596-8d62e0703fed": {"definition": "On a scoring stage, a video display placed in the conductor's sightline showing the picture being scored — typically with visual sync aids such as streamers, punches and a timecode or frame counter — so the conductor can align the performance to on-screen action. It is the conductor's picture reference at the podium.", "plain_english": "A screen placed in front of the conductor while a film score is recorded. It shows the movie, often with lines and flashes that mark key moments. This lets the conductor watch the film and lead the players so the music hits the action on time.", "purpose_function": "It gives the conductor a clear view of the picture and its sync cues so the music matches the film. It exists so the orchestra can be led to exact visual hit points.", "practical_application": "A scoring stage technician positions and feeds the conductor's monitor with the current picture cut, timecode and streamer or punch overlays generated by the click and sync system.", "category": "Music Scoring", "related_terms": ["Streamers and punches", "Click track", "Conductor click mix", "Scoring stage", "Timecode", "Sync point"], "common_mistakes": ["Feeding an out-of-date picture cut so the conductor syncs to the wrong edit.", "Placing the monitor off the conductor's sightline, breaking eye contact with the orchestra.", "Missing or mis-timed streamers, making hit points hard to catch."], "scenario_contexts": ["The conductor watches streamers on the monitor to nail a musical hit as a door slams.", "A new picture version is loaded to the conductor's monitor before the next take.", "The stage tech checks that timecode on the monitor matches the recording system."]}, "ced5b08b-055a-44dd-bd05-8cb2df985ec8": {"definition": "In 3D and game audio, the reduction in a directional sound source's gain applied as the listener moves off the source's projection axis: full gain applies within the inner cone angle, gain is interpolated across the transition zone between the inner and outer cone angles, and the source drops to a set outer-cone gain factor beyond the outer cone angle.", "plain_english": "Cone attenuation makes a sound quieter when you are off to the side of the source producing it. A sound source can aim like a flashlight beam. You hear it at full volume in the beam, and it fades as you step out of it.", "purpose_function": "It models the directivity of real sources such as a speaking mouth, a horn, or a TV, so a 3D sound softens when the listener is off-axis, adding realism and useful spatial cues to an interactive scene.", "practical_application": "A game-audio designer sets a source's inner cone angle, outer cone angle, and outer-cone gain in middleware or a game engine (Wwise, FMOD, Unreal, or OpenAL) so a directional emitter quiets down as the player moves out of its cone.", "category": "Spatial Audio", "related_terms": ["Falloff distance", "Emitter position", "Attenuation curve", "Far-field spatialization", "Audio middleware", "Doppler effect simulation"], "common_mistakes": ["Confusing cone attenuation with distance falloff; the cone sets level by the listener's angle to the source, while falloff sets level by distance.", "Leaving the outer-cone gain at zero by accident, so the source goes fully silent the instant the listener steps outside the cone.", "Setting the inner and outer cone angles equal, which removes the smooth transition zone and causes an abrupt level jump off-axis."], "scenario_contexts": ["Making an NPC's voice quieter when the player walks around behind them.", "Aiming a loudspeaker or television emitter in a level so it projects sound forward.", "Tuning a directional machine or vent so it only reads loud when faced head-on."]}, "e7f8c893-1d67-4ed6-87df-32d26a56424f": {"definition": "A digital signal process that combines an input signal with an impulse response by mathematical convolution, so the output takes on the acoustic or filtering characteristics captured in that impulse response. It is the basis of convolution reverb and of applying measured spaces, speaker or microphone responses, or filters to audio.", "plain_english": "A way for a computer to make one sound take on the 'fingerprint' of a real space or device. It captures how a place echoes, then stamps that echo onto your audio, so a dry recording can sound like it was played in a cathedral.", "purpose_function": "It lets engineers recreate the exact sound of real rooms, gear or speakers on any recording. It exists to add realistic reverb and tone using measured impulse responses instead of guesswork.", "practical_application": "A re-recording mixer loads an impulse response of a real location into a convolution reverb so dialogue or effects sit believably in that space and match the production sound.", "category": "Signal Processing", "related_terms": ["Impulse response", "Convolution reverb", "Reverb", "FIR filter", "Digital signal processing", "Worldizing"], "common_mistakes": ["Thinking any reverb plug-in is convolution; algorithmic reverbs synthesize and do not use impulse responses.", "Using a very long impulse response and overloading the CPU with latency and heavy processing.", "Applying a strong space to dialogue that must stay dry and clear."], "scenario_contexts": ["A mixer uses a convolution reverb with a real hallway impulse to match a scene's location.", "An engineer applies a measured speaker impulse to model a specific playback device.", "Convolution places clean ADR into the same room as the original production dialogue."]}, "bd1e98c4-980b-4392-b447-64e968413b82": {"definition": "A short series of metronomic click-track beats sounded ahead of a music cue's downbeat, usually one or two bars, so the conductor and players lock to the cue's tempo before recording begins.", "plain_english": "It is a set of steady clicks played just before the music starts. It counts the players in so they all begin together at the right speed.", "purpose_function": "It sets the tempo and a shared starting point before the first note, so an ensemble enters cleanly and stays in sync with picture.", "practical_application": "A scoring mixer or music editor sets a one- or two-bar count-in on the click track so the orchestra hears the beat and starts the cue in time.", "category": "Scoring & Music Editing", "related_terms": ["Click track", "Streamers and punches", "Cue countdown", "Tempo map", "Downbeat"], "common_mistakes": ["Setting the count-in too short so players cannot lock to tempo before the downbeat", "Confusing the count-in click with a visual streamer countdown", "Forgetting to trim the count-in clicks out of the final recorded cue"], "scenario_contexts": ["Recording an orchestral cue to a click at a scoring stage", "Overdubbing a soloist who needs a two-bar lead-in", "Programming a tempo map in the DAW before a scoring session"]}, "e38f9af3-9811-4e9e-8f23-3e62c7d516b5": {"definition": "A designed vocalization or movement sound for a non-human character such as a monster, animal, or alien, built by layering and processing recorded animal, human, or synthesized sources.", "plain_english": "It is a made-up sound for a creature like a monster or alien. Sound designers build it by mixing and changing real animal or human recordings.", "purpose_function": "It gives a fictional creature a believable voice and presence, supporting character and emotion where no real-world recording exists.", "practical_application": "A sound designer layers pitched-down animal growls with human vocals and processing to voice an on-screen monster, then syncs it to the performance.", "category": "Sound Design & SFX", "related_terms": ["Sound design", "Foley", "Layering", "Pitch shifting", "Sound effects (SFX)", "Vocalization"], "common_mistakes": ["Using a single raw animal recording instead of layering for a richer, original sound", "Neglecting to sync the vocalization to the creature's mouth or movement", "Over-processing until the sound loses clarity and impact"], "scenario_contexts": ["Designing a monster roar for a fantasy film", "Creating alien speech for a science-fiction scene", "Building animal vocalizations for an animated feature"]}, "63cd5a8b-9531-4481-84fe-d4cfd2ee3317": {"definition": "A visual and/or audible countdown leading into the start of a music cue, giving the conductor and players a fixed preparation interval before the downbeat, often realized with streamers and punches or numeric countdown markers.", "plain_english": "It is a short countdown that leads into a music cue. It warns the conductor and players so they are ready to start on the exact beat.", "purpose_function": "It gives an ensemble a steady lead-in so it can prepare and enter precisely on the cue's start frame in sync with picture.", "practical_application": "A music editor places a countdown ahead of the cue so the conductor sees streamers or numbers and brings the orchestra in on the hit point.", "category": "Scoring & Music Editing", "related_terms": ["Streamers and punches", "Count-in click", "Hit point", "Downbeat", "Click track"], "common_mistakes": ["Confusing the cue countdown with a program leader countdown at the head of a reel", "Setting the countdown length inconsistently so the conductor cannot rely on it", "Placing the countdown against the wrong start frame"], "scenario_contexts": ["Cuing an orchestra to a hit point on a scoring stage", "Preparing streamers and punches for a conductor", "Recording a cue where the ensemble must enter on an exact picture frame"]}, "8f9f3f6a-39a8-4aef-9d59-fd4d8638129f": {"definition": "The reshaping of a music cue by a music editor, cutting, repeating, or rearranging recorded or library music, so it fits the picture's length, structure, and sync points.", "plain_english": "It is changing a piece of film music so it fits the scene. The editor cuts, repeats, or moves parts so the music matches the picture.", "purpose_function": "It makes a cue fit the exact timing and shape of a scene without re-recording, lining up musical events with on-screen action.", "practical_application": "A music editor trims and reassembles a recorded cue in the DAW so its phrases land on the scene's key moments and its out-point matches the cut.", "category": "Scoring & Music Editing", "related_terms": ["Music editor", "Cue extension", "Cue shortening", "Hit point", "Cue reconform"], "common_mistakes": ["Cutting on the wrong beat so the edit sounds musically abrupt", "Ignoring tempo and phrase boundaries when joining sections", "Editing without checking sync against the current picture cut"], "scenario_contexts": ["Fitting a temp or library track to a scene", "Adjusting a scored cue after a picture change", "Assembling a source-music edit for on-screen playback"]}, "26cf4839-83a7-48a6-94e0-df27906a6bea": {"definition": "Lengthening a music cue to cover more screen time by repeating sections, adding bars, or extending the tail, while preserving musical continuity to a new out-point.", "plain_english": "It is making a piece of film music longer. The editor repeats or adds parts so the music keeps playing until a later point in the scene.", "purpose_function": "It stretches a cue to fill a longer scene or a moved out-point without re-recording, keeping the music continuous and coherent.", "practical_application": "A music editor loops a section or adds bars so the cue reaches a new picture out-point after the scene is recut longer.", "category": "Scoring & Music Editing", "related_terms": ["Cue shortening", "Cue edit", "Music editor", "Cue reconform", "Hit point"], "common_mistakes": ["Looping a section audibly so the repeat is obvious to the audience", "Extending past a phrase so the added bars clash harmonically", "Breaking sync at hit points while adding length"], "scenario_contexts": ["Covering a scene that was recut longer", "Filling a gap left when an adjacent cue was removed", "Extending an end-title cue to match a longer crawl"]}, "1b8c3567-25ce-4ef0-8612-795218c030c8": {"definition": "Re-editing a music cue and its edit decisions to match a revised picture cut, restoring sync of musical events to on-screen action after editorial changes shift or remove frames.", "plain_english": "It is fixing a music cue after the picture edit changes. The editor moves and trims the music so it lines up with the new cut again.", "purpose_function": "It keeps music in sync when picture is recut, so hit points and phrasing stay aligned without rebuilding the cue from scratch.", "practical_application": "After receiving a change list, a music editor reconforms cues by inserting or removing the same frames so the score realigns to the new edit.", "category": "Scoring & Music Editing", "related_terms": ["Reconform", "Change list", "Cue edit", "EDL", "Hit point"], "common_mistakes": ["Applying the wrong change list version and shifting cues incorrectly", "Reconforming to the new cut but forgetting hit-point resync within the music", "Not verifying sync against the updated picture after the reconform"], "scenario_contexts": ["Adapting the score after a new picture cut arrives", "Applying an editorial change list to the music session", "Resyncing cues before a re-record mix"]}, "f19d6f0d-3de9-46ad-aa79-bc13836cd81e": {"definition": "Reducing a music cue's length to fit a shorter picture section by removing bars or sections while preserving musical structure and sync to the remaining hit points.", "plain_english": "It is making a piece of film music shorter. The editor takes out parts so the music fits a shorter scene but still sounds whole.", "purpose_function": "It fits a cue to a trimmed scene or an earlier out-point without re-recording, keeping the music musically intact.", "practical_application": "A music editor removes internal bars or a section so a recorded cue ends at an earlier picture out-point after the scene is cut shorter.", "category": "Scoring & Music Editing", "related_terms": ["Cue extension", "Cue edit", "Music editor", "Hit point", "Cue reconform"], "common_mistakes": ["Cutting mid-phrase so the shortened cue sounds truncated", "Removing bars that carry a needed hit point", "Ignoring tempo so the join between sections stutters"], "scenario_contexts": ["Fitting a cue to a scene that was trimmed", "Tightening a cue that overruns its out-point", "Shortening a source cue for a brief on-screen appearance"]}, "6c2467c9-9064-4548-a3bc-1f0c7221cca8": {"definition": "Shifting or time-scaling a music cue so its musical events and hit points align with picture, by moving the cue's start, nudging sections, or applying tempo and time changes.", "plain_english": "It is moving or stretching a music cue so it lines up with the action. The editor nudges the music until key moments hit the picture.", "purpose_function": "It aligns musical accents with on-screen events, correcting drift or misalignment between the cue and the picture.", "practical_application": "A music editor slips the cue or adjusts tempo so an accent lands exactly on a cut or a character's move.", "category": "Scoring & Music Editing", "related_terms": ["Hit point", "Cue edit", "Tempo map", "Cue reconform", "Sync"], "common_mistakes": ["Time-stretching so far that audible artifacts appear", "Fixing one hit point while knocking others out of sync", "Adjusting timing without confirming against the locked picture"], "scenario_contexts": ["Landing a musical accent on a specific frame", "Correcting sync drift after a session change", "Aligning a temp cue to the scene before scoring"]}, "5fbabf08-6d96-4dc3-9443-d782b84742d0": {"definition": "Revising the cue sheet, the document listing each music cue with its title, timecode start and end, duration, and composer or publisher, to reflect current edits for scoring, dubbing, or music-rights reporting.", "plain_english": "It is updating the list of all music cues in a project. The list shows each cue's name, timing, and length so everyone works from correct info.", "purpose_function": "It keeps an accurate record of every cue's placement and length so the mix, delivery, and music-rights royalty reporting stay correct.", "practical_application": "A music editor updates the cue sheet after edits so timecodes, durations, and cue names match the current session before delivery.", "category": "Scoring & Music Editing", "related_terms": ["Cue sheet", "Music editor", "Timecode", "Deliverables", "Cue reconform"], "common_mistakes": ["Leaving old timecodes on the sheet after cues are re-edited", "Confusing the scoring cue sheet with the performance-rights cue sheet", "Omitting composer or publisher data needed for royalty reporting"], "scenario_contexts": ["Preparing music-rights documentation for a broadcast", "Updating cue timings after a reconform", "Delivering a final cue sheet with the mix"]}, "5eb01943-46e4-4834-b308-339a04249876": {"definition": "A background atmosphere (atmos/backgrounds) that a sound designer deliberately constructs by layering and processing multiple elements — recordings, loops, spot sounds and tonal beds — rather than using a single location recording, in order to create a specific stylized or emotional sense of place.", "plain_english": "A background sound world that a sound designer builds by hand, mixing many sounds together instead of using one plain recording of a real place. It is like painting a scene's mood rather than taking a single photo of it.", "purpose_function": "It gives a scene a controllable, evocative sense of environment that raw location recordings cannot, supporting mood, story and the feeling of a place.", "practical_application": "The designer layers loops, textures and spot sounds in the DAW and processes them to sit under dialogue and effects, delivering the result in the backgrounds/ambience stem.", "category": "Ambience & Backgrounds", "related_terms": ["Room tone", "Backgrounds (BGs)", "Ambience bed", "Sound design", "Foley", "Stem"], "common_mistakes": ["Assuming a single field recording is enough for a rich, story-specific atmosphere", "Building the ambience so loud or busy that it masks dialogue", "Forgetting to check the designed ambience for continuity across cuts and scene changes"], "scenario_contexts": ["Building an alien jungle atmosphere for a sci-fi film from layered animal, wind and synth textures", "Creating a tense, hollow room tone for a thriller interior", "Designing a stylized city backdrop that shifts mood as the story turns"]}, "d1c7cf8b-c62a-46e6-bef3-d0576d611d53": {"definition": "A sound effect intentionally constructed by the sound designer from layered and processed source recordings and synthesis, rather than taken as-is from a library or a single field recording, often to create sounds that do not exist naturally.", "plain_english": "A sound effect that a sound designer builds from scratch by combining and shaping other sounds. It is used for things that have no real sound, like a spaceship or a magic spell.", "purpose_function": "It lets the team create sounds that fit the picture and story exactly — including impossible or fantastical ones — that no single recording could provide.", "practical_application": "The designer layers, pitches and processes recordings in a DAW to build the effect, then syncs it to picture on an effects track.", "category": "Sound Design", "related_terms": ["Sound design", "Hard effects", "Foley", "Sound library", "Layering", "Sweetener"], "common_mistakes": ["Relying on a single unedited library sound and calling it a designed effect", "Layering so many elements that the sound becomes muddy or unfocused", "Not tuning the effect's pitch and length to match the on-screen action"], "scenario_contexts": ["Building a spaceship engine from layered synth, animal and machine sounds", "Creating a creature roar that no real animal makes", "Designing a signature weapon sound for an action sequence"]}, "4254d7f2-89b4-4258-901b-5626607e3874": {"definition": "A sound effect, or group of layered effects, depicting something breaking, collapsing, shattering or being demolished — impacts, cracks, debris and rubble — usually built as a designed effect for scenes of damage or destruction.", "plain_english": "The sound of something being smashed, broken or knocked down, like a wall falling or a car crash. Sound designers usually build it by layering many crash and debris sounds together.", "purpose_function": "It makes on-screen destruction feel powerful and believable, adding the weight, detail and impact that big damage needs.", "practical_application": "The designer layers impact, crack and debris/rubble elements synced to the picture, often adding low-end for weight and using automation to shape the hit.", "category": "Sound Effects", "related_terms": ["Hard effects", "Impact", "Debris", "Sound design", "Layering", "Sweetener"], "common_mistakes": ["Using one crash sound instead of layered impact, crack and debris elements", "Leaving out the settling debris tail so the destruction ends too abruptly", "Adding so much low-end weight that it overloads the mix or clips"], "scenario_contexts": ["Building the sound of a building collapsing in a disaster film", "Creating a car crash with metal impacts and shattering glass", "Designing a wall being smashed apart in an action scene"]}, "6b805c55-33bc-4ef3-b449-1b08c73bf7db": {"definition": "In dubbing and localization, the writer who adapts a translated dialogue script so the new-language lines match the on-screen actors' lip movements, timing and performance; also called a dialogue adapter or dialogue writer.", "plain_english": "In dubbing, the person who rewrites translated lines so they fit the actor's mouth movements and timing on screen. They make the new-language words look and sound natural against the picture.", "purpose_function": "It lets a film or show be re-voiced in another language while keeping lip-sync, timing and meaning believable for the audience.", "practical_application": "Working from a translation and the picture, the adaptor crafts lines that lip-sync, which voice actors then record in a dubbing or ADR session.", "category": "Dubbing & Localization", "related_terms": ["Dubbing", "ADR", "Lip-sync", "Voice-over", "Localization", "Dialogue asset"], "common_mistakes": ["Confusing the adaptor's job with a literal translator, ignoring lip-sync and timing", "Writing lines that are accurate but do not fit the actor's mouth movements", "Losing the tone or intent of the original performance while chasing sync"], "scenario_contexts": ["Adapting a translated film script so dubbed lines match the actors' lips", "Reworking a TV series dialogue for a foreign-language release", "Shortening or lengthening translated lines so they fit each on-screen mouth movement"]}, "9c871ae5-0cc6-4ba1-a4bc-56446318894e": {"definition": "The process of matching the background ambience and room tone under dialogue so that edits between takes, microphones, or ADR and production sound are seamless and the background does not audibly jump.", "plain_english": "Keeping the quiet background sound behind speech even, so cuts between different takes or recordings don't jump. It is like matching paint so a patched wall blends in.", "purpose_function": "It keeps dialogue edits invisible by making sure the background under every line stays consistent in level and character.", "practical_application": "The dialogue editor fills gaps and smooths joins with matching room tone or ambience and small level moves so the transitions are inaudible.", "category": "Dialogue Editing", "related_terms": ["Room tone", "ADR", "Dialogue editing", "Backgrounds (BGs)", "Fill", "Perspective"], "common_mistakes": ["Cutting between takes with different backgrounds and leaving an audible jump", "Forgetting to record or gather matching room tone on location", "Pasting fill that is the wrong level or tone for the surrounding lines"], "scenario_contexts": ["Smoothing a scene cut where two takes have different air-conditioner hum", "Blending an ADR line into surrounding production dialogue", "Filling a silent gap under dialogue with matching room tone"]}, "159b8b1a-4d8b-4acd-b37d-80490f3ea704": {"definition": "An individual dialogue audio element in the post workflow — such as a production recording, an ADR line, or a dialogue file or stem — that is managed and tracked as a discrete asset for editing, mixing and delivery.", "plain_english": "A single dialogue sound file used in a project, like one recorded line of speech. It is named and tracked so the team can find and use it in editing and mixing.", "purpose_function": "It lets spoken-word material be organized and tracked so it can be edited, mixed and delivered reliably across a large project.", "practical_application": "Editors import, label and version dialogue assets in the DAW and media management, keeping each tied to its scene, take and metadata.", "category": "Dialogue", "related_terms": ["Dialogue stem", "ADR", "Production sound", "Metadata", "Deliverables", "Media management"], "common_mistakes": ["Naming assets inconsistently so lines cannot be found later", "Losing the link between an asset and its scene, take or metadata", "Delivering the wrong version of a dialogue asset because versions were not tracked"], "scenario_contexts": ["Tracking every recorded line of a scene through editing and the final mix", "Managing ADR lines as assets tied to their original production takes", "Handing off labeled dialogue assets as part of a deliverables package"]}, "5e0c0b1c-0124-4028-abbf-d1d6639fd3d5": {"definition": "The application of dynamic-range compression to dialogue, reducing the level difference between loud and soft speech so the voice stays consistently intelligible and sits steadily in the mix.", "plain_english": "Using a compressor to even out speech, so loud words don't jump out and quiet words don't get lost. It keeps the voice at a steady, easy-to-hear level.", "purpose_function": "It keeps dialogue clear and consistent under music and effects and helps meet loudness targets without constant manual level rides.", "practical_application": "The mixer sets a modest ratio and threshold on the dialogue track or bus, usually after manual levelling, to control dynamics for intelligibility.", "category": "Dialogue Processing", "related_terms": ["Compression", "Dialogue levelling", "De-essing", "Intelligibility", "Loudness", "Automation"], "common_mistakes": ["Over-compressing so the dialogue sounds flat, lifeless or pumping", "Using compression to fix level problems that manual levelling should handle first", "Setting the attack so fast that consonants lose their clarity and punch"], "scenario_contexts": ["Evening out an actor who whispers then shouts in the same scene", "Keeping narration steady under a music bed", "Controlling dialogue dynamics to hit a broadcast loudness target"]}, "28b5ae62-ef1a-4d0b-acfe-45bca52896df": {"definition": "The use of a de-esser — a frequency-selective compressor — to reduce harsh sibilant sounds (s, sh, t) in dialogue without dulling the rest of the voice.", "plain_english": "Taming the sharp 'sss' and 'shh' sounds in speech so they aren't harsh, without making the whole voice sound dull. A de-esser turns down just those hissy bits when they happen.", "purpose_function": "It controls excessive sibilance that can sound harsh or tiring, especially after EQ or compression has emphasized the high frequencies.", "practical_application": "The mixer inserts a de-esser on dialogue, tunes it to the sibilant band (roughly 4–10 kHz) and sets the threshold so only strong esses are reduced.", "category": "Dialogue Processing", "related_terms": ["De-esser", "Sibilance", "Compression", "EQ", "Dialogue editing", "Intelligibility"], "common_mistakes": ["Setting the de-esser too hard so the voice develops a lisp", "Tuning the band to the wrong frequency and dulling the whole voice", "De-essing to fix a problem that a different mic or EQ choice should address"], "scenario_contexts": ["Softening harsh esses on a bright, sibilant narrator", "Cleaning up sibilance added by high-frequency EQ boosts", "Controlling a close-miked actor whose s sounds spit in the mix"]}, "fe9e60b3-a5c1-49f2-8d51-5201c70c95b3": {"definition": "The perceived front-to-back distance or spatial perspective of a voice in a scene, created through level, reverb, EQ and perspective cues so that dialogue matches the character's distance and the room shown on screen.", "plain_english": "How close or far a voice sounds in a scene. Mixers use volume, echo and tone to make speech feel near the camera or far away, matching what we see.", "purpose_function": "It matches dialogue perspective to the picture so voices feel like they truly belong in the on-screen space.", "practical_application": "The mixer matches mic perspective and adds reverb, EQ and level so a character across a room sounds farther than one in close-up.", "category": "Dialogue Mixing", "related_terms": ["Perspective", "Reverb", "Room tone", "Dialogue editing", "Panning", "Ambience"], "common_mistakes": ["Keeping every line close and dry regardless of how far the character is on screen", "Adding so much reverb for depth that dialogue loses clarity", "Mismatching perspective between production sound and ADR in the same scene"], "scenario_contexts": ["Making a character speaking across a large hall sound distant", "Matching an ADR line to the room perspective of production dialogue", "Pulling a voice forward for a close-up and pushing it back on a wide shot"]}, "fbebf045-6247-42ed-be2a-536fa9a068d8": {"definition": "The process of reducing or removing unwanted room reverberation and reflections from recorded dialogue, typically using spectral or algorithmic dereverb processing, to improve clarity and intelligibility.", "plain_english": "This means taking the echoey room sound out of recorded speech. It makes a voice sound clear and close, as if it were captured in a quiet booth instead of a big empty room.", "purpose_function": "It exists to rescue location dialogue recorded in echoey spaces so it cuts through the mix and matches quieter studio or ADR lines.", "practical_application": "A dialogue editor runs a dereverb plug-in such as iZotope RX De-reverb on a scene shot in a hard-walled room, dialing in reduction until the voice is clear without sounding hollow.", "category": "Dialogue Processing", "related_terms": ["Dialogue equalization", "Dialogue mixing", "Dialogue expansion", "Room tone", "ADR"], "common_mistakes": ["Over-processing until the voice sounds hollow, robotic, or underwater", "Expecting dereverb to fully replace a bad recording rather than reduce reverb", "Applying one static setting across a scene instead of adjusting per line", "Confusing dereverberation with noise reduction, which targets a different problem"], "scenario_contexts": ["Cleaning up dialogue shot in an empty tiled bathroom or stairwell", "Matching a reverberant wide-shot take to a tighter close-up take", "Preparing echoey location dialogue to sit alongside dry ADR lines"]}, "8eb4cd30-ffba-4794-bbfc-4f8c10c85971": {"definition": "A mix control that spreads center-panned dialogue partly into the left and right channels, so a signal placed in the center is also reproduced by the adjacent speakers rather than solely by the center channel.", "plain_english": "Normally movie dialogue comes only from the middle speaker. Divergence lets some of that voice also play from the left and right speakers, so it feels wider and does not vanish if you sit off to one side.", "purpose_function": "It exists to keep center dialogue audible and stable across a wide seating area and to blend the voice into the front sound field instead of pinning it to one speaker.", "practical_application": "A re-recording mixer adds a small amount of divergence to spread dialogue across the front three channels, or uses it so a phantom center still works when the center speaker is weak.", "category": "Dialogue Mixing", "related_terms": ["Dialogue localization", "Dialogue mixing", "Center channel", "Panning", "Downmix"], "common_mistakes": ["Adding too much divergence, which smears the dialogue image and weakens its anchor to the screen", "Assuming divergence and ordinary panning do the same thing", "Forgetting how divergence interacts with downmix and phantom-center behavior"], "scenario_contexts": ["Spreading dialogue across left, center, and right for a wide theatrical seating area", "Keeping dialogue feeling centered when a center speaker is small or absent", "Blending narration into the front field in a surround mix"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"04c7719c-9e71-4f1c-9efc-10c44e2cc0cf": {"definition": "The deliberate addition of discrete delay repeats to a dialogue line as a creative effect, used to signal a memory, dream, hallucination, large space, or supernatural quality rather than to correct a recording.", "plain_english": "This is adding repeats to a character's voice on purpose, so the words bounce back like a shout in a canyon. It is used for dreams, memories, or spooky moments, not to fix a bad recording.", "purpose_function": "It exists as a storytelling tool to mark that a voice is inside a character's head, in a huge space, or otherworldly.", "practical_application": "A mixer sends a flashback line to a delay plug-in and blends in timed repeats, often filtered, so the words echo without becoming impossible to understand.", "category": "Dialogue Processing", "related_terms": ["Dialogue mixing", "Dialogue futzing", "Dialogue equalization", "Delay", "Reverb"], "common_mistakes": ["Setting the echo so loud or long that the words become impossible to understand", "Using a raw delay with no filtering, so the effect sounds cheap", "Overusing the effect until it loses its dramatic impact"], "scenario_contexts": ["A dream or flashback sequence", "A god-like or ghostly voice", "A memory replaying a past line of dialogue"]}, "158bd326-2af1-4e4b-919a-15c2b64af302": {"definition": "The application of equalization to dialogue tracks to shape their tonal balance, reducing problem frequencies such as low-end rumble, proximity boom, sibilance, or boxiness and adding presence, so lines are clear, consistent, and intelligible.", "plain_english": "This is adjusting the tone of recorded speech by turning some pitch ranges up and others down. It removes booming or harsh sounds and adds clarity, like tuning the bass and treble so a voice is easy to understand.", "purpose_function": "It exists to make dialogue intelligible and tonally even from shot to shot, and to help voices cut through music and effects without becoming harsh.", "practical_application": "A dialogue mixer high-passes rumble, dips a boxy low-mid, and adds a gentle presence lift so a boomy location line matches the rest of the scene.", "category": "Dialogue Processing", "related_terms": ["Dialogue mixing", "Dialogue dereverberation", "Dialogue limiting", "High-pass filter", "De-essing"], "common_mistakes": ["Boosting instead of cutting, causing a harsh or unnatural tone", "Not high-passing low-frequency rumble and handling noise", "Applying one EQ across a whole scene instead of matching shot to shot", "Over-brightening until sibilance turns harsh"], "scenario_contexts": ["Removing proximity boom from a close boom take", "Matching the tone of a lav mic to a boom mic on the same line", "Helping dialogue sit clearly over a loud music cue"]}, "02e9e84f-72a2-4490-b295-a24ffcb90922": {"definition": "The use of downward expansion or gating on dialogue to reduce the level of background noise, room tone, and bleed during pauses between words or lines, lowering signal below a threshold while leaving speech largely untouched.", "plain_english": "This quietly turns down the gaps between spoken words, where only background noise sits. The voice stays full, but hiss and room noise drop when nobody is talking, like muting the mic between lines.", "purpose_function": "It exists to clean up the spaces around dialogue so noise does not pile up when many tracks play together, without dulling the speech itself.", "practical_application": "An editor sets an expander threshold just below the quietest words so background hiss drops in the pauses, then checks that word beginnings and endings are not chopped off.", "category": "Dialogue Processing", "related_terms": ["Dialogue dereverberation", "Dialogue mixing", "Room tone", "Noise gate", "Noise reduction"], "common_mistakes": ["Setting the threshold too high, which clips off soft word starts and endings", "Using heavy expansion instead of proper noise reduction, causing pumping", "Forgetting that abrupt gating makes room tone jump on and off unnaturally"], "scenario_contexts": ["Reducing air-conditioning hiss between lines of dialogue", "Cleaning bleed on a multi-mic dialogue scene", "Tightening noisy lav-mic tracks before the final mix"]}, "d384c5e7-ef0f-4b20-87fa-1ac8ace98d27": {"definition": "The intentional processing of dialogue to sound as though it is reproduced through a limited-fidelity device such as a telephone, radio, television, intercom, or PA, typically by band-limiting the frequency response and adding distortion or noise to match the source shown on screen.", "plain_english": "Futzing means making a voice sound like it comes out of a phone, radio, or TV. You cut the deep and high tones and add a little grit, so it matches the small speaker the audience sees on screen.", "purpose_function": "It exists to make off-screen or device-sourced voices believable, so a phone or radio voice truly seems to come from that device.", "practical_application": "A mixer band-passes a line, adds slight distortion and maybe a codec or noise layer, and automates it so the futz starts exactly when a character raises a phone to their ear.", "category": "Dialogue Processing", "related_terms": ["Dialogue equalization", "Dialogue mixing", "Dialogue echo effect", "Band-pass filter", "Distortion"], "common_mistakes": ["Making the futz so extreme that the words become impossible to understand", "Failing to match the futz to the on-screen device, such as a tiny phone versus a large PA", "Not automating the effect so it starts and stops with the picture", "Leaving the futzed line as wide and full as normal dialogue"], "scenario_contexts": ["A phone call heard from only one character's side", "A voice over a two-way radio or intercom", "A news anchor heard from a TV in the background"]}, "4f898b3c-ed86-42a0-adc4-8dfaa373a13f": {"definition": "The application of a limiter to dialogue to cap short-term peaks and control dynamic range, preventing overloads and keeping levels consistent so speech stays within target loudness and does not clip or jump out of the mix.", "plain_english": "A limiter puts a ceiling on how loud the voice can get. It catches sudden loud words so nothing overloads, keeping speech steady and even, like a safety lid that stops peaks from spilling over.", "purpose_function": "It exists to guard against clipping and to keep dialogue level even, so quiet and loud lines both sit within the loudness targets required for delivery.", "practical_application": "A mixer places a limiter on the dialogue bus to catch stray peaks after compression, setting the ceiling below full scale so the stem stays clean and meets delivery loudness specs.", "category": "Dialogue Processing", "related_terms": ["Dialogue mixing", "Dialogue equalization", "Compression", "Loudness normalization", "True peak"], "common_mistakes": ["Over-limiting until dialogue sounds squashed and lifeless", "Using a limiter to do the job of gain riding or compression", "Watching only peaks while ignoring loudness delivery standards", "UNSAFE: monitoring at excessive SPL for long sessions to judge peaks, risking noise-induced hearing loss; observe OSHA exposure limits"], "scenario_contexts": ["Catching plosive peaks before the dialogue stem", "Meeting a broadcast or streaming loudness and true-peak spec", "Keeping dialogue from clipping during a loud emotional line"]}, "0890c3d8-570e-45e2-83f0-6373622654e5": {"definition": "The placement of dialogue at a specific perceived position within the stereo or surround sound field, using panning, level, and channel routing so a voice appears to come from the direction of its on-screen source.", "plain_english": "This means making a voice seem to come from the right spot on the screen. If a character stands on the left, the sound is placed so your ears point that way, matching what your eyes see.", "purpose_function": "It exists to tie voices to their on-screen sources and hold the audience's attention on the picture, though most lead dialogue is localized to the center for stability.", "practical_application": "A mixer usually keeps lead dialogue in the center channel but may nudge off-screen or background voices toward their positions when it strengthens the scene without distracting the listener.", "category": "Dialogue Mixing", "related_terms": ["Dialogue divergence", "Dialogue mixing", "Center channel", "Panning", "Surround sound"], "common_mistakes": ["Hard-panning main dialogue to screen position, which distracts and breaks on downmix", "Assuming stereo panning translates the same in a theater as on headphones", "Ignoring that most narrative dialogue belongs in a stable center image"], "scenario_contexts": ["Deciding whether an off-screen voice should be panned to its side", "Keeping lead dialogue centered while placing background voices", "Matching a moving character's voice to their position across the frame"]}, "49bfd4cc-43f7-4449-b695-3889ddc48a11": {"definition": "The stage of post-production in which all dialogue elements, including production sound, ADR, and loop group, are balanced, processed, and combined into a coherent, intelligible dialogue stem that sits correctly against music and effects.", "plain_english": "This is the step where all the spoken lines are balanced and cleaned into one smooth track. The goal is to make every word clear and even, so you never struggle to hear the characters over the music and effects.", "purpose_function": "It exists to make speech consistently clear and intelligible, since dialogue carries the story and must be understood over everything else in the mix.", "practical_application": "A dialogue mixer edits, EQs, de-noises, compresses, and rides the level of each line, matching ADR to production sound and delivering a dialogue stem for the final re-recording mix.", "category": "Dialogue Mixing", "related_terms": ["Dialogue equalization", "Dialogue limiting", "Dialogue dereverberation", "ADR", "Re-recording mixing"], "common_mistakes": ["Mixing dialogue too low so it gets buried under music and effects", "Failing to match ADR tone and level to the original production sound", "Skipping cleanup so noise and inconsistency carry into the final mix", "Judging levels without checking delivery loudness targets"], "scenario_contexts": ["Balancing production dialogue with ADR replacements in a scene", "Building the dialogue stem for a film or episode", "Keeping dialogue intelligible under a busy action sequence"]}, "f01d37de-c2b3-4fbe-b182-3f680c1a805f": {"definition": "The process of removing or attenuating unwanted background sounds—such as hiss, hum, HVAC rumble, set noise, and clicks—from recorded dialogue while preserving the natural quality of the voice. It is typically performed with dedicated restoration tools using broadband and narrowband noise profiles, spectral repair, and de-clicking.", "plain_english": "This means cleaning up recorded speech by taking out background sounds like hiss, hum, or air-conditioner noise. It works a bit like using an eraser to wipe away the noise so the voice still sounds clear and natural.", "purpose_function": "It exists to make production dialogue clean and intelligible so it sits well against music and effects, and so location recordings match cleaner ADR or studio takes. Reducing noise early prevents that noise from being amplified later by EQ and compression in the mix.", "practical_application": "A dialogue editor learns a noise print from a quiet section of a clip and applies broadband reduction, spectral de-noise, and de-hum, working conservatively to avoid audible artifacts on the voice.", "category": "Dialogue Editing", "related_terms": ["Dialogue room-tone matching", "Spectral repair", "De-esser", "ADR", "Broadband noise reduction"], "common_mistakes": ["Applying too much reduction, which leaves the voice sounding hollow, watery, or robotic with audible artifacts", "Learning the noise profile from a section that already contains speech, which makes the tool remove parts of the voice", "Reducing noise on every clip to a different floor so cuts no longer match, instead of aiming for a consistent background level"], "scenario_contexts": ["Removing constant air-conditioning rumble from a location interview before the mix", "Cleaning a lav-mic take of clothing rustle and handling noise", "Reducing camera or generator hum picked up on set dialogue"]}, "ab7500be-47d3-4203-a5ab-013ad0d22c29": {"definition": "The placement of recorded dialogue within the stereo or surround sound field. In film and television mixing, principal dialogue is conventionally anchored to the center channel to keep it locked to the screen and intelligible, though it may be panned off-center to follow an on-screen or off-screen speaker's position.", "plain_english": "This is choosing where a voice sits between the speakers. In movies the main talking is usually kept in the center speaker so it stays tied to the picture and easy to understand.", "purpose_function": "It positions voices so they seem to come from the right place relative to the picture and stay clear against music and effects. Anchoring dialogue to the center channel keeps it stable even when audience members sit off to one side of the room.", "practical_application": "A re-recording mixer routes principal dialogue to the center channel by default and only pans it off-center for a clear reason, such as an off-screen line or a stylized moment.", "category": "Dialogue Mixing", "related_terms": ["Dialogue perspective", "Center channel", "Surround panning", "Re-recording mixer", "Dialogue spread"], "common_mistakes": ["Hard-panning on-screen dialogue away from center, which pulls the voice off the screen and distracts the audience", "Forgetting that dialogue placed off-center can shift or collapse in a stereo or mono downmix"], "scenario_contexts": ["Anchoring principal dialogue to the center channel in a 5.1 theatrical mix", "Panning an off-screen character's line toward the side they will enter from"]}, "8ba7f9bd-4e6d-4470-aab6-26a36eddf7d3": {"definition": "The matching of a voice's level, tonal balance, and reverberation to the apparent distance and position of the speaker within the frame, so the sound agrees with the picture. A wide or distant shot is given a more distant, roomier sound than a close-up of the same line.", "plain_english": "This means making a voice sound near or far to match how close the person looks on screen. A person far away in a wide shot should sound a little quieter and more echoey than the same person in a close-up.", "purpose_function": "It exists to keep sound and picture believable, so the audience feels the voice comes from where the character actually is. Consistent perspective helps the scene feel real without the viewer noticing the sound work.", "practical_application": "A dialogue editor or mixer adjusts level, EQ, and added reverb shot by shot so a line recorded on one mic still feels close in a close-up and more distant in a wide shot.", "category": "Dialogue Mixing", "related_terms": ["Dialogue reverb", "Dialogue panning", "Dialogue presence", "ADR", "Worldizing"], "common_mistakes": ["Leaving every line equally close and dry, so distant characters still sound like they are right on the microphone", "Overdoing distance so on-screen dialogue becomes too roomy and hard to understand", "Ignoring perspective changes between angles, so the voice jumps in closeness at each cut"], "scenario_contexts": ["Making a character's voice recede as the camera pulls back to a wide shot", "Matching ADR perspective to the original location shot", "Giving an off-screen voice from another room a more distant, filtered sound"]}, "39817250-feba-405e-801d-e4b4b046b6f8": {"definition": "The perceived immediacy, clarity, and intimacy of a voice that makes it feel close and forward in the mix. It is commonly enhanced by lifting the presence frequency region (roughly 2–5 kHz) and controlling low-mid buildup, so the voice cuts through effects and music.", "plain_english": "This is how close, clear, and up-front a voice feels to the listener. Adding presence is like bringing the speaker a step nearer so their words stand out over the music and background.", "purpose_function": "It exists to keep dialogue intelligible and engaging so the audience follows the story without straining. Good presence lets a voice sit on top of a busy mix without simply turning it up louder.", "practical_application": "A mixer gently boosts the upper-midrange presence band and trims muddiness so a voice feels intimate and clear, checking it against music and effects rather than in isolation.", "category": "Dialogue Mixing", "related_terms": ["Dialogue perspective", "Presence (EQ)", "Intelligibility", "De-esser", "Dialogue resonance control"], "common_mistakes": ["Boosting the presence range too hard, which makes the voice harsh and exaggerates sibilance", "Chasing presence with EQ when the real problem is background noise or a distant, roomy recording", "Judging presence on the solo'd voice instead of within the full mix"], "scenario_contexts": ["Bringing a soft-spoken lead forward so it stays clear over a music cue", "Adding presence to a distant boom take to make it feel more intimate", "Matching the presence of ADR to nearby production dialogue"]}, "f441d391-a465-44db-9ccf-ec4b80971987": {"definition": "The reduction of unwanted resonant peaks in recorded dialogue—such as low-mid boominess from proximity effect or room modes, chesty buildup, or nasal and honky midrange ringing—usually with narrow subtractive EQ or dynamic EQ that acts only when the offending frequency spikes.", "plain_english": "This means taming certain frequencies that ring out or boom in a voice and make it sound boxy or muddy. It is like turning down just the one note that keeps buzzing, without changing the rest of the voice.", "purpose_function": "It exists to make dialogue sound even and natural so no single frequency jumps out or masks the words. Controlling resonances also keeps later processing like compression from grabbing onto a booming or ringing tone.", "practical_application": "A mixer sweeps a narrow EQ band to find a boom or honk in a voice, then cuts it—often with dynamic EQ so the cut only engages when that frequency rings out.", "category": "Dialogue Mixing", "related_terms": ["Dynamic EQ", "Proximity effect", "Dialogue presence", "De-esser", "Room modes"], "common_mistakes": ["Using wide, deep cuts that fix one boom but hollow out the whole voice", "Treating natural voice character as a problem and EQing until the voice sounds thin and unnatural", "Applying a fixed cut for a resonance that only appears on loud words, where dynamic EQ would be cleaner"], "scenario_contexts": ["Removing low-mid boom from a lav mic worn under clothing", "Taming a boxy room resonance on dialogue shot in a small hard-walled set", "Reducing a nasal honk on a specific actor's close-mic delivery"]}, "768c377f-f0bb-485c-b3c2-1a6ad83bb0e1": {"definition": "Reverberation added to dialogue to place the voice believably in the acoustic space of the scene and to blend edits and ADR with production sound. The reverb type, decay, and pre-delay are matched to the size and surfaces of the depicted room.", "plain_english": "This is adding a sense of room echo to a voice so it sounds like it belongs in the space on screen. A voice in a big stone hall gets long echo, while a small carpeted room gets almost none.", "purpose_function": "It exists to make dialogue sit in the scene's space and to help re-recorded or cleaned-up lines match the natural room sound of the location. Matched reverb hides edits so replaced words and ADR are not noticeable.", "practical_application": "A mixer sends dialogue to a reverb tuned to the on-screen space—short and tight for a small room, longer for a large hall—and matches ADR reverb to the surrounding production dialogue.", "category": "Dialogue Mixing", "related_terms": ["Dialogue perspective", "ADR", "Worldizing", "Pre-delay", "Dialogue slap delay"], "common_mistakes": ["Adding so much reverb that the dialogue loses clarity and intelligibility", "Using a reverb that does not match the on-screen space, so the voice feels detached from the picture", "Reverbing the center dialogue without matching it to the room tone and effects, breaking the illusion"], "scenario_contexts": ["Placing a dry ADR line into the reverberant space of a church scene", "Matching cleaned-up dialogue to the natural room sound of a location", "Giving an off-screen shouted line the long decay of a large warehouse"]}, "42224098-ad28-41bc-a7f0-865201e66cfa": {"definition": "The use of room tone—the ambient background sound of a location recorded with no dialogue—to fill silent gaps, smooth edit points, and blend ADR or noise-reduced sections so the background stays continuous and cuts are inaudible.", "plain_english": "Room tone is the quiet background hum of a place with no one talking. Matching it means filling gaps and edits with that same background so the sound never drops out or jumps when the dialogue is cut.", "purpose_function": "It exists to keep the background even under dialogue so edits, silences, and replaced lines do not stand out as sudden changes in the ambient level. A continuous bed of matched tone makes cut-together takes sound like one seamless recording.", "practical_application": "A dialogue editor lays matching room tone under gaps, hard edits, and ADR, filling any spot where the original background drops out so the mix has an unbroken ambient floor.", "category": "Dialogue Editing", "related_terms": ["Dialogue noise reduction", "ADR", "Ambience", "Fill", "Crossfade"], "common_mistakes": ["Leaving a dead-silent gap after an edit or noise reduction, so the background audibly drops out", "Using room tone from a different location or take, so the fill does not match the surrounding sound", "Butting room tone in without crossfades, creating clicks or audible seams at the joins"], "scenario_contexts": ["Filling the silence under an ADR line so it matches the location background", "Smoothing the point where a noisy section was cleaned to a lower noise floor", "Bridging a gap left after removing an unwanted off-camera sound"]}, "cc1d5a34-b328-4fa3-9f8a-3c482211f3bc": {"definition": "A single short, discrete echo (slapback) applied to dialogue, typically in the range of tens of milliseconds up to around a hundred milliseconds, used to suggest a hard reflective space or as a stylized effect. Unlike reverb, it produces one distinct repeat rather than a dense decaying tail.", "plain_english": "This is one quick echo added to a voice, like a single bounce off a far wall. It is used to make speech sound like it is in a big hard room, or as a special effect such as a loudspeaker announcement.", "purpose_function": "It exists to imply a large hard-surfaced space or to create a stylized voice effect without the wash of full reverb. A single clean repeat can suggest scale or otherworldliness while keeping the words readable.", "practical_application": "A mixer sets a delay to a short single repeat and blends a little of it under the dialogue to evoke a cavern, arena announcement, or dream-like voice, timing it so it does not blur the words.", "category": "Dialogue Mixing", "related_terms": ["Dialogue reverb", "Pre-delay", "Slapback", "Dialogue perspective", "Worldizing"], "common_mistakes": ["Setting the delay time too long, so the echo doubles the words and hurts intelligibility", "Mixing the slap too loud, which makes it a distracting effect instead of a subtle sense of space", "Using slap delay where matched natural reverb would sit more convincingly in the scene"], "scenario_contexts": ["Suggesting a large cave or empty warehouse under a shouted line", "Creating a stylized public-address or announcement voice", "Adding an eerie single repeat to a dream or flashback voice"]}, "461226b9-1372-483f-89c7-c3d818170f0e": {"definition": "The widening of dialogue beyond a single point so it occupies more of the front stereo or surround field, achieved with techniques such as adding decorrelated left/right content or stereo processing. Because dialogue is normally kept mono and centered, spread is used sparingly for specific creative effects or crowd and off-screen textures.", "plain_english": "This means making a voice feel wider across the speakers instead of coming from one point. Voices are usually kept in the center, so spreading them out is only done now and then for a special effect, like a huge or ghostly voice.", "purpose_function": "It exists to give a voice size or an unnatural, enveloping quality for stylized moments, or to broaden layered crowd and background voices. Used carefully, it adds width without pulling important dialogue away from the screen.", "practical_application": "A mixer applies stereo widening or decorrelation to a voice for a godlike, dreamlike, or crowd effect, then checks the result in mono to make sure the words do not thin out or cancel.", "category": "Dialogue Mixing", "related_terms": ["Dialogue panning", "Center channel", "Decorrelation", "Surround panning", "Dialogue reverb"], "common_mistakes": ["Spreading principal on-screen dialogue, which pulls the voice off the screen and weakens intelligibility", "Widening with techniques that cancel in mono, so the voice loses level or vanishes in a mono downmix", "Overusing spread as a default width instead of reserving it for deliberate effects"], "scenario_contexts": ["Widening a supernatural or godlike voice for scale", "Spreading layered crowd or background voices across the front field", "Creating a disorienting, enveloping voice for a dream sequence"]}, "5e51ac3c-3eff-4d45-8b90-0299259440c0": {"definition": "A sound source that radiates energy unevenly with direction, projecting more strongly along a principal axis than to the sides or rear. In immersive and game audio it is an audio object or virtual source given a directivity pattern such as a cone, so its level and tone depend on how it is oriented toward the listener; in acoustics the term describes any loudspeaker or source with pronounced directivity.", "plain_english": "This is a sound source that is louder in the way it points, like a beam of sound. Turn it away from you and it gets quieter and duller.", "purpose_function": "It exists to make virtual and real sources behave like real objects, which are usually louder when they face you. Giving an emitter a direction adds realism and helps aim and place sound in a scene.", "practical_application": "A sound designer sets an emitter's facing and cone width in a game engine or object renderer so a character's voice or a speaker prop sounds right as it turns toward or away from the listener.", "category": "Spatial Audio", "related_terms": ["Distance attenuation", "Distance parameter", "Audio object", "Panning", "Omnidirectional source", "Sound propagation"], "common_mistakes": ["Treating every emitter as omnidirectional, so a source sounds the same no matter which way it faces", "Setting the directivity cone too narrow, so the sound cuts out abruptly as the source turns", "Confusing a directional emitter with a directional microphone; one radiates sound, the other picks it up"], "scenario_contexts": ["Placing a character's voice as a directional emitter in a VR scene so it dims when they turn away", "Simulating a loudspeaker prop that is loud in front and muffled behind", "Aiming a vehicle's engine emitter so its tone changes as the car passes the listener"]}, "e8ff80d8-8b25-405c-92f1-f898b97cc9b7": {"definition": "A Foley footstep performance and its recording made on a dirt or earthen surface, capturing the soft, gritty, slightly crunchy impacts of feet on loose ground. It is one of a library of surface-specific footstep types Foley artists create to match a character's shoes and the terrain shown on screen.", "plain_english": "These are footstep sounds made by walking on dirt, so they sound soft and a little crunchy. A Foley artist records them to match a character walking on bare ground on screen.", "purpose_function": "They exist to give on-screen walking on dirt a believable, matched sound when the location recording is unusable or missing. Surface-matched steps help sell where a character is and how they move.", "practical_application": "A Foley artist steps in a dirt pit or tray in sync with the picture, choosing shoes and effort that match the actor, and the editor then trims and locks the takes to the frame.", "category": "Foley", "related_terms": ["Foley", "Foley pit", "Footsteps", "Surface sounds", "Ambience", "Spotting session"], "common_mistakes": ["Using the same footstep surface for every scene, so dirt, wood, and tile all sound alike", "Performing steps out of sync with the actor's feet on screen", "Recording dirt steps too cleanly or too loud, so they feel bigger than the character's real weight and pace"], "scenario_contexts": ["Adding footsteps for a character crossing a dry field where the location sound was too noisy", "Matching a Western character's boots walking down a dusty street", "Replacing footsteps lost under dialogue in an outdoor scene"]}, "b76bc618-261a-481e-8fab-e43fcbbcbdd0": {"definition": "The decrease in sound pressure level as distance from a source increases. For a point source in a free field the level falls by about 6 dB for each doubling of distance (the inverse-square law); in post production it is also modeled by panners and object renderers so that sources seem nearer or farther.", "plain_english": "This means a sound gets quieter the farther away it is. In open air, moving twice as far from a source drops its loudness by about 6 dB, which is a clearly noticeable step down.", "purpose_function": "It exists as a basic rule of how sound behaves, letting mixers and tools make sources feel close or distant. Modeling it keeps sound believable and matched to how far away things look on screen.", "practical_application": "A mixer or sound designer lowers level, and usually adds high-frequency loss and reverb, as a source moves away, or sets a renderer's distance model so an object fades naturally with range.", "category": "Acoustics", "related_terms": ["Inverse-square law", "Distance parameter", "Sound pressure level", "Free field", "Perspective", "Air absorption"], "common_mistakes": ["Assuming level always drops 6 dB per doubling; reflections in an enclosed room make the real falloff gentler", "Changing only level for distance and forgetting the high-frequency dulling and added room sound of a far source", "Confusing distance attenuation with air absorption, which mainly cuts high frequencies over long distances"], "scenario_contexts": ["Setting how quickly a passing car quiets as it moves away", "Matching a shouted line's level to a character standing far from camera", "Tuning an object renderer's distance curve so a helicopter fades in from the horizon"]}, "716d3a04-30e9-4fce-b67f-94c8eb7090c6": {"definition": "A control in a panner, spatial-audio object, or game-audio emitter that sets the perceived distance of a source from the listener. Adjusting it scales cues such as level, high-frequency roll-off, direct-to-reverberant ratio, and stereo width so the source is placed nearer or farther.", "plain_english": "This is a setting that tells the software how far away a sound should seem. Turn it up and the sound gets quieter, duller, and more echoey, as if it moved away.", "purpose_function": "It exists so a mixer can move a sound in depth with one control instead of adjusting several by hand. It ties the distance cues together so a source shifts nearer or farther in a natural, consistent way.", "practical_application": "A designer automates an object's distance parameter so a car pulls away, letting the renderer handle the matching drop in level, brightness, and added reverb.", "category": "Spatial Audio", "related_terms": ["Distance attenuation", "Audio object", "Panning", "Direct-to-reverberant ratio", "Perspective", "Object renderer"], "common_mistakes": ["Assuming the distance parameter only changes volume, when it usually also affects tone and reverb", "Pushing distance to an extreme so a source becomes too dull and washed out to read", "Expecting the same distance setting to sound identical across different renderers or panners"], "scenario_contexts": ["Automating a source's distance so it recedes with a camera pull-back", "Placing a background voice deep in a room with an object panner", "Fading a sound effect into the distance in a game engine"]}, "0b5600fa-f1fc-4f98-b176-d19678c0531c": {"definition": "A vocal or Foley performance deliberately delivered to convey that its source is far from the camera or listener, by projecting or calling out, backing away from the microphone, or adjusting effort and articulation so the recording matches a distant on-screen perspective. It is common in ADR and loop-group work, where near, medium, and distant takes are captured for a line.", "plain_english": "This is performing a line or sound so it feels like it comes from far away. The actor might call out, step back from the mic, or push their voice to match a character who is across the room or down the street.", "purpose_function": "It exists so distant characters and actions sound like they are really far off, not recorded up close. Capturing the right effort and delivery is more convincing than only turning a close take down in level.", "practical_application": "In an ADR or loop-group session the supervisor asks talent for near, medium, and distant versions of a line, and the mixer positions the performer or mic so the distant take already has the right effort and room sound.", "category": "ADR", "related_terms": ["ADR", "Loop group", "Dialogue perspective", "Off-mic", "Mic distance", "Worldizing"], "common_mistakes": ["Recording every line close and flat, then trying to fake distance later with only a volume cut", "Having talent shout for distance but staying right on the mic, so the effort and closeness disagree", "Ignoring the added room sound a truly distant source would have"], "scenario_contexts": ["Recording a character shouting from across a valley in ADR", "Capturing loop-group calls meant to sit far in the background of a crowd", "Getting a distant, off-screen version of a line to match a wide shot"]}, "a45df0d5-5cf4-41ac-a9b4-032d72d98c2d": {"definition": "The sustained, often pitched squeal or groan produced by a door's hinges as it slowly opens or closes, caused by friction in the hinge. As a sound effect it is recorded or performed and then stretched, trimmed, and pitched to match the speed and length of a door move on screen, and is frequently exaggerated for suspense.", "plain_english": "This is the long squeaky groan a door makes when its hinges rub as it swings. In films it is often made louder and creepier to build tension.", "purpose_function": "It exists to give an opening or closing door a believable, expressive sound and, in drama or horror, to build mood and suspense. Matching the creak to the on-screen motion sells the action.", "practical_application": "A Foley artist or editor performs or picks a creak, then stretches, trims, and pitches it so its length and movement follow the door on screen.", "category": "Foley", "related_terms": ["Foley", "Door slam", "Door latch", "Hard effects", "Sound library", "Spotting session"], "common_mistakes": ["Using a creak whose length or speed does not match the door's movement on screen", "Reaching for the same stock creak so different doors all sound identical", "Making every door creak, even ones a scene implies are well-oiled and quiet"], "scenario_contexts": ["Adding a slow, eerie creak to a door opening in a horror scene", "Matching a short creak to a character easing a door shut quietly", "Building a haunted-house feel from layered door and floor creaks"]}, "127a5ee4-9e06-416a-8223-df9b9203c149": {"definition": "The sound of a door's handle, knob, or lever being grasped and turned, including the mechanical movement of the latch it operates, without the door itself opening or slamming. As a Foley element it is performed on a real handle or matching prop to follow a character reaching for or working a door.", "plain_english": "This is the small rattly, clicky sound of someone grabbing and turning a door handle or knob. It is the noise the handle makes before the door actually opens.", "purpose_function": "It exists to add the small, realistic detail of a character operating a door, which helps sell the action and the character's intent. These little sounds make a scene feel physical and real.", "practical_application": "A Foley artist works a matching handle or knob in sync with the actor's hand, capturing the grab, turn, and mechanism so the editor can place it exactly on the picture.", "category": "Foley", "related_terms": ["Foley", "Door latch", "Door creak", "Door slam", "Foley props", "Footsteps"], "common_mistakes": ["Performing the handle sound out of sync with the actor's hand on screen", "Using a handle or latch that sounds nothing like the door shown", "Making the movement too loud or busy, so a small action sounds exaggerated"], "scenario_contexts": ["Adding the turn of a knob as a character quietly enters a room", "Building tension as someone slowly works a locked door's handle", "Covering the small handle sounds lost while dialogue was being recorded"]}, "1161873d-8eae-4904-adc4-03f7e259d08a": {"definition": "The short, sharp click of a door's latch bolt engaging or releasing in the strike plate as the door is closed or opened, distinct from the louder impact of a slam. As a sound effect it marks the exact moment a door catches shut or is unlatched.", "plain_english": "This is the small click a door makes when it catches shut or is opened. It is the neat little click of the catch, not the bang of a slam.", "purpose_function": "It exists to mark, with a small precise sound, that a door has securely closed or been released. That click gives a closing door a finished, believable ending and can signal privacy or intent in a scene.", "practical_application": "A Foley artist or editor places a latch click at the exact frame the door meets the frame, choosing a click that matches the door's size and hardware.", "category": "Foley", "related_terms": ["Foley", "Door slam", "Door creak", "Door handle movement", "Hard effects", "Sync"], "common_mistakes": ["Placing the latch click a few frames off from where the door actually catches", "Using a heavy latch on a light door or the reverse, so the sound does not match", "Forgetting the latch entirely, so a door closes with no sense of it catching shut"], "scenario_contexts": ["Adding a soft latch as a character eases a door shut without waking anyone", "Marking the click of a door being quietly unlatched", "Finishing a gentle door close where a full slam would be too much"]}, "ab41de99-36a7-4902-9498-a05232d56926": {"definition": "The loud, percussive impact of a door being forcefully shut, combining the low thud of the door hitting the frame, the latch, and often a rattle of the door and hardware. It is a common hard effect used both realistically and dramatically, and is frequently sweetened for emphasis.", "plain_english": "This is the loud bang of a door being shut hard. It mixes the deep thud of the door hitting the frame with the click of the latch and a bit of rattle.", "purpose_function": "It exists to give a forcefully closed door a strong, believable impact and, in drama, to punctuate a moment such as anger or a scene ending. A well-placed slam adds weight and emotion.", "practical_application": "A Foley artist slams a matching door in sync with the picture, or an editor places and layers a library slam, adjusting weight and low end so it fits the door and the moment.", "category": "Foley", "related_terms": ["Foley", "Door latch", "Door creak", "Hard effects", "Sweetening", "Layering"], "common_mistakes": ["Using an oversized, boomy slam on a light door, so the impact sounds fake", "Placing the slam a frame or two off from where the door hits, so sound and picture disagree", "Layering so many slam elements that it turns into a mushy, unrealistic bang"], "scenario_contexts": ["Punctuating an argument as a character storms out and slams the door", "Matching a car door thud to a character getting in and shutting it", "Adding weight to a heavy vault or steel door closing"]}, "68d862eb-c7a7-49c9-bbf8-a75e5551c930": {"definition": "The recreation in post-production of the Doppler effect — the apparent rise and then fall in a sound's pitch as its source moves toward and then past the listener — using pitch, level, filtering, and panning automation, or a dedicated plug-in, to sell the motion of an object such as a passing vehicle or aircraft.", "plain_english": "It is a trick that makes a sound seem to rush past you. When a car races toward you, its sound seems higher. Once it passes, the sound drops lower. Editors copy that pitch change so a sound moves past you on screen.", "purpose_function": "It adds a convincing sense of speed and motion to moving-source effects, matching what audiences expect from real passing objects and reinforcing the on-screen action.", "practical_application": "A sound editor applies a Doppler plug-in or automates pitch, level, filtering, and pan across a fly-by so a plane, car, or projectile sounds like it truly travels past the camera.", "category": "Sound Design", "related_terms": ["Pitch shifting", "Panning automation", "Sound design", "Whoosh", "Automation"], "common_mistakes": ["Making the pitch rise and fall equal, when the shift is fastest right as the source passes the listener.", "Automating pitch alone without matching level and pan, so it sounds processed rather than like real motion.", "Overdoing the pitch swing so a slow-moving object sounds unnaturally fast."], "scenario_contexts": ["Designing a car or motorcycle pass-by for an exterior scene.", "Selling a jet or helicopter fly-over in an action sequence.", "Adding motion to a whoosh, arrow, or bullet as it crosses frame."]}, "ea34bb4c-285c-48ce-b8f7-7046f715b91c": {"definition": "A Foley or hard sound effect consisting of the impact and rattle of a drawer being pushed shut forcefully, recorded or edited in sync with picture to cover an on-screen action.", "plain_english": "It is the sound of a drawer being shoved shut hard. A Foley artist makes it by slamming a real drawer while watching the scene. It adds a solid thud where a character closes a drawer on screen.", "purpose_function": "It supplies the sharp, physical impact an audience expects when a drawer is shut hard, adding realism and emotional weight, such as anger, to the moment.", "practical_application": "A Foley artist performs the slam on a props stage in sync with picture, or a sound editor cuts a library recording to match the exact frame the drawer hits.", "category": "Foley", "related_terms": ["Foley", "Hard effect", "Prop effect", "Drawer slide", "Spot effect"], "common_mistakes": ["Placing the impact a frame or two off from picture, so the slam looks out of sync.", "Using one generic slam for every drawer instead of matching the size and material on screen.", "Ignoring the secondary rattle or contents shifting, which makes the effect sound flat."], "scenario_contexts": ["Covering a character angrily shutting a desk drawer.", "Building a kitchen or office scene that needs believable prop sounds.", "Replacing weak or noisy production-sound drawer closes during Foley."]}, "28d8f2c6-3b4e-4344-b04b-5b3c6c9b2922": {"definition": "A Foley or hard sound effect of a drawer being pulled open or pushed closed along its runners, capturing the sustained sliding, rolling, or scraping of the drawer in its frame, cut in sync with the on-screen action.", "plain_english": "It is the sound of a drawer sliding open or shut. A Foley artist moves a real drawer in time with the picture to make it. Unlike a slam, it is the smooth rolling sound, not the bang.", "purpose_function": "It gives the continuous movement sound of a drawer opening or closing, so the action feels real even when the production recording is missing or too quiet.", "practical_application": "A Foley artist slides a matching drawer in sync with picture, choosing a wooden, metal, or roller-bearing drawer to fit the object shown on screen.", "category": "Foley", "related_terms": ["Foley", "Drawer slam", "Hard effect", "Prop effect", "Spot effect"], "common_mistakes": ["Matching the speed of the slide poorly, so the sound ends before or after the on-screen drawer stops.", "Using a metal roller sound for a wooden drawer, which breaks the illusion.", "Forgetting the small bump or stop at the end of the travel."], "scenario_contexts": ["A character opening a desk drawer to retrieve an object.", "Detailing a bedroom or kitchen scene with furniture movement.", "Adding drawer motion under dialogue where production sound is unusable."]}, "3aa08930-4ba0-4177-b47c-301d877a1e7f": {"definition": "A composite dialogue take built by comping — selecting and joining the best portions of several dubbing or ADR takes into one seamless replacement performance fitted to picture.", "plain_english": "It is one good line built from several tries. The editor picks the best word or phrase from each take and joins them together. This gives a clean, well-matched replacement of the actor's dialogue.", "purpose_function": "It lets editors deliver the strongest possible dialogue and lip-sync by combining the best moments from many takes instead of relying on a single flawed one.", "practical_application": "An ADR or dialogue editor auditions the recorded takes for a line, then cuts the best syllables and breaths together into one comped take fitted precisely to picture.", "category": "Dubbing", "related_terms": ["ADR", "Dubbing cue", "Dubbing loop", "Dialogue editing", "Lip sync"], "common_mistakes": ["Joining takes where tone, level, or room sound differ, creating audible jumps.", "Comping for a perfect read while losing sync with the actor's lip movements.", "Not logging which takes were used, which makes later revisions hard."], "scenario_contexts": ["Building the final ADR line for a scene from several actor passes.", "Assembling foreign-language dub dialogue that must match lip movement.", "Salvaging a usable performance when no single take is clean throughout."]}, "13f2f768-3c2f-4f03-91df-887ab105e661": {"definition": "A discrete, numbered segment of dialogue marked for dubbing or ADR — a single line or short passage identified on a cue sheet with its timecode and in and out points, to be re-recorded and fitted to picture.", "plain_english": "It is one short chunk of dialogue that needs to be re-recorded. Each cue has a number and a start and end time. The actor and editor work through the cues one at a time.", "purpose_function": "It breaks a scene's replacement dialogue into small, trackable units so the team can record, log, and edit each line in an organized session.", "practical_application": "Using a cue sheet, the dubbing team loads each cue in turn, records the actor to that segment, and logs which take was kept for the editor.", "category": "Dubbing", "related_terms": ["ADR", "Cue sheet", "Dubbing loop", "Dubbing comp", "Timecode"], "common_mistakes": ["Setting cue in and out points too tight, cutting off breaths or word endings needed for a natural read.", "Mislabeling or misnumbering cues, so takes get logged against the wrong line.", "Making cues too long, which makes it hard for the actor to match sync."], "scenario_contexts": ["Preparing an ADR cue sheet from the editor's list of lines to replace.", "Running a recording session line by line through each marked cue.", "Tracking which cues are recorded, approved, or still outstanding."]}, "d51a3964-7b0b-4fec-a533-440889e4c407": {"definition": "The person who directs performers during a dubbing session, guiding the timing, delivery, emotion, and lip-sync of replacement or translated dialogue so it matches the original performance and the picture.", "plain_english": "It is the person in charge of the actors during dubbing. They help the voice match the timing, feeling, and lip movements on screen. They make sure the new dialogue fits the original scene.", "purpose_function": "It ensures replacement or foreign-language dialogue stays faithful to the original performance in emotion and sync, keeping a consistent standard across the project.", "practical_application": "In an ADR or localization session the dubbing director coaches each actor line by line, calling for retakes until the delivery and sync satisfy the picture.", "category": "Dubbing", "related_terms": ["ADR", "Dubbing engineer", "Dubbing cue", "Lip sync", "Foreign-language dubbing"], "common_mistakes": ["Chasing perfect lip-sync at the expense of a believable, emotional performance.", "Failing to reference the original performance, so the dub drifts in tone.", "Confusing the dubbing director's creative role with the engineer's technical one."], "scenario_contexts": ["Directing voice actors in a foreign-language dub of a film or series.", "Guiding an actor through ADR retakes to match the original take.", "Maintaining consistent character voices across many episodes."]}, "088b1a52-3f7c-4a87-a2b7-aaecf6b5ba50": {"definition": "The engineer responsible for the technical side of a dubbing session — configuring and running the recording and playback system, capturing clean, in-sync replacement dialogue, and managing routing and take logging so the director and editor can focus on performance.", "plain_english": "It is the tech person who runs the gear during dubbing. They set up the microphone, record clean lines in time with the picture, and keep the takes organized. This lets the director focus on the actor.", "purpose_function": "It provides reliable, technically clean recording and playback so replacement dialogue is captured in sync and ready for editing without technical faults.", "practical_application": "During a session the dubbing engineer cues playback for each line, records the actor's takes, watches levels and sync, and names and stores the files for the dialogue editor.", "category": "Dubbing", "related_terms": ["ADR", "Dubbing director", "Dubbing cue", "Dubbing loop", "Signal routing"], "common_mistakes": ["Recording at the wrong level or with a mismatched mic, so the ADR will not sit with the production dialogue.", "Losing sync between playback and the recorder, making takes unusable.", "Poorly naming or logging files, causing confusion in the edit."], "scenario_contexts": ["Setting up and running an ADR stage for a recording session.", "Capturing foreign-language dub takes to picture.", "Delivering labeled, in-sync dialogue files to the editor."]}, "df2950ad-de39-41d7-911f-55375a058cab": {"definition": "A short, repeating segment of picture and its guide track covering a single line or phrase, played back over and over during a dubbing or ADR session so a performer can rehearse and then record dialogue in sync — a practice named for the physical film loops originally used.", "plain_english": "It is a short piece of the scene that plays again and again. The actor watches and listens a few times, then records the line to match. The word comes from the old film loops that were spliced end to end.", "purpose_function": "It lets a performer learn the exact rhythm and lip movement of a line through repetition before recording, improving sync and speed in the session.", "practical_application": "The system plays the loop for a cue with beeps or a streamer, the actor rehearses to it, then records take after take against the same loop until the sync and read are right.", "category": "Dubbing", "related_terms": ["ADR", "Looping", "Dubbing cue", "Streamer", "Lip sync"], "common_mistakes": ["Making the loop too short, so the actor cannot feel the rhythm of the line.", "Not including enough pre-roll, leaving the actor no run-up to the first word.", "Assuming looping and ADR are entirely separate, when ADR grew directly out of loop-based dubbing."], "scenario_contexts": ["Running an actor through repeated plays of a line before recording ADR.", "Rehearsing lip-sync timing on a difficult on-camera close-up.", "Explaining the historical origin of the term 'looping' to trainees."]}, "d7844f0d-62c8-4950-9dbb-a4249d88ebda": {"definition": "In film and television post-production—chiefly British and European usage—the sound engineer who creates the final mix of a soundtrack, balancing dialogue, ADR, Foley, sound effects, and music in a dubbing theatre. It is the equivalent of the American term re-recording mixer.", "plain_english": "A dubbing mixer is the sound engineer who blends all of a film's sounds into one final soundtrack. They balance the voices, effects, and music so everything sounds right together.", "purpose_function": "It exists to combine all the separate sound elements of a production into one balanced, coherent final mix that meets the loudness, format, and artistic needs of the deliverable. Doing this in one skilled pass keeps dialogue clear against music and effects.", "practical_application": "Working in a dubbing theatre from prepared tracks or stems, the dubbing mixer rides levels, applies EQ, dynamics, and reverb to picture, then prints the final mix plus the required stems and deliverable versions.", "category": "Post Roles", "related_terms": ["Re-recording mixer", "Dubbing studio", "Dubbing session", "Final mix", "ADR", "Stems"], "common_mistakes": ["Confusing the dubbing mixer with the sound editor; the editor prepares and places sounds, while the mixer balances and finalizes them", "Assuming 'dubbing' here means foreign-language dubbing, when in this British sense it means the final re-recording mix", "Thinking one pass yields the deliverable, when the mixer usually creates a print master plus separate stems and versions"], "scenario_contexts": ["Mixing the final 5.1 soundtrack of a feature film in a dubbing theatre", "Balancing dialogue against a loud music cue so key lines stay intelligible", "Delivering a print master plus dialogue, music, and effects stems to the distributor"]}, "4fd452c3-4e0f-41b6-8a09-8233fc4ef8f7": {"definition": "A short, supplementary dubbing recording made after the main session to capture lines or sections that were missed, unusable, or changed later, without repeating the whole session. It supplies the small amount of additional material needed to complete or correct the dubbed dialogue.", "plain_english": "A dubbing pickup is a quick extra recording to fix or add a few lines that were missed the first time. It saves booking the whole cast and studio again just for a small change.", "purpose_function": "It exists so a small part of a dubbed performance can be corrected or completed efficiently, so a few problem lines do not force a re-do of the entire session. This saves cost and studio time.", "practical_application": "When review reveals a flubbed or newly rewritten line, the technician schedules a pickup, cues the actor to the exact timecode, and records just that portion to drop into the edit.", "category": "Recording Workflow", "related_terms": ["Dubbing retake", "Dubbing take", "Dubbing session", "ADR", "Pickup"], "common_mistakes": ["Confusing a pickup with a retake; a pickup captures a missing or added section, while a retake re-records an existing one", "Not matching the microphone, distance, and level of the original session, so the pickup does not cut together cleanly", "Failing to log the exact timecode of the pickup, making it hard to place in the edit"], "scenario_contexts": ["Recording one corrected line a week after the main dubbing session", "Capturing a newly added line of dialogue after a picture change", "Grabbing a missed reaction line the director wants added"]}, "68c110e9-325b-4f61-a36a-f8a677203e7f": {"definition": "A repeated recording of a line or passage during dubbing, made because the previous take was unsatisfactory in performance, timing, or technical quality. It produces a fresh version of the same material to picture.", "plain_english": "A dubbing retake is another go at recording a line that was not good enough the first time. It is like re-doing one sentence until it matches the picture and sounds right.", "purpose_function": "It exists to give the editor a better version of a specific take where the earlier attempt failed on performance or sync. Having a usable alternative avoids a costly return session later.", "practical_application": "If a take drifts out of sync or the delivery falls flat, the mixer or director calls a retake, and the actor performs the same line again to picture until it works.", "category": "Recording Workflow", "related_terms": ["Dubbing take", "Dubbing pickup", "Dubbing session", "ADR", "Lip sync"], "common_mistakes": ["Assuming every retake replaces the last, when good practice keeps earlier takes in case they read better in the edit", "Confusing a retake with a pickup; a retake redoes an existing line, a pickup adds a missing one", "Not resetting to the same start cue, so the retake no longer matches the timing of the picture"], "scenario_contexts": ["Re-recording a line that landed a frame late against the actor's lip movements", "Doing another take because the first reading lacked emotion", "Repeating a take spoiled by a mouth click or background noise"]}, "ecd8b294-c154-48c4-a756-06ce44520251": {"definition": "A script prepared for a dubbing session that sets out each line to be recorded with its character, its timecode or footage cue, and any adaptation needed to match lip movement and timing. It is used for both ADR and foreign-language dubbing.", "plain_english": "A dubbing script is the marked-up script the cast reads from in a dubbing session. It shows each line, who says it, and exactly when it must be spoken to match the picture.", "purpose_function": "It exists to give the actors, director, and engineer a shared reference so each line is recorded in the right order and timed to the picture. Clear cues keep a long session organised and in sync.", "practical_application": "The technician loads the dubbing script alongside the picture, cues the actor to the marked timecode, and records each line in script order, checking it against the image.", "category": "Post Documentation", "related_terms": ["Dubbing session", "ADR", "Timecode", "Lip sync", "Continuity script"], "common_mistakes": ["Treating it as the original screenplay, when a dubbing script is reorganised by line and timecode for recording", "Ignoring the timing cues, which are what keep the recording in sync with the picture", "Not updating the script after picture changes, so the cues no longer match the edit"], "scenario_contexts": ["Recording foreign-language dialogue matched to the original actors' lip movements", "Running an ADR session line by line from the marked script", "Updating cue timecodes after the picture is re-edited"]}, "70c1006d-efc5-4dc5-9d71-eab90c81a198": {"definition": "A scheduled recording session in which dialogue is dubbed to picture—either replacement dialogue (ADR) or foreign-language dialogue—with actors performing lines in sync with the edited image. Multiple takes are usually recorded for later selection.", "plain_english": "A dubbing session is a booked studio session. Actors record voices in time with the picture. It is used to replace unclear lines. It also works for recording dialogue in another language.", "purpose_function": "It exists to provide a controlled setting for capturing clean, well-synced dialogue that replaces or adds to the production sound. A booked session gathers the cast, gear, and picture in one place efficiently.", "practical_application": "The engineer sets up the microphone and playback, cues the actor to each line against picture, and records several takes until both performance and sync are right.", "category": "Recording Workflow", "related_terms": ["ADR", "Dubbing take", "Dubbing script", "Dubbing studio", "Lip sync"], "common_mistakes": ["Confusing a dubbing session with the final mix; here it means recording dialogue, not balancing the whole soundtrack", "Not checking sync against picture during the session, only to find drift later", "Failing to keep a consistent microphone setup between sessions, so retakes and pickups do not match"], "scenario_contexts": ["Booking actors to re-voice lines lost to on-set noise", "Recording a full foreign-language version of a film", "Adding crowd and background voices to match a scene"]}, "853525f5-6799-4c40-982f-5afe3bd3f229": {"definition": "A studio designed and equipped for dubbing work, providing an acoustically controlled recording space, picture playback locked in sync with the audio, and accurate monitoring. It is used to record ADR and foreign-language dialogue and, in larger rooms, the final re-recording mix.", "plain_english": "A dubbing studio is a quiet, sound-treated room built for recording voices to picture. It has screens and playback gear so actors can speak their lines exactly in time with the film.", "purpose_function": "It exists to give a distraction-free, acoustically neutral space with synced picture so dubbed dialogue can be recorded cleanly and matched to the image. Its treatment keeps room sound from leaking into takes.", "practical_application": "A technician runs the recording and playback systems in the dubbing studio, keeps audio locked to picture, and delivers clean, well-labelled takes to the editor.", "category": "Post Facilities", "related_terms": ["Dubbing theatre", "ADR", "Dubbing session", "Edit suite", "Re-recording mixer"], "common_mistakes": ["Confusing a dubbing studio with a music recording studio, when it is optimised for dialogue and synced picture", "Overlooking acoustic treatment, which lets room tone contaminate takes", "Assuming any control room can lock cleanly to picture without proper sync equipment"], "scenario_contexts": ["Recording ADR lines against a projected picture", "Producing a dubbed foreign-language version of a program", "Mixing the final soundtrack in a large dubbing studio or theatre"]}, "fbe0217a-0c3b-43f5-b25b-863ddda05d4d": {"definition": "A single recorded attempt at a line or passage during a dubbing session. Each performance to picture is numbered as a separate take so the best one can be chosen or combined in the edit.", "plain_english": "A dubbing take is one recorded try at a line during a dubbing session. Actors usually do several takes, and the editor later picks the best one.", "purpose_function": "It exists to capture each attempt separately so the director and editor can compare performances and choose the best sync and delivery. Keeping takes distinct makes later selection reliable.", "practical_application": "The engineer labels and logs each take by number, records several per line, and notes which ones the director circles as preferred for the edit.", "category": "Recording Workflow", "related_terms": ["Dubbing retake", "Dubbing pickup", "Dubbing session", "ADR", "Circled take"], "common_mistakes": ["Not clearly numbering takes, which makes the preferred one hard to find in the edit", "Deleting earlier takes too soon, before the edit confirms which one is best", "Confusing a take with a retake, when a retake is simply another take called after an unsatisfactory one"], "scenario_contexts": ["Recording takes one through five of a single line for the director to choose from", "Logging the circled takes the director marks as keepers", "Comparing takes for the best lip sync during the edit"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"5a96939f-050a-4608-919e-85e7d8161bab": {"definition": "An interactive audio system, common in games and other real-time media, in which music is built from segments, layers, or variations that change in real time in response to events, player state, or other inputs, rather than playing as a fixed linear track. It is typically implemented with audio middleware that manages transitions and synchronisation.", "plain_english": "A dynamic music system is music that changes as things happen, instead of playing one fixed track. In a game, the music can grow tense when danger appears and calm down when it passes.", "purpose_function": "It exists to keep music matched to unpredictable, interactive action so the score responds to what the user does rather than being locked to a single timeline. This keeps the music feeling connected to the moment.", "practical_application": "Using middleware such as Wwise or FMOD, a technician builds the music in stems and segments with rules and transitions, so the engine can switch layers or cues smoothly as gameplay changes.", "category": "Interactive Audio", "related_terms": ["Adaptive music", "Audio middleware", "Stems", "Vertical layering", "Horizontal re-sequencing"], "common_mistakes": ["Confusing dynamic music with simply lowering the volume, when it changes what plays and not just the level", "Ignoring transition and sync rules, so layers switch with audible jumps", "Exporting one flat mix instead of the separate stems the engine needs to control"], "scenario_contexts": ["Building game music that intensifies during combat and relaxes when it ends", "Layering instruments in as the player nears an objective", "Switching musical themes as a player moves between areas"]}, "c48c1a34-ea62-4b7b-a66a-06e1b0f351d5": {"definition": "A room equipped for editing picture and/or sound, containing the editing workstation, any control surfaces, calibrated video and audio monitoring, and playback systems used to assemble and refine a program before final mixing and delivery.", "plain_english": "An edit suite is a room set up for editing a film or show. It has the computer, screens, and speakers an editor needs to cut and arrange the picture and sound.", "purpose_function": "It exists to give a controlled, well-monitored space where an editor can assemble, trim, and refine material accurately before it moves on to mixing and delivery. Consistent monitoring keeps editing decisions reliable.", "practical_application": "An editor works in the edit suite to build the cut, sync sound to picture, and prepare sequences and exports that hand off cleanly to the dubbing or grading stage.", "category": "Post Facilities", "related_terms": ["Dubbing studio", "Timecode", "Picture lock", "Conform", "Non-linear editor"], "common_mistakes": ["Assuming edit-suite monitoring is calibrated for final mixing, when critical loudness and balance decisions belong in the dubbing theatre", "Not maintaining consistent timecode and frame rate, which causes sync problems downstream", "Treating an edit-suite export as a final deliverable rather than a handoff to the mix"], "scenario_contexts": ["Cutting a television episode to picture lock in the edit suite", "Syncing production sound to picture before an ADR session", "Preparing a conformed sequence to hand to the dubbing stage"]}, "68254dbd-85fc-46de-b7ae-467282b6a5a0": {"definition": "A dedicated post-production room and workstation configured for sound-effects editing, where an effects editor selects, cuts, syncs, and organizes hard effects, backgrounds, and designed elements into structured tracks and stems for the re-recording mix.", "plain_english": "A special editing room where a sound editor picks and lines up the sound effects for a film. It is like a workshop where every crash, footstep, and background noise is placed to match the picture.", "purpose_function": "It gives the sound-effects editor the tools, calibrated monitoring, and track layout needed to build and sync all non-dialogue, non-music sound so it is ready to hand off to the dub stage.", "practical_application": "An effects editor works in the suite to spot the picture, import library and recorded effects, cut them to sync, and split them across organized tracks and stems for the re-recording mixer.", "category": "Post-Production Facility", "related_terms": ["Sound-effects editing", "Foley", "Backgrounds", "Re-recording mix", "Dialogue editing", "Spotting session"], "common_mistakes": ["Confusing the effects-editing suite with the final dub/mix stage; editing prep and re-recording are separate rooms and roles.", "Failing to organize effects onto consistent, clearly named tracks and stems, which slows the mix.", "Not calibrating monitoring to a known reference level, so balance decisions do not translate to the dub stage."], "scenario_contexts": ["Cutting hard effects and backgrounds to sync before a re-recording mix.", "Building organized SFX stems for delivery to the dub stage.", "Editing and cleaning field-recorded effects into usable, synced elements."]}, "e00efe8d-0a0a-4394-b2fb-877a7c132fba": {"definition": "An auditory cue that conveys the perceived vertical position (height) of a sound source, arising mainly from direction-dependent spectral filtering by the listener's head and outer ears, as captured in the head-related transfer function.", "plain_english": "A clue your ears use to tell how high or low a sound is. Your outer ear changes the sound for high and low sources. Your brain reads that change as height.", "purpose_function": "It lets the hearing system, and immersive audio systems that model it, place sounds above or below the listener rather than only left to right, which is essential for height channels and object-based formats.", "practical_application": "When mixing immersive formats such as Dolby Atmos, an engineer relies on elevation cues (real height speakers, or modeled spectral cues in binaural rendering) to make objects seem to come from overhead.", "category": "Spatial Audio", "related_terms": ["Head-related transfer function", "Binaural rendering", "Object-based audio", "Localization", "Height channel", "Dolby Atmos"], "common_mistakes": ["Assuming left-right panning alone can create height; elevation depends on spectral cues, not horizontal panning.", "Relying on generic, non-individualized HRTFs and expecting reliable height perception for every listener.", "Applying heavy EQ that flattens the spectral cues the ear uses to judge elevation."], "scenario_contexts": ["Rendering height objects in a binaural Dolby Atmos mix for headphones.", "Positioning a flying object overhead in an immersive film mix.", "Diagnosing why a height-panned sound does not seem elevated on headphones."]}, "8f668858-a710-4294-876b-f46155c8bc58": {"definition": "The location, in a 2D or 3D coordinate space, of a virtual sound source (an emitter) relative to the listener, used by a spatial or object-based audio engine to compute direction, distance, level, and filtering for rendering.", "plain_english": "Where a sound sits in the virtual world. The system uses this to know how far away and which way the sound should seem to come from. Move it closer and it gets louder.", "purpose_function": "It drives spatialization: the engine combines the emitter's position with the listener's position to set panning, level, distance attenuation, and reverb so the sound seems to come from the right place.", "practical_application": "In game-audio middleware or object-based mixing, a sound designer sets or animates an emitter's position so effects track on-screen or in-world sources as they move relative to the listener.", "category": "Spatial Audio", "related_terms": ["Listener", "Object-based audio", "Distance attenuation", "Panning", "Spatialization", "Dolby Atmos"], "common_mistakes": ["Confusing emitter position (the source) with listener position (the reference point); they are distinct.", "Forgetting to update or animate the position, so a moving on-screen source stays static in the mix.", "Ignoring distance attenuation and reverb, so a far emitter is still unrealistically loud and dry."], "scenario_contexts": ["Animating a passing car's emitter so it pans and fades across the field.", "Placing an object's position in a Dolby Atmos session to sit above the listener.", "Setting emitter coordinates in game middleware so a sound tracks its in-world object."]}, "5be2da77-9cab-448f-af21-3fe4d00a8c73": {"definition": "In scalable (layered) audio coding, a supplementary bitstream that adds to a self-contained base layer to improve quality, providing higher resolution, extended bandwidth, additional channels, or lossless reconstruction, so a decoder can use the base alone or base-plus-enhancement.", "plain_english": "An extra chunk of audio data added on top of a basic version to make it sound better. A simple player uses just the basic part. A better player adds the extra layer for higher quality.", "purpose_function": "It lets one delivery stream serve different devices and bandwidths: a basic decoder plays the base layer, while a more capable decoder adds the enhancement layer for higher resolution or extra channels.", "practical_application": "In deliverables built on scalable codecs (for example MPEG-4 scalable-to-lossless), an encoding operator manages base and enhancement layers so both compatible and high-end playback are supported from one file.", "category": "Coding & Delivery", "related_terms": ["Base layer", "Scalable coding", "Lossless coding", "Bitstream", "Codec", "Bit depth"], "common_mistakes": ["Assuming the enhancement layer plays on its own; it is meaningless without its base layer.", "Confusing an audio enhancement layer with a video enhancement layer (as in scalable video); they are separate streams.", "Stripping the enhancement layer during transcode and losing the intended lossless or extended-channel quality."], "scenario_contexts": ["Encoding a scalable stream that degrades gracefully for low-bandwidth clients.", "Delivering one file that plays lossy on basic decoders and lossless on capable ones.", "Troubleshooting why high-resolution playback fails when only the base layer survived a transcode."]}, "02194985-0db9-44a1-a1fb-2e4f721a987d": {"definition": "The way a process, plug-in, or editor treats the amplitude envelope of a signal (its attack, sustain, and decay over time), including how transients are preserved, shaped, or smoothed during dynamics processing, editing, and level automation.", "plain_english": "How a tool deals with the shape of a sound's loudness over time, its punchy start and its fade out. Good handling keeps a drum hit snappy instead of squashing its sharp start.", "purpose_function": "It determines whether the natural shape and transients of a sound are kept, tightened, or softened, which affects clarity, punch, and how edits and level moves sound.", "practical_application": "An editor watches envelope handling when applying compression, transient shaping, fades, or automation so that attacks stay natural and edits do not create clicks or pumping.", "category": "Signal Processing", "related_terms": ["Amplitude envelope", "Attack", "Transient", "Compression", "Automation", "Fade"], "common_mistakes": ["Setting compressor attack too fast and flattening transients, dulling the sound's natural envelope.", "Editing or fading across a transient, which can cause clicks or an unnatural envelope.", "Confusing an amplitude envelope with a filter or automation envelope; here the term refers to level over time."], "scenario_contexts": ["Preserving a gunshot's sharp attack while controlling its overall level.", "Editing across a sustained tone without creating a click at the cut.", "Using transient shaping to restore punch lost to heavy compression."]}, "8e86180c-095d-405f-99b3-014cb886f570": {"definition": "The artificial modeling of a space's reflections and reverberation (early reflections and reverb tail) using algorithmic reverb, convolution with an impulse response, or geometric acoustic modeling, to place a dry sound convincingly within a simulated acoustic environment.", "plain_english": "Faking the echoes and reverb of a real room so a clean recording sounds like it was there. It is like adding the natural bounce of a hall or cave to a dry voice.", "purpose_function": "It lets sound editors and mixers match dialogue, effects, and Foley to the on-screen space, creating a believable sense of room size and surfaces without recording in that actual place.", "practical_application": "A re-recording mixer uses convolution or algorithmic reverb to simulate a cathedral, tiled bathroom, or forest so that ADR and effects sit naturally in the scene's environment.", "category": "Reverberation & Acoustics", "related_terms": ["Convolution reverb", "Early reflections", "Impulse response", "Reverberation", "Room tone", "Worldizing"], "common_mistakes": ["Matching the reverb tail of a big space but ignoring early reflections, so the result sounds artificial.", "Over-reverberating dialogue so it loses intelligibility.", "Using a reverb whose character does not match the on-screen room, breaking the illusion of place."], "scenario_contexts": ["Placing ADR into a tiled bathroom so it matches the production sound.", "Simulating a large stone hall for a scene shot on a dry stage.", "Matching effects reverb to a location's acoustics for a seamless mix."]}, "b6586eb2-23f8-4bec-b0f9-998463217ea6": {"definition": "A sound effect that conveys the ambient character of a location, the continuous background layer such as wind, traffic, room tone, crowds, or wildlife, used to establish and sustain a scene's sense of place rather than to mark a single on-screen action.", "plain_english": "The background sounds that tell you where a scene is, like traffic, birds, or a humming office. They set the mood instead of matching one exact action.", "purpose_function": "It establishes the setting, fills silence, and smooths edits by providing a continuous sense of place under dialogue and hard effects.", "practical_application": "A sound editor lays environmental effects (backgrounds, or \"atmos\") on dedicated tracks to build a believable, continuous world beneath the dialogue and spot effects.", "category": "Sound Effects", "related_terms": ["Ambience", "Backgrounds", "Room tone", "Hard effects", "Foley", "Sound design"], "common_mistakes": ["Confusing environmental backgrounds with hard effects; backgrounds are continuous, hard effects are specific and synced.", "Letting a background loop repeat audibly instead of varying it, which breaks realism.", "Mixing environmental effects so loud they mask dialogue."], "scenario_contexts": ["Laying a city-traffic background under a street dialogue scene.", "Adding forest ambience with birds and wind to establish a woodland setting.", "Filling a quiet interior with subtle room tone so cuts feel continuous."]}, "5569c8e2-2749-492e-8f6e-0847755c460b": {"definition": "An audio playback approach in which sounds are triggered by discrete events (game actions, user inputs, or system messages) rather than played along a fixed timeline, with audio middleware mapping each event to sounds, parameters, and behaviors at runtime.", "plain_english": "Sound that plays when something happens, not on a set schedule. Press a button or jump, and the matching sound fires right then.", "purpose_function": "It lets interactive media react in real time, so the same session can play different, non-linear sound based on what happens, which a fixed timeline mix cannot do.", "practical_application": "A game-audio designer builds events in middleware such as Wwise or FMOD, linking each game trigger to sounds and mix changes so audio responds to gameplay as it unfolds.", "category": "Interactive Audio", "related_terms": ["Audio middleware", "Trigger", "Emitter position", "Real-time mixing", "Wwise", "FMOD"], "common_mistakes": ["Treating event-driven audio like a linear timeline mix, ignoring that events fire unpredictably.", "Not managing voice count and priority, so many simultaneous events overload playback.", "Forgetting to add variation, so a repeated event plays the exact same sound every time."], "scenario_contexts": ["Triggering a footstep sound each time a character's foot lands in a game.", "Firing a UI click sound when a player selects a menu item.", "Changing the music state when the player enters combat."]}, "1aeae003-1e78-4ae3-8496-e05cbe33ebf1": {"definition": "In interactive game audio, a game-sync value (a Wwise State, a switch, or an engine parameter) that flags the player as being in an exploration, non-combat context, used by the audio system to select or blend the ambience and adaptive-music layers appropriate to that state.", "plain_english": "A setting that tells the game you are just exploring, not fighting. The game reads it and plays calmer background music. When the state changes, the music changes to match what you do.", "purpose_function": "It lets the soundtrack respond to gameplay by tying a named game state to the right music and ambience, so the mood shifts automatically as the player moves between exploring and other situations such as combat.", "practical_application": "A game-audio designer maps the game's exploration state to a State or parameter in middleware such as Wwise or FMOD, then routes it to a music switch container so exploration music plays and transitions out when combat begins.", "category": "Game Audio", "related_terms": ["Combat-state parameter", "Event-driven audio", "Conditional playback", "Game audio", "Audio middleware", "Adaptive music"], "common_mistakes": ["Thinking the parameter itself makes sound; it only reports the game state, and the audio system must be set up to react to it.", "Forgetting to define musical transitions, so the switch from exploration to combat music cuts abruptly instead of blending.", "Confusing a discrete state (a game context like exploration) with a continuous parameter such as distance or intensity."], "scenario_contexts": ["Playing calm exploration music that swells into combat music when enemies appear.", "Switching ambient beds as the player leaves a safe town and enters open wilderness.", "Debugging why exploration music keeps playing after a fight has already started."]}, "d7419a6c-d49e-4eec-9c7c-9547bcde5b45": {"definition": "A form of time-scale modification in which an audio signal's duration is expanded by a very large factor (often several hundred to several thousand percent) without a proportional change in pitch, producing sustained, smeared textures from short source material. It is typically achieved with phase-vocoder or granular resynthesis processing.", "plain_english": "It means slowing a sound down by a huge amount so it lasts much longer. The pitch stays the same, so it does not sound lower. A one-second clip can become a long, hazy drone, like a rubber band stretched far past its normal size.", "purpose_function": "It lets sound editors turn brief recordings into long evolving beds, drones, and transitions, giving scenes atmosphere and tension without needing new source material.", "practical_application": "A technician loads a short clip into a phase-vocoder or granular tool (such as a time-stretch plug-in or Paulstretch), sets a large stretch ratio, and layers the result under a scene as an ambient wash or riser.", "category": "Time Processing", "related_terms": ["Time stretching", "Phase vocoder", "Granular synthesis", "Pitch shifting", "Sound design", "Ambience"], "common_mistakes": ["Expecting clean results at extreme ratios; very large stretch factors add phasing, smearing, and metallic artifacts", "Confusing time stretching with pitch shifting, when extreme stretch changes length, not pitch", "Stretching a low-resolution or heavily compressed source, which exaggerates artifacts", "Forgetting that huge stretches raise processing time and file length dramatically"], "scenario_contexts": ["Creating a long ambient drone from a two-second vocal or metal hit for a tense scene", "Building a slow riser or transition into a scene change", "Turning a short field recording into an evolving background texture for a deliverable stem"]}, "fb19f94a-4216-4fd5-9c60-bf6f115e2534": {"definition": "In spatial and object-based audio, the distance parameter that governs how a sound source's level attenuates as its virtual position moves away from the listener, typically following an inverse-square (about 6 dB per doubling of distance) or a defined minimum/maximum distance curve.", "plain_english": "It is the setting that controls how fast a sound gets quieter as it moves farther from the listener. Like a friend's voice fading as they walk down the street, the sound drops off over the distance you set.", "purpose_function": "It supplies distance cues in a mix so objects placed far from the listener sound faint and near objects sound loud, making a spatial or immersive scene feel believable.", "practical_application": "When placing an audio object in an immersive panner or a game or VR engine, a technician sets the minimum and maximum distance and the falloff curve so the element attenuates correctly as it or the listener moves.", "category": "Spatial Audio", "related_terms": ["Distance attenuation", "Inverse-square law", "Object-based audio", "Panning", "Far-field spatialization", "Reverb"], "common_mistakes": ["Relying on level change alone, when distant sources also lose high frequencies and gain reverb", "Setting the falloff curve too steep, so objects vanish abruptly instead of fading", "Confusing falloff distance with panning position; one sets loudness over distance, the other sets direction", "Ignoring that different renderers use different default distance models"], "scenario_contexts": ["Placing a passing vehicle object in an immersive mix so it fades as it moves away", "Setting distance attenuation for a sound source in a game or VR audio engine", "Tuning how quickly off-screen crowd noise drops as the camera pushes in"]}, "71e22437-5378-4cb1-8e23-e3e909295680": {"definition": "The positioning of sound sources in the region far enough from the listener (generally beyond about one metre and many wavelengths) that wavefronts arrive as effectively plane waves, so localization relies on far-field HRTF cues, level, and reverberation rather than the strong distance-dependent cues present very close to the head.", "plain_english": "It means placing sounds so they seem to come from far away, not right next to your ear. When something is far off, the main clues are how loud it is and its echo. Those clues replace the closeness you feel when a sound is inches from your head.", "purpose_function": "It creates a natural sense of depth and surrounding space in immersive and binaural mixes, keeping distant elements from sounding unnaturally close or stuck inside the listener's head.", "practical_application": "A technician uses far-field HRTFs and adds distance cues (lower level, less high frequency, more reverb) when placing ambience, off-screen action, or background elements away from the listener in a binaural or object-based mix.", "category": "Spatial Audio", "related_terms": ["Near-field spatialization", "HRTF", "Binaural audio", "Distance attenuation", "Falloff distance", "Reverb"], "common_mistakes": ["Using near-field HRTFs for distant sources, which makes them feel too close", "Thinking direction is enough, when far-field placement also needs distance cues like reverb and level", "Confusing far-field placement with simply turning a sound down", "Ignoring room reflections, which are a key far-field distance cue"], "scenario_contexts": ["Placing distant ambience and off-screen events in a binaural mix for headphones", "Building depth in an object-based film mix so backgrounds sit behind the on-screen action", "Positioning a far-off vehicle or crowd so it reads as distant rather than nearby"]}, "b78da41e-1a94-405b-bafa-3fbe53e8c29e": {"definition": "The post-production discipline of preparing, cutting, and synchronizing music to picture, including spotting, building temp tracks, conforming cues to editorial changes, and delivering edited music elements for the final re-recording mix.", "plain_english": "It is the job of fitting music to a film. The goal is for every piece of music to start, change, and end at the right moment on screen. The music editor trims and lines up the music like puzzle pieces so it matches the story.", "purpose_function": "It ensures music supports the picture precisely and stays in sync through editorial changes, giving the re-recording mixer clean, correctly placed music to balance in the final mix.", "practical_application": "A music editor spots scenes with the director and composer, lays in temp music, conforms cues when the picture is re-cut, and prepares the music stems and cue sheets for the dub stage.", "category": "Music Editorial", "related_terms": ["Temp track", "Spotting session", "Cue", "Conform", "Final music edit", "Stem"], "common_mistakes": ["Treating temp music as final and forgetting it must be cleared, licensed, or replaced", "Not reconforming music after a picture change, causing cues to drift out of sync", "Overlooking accurate cue sheets, which are needed for rights and delivery", "Confusing the music editor's role with that of the composer or the re-recording mixer"], "scenario_contexts": ["Building a temp music track for an early cut screening", "Conforming score cues after the picture editor changes a scene's length", "Preparing music stems and cue sheets for the final dubbing stage"]}, "e445f326-07f8-45e4-86c2-471f72726b49": {"definition": "The locked, fully conformed version of a film or program's edited music, cut and synchronized to the final picture and delivered as the music elements or stems used in the final re-recording mix.", "plain_english": "It is the finished, locked version of all the music, lined up exactly to the final cut of the picture. Nothing more changes; these are the music tracks that go into the last mix.", "purpose_function": "It gives the re-recording mixer a stable, picture-accurate set of music elements to balance against dialogue and effects, so the music in the finished program is correctly timed and placed.", "practical_application": "After picture lock, the music editor makes the final conform of every cue, cleans edits and crossfades, and hands off the final music stems and session for the dub.", "category": "Music Editorial", "related_terms": ["Film music editing", "Picture lock", "Conform", "Stem", "Final mix", "Cue"], "common_mistakes": ["Finalizing music before picture lock, forcing costly re-conforms", "Delivering music stems that do not match the agreed deliverable spec or layout", "Leaving audible edit clicks or bad crossfades in the final cues", "Assuming temp music can stand as the final edit without clearance or replacement"], "scenario_contexts": ["Delivering conformed music stems to the dub stage after picture lock", "Preparing the final music elements for a broadcast or streaming deliverable", "Handing the re-recording mixer the locked music for the final mix"]}, "cfcdc5b3-bb5e-4323-9db5-33c460c26d61": {"definition": "A sound-design effect that simulates a fast object passing the listener by combining a Doppler pitch glide (higher than the true pitch while approaching, crossing through the true pitch at the point of closest approach, then dropping below it as the object recedes), a level swell and fade, and a directional pan across the sound field to convey approach, pass, and recede.", "plain_english": "It is the whoosh of something fast rushing past you, like a race car or a jet flying by. The sound rises in pitch and loudness as it comes toward you, then drops as it speeds away.", "purpose_function": "It gives moving objects a convincing sense of speed and direction on screen, selling the moment a car, plane, projectile, or creature streaks past the point of view.", "practical_application": "A sound editor takes a pass-by or steady recording, applies a Doppler pitch move, automates level and pan to follow the on-screen path, and often layers whoosh or air elements to sharpen the pass.", "category": "Sound Design", "related_terms": ["Doppler effect", "Panning", "Automation", "Pitch shifting", "Whoosh", "Sound design"], "common_mistakes": ["Panning across without any Doppler pitch change, which sounds flat and fake", "Making the pitch shift too large, turning a fly-by into a cartoon slide", "Mismatching the pan and level move to the object's on-screen path and speed", "Forgetting that the closest point is the loudest, but is where the pitch crosses through the object's true frequency, not where it is highest; the pitch is highest earlier, while the object is still approaching"], "scenario_contexts": ["Creating a race car passing the camera in a chase scene", "Designing a jet or missile streaking past the frame", "Adding a fast creature or arrow that whips past the point of view"]}, "9b2472e2-b2de-43b3-b1b3-dbd132448751": {"definition": "A discrete recorded Foley sound, such as footsteps, cloth movement, or prop handling performed in sync to picture, stored and catalogued as an individual media element in a post-production session or asset library for use and delivery.", "plain_english": "It is a single Foley sound saved as its own file, like one recording of footsteps or a door handle. Editors keep these clips organized so they can drop the right everyday sound onto the picture.", "purpose_function": "It provides a managed, reusable unit of performed everyday sound that editors place against picture and deliver as part of the sound package, keeping projects organized and trackable.", "practical_application": "After a Foley session, a technician edits and names each recorded pass, files it in the session or library with metadata, and places or delivers it as part of a Foley stem.", "category": "Foley", "related_terms": ["Foley", "Footsteps", "Prop", "Stem", "Sound library", "Sync"], "common_mistakes": ["Poor naming or metadata, making assets impossible to find later", "Assuming Foley assets replace all ambience and hard effects, when they cover performed, everyday sounds", "Recording out of sync with picture, so the asset needs heavy editing", "Confusing Foley assets with library sound effects, which are pre-recorded rather than performed to picture"], "scenario_contexts": ["Filing each footstep and cloth pass after a Foley session", "Delivering a Foley stem as part of the final sound package", "Reusing a catalogued prop-handling asset in a later scene"]}, "379752b3-3119-4bac-b43a-9e9f286325c4": {"definition": "The editorial stage in which unwanted noise, extraneous sounds, and timing errors are removed from recorded Foley, and the cues are tightened to sync so the Foley sits cleanly in the mix.", "plain_english": "After Foley is recorded, an editor goes through it and takes out the extra noises and mistakes. It is like editing the coughs and bumps out of a voice recording so only the good sounds are left.", "purpose_function": "It strips recording flaws and background noise so each Foley cue is clean and can be placed tightly against picture. This lets the Foley blend into the mix without drawing attention.", "practical_application": "A Foley editor cuts out breaths, prop bumps, and dead air, then nudges each footstep or cloth move into tight sync before handing the tracks to the re-recording mixer.", "category": "Foley Editing", "related_terms": ["Foley artist", "Sound effects editing", "Sync", "Spotting session", "Re-recording mixer", "Foley library recording"], "common_mistakes": ["Leaving prop bumps, breaths, or chair creaks in the tracks so they intrude on the mix", "Cutting so tightly that natural tails or the start of a sound are clipped off", "Confusing cleanup with mixing, when cleanup only prepares tracks and does not set final levels or EQ"], "scenario_contexts": ["Prepping a reel of recorded footsteps for the final mix", "Removing a director's cough that leaked into a quiet Foley take", "Tightening cloth moves to sync before the re-recording stage"]}, "3fa9a532-e442-4235-8333-a929cf3b6b3c": {"definition": "An organized collection of garments, fabrics, and cloth items kept on a Foley stage so the artist can match and perform the cloth-movement sounds of a character's wardrobe.", "plain_english": "A stash of different clothes and fabrics kept in the Foley studio. The artist picks fabric that matches what a character wears, then moves it near a mic to make the rustling sounds of people walking or shifting.", "purpose_function": "It lets the Foley artist reproduce believable clothing rustle that matches each character's wardrobe, adding realism to on-screen movement. Having many fabrics on hand means the right texture is always available.", "practical_application": "When cueing a scene, the Foley artist grabs a jacket or fabric whose weight and weave match the actor's costume, then performs the cloth moves in sync with the picture.", "category": "Foley Library", "related_terms": ["Foley artist", "Cloth pass", "Foley pit", "Foley prop library", "Foley shoe library", "Footsteps"], "common_mistakes": ["Using a fabric whose weight or weave does not match the character's costume", "Forgetting that cloth Foley is needed at all, leaving movement sounding thin", "Letting jewelry, zippers, or buttons add sounds the scene does not call for"], "scenario_contexts": ["Matching a leather jacket's creak for an action scene", "Performing the swish of a long gown as a character walks", "Adding subtle cloth movement so a nearly still character still feels alive"]}, "0fd5f5db-73ca-48e8-94b3-4636fed3d3b2": {"definition": "The practice of recording Foley performances as reusable sound-library assets, captured wild rather than to picture and catalogued for later use, instead of performing them in sync to a specific scene.", "plain_english": "Recording Foley sounds on their own to save and reuse later, instead of playing them along to a movie. It is like recording a batch of footstep and door sounds once, then keeping them in a sound bank for future projects.", "purpose_function": "It builds a stock of clean, isolated Foley sounds that editors can pull from when a live session is not scheduled or a quick fill is needed. This saves time and money on later projects.", "practical_application": "A Foley team records clean takes of footsteps, cloth, and prop handling without picture, labels and stores them, and an editor later drops these files into a project as needed.", "category": "Foley Recording", "related_terms": ["Sound library", "Wild recording", "Foley artist", "Sound effects editing", "Foley cleanup", "Spotting session"], "common_mistakes": ["Treating library Foley as a full replacement for performing to picture, which weakens sync", "Recording without clean labeling, so files cannot be found later", "Capturing takes with room noise or handling that limits reuse"], "scenario_contexts": ["Building a stock of footstep sounds during studio downtime", "Recording prop handling sounds for reuse across a TV series", "Capturing a clean set of door sounds to fill gaps in a rushed schedule"]}, "e8b53a1d-923b-4e2c-b031-226b6f07f1cb": {"definition": "The final, fully mixed Foley stem printed at the printmaster stage of the final mix, kept as a separate deliverable so the Foley can be recombined for the M&E track, foreign-language versions, and archival re-mixes.", "plain_english": "The finished Foley track, saved by itself after the final mix. Keeping it apart lets a movie be dubbed in other languages without redoing the Foley.", "purpose_function": "Printing Foley as its own stem lets the mix be rebuilt without dialogue for foreign dubs and preserves the Foley for future re-versioning. It is a standard part of delivery to the studio.", "practical_application": "At the end of the final mix, the re-recording mixer prints the Foley stem alongside the dialogue, music, and effects stems, and it feeds the M&E deliverable.", "category": "Foley Deliverables", "related_terms": ["Printmaster", "M&E", "Stem", "Re-recording mixer", "Final mix", "Deliverables"], "common_mistakes": ["Confusing the Foley stem with the full effects stem", "Forgetting the Foley printmaster is needed to build the M&E for foreign versions", "Assuming a single mixed master is enough and skipping separate stems"], "scenario_contexts": ["Delivering separate stems to the studio at the end of the final mix", "Building an M&E track for a foreign-language dub", "Archiving the Foley element for a future re-release remix"]}, "9309ebf8-5564-46b8-87dd-17c459f7836b": {"definition": "An organized collection of physical objects and props kept on a Foley stage to create handling, impact, and manipulation sounds, from keys and dishes to tools and weapons, matched to on-screen action.", "plain_english": "A big collection of everyday objects kept in the Foley studio to make sound effects by hand. Need jingling keys or clinking dishes? The artist grabs the real object from the shelf and performs it.", "purpose_function": "It gives the Foley artist ready access to objects that produce the exact handling and impact sounds a scene needs. A well-stocked prop library speeds up sessions and improves realism.", "practical_application": "For a scene where a character sets down a coffee cup, the artist pulls a matching ceramic cup from the library and performs the placement in sync.", "category": "Foley Library", "related_terms": ["Foley artist", "Foley prop table", "Foley pit", "Foley shoe library", "Sound effects editing", "Footsteps"], "common_mistakes": ["Grabbing a prop that looks right but sounds wrong on mic", "Not returning and organizing props, so the next session wastes time", "Assuming a plug-in library can replace hand-performed prop sounds for tight sync"], "scenario_contexts": ["Finding a ceramic cup to match a kitchen scene", "Pulling keys and coins for a pocket-search moment", "Sourcing a squeaky chair for an office sequence"]}, "ca047bb4-bfb8-4df8-aea4-dcd496fc12a9": {"definition": "The work surface on a Foley stage where the artist arranges the props needed for a cue or reel within easy reach of the microphone, so items can be picked up and performed in sync with picture.", "plain_english": "The table in the Foley studio where the artist lays out the objects they need for a scene. Keeping everything close means they can grab each prop right on cue, like a chef keeping ingredients within arm's reach.", "purpose_function": "It keeps the current props organized and reachable so performances stay tight to picture without fumbling. A good layout keeps sessions efficient and reduces unwanted noise.", "practical_application": "Before recording a reel, the Foley artist sets out the cups, papers, and keys they will need on the prop table beside the mic, arranged in performance order.", "category": "Foley Stage", "related_terms": ["Foley artist", "Foley prop library", "Foley pit", "Foley stage", "Footsteps", "Sound effects editing"], "common_mistakes": ["Overloading the table so props knock together and add unwanted noise", "Placing the table too far from the mic to perform in sync", "Not arranging props in cue order, causing fumbling during takes"], "scenario_contexts": ["Laying out props in cue order before recording a reel", "Keeping a phone, keys, and mug within reach for a morning scene", "Reorganizing the table between reels as the props change"]}, "b6ee8c56-7043-468f-be70-766e362c89c5": {"definition": "A collection of footwear of many styles, sizes, eras, and sole types kept on a Foley stage so the artist can match a character's shoes and perform footsteps that suit the surface and action.", "plain_english": "A big shelf of shoes kept in the Foley studio. The artist picks a pair that matches what a character wears, like boots or heels, and walks in them on the right surface to make footstep sounds.", "purpose_function": "It lets the Foley artist reproduce footsteps whose weight, material, and sound match each character and surface. A varied shoe collection covers many characters and time periods.", "practical_application": "For a scene with a woman in heels on a tile floor, the artist selects heeled shoes from the library and performs the steps on the matching surface in the pit.", "category": "Foley Library", "related_terms": ["Foley artist", "Footsteps", "Foley surface pit", "Foley surface library", "Foley pit", "Foley stage"], "common_mistakes": ["Using one pair of shoes for every character regardless of match", "Ignoring how the sole material changes the footstep sound", "Forgetting to match the shoe to the walking surface in the pit"], "scenario_contexts": ["Choosing heels for a character crossing a tile lobby", "Selecting work boots for a construction scene", "Finding period-correct shoes for a historical drama"]}, "d2f0446c-3a2b-400a-8b5b-d0efe366a922": {"definition": "The assortment of flooring and ground materials, such as wood, tile, gravel, concrete, grass, and metal, kept on a Foley stage so footsteps and movement can be performed on the surface that matches the scene.", "plain_english": "A set of different floor materials kept in the Foley studio, like wood, gravel, and tile. The artist walks or moves on the one that matches the scene so the footsteps sound right.", "purpose_function": "It provides the correct surface underfoot so footsteps and movement carry the right texture and tone for each location. Matching the surface is key to believable footsteps.", "practical_application": "For a character walking on a gravel path, the artist steps onto the gravel section of the surface library to perform the footsteps in sync.", "category": "Foley Library", "related_terms": ["Foley surface pit", "Footsteps", "Foley shoe library", "Foley artist", "Foley pit", "Foley stage"], "common_mistakes": ["Performing footsteps on the wrong surface for the scene's location", "Assuming one surface can stand in for all grounds", "Neglecting to keep surfaces clean and consistent between sessions"], "scenario_contexts": ["Performing footsteps on gravel for an outdoor path", "Switching to a wood section for footsteps on a porch", "Using a tile surface for indoor hard-floor steps"]}, "9060888d-81f8-447c-a8a7-1fb385b3f77b": {"definition": "A set of built-in floor bays on a Foley stage, each filled with a different walking surface such as gravel, dirt, concrete, wood, or water, into which the artist steps to perform footsteps and movement that match the on-screen ground.", "plain_english": "Special floor boxes in the Foley studio, each filled with a ground material like gravel or dirt. The artist steps into the one that fits the scene. It works a bit like a sandbox built into the floor.", "purpose_function": "It gives the Foley artist real surfaces to walk on so footsteps carry authentic texture and resonance for each location. Building surfaces into the floor keeps them fixed and ready to perform.", "practical_application": "When a character crosses a gravel road, the artist steps into the gravel pit and walks in time with the picture to create the footsteps.", "category": "Foley Stage", "related_terms": ["Foley pit", "Foley stage", "Footsteps", "Foley surface library", "Foley shoe library", "Foley artist"], "common_mistakes": ["Stepping onto a surface that does not match the on-screen ground", "Letting loose material like gravel spill and add stray noise", "UNSAFE: Stepping into wet or uneven pit sections without care, risking slips and falls"], "scenario_contexts": ["Walking in the gravel bay for a country-road scene", "Stepping into the water pit for a scene wading through a puddle", "Using the concrete section for city sidewalk footsteps"]}, "379cbe86-60da-42eb-a8c3-72c78e90b93f": {"definition": "A Foley footstep element in which the foot is dragged or scraped along the surface instead of lifted cleanly, producing a sliding, scuffing sound synced to a character shuffling, pivoting, or dragging their feet on screen.", "plain_english": "A footstep sound made by sliding a foot along the ground instead of taking a clean step. A Foley artist makes it to match a character who shuffles or turns.", "purpose_function": "It adds realism to movement by covering shuffles, turns, and drags that plain steps miss, so on-screen walking sounds natural and complete.", "practical_application": "A Foley artist performs foot slides in the Foley pit while watching picture, sliding a matching shoe across a matching surface to hit each scuff or pivot.", "category": "Foley", "related_terms": ["Footstep performance", "Footstep cue", "Foley pit", "Foley artist", "Footstep synchronization"], "common_mistakes": ["Recording foot slides so loud they overpower the clean footsteps in the mix.", "Forgetting that pivots and turns need slides, leaving movement sounding stiff.", "Sliding on the wrong surface so the texture does not match what is on screen."], "scenario_contexts": ["A character shuffles across a wooden floor in slippers.", "A dancer pivots and the shoe scrapes the stage.", "Someone drags their feet down a gravel path."]}, "51bd3752-06b9-47f5-8287-9ca00ca62cec": {"definition": "A specific point in a scene, marked against picture, where a character's footsteps must be created and placed in sync; it is treated as one discrete item of Foley or editorial work.", "plain_english": "A marked spot in a scene where footsteps need to be added and matched to the picture. It is one job on the Foley to-do list.", "purpose_function": "It tells the Foley team exactly where footsteps are needed, so nothing is missed and the work can be planned scene by scene.", "practical_application": "During a spotting session the team logs footstep cues, then the Foley artist works through each cue while watching the matching picture.", "category": "Foley", "related_terms": ["Spotting session", "Footstep performance", "Footstep synchronization", "Foley artist", "Cue sheet"], "common_mistakes": ["Confusing a footstep cue with a music cue on the same timeline.", "Missing off-screen footsteps that still need a cue.", "Logging cues without noting the surface, so the wrong texture gets recorded."], "scenario_contexts": ["Spotting a scene and marking every place a character walks.", "Building a Foley cue sheet before a record day.", "Checking off footstep cues as each one is recorded."]}, "ddd6559d-7f09-4fe4-a5cf-e60170c6fc60": {"definition": "The physical act of a Foley artist walking or stepping in real time to picture, matching a character's pace, weight, gait, and surface to create their footstep sounds.", "plain_english": "This is a Foley artist actually walking in the studio to make a character's footsteps. They match the speed, weight, and floor of the person on screen.", "purpose_function": "It gives on-screen movement believable footsteps with the right rhythm and feel, which pre-recorded library steps often cannot match exactly.", "practical_application": "The Foley artist watches picture, chooses matching shoes and a surface in the pit, and walks the scene in sync while it is recorded.", "category": "Foley", "related_terms": ["Foley artist", "Footstep cue", "Footstep synchronization", "Foley pit", "Foot slide"], "common_mistakes": ["Matching only the beat but not the character's weight or mood.", "Wearing shoes that do not suit the character or the surface.", "UNSAFE: leaving loose props or trip hazards in the Foley pit during a walking performance."], "scenario_contexts": ["Walking a character's approach down a hallway.", "Performing a nervous, uneven gait for a tense scene.", "Matching a soldier's heavy boots on gravel."]}, "809b1806-d56f-48aa-8c66-16c58d00445a": {"definition": "The process of aligning performed or edited footstep sounds so that each step lands precisely on the corresponding foot contact seen on screen.", "plain_english": "This means lining up each footstep sound with the exact moment a foot hits the ground on screen. If it is off, the walking looks wrong.", "purpose_function": "Tight sync makes footsteps feel like they belong to the character, keeping the audience from noticing the sound was added later.", "practical_application": "The editor nudges footstep sounds frame by frame in the DAW so each hit matches the on-screen foot plant.", "category": "Foley", "related_terms": ["Footstep performance", "Footstep cue", "Sync", "Frame accuracy", "Foley artist"], "common_mistakes": ["Syncing to the leg swing instead of the moment the foot actually lands.", "Ignoring sync drift after a picture re-cut.", "Assuming close is good enough when the steps are exposed in a quiet scene."], "scenario_contexts": ["Lining up boots to a slow, deliberate walk.", "Fixing footsteps after the picture is re-cut.", "Matching running steps in an action chase."]}, "4cf15c84-d566-4844-b46a-41b68d35dd45": {"definition": "The overall setup and method used to produce footstep sounds — the range of pit surfaces, the shoe and prop collection, and the microphone and recording arrangement — organized so a Foley team can match any character and location.", "plain_english": "This is the whole setup a Foley team uses to make footsteps: different floor surfaces, a shelf of shoes, and the microphone. It lets them match any character and place.", "purpose_function": "An organized footstep setup lets the team quickly pick the right surface and shoes, so steps for any scene can be made in a consistent, efficient way.", "practical_application": "A Foley stage keeps pits of wood, gravel, tile, and grass, a shoe wardrobe, and a close mic ready so the artist can switch surfaces between cues.", "category": "Foley", "related_terms": ["Foley pit", "Footstep performance", "Foley stage", "Footstep cue", "Foot slide"], "common_mistakes": ["Thinking one surface can cover every scene.", "Neglecting the shoe collection, so characters all sound alike.", "Poor mic placement that misses the detail of each step."], "scenario_contexts": ["Setting up a Foley stage before a project starts.", "Switching from a tile pit to gravel between scenes.", "Choosing shoes and surface to match a new character."]}, "0d1caa23-d82f-4c88-b920-ccb3204a65a4": {"definition": "A prominent, story-relevant sound effect placed clearly in the mix and usually synced to on-screen action, as opposed to the quieter background or ambient effects that fill out a scene.", "plain_english": "A sound effect meant to stand out and be noticed, like a slamming door or a gunshot. It sits up front in the mix, unlike quiet background sounds.", "purpose_function": "It draws attention to key actions and objects, helping tell the story and guiding what the audience focuses on.", "practical_application": "The sound editor cuts foreground effects to picture, and the re-recording mixer keeps them loud and clear above the background ambience.", "category": "Sound Effects", "related_terms": ["Hard effect", "Background effect", "Ambience", "Spot effect", "Foley"], "common_mistakes": ["Burying a key foreground effect under music or ambience.", "Confusing foreground effects with background fill.", "Forgetting to sync a foreground effect to the action it represents."], "scenario_contexts": ["A door slam that punctuates a dramatic exit.", "A phone ringing that a character reacts to.", "A sword clash in a fight scene."]}, "8f14622d-a3dd-4c3c-bcb2-768db31b9ff5": {"definition": "The re-recording of dialogue in a language other than the production's original language, performed in sync to picture, used to create localized versions or to supply foreign-language lines within a film.", "plain_english": "Recording a scene's lines again in a different language while matching the actors' mouths on screen. It is used to make versions of a film for other countries.", "purpose_function": "It lets a film be released in other languages while keeping the lip-sync and performance believable for local audiences.", "practical_application": "In an ADR studio a voice actor watches picture and records lines in the target language, matching the timing and lip movement of the original.", "category": "Localization", "related_terms": ["ADR", "Foreign-language dubbing", "Lip sync", "Foreign-language dialogue stem", "M&E"], "common_mistakes": ["Focusing on translation accuracy while ignoring lip sync.", "Forgetting that the M&E mix must support the new dialogue.", "Assuming timing from the original will fit the translated lines exactly."], "scenario_contexts": ["Recording a French version of an English film.", "Replacing a foreign-language line the audience must understand.", "Dubbing a series for release in several countries."]}, "d99b2876-660e-4848-98dd-1bbeb21cff14": {"definition": "A mix stem containing only the dialogue of a foreign-language (dubbed) version, delivered separately so it can be combined with the music and effects stems to build a fully localized final mix.", "plain_english": "This is a separate track holding just the dialogue for a dubbed, foreign-language version. It is combined with the music and effects tracks to finish that version's mix.", "purpose_function": "Keeping the foreign dialogue on its own stem lets each language version be mixed and adjusted without redoing the music and effects.", "practical_application": "The mix is delivered as split stems, and the foreign-language dialogue stem is dropped in over the shared M&E to create each localized master.", "category": "Deliverables", "related_terms": ["Dialogue stem", "M&E", "Foreign-language dubbing", "Stem", "Printmaster"], "common_mistakes": ["Confusing a dialogue stem with the full final mix.", "Mismatching stem levels so the dubbed dialogue does not sit like the original.", "Delivering stems out of sync or at the wrong sample rate."], "scenario_contexts": ["Delivering split stems for international versions.", "Swapping in a dubbed dialogue stem over shared M&E.", "Archiving stems so future language versions can be built."]}, "97684062-de8d-4eac-b10d-8f90fee24d06": {"definition": "The post-production process of replacing a production's original dialogue with performances recorded in another language, synced to the picture, so the work can be released for audiences who speak that language.", "plain_english": "Dubbing means swapping a film's original speech for new voices in another language, matched to the actors' mouths. It lets people watch in their own language.", "purpose_function": "It makes films and shows accessible in other markets while keeping the story and lip movement believable.", "practical_application": "A dubbing studio casts local voice actors who record translated lines to picture, which are then mixed over the original music and effects.", "category": "Localization", "related_terms": ["Foreign-language ADR", "M&E", "Foreign-language dialogue stem", "Lip sync", "Localization"], "common_mistakes": ["Translating literally so the lines no longer match the lip movement.", "Mixing dubbed dialogue without a proper M&E stem to sit it over.", "Ignoring the energy and timing of the original performance."], "scenario_contexts": ["Releasing a film dubbed for another country.", "Recording local-language voices for a streaming series.", "Building a dubbed master from the M&E and new dialogue."]}, "9aac2f1a-7d42-4dee-84fb-f74d67ff114d": {"definition": "The final, format-encoded master mix of a film's soundtrack rebuilt for a specific language, combining the original music-and-effects (M&E) stems with newly dubbed foreign-language dialogue, matched to the format, sync, and levels of the original printmaster.", "plain_english": "A finished movie soundtrack made in another language. The mixer keeps the original music and sound effects. Then they swap the spoken lines for new lines dubbed in that language.", "purpose_function": "It lets a film be released in other countries with local-language dialogue while keeping the same music and effects mix, so the picture can be distributed worldwide without remaking the whole soundtrack.", "practical_application": "A re-recording mixer builds it from the delivered M&E stems plus the dubbed dialogue stem, matching loudness and format specs before delivery to the distributor.", "category": "Deliverables", "related_terms": ["Music and effects (M&E)", "Printmaster", "Dubbing", "ADR", "Dialogue stem", "Stems"], "common_mistakes": ["Confusing the M&E with the printmaster: the M&E is a dialogue-free stem, while the printmaster is the finished, combined mix.", "Leaving essential sync effects or non-verbal vocalizations only in the dialogue stem, so gaps appear when the original dialogue is removed for the foreign version.", "Not matching the loudness and format specs of the original, so the foreign printmaster fails delivery QC."], "scenario_contexts": ["Preparing a feature for release in France by combining the M&E with French dubbed dialogue.", "A streaming platform requesting localized printmasters in several languages for a series.", "QC-checking a foreign printmaster against the original for level, format, and sync."]}, "0187e321-5499-4666-b01c-754902d6b0b3": {"definition": "Conducting music that is not in strict, measured tempo (free time, senza misura, or ad libitum), in which the conductor guides entrances, phrasing, and pacing through gesture, cueing, and eye contact rather than beating a fixed, steady pulse.", "plain_english": "Leading players through music that has no strict, steady beat. The conductor uses hand signals and eye contact to tell each player when to come in and how fast to move.", "purpose_function": "It keeps an ensemble together during passages meant to breathe or float freely, where a mechanical, evenly counted beat would sound stiff and unmusical.", "practical_application": "A conductor gives clear preparatory gestures and eye contact to cue entrances and control rubato in cadenzas, freely timed openings, or film-score fermatas without a click track.", "category": "Conducting", "related_terms": ["Rubato", "Fermata", "Ad libitum", "Cue", "Tempo", "Downbeat"], "common_mistakes": ["Thinking free-time means no leadership; the conductor still tightly controls entrances and pacing through gesture.", "Beating a subdivided pulse anyway, forcing the rigid feel the passage is meant to avoid.", "Giving unclear or late preparatory gestures, causing ragged, mistimed ensemble entrances."], "scenario_contexts": ["Conducting a slow, rubato film-score cue recorded without a click track.", "Leading an ensemble through a cadenza or a freely timed opening phrase.", "Shaping a ritardando into a fermata and cueing its release."]}, "79923475-794e-49df-8132-25c70ab44c91": {"definition": "A sound-synthesis method in which the frequency of one oscillator (the carrier) is modulated at an audio rate by another oscillator (the modulator), generating sidebands that produce complex, harmonically rich timbres from simple sine sources.", "plain_english": "A way to build sounds by using one fast wobbling tone to shake the pitch of another tone. That shaking adds many extra tones (overtones), so a plain tone can turn bright, metallic, or bell-like.", "purpose_function": "It creates rich, evolving timbres such as bells, electric pianos, and brass efficiently, without needing many oscillators or recorded samples.", "practical_application": "A sound designer sets carrier-to-modulator ratios and modulation depth on an FM synth (such as a Yamaha DX7 or a software FM instrument) to dial in metallic, bell, or electric-piano tones.", "category": "Synthesis", "related_terms": ["Carrier", "Modulator", "Operator", "Sideband", "Additive synthesis", "Subtractive synthesis"], "common_mistakes": ["Confusing audio-rate FM synthesis with slow vibrato; only audio-rate modulation creates the sidebands that define FM timbres.", "Assuming more modulation always sounds better, when too much depth quickly turns the tone harsh and inharmonic.", "Swapping the carrier and modulator roles when setting the frequency ratio, giving an unexpected timbre."], "scenario_contexts": ["Programming an electric-piano patch on a DX7-style FM synth.", "Designing metallic or bell-like sound effects for a game or film.", "Recreating classic 1980s FM bass and lead sounds in a software instrument."]}, "9459314e-3bae-446f-a2d5-5989db7fcb61": {"definition": "A process that shifts every frequency component of a signal up or down by the same fixed number of hertz (a linear shift). Unlike pitch shifting, it does not preserve harmonic ratios, so the output becomes inharmonic and detuned.", "plain_english": "An effect that moves every part of a sound up or down by the same amount. Because low and high parts shift equally, their natural spacing breaks. The sound then turns metallic or out of tune.", "purpose_function": "It creates inharmonic, metallic, or dissonant textures for sound design, and historically has been used to nudge frequencies off a room's feedback tuning to gain a little feedback margin in sound reinforcement.", "practical_application": "An engineer uses a frequency-shifter plug-in for robotic or sci-fi effects, or applies a shift of a few hertz in a PA system to push back acoustic feedback.", "category": "Signal Processing", "related_terms": ["Pitch shifting", "Ring modulation", "Single-sideband modulation", "Heterodyning", "Acoustic feedback", "Modulation"], "common_mistakes": ["Confusing frequency shifting with pitch shifting; pitch shifting keeps harmonic ratios, frequency shifting does not.", "Expecting a musical transposition, when a linear hertz shift detunes the overtones and sounds inharmonic.", "Using too large a shift for feedback control, which audibly detunes the program material."], "scenario_contexts": ["Creating robotic or alien voices in film and game post.", "Adding a few hertz of shift to a live PA to raise the feedback threshold.", "Designing clangorous, metallic sound-design textures."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"8d16ebcf-77d6-469d-9539-e72f192555d2": {"definition": "A signal whose frequency changes continuously over time from a start to an end frequency, either linearly or logarithmically; also called a swept sine or chirp. It is used as a test stimulus to excite a system across its whole range, and sometimes as an effect.", "plain_english": "A tone that slides smoothly from a low pitch to a high one, or the other way. Engineers play it through a system to test how it responds at every pitch. It works a bit like running a finger up a piano to hear each note.", "purpose_function": "It exercises a device or room across its full frequency range so an engineer can measure frequency response, resonances, and distortion.", "practical_application": "A technician plays a logarithmic sine sweep through a loudspeaker and captures it with measurement software to derive the frequency response and impulse response.", "category": "Test & Measurement", "related_terms": ["Chirp", "Frequency response", "Impulse response", "Pink noise", "Signal generator", "Room measurement"], "common_mistakes": ["Playing a sweep at too high a level, which can distort or damage high-frequency drivers.", "UNSAFE: Running loud sweeps without hearing protection or without warning others nearby; sustained high-level tones can harm hearing.", "Using a linear sweep when a logarithmic sweep would give more even resolution and better distortion rejection."], "scenario_contexts": ["Measuring a loudspeaker's frequency and impulse response with a swept sine.", "Finding room resonances and ringing modes before tuning a system.", "Testing the usable bandwidth of a signal chain or crossover."]}, "287c3050-5cea-4c73-930a-60e336b77569": {"definition": "The listener's ability to judge whether a sound source lies in front of or behind the head, resolved mainly by spectral (pinna/HRTF) cues and small head movements, because interaural time and level differences alone are ambiguous along the front-back axis.", "plain_english": "Telling whether a sound comes from in front of you or from behind. Timing and loudness clues at the two ears are almost the same both ways. So your brain uses the way your outer ear colors the sound, plus small head turns, to decide.", "purpose_function": "It is part of how we locate sounds in three dimensions, and it matters wherever front-back cues must be reproduced correctly, as in surround, binaural, and immersive audio.", "practical_application": "A spatial-audio engineer relies on accurate pinna/HRTF cues, speaker placement, or head-tracking so that rear content does not collapse to the front for the listener.", "category": "Psychoacoustics", "related_terms": ["Localization", "Cone of confusion", "HRTF", "Binaural audio", "Interaural time difference", "Pinna cues"], "common_mistakes": ["Assuming interaural time and level differences alone locate a source; they cannot resolve front from back.", "Ignoring pinna/HRTF spectral cues when designing binaural or immersive mixes, causing front-back confusion.", "Expecting headphone playback without individualized HRTFs to give reliable front-back imaging."], "scenario_contexts": ["Mixing a surround or Atmos scene where a sound must clearly read as behind the listener.", "Designing binaural audio for VR and testing for front-back reversals.", "Diagnosing why rear-channel effects seem to collapse to the front on a given system."]}, "ca41804a-c6a0-43bb-9c73-2d7cd80d497b": {"definition": "The discipline of creating and implementing sound for interactive games, including dialogue, sound effects, music, and ambience, where the audio responds dynamically in real time to player actions and game state rather than following a fixed timeline.", "plain_english": "The sound side of video games: the effects, voices, music, and background noise you hear while playing. Unlike a movie, the sound changes as you play and reacts to what you do.", "purpose_function": "It provides interactive, responsive sound that gives the player feedback, builds atmosphere, and guides attention, adapting in real time to gameplay.", "practical_application": "Sound designers create assets and set up rules in audio middleware such as Wwise or FMOD so that sounds trigger, blend, and change with in-game events.", "category": "Game Audio", "related_terms": ["Game-audio designer", "Audio middleware", "Interactive audio", "Adaptive music", "Sound design", "Wwise"], "common_mistakes": ["Treating game audio like linear film audio, when game sound must be built to react to unpredictable player actions.", "Ignoring memory, voice-count, and CPU limits, so audio glitches or gets cut off at runtime.", "Delivering only finished mixes instead of implementing assets in middleware with proper triggers and states."], "scenario_contexts": ["Building a footstep system that changes with surface type in a game engine.", "Setting up adaptive music that shifts with combat intensity.", "Implementing sound events in middleware and mixing them against the game's states."]}, "3aeba52d-3e1f-408c-a32f-8d4b3109c1f3": {"definition": "The audio professional responsible for creating and implementing a game's sound: designing sound effects, dialogue, ambience, and often interactive music, and setting up how those assets behave in real time within the game engine or audio middleware.", "plain_english": "The person who makes and sets up the sounds in a video game. They create the effects and voices, then build the rules for how and when each sound plays as you play.", "purpose_function": "The role exists to produce and integrate all of a game's sound so it responds correctly to gameplay and supports feedback, immersion, and mood.", "practical_application": "They author assets in a DAW, then implement them in middleware such as Wwise or FMOD, wiring events, parameters, and mix states to the game engine.", "category": "Roles", "related_terms": ["Game audio", "Sound designer", "Audio middleware", "Technical sound designer", "Audio implementation", "Wwise"], "common_mistakes": ["Assuming the role is only asset creation, when implementation and real-time behavior are a core part of the job.", "Overlooking performance budgets (voices, memory, CPU) when designing sounds.", "Not collaborating early with programmers and designers, so audio hooks are missing in the build."], "scenario_contexts": ["Designing and implementing a weapon's layered sound set in Wwise.", "Balancing a game's runtime mix across dialogue, music, and effects.", "Debugging why an in-game event fails to trigger its sound."]}, "5e22c4a2-f1a3-4666-818e-66aecd0ae526": {"definition": "The runtime software system in a video game that plays back, processes, and spatializes audio in response to game events, typically implemented with audio middleware such as Audiokinetic Wwise or FMOD. It manages voice allocation, real-time mixing, DSP, and 3D positioning during play, unlike a linear DAW timeline.", "plain_english": "It is the part of a game that plays sound while you play. Instead of a fixed soundtrack, it picks and mixes sounds live as the game reacts to what you do.", "purpose_function": "It exists to turn game events and player actions into sound in real time, managing which sounds play, how they mix, and where they sit in 3D space so audio stays interactive rather than pre-rendered.", "practical_application": "A technician authors and tests audio behaviors inside the engine or its middleware, setting up events, buses, and DSP so assets trigger and mix correctly at runtime on each target platform.", "category": "Game Audio", "related_terms": ["Game-audio integrator", "Game-audio mixer", "Game-state parameter", "Gameplay audio", "Interactive audio"], "common_mistakes": ["Confusing a game-audio engine with a DAW; the engine responds to live game events rather than playing a fixed timeline.", "Assuming the engine chooses sounds on its own; behaviors must be authored in the middleware first.", "Ignoring platform voice limits, which causes sounds to be cut off or dropped at runtime."], "scenario_contexts": ["Setting up footstep sounds that change with the surface type during gameplay.", "Managing the number of simultaneous voices so a busy battle scene does not overload the CPU.", "Positioning a sound in 3D so it follows an on-screen character."]}, "016181fa-847a-4b31-b653-743b24427757": {"definition": "The practitioner who implements finished audio assets into a game's engine or middleware, building the events, parameters, and mix structures that determine how sound behaves in response to gameplay. The role bridges sound design and programming, focusing on runtime behavior rather than asset creation.", "plain_english": "This is the person who puts the sound files into the game and sets the rules for when they play. They connect the sounds a designer made to the actions in the game.", "purpose_function": "The role exists to translate creative audio content into working, interactive behavior, ensuring sounds trigger, mix, and adapt correctly as the game runs.", "practical_application": "Working in tools like Wwise or FMOD, the integrator wires audio events to game calls, sets up parameters and mix buses, and tests that assets play back properly on each target platform.", "category": "Game Audio", "related_terms": ["Game-audio engine", "Game-audio mixer", "Game-state parameter", "Gameplay audio", "Interactive audio"], "common_mistakes": ["Thinking the integrator creates the sounds; the role mainly implements assets others record or design.", "Leaving parameters untested, so audio behaves correctly in the tool but not in the running game.", "Forgetting platform memory and voice limits when integrating large sound sets."], "scenario_contexts": ["Hooking up a weapon's fire, reload, and impact sounds to the correct game events.", "Building a music system that shifts intensity as combat starts and ends.", "Debugging why a sound plays in the editor but not in the shipped build."]}, "a2e85104-1b0c-46e9-ac35-c3f8795dbaca": {"definition": "The practitioner responsible for balancing and mixing a game's audio, setting relative levels, dynamics, and spatial placement of dialogue, music, and effects within the engine or middleware so the mix holds together across unpredictable, interactive playback.", "plain_english": "This is the person who balances all the sounds in a game so nothing is too loud or too quiet. Because players act in different ways, the mix has to sound good no matter what happens.", "purpose_function": "The role exists to keep dialogue, music, and effects clear and well balanced during interactive play, where the exact combination of sounds is not known in advance.", "practical_application": "Using bus structures, side-chaining, and dynamic mix states in middleware, the mixer sets levels and priorities so important sounds stay audible during both busy and quiet moments.", "category": "Game Audio", "related_terms": ["Game-audio engine", "Game-audio integrator", "Game-state parameter", "Gameplay audio", "Real-time mixing"], "common_mistakes": ["Mixing for one playthrough only, so the balance breaks when players act differently.", "Overlooking dynamic range, leaving quiet detail lost or loud moments harsh.", "Not using priority or ducking, so critical dialogue gets buried under effects."], "scenario_contexts": ["Ducking background music and ambience so mission dialogue stays clear.", "Setting voice priorities so key sounds survive when many effects play at once.", "Building a mix state that changes when the player opens a menu or pauses."]}, "81f6bf3e-8003-4a82-875c-96968d00ed12": {"definition": "A continuously variable value exposed by the game to the audio system that reflects some aspect of game state — such as speed, health, or distance — and is mapped to audio properties in real time. In Wwise this is a Game Parameter driving an RTPC; in FMOD it is a parameter.", "plain_english": "It is a number the game keeps updating, like speed or health, that the sound system watches. As that number changes, it changes the sound, such as making engine noise rise with speed.", "purpose_function": "It exists to let audio respond smoothly and continuously to what is happening in the game, instead of only reacting to on/off events.", "practical_application": "A technician maps a parameter such as vehicle RPM to pitch or volume so the sound tracks the value automatically as the player drives.", "category": "Game Audio", "related_terms": ["Game-audio engine", "Game-audio integrator", "Game-audio mixer", "Gameplay audio", "Interactive audio"], "common_mistakes": ["Confusing a continuous parameter with a one-shot event trigger; the parameter changes sound gradually.", "Setting curves that jump, causing audible steps or zipper noise as the value moves.", "Not clamping the value range, so extreme game states push audio to unintended settings."], "scenario_contexts": ["Raising engine pitch as a car's speed increases.", "Making music more tense as the player's health drops.", "Opening a low-pass filter as the player moves closer to a sound source."]}, "ae7e20e8-b324-45a8-82af-29789be00b10": {"definition": "The interactive audio heard during active play — sound effects, dialogue, music, and ambience triggered and mixed in real time by the game engine — as distinct from linear, pre-rendered material such as cinematics or trailers.", "plain_english": "This is all the sound you hear while actually playing the game, made live as you play. It is different from the fixed sound in a cutscene or a movie clip.", "purpose_function": "It exists to give the player continuous, responsive audio feedback tied to their actions and the game world, supporting immersion and conveying gameplay information.", "practical_application": "Sound teams design and implement gameplay audio to react to events and parameters, testing it in the running game rather than on a fixed timeline.", "category": "Game Audio", "related_terms": ["Game-audio engine", "Gameplay sound effect", "Game-state parameter", "Game-audio mixer", "Interactive audio"], "common_mistakes": ["Treating gameplay audio like a linear mix; it must work across many possible player actions.", "Forgetting that repeated sounds need variation to avoid obvious looping.", "Mixing gameplay audio without testing on the target platform's speakers or headphones."], "scenario_contexts": ["Footsteps, gunfire, and ambience reacting live during a level.", "Interface sounds confirming a menu selection.", "Ambient audio shifting as the player moves between areas."]}, "b6cba015-d0d2-432a-97e0-0bcdcf56e9fd": {"definition": "A sound effect triggered by in-game actions or events during play — such as footsteps, weapon fire, item pickups, or impacts — implemented to fire and mix in real time rather than being fixed to a timeline.", "plain_english": "This is a sound that plays because of something you do in the game, like a jump, a hit, or picking up an item. The game plays it right when the action happens.", "purpose_function": "It exists to give immediate audio feedback for player and world actions, helping the player understand what is happening and making the world feel responsive.", "practical_application": "A technician links each effect to its game event and adds variation so it stays convincing when it plays many times.", "category": "Game Audio", "related_terms": ["Gameplay audio", "Game-audio engine", "Game-state parameter", "Game-audio integrator", "Foley"], "common_mistakes": ["Using one identical sample every time, which sounds fake after a few plays.", "Forgetting to limit how many copies can play at once, causing a harsh pile-up.", "Setting the effect too loud relative to dialogue and music."], "scenario_contexts": ["A coin pickup sound firing each time an item is collected.", "A footstep effect changing with the surface underfoot.", "An impact sound playing when a projectile hits a wall."]}, "12581676-9ae7-413c-b530-a0e36a147aa1": {"definition": "Ensuring that two mating audio or data connectors have opposite, compatible genders — a male (pin/plug) end joining a female (socket/receptacle) end. Where both ends share the same gender, a gender changer (an adapter with the same connector gender on both ends, e.g. female-to-female, used to join two same-gender connectors) is used to complete the connection.", "plain_english": "Plugs come in two types, often called male and female, and they only join if they are opposite. Gender matching just means checking that a plug and its socket fit together, and using a small adapter if they do not.", "purpose_function": "It exists to make sure cables and gear actually connect, since two same-gender ends cannot mate; matching genders keeps signal paths complete and reliable.", "practical_application": "When patching or building cables, a technician checks connector gender at each end and keeps gender changers on hand to bridge two same-gender connectors in the field.", "category": "Connectors", "related_terms": ["XLR connector", "Gender changer", "Adapter", "Patch cable", "Connector"], "common_mistakes": ["Assuming any two connectors will join; two male or two female ends will not mate.", "Confusing gender with connector type; an XLR and a TRS differ in type as well as gender.", "Forcing mismatched connectors, which can bend pins or damage the receptacle."], "scenario_contexts": ["Joining two male-ended cables using a female-to-female gender changer.", "Checking whether a device's rear panel needs a male or female cable end.", "Assembling a custom cable and choosing the correct connector gender for each end."]}, "6a9102d1-ff45-4d0b-abc4-00c370e8d1c8": {"definition": "In Foley and sound-effects work, the recorded sound of glass objects being handled — picked up, set down, clinked, or slid — performed to match on-screen action. It falls under the handling (prop) category of Foley, alongside footsteps and cloth moves.", "plain_english": "This is the Foley sound of glass being picked up, set down, or clinked, recorded to match what you see on screen. A Foley artist makes it by handling real glass in time with the picture.", "purpose_function": "It exists to add believable, synced sound for glass props that a scene needs but that the production recording did not capture cleanly.", "practical_application": "A Foley artist performs glass handling to picture on a Foley stage, and the editor syncs and mixes it into the effects stems.", "category": "Foley", "related_terms": ["Foley", "Handling noise", "Sound effects editing", "Foley stage", "Effects stem"], "common_mistakes": ["Recording glass handling out of sync with the on-screen movement.", "Using the wrong type of glass, so the sound does not match the object shown.", "UNSAFE: Handling or breaking glass without eye protection and cut-resistant gloves risks injury from shards."], "scenario_contexts": ["Adding the clink of a glass being set on a table in a dialogue scene.", "Replacing the sound of a character picking up a bottle.", "Building a layered sound for a hand sliding across a glass surface."]}, "c659712b-241c-48e5-882f-8763a503b01b": {"definition": "A sound-processing technique that breaks audio into very short segments called grains (typically about 1 to 100 ms) and recombines them — reordering, layering, repitching, or respacing them — to transform the sound. It underlies granular synthesis and effects such as time-stretching, texture generation, and pitch shifting.", "plain_english": "This chops a sound into tiny pieces, then plays them back in new ways to change how it sounds. It is a bit like cutting a recording into thousands of little bits and rearranging them into clouds of sound.", "purpose_function": "It exists to let a sound designer stretch, freeze, blur, or completely reshape a sound independently of its original speed and pitch.", "practical_application": "A technician uses a granular plug-in or synth to time-stretch dialogue, build evolving textures, or turn a short sample into a long ambient pad.", "category": "Signal Processing", "related_terms": ["Granular synthesis", "Time-stretching", "Pitch shifting", "Sound design", "Sampler"], "common_mistakes": ["Confusing grain size with pitch; grain length changes texture, not the note.", "Setting grains too short or too regular, which adds buzzy or metallic artifacts.", "Expecting clean results on transient-rich material without adjusting grain overlap."], "scenario_contexts": ["Stretching a two-second sample into a minute-long drone.", "Creating a shifting ambient texture from a single recorded note.", "Time-stretching production dialogue to fit a re-timed picture."]}, "f85e49d3-2100-4eb9-9c4e-76e7e2c75a1f": {"definition": "A Foley footstep performance created by stepping on loose gravel (or a gravel/dirt pit) in sync with the picture, producing the synchronized footstep sounds of a character moving over stony, rough ground.", "plain_english": "These are footstep sounds made by a Foley artist stepping on real gravel. They are added so a character on screen sounds like they are walking on small stones. It is like acting out the walk with your feet to match the movie.", "purpose_function": "It supplies realistic, sync-accurate footstep sounds for shots where the production audio lacks clean or convincing steps on stony ground, adding weight and texture to a character's movement.", "practical_application": "A Foley artist watches the picture and steps in a gravel pit in time with the actor, while the recordist captures separate takes for heels, scuffs and pivots to match each move.", "category": "Foley", "related_terms": ["Foley", "Footsteps", "Foley pit", "Hard sound effect", "Ambience", "Spotting session"], "common_mistakes": ["Looping one generic gravel sound instead of performing steps in sync with each footfall.", "Ignoring shoe type and body weight, so a heavy boot sounds the same as a light sneaker.", "Recording steps too evenly, losing the natural irregular rhythm of real walking.", "Failing to match the moisture and density of the surface heard or seen in the picture."], "scenario_contexts": ["Replacing footsteps for a character walking up a gravel driveway when production sound is unusable.", "Building a Foley track for a period drama where actors cross a stony courtyard.", "Adding footstep detail to a wide exterior shot filmed on a dirt-and-gravel road."]}, "c5b83aa1-4ccb-4de3-9b8b-01c2e20dfef7": {"definition": "In Foley, a hand-contact sound is a body-Foley effect made when a performer's hand touches, grips, pats or brushes against skin, clothing or a prop, giving on-screen hand movements an audible point of contact.", "plain_english": "This is the small sound a hand makes when it touches something, like skin, cloth, or an object. Foley artists add these touches so hand movements on screen sound real. Without them, a handshake or a pat can feel silent.", "purpose_function": "It adds subtle, believable contact sounds to hand gestures and touches that production microphones rarely capture, helping physical actions feel tangible.", "practical_application": "A Foley artist pats their own arm, a prop or a cushion in sync with an actor shaking hands, gripping a rail or resting a palm on a table, recording each touch as its own contact.", "category": "Foley", "related_terms": ["Foley", "Hand slap", "Foley moves", "Cloth pass", "Hard sound effect", "Spotting session"], "common_mistakes": ["Making hand contacts too loud, so gentle touches sound like slaps.", "Skipping contacts entirely, leaving hand gestures feeling silent and fake.", "Using the wrong material, so a hand on metal sounds like a hand on wood.", "Failing to match the force of the touch shown on screen."], "scenario_contexts": ["Adding the sound of two characters shaking hands in a dialogue scene.", "Foleying a character gripping a ladder rung during a climb.", "Covering the touch of a hand placed on a shoulder in an emotional moment."]}, "f2ee52f3-ebf0-4668-a744-812c3513808b": {"definition": "A hand slap is a sharp, percussive sound effect made by striking a flat hand against a surface, skin or another hand, used in Foley and sound design to cover on-screen slaps, pats, high-fives and impact accents.", "plain_english": "A hand slap is the sharp smack you hear when a flat hand hits something. Sound artists make it to match a slap, a high-five, or a pat on screen. They pick the surface and force so it fits the action.", "purpose_function": "It delivers a crisp, well-timed impact sound for hand strikes that need clear emphasis and sync, since real on-set slaps are often mistimed, unsafe to perform, or poorly recorded.", "practical_application": "A Foley artist slaps a palm against skin, a leather cushion or a tabletop in sync with the picture, choosing the surface and strength to match the shot's intensity.", "category": "Foley", "related_terms": ["Foley", "Hand contact", "Hard sound effect", "Impact", "Sweetener", "Spotting session"], "common_mistakes": ["Placing the slap off-sync so the sound lands before or after the on-screen hit.", "Using a slap that is too thin or too big for the action shown.", "Recording only one take, leaving no options to fit the picture.", "Adding heavy reverb that smears the sharp transient."], "scenario_contexts": ["Covering a dramatic face slap in a confrontation scene.", "Adding a crisp high-five between two characters.", "Sweetening a fight sequence where a slap needs extra snap."]}, "3eba25e6-a019-4e1d-a5e7-d26035458016": {"definition": "In Foley, the practice of performing and editing hand-related sounds — grabs, pats, claps and prop contacts — so they line up precisely, frame by frame, with the actor's hand movements on screen.", "plain_english": "It means making the sound of hands match what the hands do on screen. If the actor claps, the clap sound must land at the exact same moment.", "purpose_function": "It restores believable, sync-accurate hand sounds that the production microphone missed or captured poorly, keeping what the audience sees and hears in agreement.", "practical_application": "A Foley artist loops the picture and re-performs each hand action to a monitor, then the Foley editor nudges the takes in the DAW until every contact hits its frame.", "category": "Foley", "related_terms": ["Hand contact", "Hand slap", "Picture synchronization", "Hit point", "Heel strike"], "common_mistakes": ["Treating rough sync as good enough — hand sounds even a frame or two off read as fake to the audience.", "Performing the motion without watching the picture, so the rhythm of the sounds drifts from the on-screen action.", "Doubling hand sounds that already exist in usable production audio."], "scenario_contexts": ["Adding clap and handshake sounds to a dialogue scene shot on a noisy location.", "Re-syncing hand pats and applause for a crowd insert.", "Matching prop-handling hand contacts in an ADR-heavy scene where production audio was discarded."]}, "6bb014c1-109f-4913-bb70-4252345692e9": {"definition": "A hard sound effect (or 'hard effect') is a synchronous, cut-to-picture sound effect tied to a specific on-screen action or event — such as a gunshot, door slam, phone ring or car pass-by — as distinct from continuous backgrounds/ambiences or performed Foley.", "plain_english": "A hard sound effect is a sound tied to one clear action on screen, like a gunshot or a door slam. It is cut so it hits exactly when the action happens. This is different from steady background sounds that just fill a scene.", "purpose_function": "It provides the specific, sync-critical event sounds that sell key on-screen actions, forming the sound-effects layer that sits between ambient backgrounds and performed Foley.", "practical_application": "A sound-effects editor spots each event, pulls a matching library or recorded effect, and cuts it frame-accurately to the action, often layering several files to build the final sound.", "category": "Sound effects", "related_terms": ["Foley", "Ambience", "Sound effects editing", "Spotting session", "Sync point", "Sweetener"], "common_mistakes": ["Confusing hard effects with Foley; hard effects are cut from recordings, while Foley is performed to picture.", "Placing an effect a frame or two off, which breaks the sense of sync.", "Relying on a single library file without layering for weight and realism.", "Forgetting to match the effect's perspective and space to the shot."], "scenario_contexts": ["Cutting a gunshot to each muzzle flash in an action scene.", "Adding a door slam and latch to a character leaving a room.", "Placing a phone ring and a car horn as specific events in a city scene."]}, "fe2702a6-1c7a-4d5e-8397-de72d0545e86": {"definition": "Harmonic resynthesis analyzes a sound into its component partials (their frequencies, amplitudes and phases over time) and then reconstructs the sound from those partials, so the harmonic content can be edited, pitch-shifted, time-stretched or cleaned before it is synthesized again.", "plain_english": "Harmonic resynthesis breaks a sound into its separate tone layers, then rebuilds it from those layers. Because it is rebuilt, you can change its pitch or length, or clean it up first. Think of splitting one note into its individual overtones, then rebuilding it however you like.", "purpose_function": "It lets an engineer reshape a sound at the level of its individual harmonics — for tuning, stretching, noise removal or creative morphing — instead of treating the recording as a fixed waveform.", "practical_application": "In tools such as Melodyne or spectral editors, a dialogue or music editor uses harmonic resynthesis to retune a note, remove a tonal artifact, or stretch a sound while keeping it natural.", "category": "Signal processing", "related_terms": ["Additive synthesis", "Spectral editing", "Time stretching", "Pitch shifting", "Fourier analysis", "Formant"], "common_mistakes": ["Assuming resynthesis is lossless; strong edits can add artifacts or a synthetic quality.", "Pushing pitch or time too far, which exposes smearing and phase problems.", "Forgetting that noisy or inharmonic sounds resynthesize poorly.", "Confusing resynthesis with simple EQ, which only filters the original waveform."], "scenario_contexts": ["Retuning an off-pitch sung note in a music mix.", "Removing a ringing tone from dialogue without dulling the voice.", "Time-stretching a sound effect to fit a longer on-screen action."]}, "02189d6e-4d30-4ed2-9c4f-0f59817916b8": {"definition": "A head-related transfer function (HRTF) is the frequency- and direction-dependent filtering that a listener's head, torso and outer ears (pinnae) impose on a sound travelling from a source to the eardrum, encoding the spatial cues the brain uses to localize sound; it is normally measured as a left/right pair of responses for many source directions.", "plain_english": "An HRTF describes how your head and ears change a sound depending on where it comes from. Your brain uses these tiny changes to tell if a sound is to your left, right, above, or behind you. Headphone apps copy these changes to make sounds seem to come from all around you.", "purpose_function": "It captures the direction-dependent cues — level, timing and spectral shaping between the two ears — that let the brain localize sound, and it is the basis for binaural and immersive audio rendered over headphones.", "practical_application": "A technician loads HRTF-based processing, such as a binaural renderer or immersive mix tool, so a headphone mix places dialogue, effects and music at specific positions around the listener.", "category": "Psychoacoustics", "related_terms": ["Binaural audio", "Interaural time difference", "Interaural level difference", "Spatial audio", "Immersive audio", "Localization"], "common_mistakes": ["Assuming one generic HRTF fits everyone; individual ear shapes change localization accuracy.", "Expecting HRTF cues to translate to loudspeakers, where crosstalk changes the result.", "Confusing an HRTF (a directional filter) with reverb, which adds room reflections rather than directional cues.", "Ignoring the front/back and up/down confusions that generic HRTFs commonly cause."], "scenario_contexts": ["Rendering a binaural headphone mix of a Dolby Atmos program.", "Building a VR or game audio engine that positions sounds around the player.", "Creating an immersive music mix intended for headphone listening."]}, "634e9e21-d40c-4fd9-a6ec-dc1d2b764f3f": {"definition": "A dedicated listening space used to audition a finished mix over reference headphones, confirming that its balance, dialogue clarity and spatial imaging translate for the large audience that listens on headphones and earbuds.", "plain_english": "It is a room set up to check how a mix sounds through headphones. Many people watch shows with earbuds, so mixers make sure it still sounds right there.", "purpose_function": "It exists because a mix balanced on room monitors can shift on headphones, so a controlled headphone check protects dialogue and spatial cues for headphone listeners.", "practical_application": "A re-recording mixer takes a near-final mix into this space, plays it on calibrated headphones, and flags any dialogue, bass or panning that only works on the main monitors.", "category": "Post Facilities", "related_terms": ["Immersive-audio mixing room", "Screening room", "Picture monitor", "Post-production suite", "Post-production facility"], "common_mistakes": ["Assuming a mix that sounds great on studio monitors will automatically translate to headphones.", "Judging headphone translation on random consumer earbuds instead of a known reference set.", "Monitoring too loud on headphones, which hides balance problems that appear at normal listening levels."], "scenario_contexts": ["Checking a streaming series mix that most viewers will hear on earbuds.", "Confirming a binaural or immersive headphone render before delivery.", "Spotting a boosted low end that only becomes obvious on closed-back headphones."]}, "9b833db6-04ac-4844-95ec-6bd248452b7f": {"definition": "A game parameter (real-time parameter control) that reports a character's or object's remaining health to the audio engine, letting the game's sound change continuously as that health value rises or falls.", "plain_english": "It is a number from the game that tells the sound system how healthy a character is. As health drops, the audio can change, like a heartbeat that gets louder when you are hurt.", "purpose_function": "It links game state to sound so audio can react to health in real time — muffling the mix, adding a heartbeat, or shifting the music when a player nears death.", "practical_application": "A game-audio implementer maps the health parameter to a low-pass filter and a heartbeat loop in Wwise or FMOD, so the mix darkens and the pulse rises as health falls toward zero.", "category": "Interactive Audio", "related_terms": ["Parameter-driven audio", "Positional audio", "Procedural ambience", "Playback behavior", "Physics-driven sound"], "common_mistakes": ["Confusing the health parameter (a game value) with the audio effects it drives, such as the heartbeat itself.", "Mapping health to sound with an abrupt curve, so the audio jumps instead of changing smoothly.", "Updating the parameter too infrequently, causing audible stepping as health changes."], "scenario_contexts": ["Adding a rising heartbeat as a player's health drops in a shooter.", "Muffling and desaturating the mix during a low-health near-death state.", "Switching music intensity when a boss's health crosses a threshold."]}, "5342c78a-95dd-42c9-aa10-55f0aae924d9": {"definition": "In Foley footstep performance, the heel strike is the initial contact of the shoe's heel with the surface at the start of a footfall, producing the first sharp transient before the weight rolls through to the ball and toe.", "plain_english": "A heel strike is the first tap of a footstep, when the back of the shoe hits the ground. Foley artists make this sound by hand so people walking on screen sound real.", "purpose_function": "It gives each footstep a defined attack and a sense of weight and gait, letting synced footsteps read as convincing, grounded human movement.", "practical_application": "The Foley walker performs heel-then-toe against picture on a matched surface, emphasizing or softening the heel strike to fit the character's pace, weight, and footwear.", "category": "Foley", "related_terms": ["High-heel Foley", "Footsteps", "Foley pit", "Heel-toe technique", "Sync point", "Surfaces"], "common_mistakes": ["Landing flat-footed so steps lack the natural heel transient and sound artificial.", "Ignoring the actor's gait and weight, so footsteps fall out of sync or feel mismatched.", "Using the wrong surface, so the heel strike does not match the floor seen on screen."], "scenario_contexts": ["Footstepping a character walking across a hardwood floor.", "Matching a heavy villain's slow, weighty heel strikes.", "Replacing noisy production footsteps in a dialogue scene."]}, "88549e04-2e0f-454d-908f-db66ec09ee40": {"definition": "High-heel Foley is the performance and recording of footsteps for characters wearing high-heeled shoes, capturing the distinctive sharp, hard-heeled click and the narrow heel contact against each surface.", "plain_english": "This is Foley made with high-heeled shoes to match an actor wearing heels. The artist walks in heels on the right floor so each sharp click lines up with the picture.", "purpose_function": "It supplies footstep sounds that match on-screen heeled footwear, conveying the character, poise, and pace that generic footsteps cannot.", "practical_application": "The Foley artist wears or hand-operates real heels, walking in sync on matched surfaces and adjusting pace and pressure to fit the actor's movement and mood.", "category": "Foley", "related_terms": ["Heel strike", "Footsteps", "Foley pit", "Surfaces", "Sync point", "Props"], "common_mistakes": ["Using flat-shoe footsteps for a heeled character, losing the characteristic sharp click.", "Not matching the surface, so the heel tone is wrong for the floor on screen.", "Overplaying the clicks so they distract from the dialogue."], "scenario_contexts": ["Footstepping an actress crossing a marble lobby in heels.", "Adding tension to a slow, deliberate walk down a corridor.", "Replacing heel footsteps lost under location noise."]}, "a58e251e-1ab0-4ef0-9b81-f8056e77758e": {"definition": "A hit point (also called a sync point or catch point) is a specific moment in the picture where the music or a sound effect is deliberately aligned to coincide with an on-screen action or dramatic accent.", "plain_english": "A hit point is a moment where the music must land exactly with something on screen. Think of a punch or a door slam. Composers mark these spots so the music hits them right on time.", "purpose_function": "It anchors the score or effect to the image, reinforcing key story beats and making the audio feel purpose-built for the scene.", "practical_application": "During spotting, the composer or editor logs hit points as timecoded markers, then shapes tempo maps or edits so downbeats and accents fall exactly on those frames.", "category": "Synchronization", "related_terms": ["Spotting session", "Sync point", "Timecode", "Marker", "Mickey-mousing", "Tempo map"], "common_mistakes": ["Confusing a hit point with a general scene marker; a hit point specifically calls for musical or sound emphasis.", "Placing hits by ear without locking markers to timecode, so they drift when the tempo changes.", "Over-hitting every action (excessive Mickey-mousing), which makes the score feel cartoonish."], "scenario_contexts": ["Aligning an orchestral accent to a sword strike in an action scene.", "Marking the frame where a title card appears so the cue swells to it.", "Syncing a low boom to a hard cut in a trailer."]}, "b2a657c5-2321-42e2-909a-73ac42585f29": {"definition": "Hybrid layering is the technique of stacking organic recorded elements with synthesized or heavily processed elements into a single composite sound, blending real-world detail with designed weight or character.", "plain_english": "Hybrid layering means stacking real recorded sounds with computer-made sounds to build one bigger sound. It is like mixing a real drum hit with a synth boom to make it feel huge.", "purpose_function": "It lets a sound designer combine the realism of recordings with the size and tone of synthesis, producing sounds that are both believable and larger than life.", "practical_application": "A designer might layer a recorded metal clang with a synth sub and a processed whoosh, tuning each layer's level and timing so they fuse into one convincing hit.", "category": "Sound design", "related_terms": ["Hybrid sound design", "Layering", "Sweetener", "Sub drop", "Impact tail", "Transient"], "common_mistakes": ["Stacking so many layers that the result turns muddy instead of powerful.", "Not time-aligning the layers, so the transients smear.", "Relying only on synth layers and losing believable organic detail."], "scenario_contexts": ["Building a sci-fi weapon by layering real recordings with synth tones.", "Reinforcing a punch with a recorded impact plus a low synth body.", "Designing a creature vocal from animal recordings and processed synth."]}, "795e9368-267a-4d81-9969-75d798da9d6a": {"definition": "Hybrid sound design is an approach that combines recorded, real-world sources with synthesized and processed sound, drawing on both to create effects that feel grounded yet stylized or otherworldly.", "plain_english": "Hybrid sound design blends real recorded sounds with synth and computer sounds. Using both gives sounds that feel real but also bigger and stranger than life.", "purpose_function": "It exists to give designers the authenticity of field recordings together with the control and impossibility of synthesis, for modern film, game, and trailer sound.", "practical_application": "A sound designer records real materials, then augments or reshapes them with synthesizers and plug-ins, layering and processing until the effect suits the picture.", "category": "Sound design", "related_terms": ["Hybrid layering", "Sound design", "Foley", "Synthesis", "Field recording", "Sweetener"], "common_mistakes": ["Treating 'hybrid' as purely synthetic and dropping all organic recordings.", "Over-processing until the sound loses any real-world reference.", "Ignoring the picture's tone, so stylized design fights a realistic scene."], "scenario_contexts": ["Designing the sound world of a science-fiction film.", "Creating a game's magic and weapon effects.", "Building a movie trailer's impacts and risers."]}, "192d3010-3e80-4ebb-9e74-0b5a6925b8f0": {"definition": "Hyper-real Foley is Foley performed and processed to be more detailed, present, and impactful than the action would sound in reality, heightening everyday movements for dramatic effect.", "plain_english": "Hyper-real Foley makes everyday sounds bigger and clearer than they really are. A punch or a footstep is boosted so it feels more exciting than in real life.", "purpose_function": "It amplifies the emotional and physical presence of on-screen actions, drawing the audience's attention and giving scenes a heightened, cinematic feel.", "practical_application": "The Foley artist and mixer exaggerate cloth, footsteps, and prop handling, performing bigger and adding EQ, layering, or processing so ordinary movements feel vivid and intense.", "category": "Foley", "related_terms": ["Foley", "Heel strike", "Sweetener", "Sound design", "Hybrid layering", "Cloth pass"], "common_mistakes": ["Pushing effects so far they break believability and pull viewers out of the scene.", "Applying hyper-real treatment everywhere instead of only where the story needs emphasis.", "Letting exaggerated Foley mask or fight the dialogue."], "scenario_contexts": ["Heightening every movement in a tense action or horror beat.", "Making a superhero's punches and landings feel powerful.", "Emphasizing a character's handling of a key prop."]}, "78b06fdb-fb22-43e6-b1bf-396c6d7ec73e": {"definition": "An immersive-audio mixing room is a control room designed and calibrated for object- and channel-based immersive formats such as Dolby Atmos, using a bed of ear-level surround speakers plus overhead height speakers (commonly a 7.1.4 layout) and a renderer so sounds can be placed anywhere in three-dimensional space.", "plain_english": "This is a mix room with speakers all around you and even above your head. The mixer can place each sound in the space so it seems to come from any side, as in Dolby Atmos films.", "purpose_function": "It provides an accurate, standards-calibrated environment for monitoring and mixing height-inclusive immersive audio, so the mix translates to cinema and consumer immersive playback.", "practical_application": "Re-recording mixers work here with a Dolby Atmos renderer, panning objects around and overhead, checking bed and object levels, and confirming the mix folds down correctly to 5.1 and stereo.", "category": "Immersive mixing", "related_terms": ["Dolby Atmos", "Bed", "Object-based audio", "Height channels", "LFE", "Renderer"], "common_mistakes": ["Assuming any 5.1 room can mix Atmos without adding calibrated height speakers.", "Neglecting bass management and time-alignment across the added overhead speakers.", "Mixing only for the immersive format and never checking the stereo and 5.1 fold-down deliverables."], "scenario_contexts": ["Mixing a feature's Dolby Atmos theatrical deliverable.", "Creating a 7.1.4 near-field immersive music mix.", "Rendering and QC-ing an Atmos master plus its binaural and 5.1 re-renders."]}, "03d52bdc-e0fd-4487-9eee-cd697d3c7de0": {"definition": "A game-audio system that generates collision and impact sounds at runtime by taking physics data — such as material type, velocity and mass — and selecting or shaping the appropriate hit, thud or crash.", "plain_english": "It is a set-up that makes crash and bump sounds by itself when things collide in a game. It picks the right sound based on what hit what and how hard.", "purpose_function": "It exists so that unpredictable, physics-driven collisions still produce believable, varied impact sounds without a sound designer hand-placing every hit.", "practical_application": "An implementer connects the physics engine's collision events to sound containers keyed by material and velocity, so a light tap and a heavy crash draw from different samples.", "category": "Interactive Audio", "related_terms": ["Physics-driven sound", "Impact tail", "Parameter-driven audio", "Positional audio", "Procedural ambience"], "common_mistakes": ["Triggering one impact sound regardless of velocity, so gentle and violent hits sound identical.", "Not limiting simultaneous impacts, so a pile-up of collisions creates a harsh, distorted burst.", "Ignoring material data, so a metal-on-stone hit plays a wood sound."], "scenario_contexts": ["Generating debris and impact sounds as a physics-driven structure collapses.", "Playing correct hit sounds when objects of different materials collide in a sandbox game.", "Scaling impact loudness with collision force in a racing or combat title."]}, "7a7c010b-ecb2-4744-ae0d-01b3d3720aee": {"definition": "An impact tail is the resonant decay — the ring, rumble, or reverberant wash — that follows the sharp transient of an impact or hit, sustaining and coloring the sound after its initial strike.", "plain_english": "An impact tail is the ring or rumble that keeps going right after a big hit. Like the boom fading away after a heavy door slam, it makes the hit feel powerful.", "purpose_function": "It gives an impact its sense of size, space, and power, letting a brief hit feel weighty and keep resonating rather than stopping abruptly.", "practical_application": "A designer shapes the impact tail with reverb, pitch, and layered sub or debris elements, then edits its length so hits sit correctly against picture and do not clutter the mix.", "category": "Sound design", "related_terms": ["Reverb tail", "Sub drop", "Layering", "Transient", "Whoosh", "Hybrid layering"], "common_mistakes": ["Cutting the tail too short, so the hit feels small and abrupt.", "Letting tails overlap and pile up until the low end turns muddy.", "Adding so much reverb tail that the transient loses its punch."], "scenario_contexts": ["Designing a cinematic trailer impact with a long sub tail.", "Adding a resonant tail to a door slam in a large room.", "Shaping the decay of an explosion hit to match the cut."]}, "943790d2-7b2b-4416-a284-276efa28b0a7": {"definition": "The precise placement of an impact sound — a hit, collision, footfall accent, or blow — so it lands in sync with the visual event or musical beat it supports. Editors may push it a frame or two early or late so the moment reads with the right weight and force.", "plain_english": "This is lining up a hit sound with the moment you see the hit on screen. The editor moves the sound a little until the punch or crash feels solid.", "purpose_function": "It exists to make on-screen hits and accents feel powerful and believable by matching their sound tightly to the picture or the beat.", "practical_application": "An editor nudges an impact sound against the picture frame by frame until the hit feels right, then locks it to the cut.", "category": "Sound Editing", "related_terms": ["Sync point", "Spotting", "Sound effects editing", "Foley", "Hit point"], "common_mistakes": ["Placing the sound exactly on the contact frame when leading it slightly would feel more powerful.", "Ignoring the sound's own attack time, so the hit feels late even when it looks aligned.", "Using identical timing on every hit, which flattens the sense of weight and variation."], "scenario_contexts": ["Syncing a punch to the frame a fist connects in a fight scene.", "Timing a car crash so the metal and glass land together.", "Aligning a weapon impact to the moment a projectile strikes in a game."]}, "869fb0ed-6799-4038-9f12-6d791e4222fc": {"definition": "The real-time audio mix heard during active gameplay, produced by the game engine or middleware as it balances dialogue, music, effects, and ambience in response to player actions. It differs from the fixed mix of pre-rendered cinematics or trailers because the exact combination of sounds is not known in advance.", "plain_english": "This is how a game sounds while you are actually playing it. The game balances the voices, music, and effects live, so the mix changes as you move and act.", "purpose_function": "It exists to keep a game's sounds clear and well balanced during unpredictable, interactive play, where the exact set of sounds cannot be planned ahead.", "practical_application": "A game mixer sets bus levels, voice priorities, and ducking rules in middleware so the in-game mix holds up across busy fights and quiet exploration alike.", "category": "Game Audio", "related_terms": ["Interactive audio", "Game-audio mixer", "Real-time mixing", "Interactive mix bus", "Cinematic mix"], "common_mistakes": ["Mixing for one playthrough only, so the balance breaks when players act differently.", "Confusing the in-game mix with the cinematic mix, which is fixed and pre-rendered.", "Skipping ducking or priority, so key dialogue gets buried under effects."], "scenario_contexts": ["Balancing gunfire, music, and voice during a live firefight.", "Ducking music under mission dialogue while the player keeps moving.", "Checking the mix on both TV speakers and headphones."]}, "2d29e75b-e53e-4517-906a-5947dc4ac9d3": {"definition": "A continuously variable game parameter that represents how intense the current gameplay is — such as combat level, threat, or excitement — and is mapped to audio behavior so music and effects respond in real time. In Wwise it is typically a Game Parameter driving an RTPC; in FMOD it is a parameter.", "plain_english": "This is a number the game raises and lowers to show how tense things are, like how much fighting is going on. The sound system watches it and makes the music build up or calm down to match.", "purpose_function": "It exists to let music and sound follow the heat of the moment automatically, rising during action and easing off when things settle.", "practical_application": "A composer or integrator maps the intensity value to music layers or filters so the score swells as combat ramps up and thins out when it ends.", "category": "Game Audio", "related_terms": ["Interactive music system", "Game-state parameter", "Interactive audio", "Vertical layering", "RTPC"], "common_mistakes": ["Confusing the smooth intensity value with a simple on or off event trigger.", "Setting jumpy curves, so the music steps abruptly instead of building smoothly.", "Not clamping the value range, so extreme game states push audio to unintended settings."], "scenario_contexts": ["Adding music layers as combat intensity climbs.", "Easing tense strings back as a chase winds down.", "Driving reverb or filtering from a rising threat value."]}, "c25d86a4-5b96-4f68-8509-25814bdc1856": {"definition": "Audio that responds in real time to user input or system state, changing what plays and how it is mixed based on events and parameters rather than following a fixed timeline. It is the defining characteristic of game and other real-time audio, as opposed to linear, pre-rendered playback.", "plain_english": "This is sound that reacts to what you do. Instead of playing the same fixed track every time, it changes live based on your actions and the situation.", "purpose_function": "It exists to make sound respond to the user and the current situation, so audio reflects actions and changing conditions instead of repeating one set recording.", "practical_application": "A sound designer authors events and parameters in middleware such as Wwise or FMOD so audio triggers, adapts, and mixes itself as the user plays.", "category": "Game Audio", "related_terms": ["Interactive music system", "Game-audio engine", "Game-state parameter", "Adaptive audio", "In-game mix"], "common_mistakes": ["Treating interactive audio like a linear mix that plays the same way every time.", "Forgetting that repeated sounds need variation to avoid an obvious loop.", "Confusing interactive audio, which reacts to input, with a simple background loop."], "scenario_contexts": ["Footsteps changing with surface and speed as a player moves.", "A menu sound firing the moment a button is pressed.", "Music shifting when the player enters combat."]}, "084967d0-2d8d-480d-b28e-208506a591a8": {"definition": "A mix bus in a game audio engine whose levels, processing, or routing change in real time in response to game state — for example a bus that ducks, boosts, or filters a group of sounds when the player opens a menu, goes underwater, or takes damage. It groups related sounds so the interactive mix can act on them together.", "plain_english": "This is a channel that several game sounds share, and its settings change live as you play. For example, it can quiet all the world sounds at once the moment you open a menu.", "purpose_function": "It exists to let the game adjust whole groups of sounds together in real time, keeping the mix balanced as conditions change.", "practical_application": "An integrator routes sounds to interactive buses and sets mix states or side-chains so the engine reshapes the balance automatically during play.", "category": "Game Audio", "related_terms": ["In-game mix", "Real-time mixing", "Ducking", "Interactive audio", "Game-audio mixer"], "common_mistakes": ["Treating the bus as a fixed group when its whole point is to change with game state.", "Not testing overlapping states, so two mix changes fight and cause level jumps.", "Routing a sound to the wrong bus, so a mix change affects the wrong group."], "scenario_contexts": ["Ducking a world-sound bus when a menu opens.", "Low-pass filtering an effects bus while the player is underwater.", "Boosting a music bus during a scripted set piece."]}, "af64ee25-eb09-4ddd-87f0-4c407de1c9a1": {"definition": "A system that changes a game's music in real time to match gameplay, using techniques such as vertical layering (adding or removing instrument layers) and horizontal re-sequencing (switching between musical segments) driven by game events and parameters. It keeps the score musical while adapting to unpredictable play.", "plain_english": "This is the part of a game that changes the music as you play. It can add instruments or switch to a new section when the action heats up, instead of looping one fixed track.", "purpose_function": "It exists to keep a game's music matched to the mood and action while staying smooth and musical, even though the player's path is not known in advance.", "practical_application": "A composer builds layers and segments, and an integrator wires them to parameters like intensity so the music transitions cleanly as the game changes.", "category": "Game Audio", "related_terms": ["Interactive audio", "Intensity parameter", "Vertical layering", "Horizontal re-sequencing", "Adaptive music"], "common_mistakes": ["Writing music that only works as one fixed loop, so transitions sound abrupt.", "Ignoring musical timing on switches, so changes land off the beat.", "Building so many layers that the system becomes hard to balance and test."], "scenario_contexts": ["Adding a percussion layer as combat intensity rises.", "Switching from an exploration theme to a battle theme on a musical bar.", "Fading music down to a calm layer when the player reaches safety."]}, "10f4eec6-16f7-4d8f-8ab8-3cc0b4469c23": {"definition": "Processing applied to a voice recording to make it sound as if it is coming through an intercom or communication device, typically by band-limiting the frequency range and adding compression, light distortion, and sometimes noise. It is a form of source or \"futz\" treatment used to place dialogue inside a speaker, radio, or headset within the story world.", "plain_english": "This is the effect that makes a voice sound like it is coming through an intercom or radio. It cuts the low and high tones and adds a little grit so the voice seems to come from a small speaker.", "purpose_function": "It exists to make a character's dialogue believably match an on-screen or in-world speaker, radio, or headset instead of sounding like a clean studio recording.", "practical_application": "A dialogue editor or mixer runs the line through EQ, compression, and distortion — often a dedicated futz plug-in — to place the voice inside the device the scene shows.", "category": "Dialogue Editing", "related_terms": ["Futz", "Worldizing", "Dialogue editing", "Band-pass filter", "Production dialogue"], "common_mistakes": ["Cutting too much frequency, so the line becomes hard to understand.", "Applying the same treatment to every device, ignoring how a radio, phone, and PA differ.", "Processing the original file with no clean copy kept for later changes."], "scenario_contexts": ["Making a pilot's voice sound like it comes over a cockpit intercom.", "Treating a guard's line heard over a building PA speaker.", "Creating radio chatter for soldiers talking over headsets."]}, "ada439d8-42df-46f8-aa55-0268edb303c5": {"definition": "A sound that gives feedback for a user-interface action in a game or application — such as a menu move, button press, confirmation, or error — usually short, non-diegetic, and triggered directly by the interface rather than by the game world.", "plain_english": "This is a short sound that plays when you use a menu, like a click when you press a button or a beep when you choose something. It tells you your action worked.", "purpose_function": "It exists to confirm and guide a user's interface actions with clear, immediate audio feedback, making menus feel responsive and easy to use.", "practical_application": "A sound designer creates and assigns interface sounds to events like hover, select, confirm, and cancel, then balances them so they are noticeable but not tiring.", "category": "Game Audio", "related_terms": ["Interactive audio", "Gameplay audio", "Non-diegetic sound", "Sound effect", "User feedback"], "common_mistakes": ["Making interface sounds too loud or harsh, so they tire the user quickly.", "Reusing one sound for different actions, so the user cannot tell them apart.", "Forgetting hover or error sounds, leaving some actions with no feedback."], "scenario_contexts": ["A click as the player moves through a menu.", "A confirmation chime when a purchase completes.", "An error buzz when an action is not allowed."]}, "dbf99a52-21db-422c-8b1b-61dba87c64a0": {"definition": "A version of a program's final mix that omits the original-language dialogue while keeping music and effects — a music-and-effects (M&E) mix — so the dialogue can be replaced with a dubbed foreign-language track. It is a standard deliverable that lets a film or show be released in other languages without remaking the whole soundtrack.", "plain_english": "This is a version of the soundtrack that keeps the music and sound effects but drops the spoken lines. Other countries add their own language over it, so the film can be shown around the world.", "purpose_function": "It exists to let a program be dubbed into other languages by supplying a full soundtrack minus dialogue, ready for a new voice track.", "practical_application": "A re-recording mixer prints an M&E stem alongside the main mix, checking that effects and Foley cover any sounds that were tied to the removed dialogue.", "category": "Deliverables", "related_terms": ["M&E", "Stem", "Dubbing", "Foley", "Re-recording mix"], "common_mistakes": ["Leaving dialogue-linked effects only in the dialogue stem, so the M&E has gaps.", "Forgetting on-camera vocals like efforts or crowd walla that a dub still needs.", "Confusing the international mix with a full mix that still contains the original dialogue."], "scenario_contexts": ["Delivering an M&E mix so a film can be dubbed into Spanish and French.", "Filling effects gaps left where original dialogue also carried a sound.", "Supplying music-and-effects stems to a streaming platform's localization team."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"7514b4f0-e1b7-41bf-8c31-1d0c9c6e13d6": {"definition": "A Foley 'moves' cue that recreates the cloth sounds of a jacket as a character moves, dresses, or gestures, performed in sync to picture and recorded to replace or reinforce the garment's rustle.", "plain_english": "It is the sound of a jacket rustling as someone moves. A Foley artist makes this sound by hand in a studio while watching the film. It fills in noise the camera mic missed.", "purpose_function": "It restores the natural clothing sounds a scene needs for realism, which are often thin or missing on the production dialogue tracks, and gives the mix a clean, controllable cloth element.", "practical_application": "A Foley artist wears or handles a jacket and performs its movements in sync with the picture while the Foley mixer records the passes onto dedicated cloth tracks.", "category": "Foley", "related_terms": ["Foley", "Cloth movement", "Foley footsteps", "Jewelry movement", "M&E"], "common_mistakes": ["Assuming clothing sounds are captured well enough on the boom and do not need Foley.", "Performing moves out of sync so the cloth rustle drifts from the picture.", "Recording the jacket too loudly so it distracts from dialogue in the final mix."], "scenario_contexts": ["Replacing missing clothing rustle in a scene shot with a distant boom.", "Adding cloth movement for an international M&E version where original incidental sounds are removed.", "Reinforcing a character standing up and putting on a jacket before leaving a room."]}, "465e84b5-4318-41c6-99c0-edb9fc3bbc7b": {"definition": "A Foley moves/specifics cue that recreates the small metallic sounds of jewelry — such as bracelets, necklaces, rings, or earrings — jingling or clinking as a character moves, recorded in sync to picture.", "plain_english": "It is the tiny clink and jingle of jewelry as a person moves. A Foley artist makes these sounds by handling real jewelry in time with the film. This adds detail the set microphone may not have caught.", "purpose_function": "It adds fine, believable detail to a character's movement and wardrobe, and supplies those sounds as clean, separate elements the mixer can place and balance.", "practical_application": "A Foley artist handles bracelets, chains, and similar jewelry props and performs the jingles in sync while the Foley mixer records them to dedicated tracks.", "category": "Foley", "related_terms": ["Foley", "Specifics", "Jacket movement", "Key jingle", "ADR"], "common_mistakes": ["Overplaying the jingle so it pulls focus from dialogue.", "Using jewelry that sounds nothing like what is seen on screen.", "Letting the sound drift out of sync with the actor's motion."], "scenario_contexts": ["A close-up of a character adjusting a bracelet or necklace.", "Rebuilding jewelry sounds for an M&E track used in dubbing.", "Adding jingle to a character wearing many bangles that were silent on the production track."]}, "634619fc-c3c4-4284-a785-d97f91089798": {"definition": "A Foley specifics cue that reproduces the metallic jingling and clinking of a set of keys as a character carries, handles, or drops them, performed and recorded in sync to picture.", "plain_english": "It is the jingle of a bunch of keys, made by hand for a film. A Foley artist shakes or handles real keys in time with the picture. It gives the scene a sharp, clear sound the camera mic often misses.", "purpose_function": "It provides a crisp, recognizable prop sound that supports action and character, delivered as a separate clean element the re-recording mixer can control.", "practical_application": "A Foley artist jingles a suitable key set in sync with the actor's hand while the Foley mixer records takes onto a specifics track.", "category": "Foley", "related_terms": ["Foley", "Specifics", "Jewelry movement", "Jacket movement", "ADR"], "common_mistakes": ["Recording the keys much louder than they would sound in the real space.", "Choosing keys whose pitch or number does not match what is on screen.", "Missing the exact frame where the keys are picked up or set down."], "scenario_contexts": ["A character unlocking a door as the keys jingle in hand.", "Rebuilding the key sound for an international M&E deliverable.", "A tense scene where dropped keys need a clear, well-timed jingle."]}, "4c0a28ca-e784-4dfa-8cf2-335f39ea926f": {"definition": "The oversight of a localized (dubbed or voiced) version to ensure the target-language dialogue is accurate in translation, correctly pronounced, and well matched to lip-sync and performance, carried out by a language or dubbing supervisor.", "plain_english": "It is checking that a film's new-language voices are correct and natural. A supervisor makes sure the translation is right and the words match the actors' lips. This keeps the dubbed version true to the original.", "purpose_function": "It protects the meaning, tone, and technical fit of a foreign-language version so the localized release feels true to the original for its new audience.", "practical_application": "During or after dubbing sessions, the language supervisor reviews takes for translation accuracy, pronunciation, and sync, and flags lines that must be re-recorded.", "category": "Localization", "related_terms": ["Dubbing", "Language-version recording", "Language-specific ADR", "Language-version quality control", "M&E"], "common_mistakes": ["Assuming a good translation on paper will automatically fit the actor's lip movements.", "Skipping pronunciation checks for names and technical words.", "Confusing language supervision with simple subtitle proofreading."], "scenario_contexts": ["Overseeing a Spanish dub of a series for accuracy and sync.", "Approving pronunciation of character names across all language versions.", "Sending flagged lines back for re-recording during a dubbing session."]}, "1d2eb416-54aa-4840-988d-22dc628ddb6e": {"definition": "Automated Dialogue Replacement performed for one specific language version of a production, where voice actors re-record dialogue in that language in sync to picture, producing clean, matched lines for that localized release.", "plain_english": "It is re-recording a film's dialogue in one chosen language. Voice actors watch the picture and speak their lines in sync in a studio. This gives that language its own clean, matched dialogue.", "purpose_function": "It supplies each target market with sync dialogue in its own language, kept separate from other versions so each can be mixed and delivered on its own.", "practical_application": "A dubbing studio cues the picture, and voice actors perform lines in the target language to sync while the ADR mixer records them for that version's mix.", "category": "Localization", "related_terms": ["ADR", "Dubbing", "Language-version recording", "Language supervision", "M&E"], "common_mistakes": ["Reusing one language's ADR timing for another without re-checking sync.", "Forgetting that each language version needs its own clean recording, not the original mix.", "Ignoring differences in line length between languages that break lip-sync."], "scenario_contexts": ["Recording French lines to picture for a French release.", "Replacing an on-set foreign line with studio ADR for one market.", "Building sync dialogue for a dub that will be mixed over the M&E."]}, "d4346fe9-1883-4fb9-9b5d-31f8eb69eab2": {"definition": "The quality-control review of a completed localized (dubbed or subtitled) version to confirm it meets translation, sync, performance, and technical delivery standards before the version is released.", "plain_english": "It is the final check of a film made for a new language. Reviewers make sure the voices sync, the translation is right, and the file meets the required specs. Only then is that version approved.", "purpose_function": "It catches sync, translation, and technical faults in a language version before delivery, protecting quality and preventing costly rejects from the distributor.", "practical_application": "A QC operator watches the localized version against a checklist, logging any sync slips, wrong lines, level problems, or spec errors for fixing.", "category": "Localization", "related_terms": ["Language-version recording", "Language supervision", "Dubbing", "Deliverables", "M&E"], "common_mistakes": ["Checking only the audio and missing subtitle or spec errors.", "Passing a version without comparing sync against the original picture.", "Assuming the source master's QC covers the localized version too."], "scenario_contexts": ["Reviewing a German dub before it ships to a broadcaster.", "Logging a lip-sync drift found in one reel of a language version.", "Confirming loudness and file specs on a localized deliverable."]}, "291a054b-0e02-4ba3-a57d-7168f34d65b9": {"definition": "The recording session in which dialogue for a specific target-language version is captured to picture, producing the localized voice tracks that are later edited and mixed over the program's M&E.", "plain_english": "It is the studio session where a film's dialogue is recorded in a new language. Voice actors speak their lines in sync with the picture. These new voices later replace the original ones in that version.", "purpose_function": "It creates the target-language dialogue needed to build a dubbed version, keeping those voices as a clean, separate element for editing and mixing.", "practical_application": "In a dubbing studio, actors watch the picture and perform lines in the target language while the mixer records takes for later editing over the M&E.", "category": "Localization", "related_terms": ["Dubbing", "Language-specific ADR", "Language supervision", "Language-version quality control", "M&E"], "common_mistakes": ["Recording without a clean M&E to mix the new voices over.", "Letting take levels or mic setup drift between actors in a session.", "Not matching recorded line length to the on-screen mouth movements."], "scenario_contexts": ["Recording an Italian dub of a feature over several days.", "Capturing target-language voices to sync for a streaming release.", "Re-recording a few lines a supervisor flagged as off-sync."]}, "5306e670-3d6e-4eaf-a8d7-50bdad62aa4d": {"definition": "A dialogue-editing or mixing choice to use the lavalier (body-worn) microphone track as the primary source for a line rather than the boom, usually because the lav gives cleaner, closer, or more usable dialogue in that moment.", "plain_english": "It means picking the tiny clip-on mic as the main sound for a line, not the boom. Editors do this when the clip-on mic sounds cleaner or clearer. It helps get the best, most usable voice for each moment.", "purpose_function": "It lets the editor choose the best-sounding microphone per line so the finished dialogue is clear and consistent, especially when the boom is blocked, distant, or noisy.", "practical_application": "While cutting dialogue, the editor auditions the boom and lav for each line and cuts to the lav when it is cleaner, matching level and tone across the switch.", "category": "Dialogue editing", "related_terms": ["Boom microphone", "Lavalier microphone", "Production sound", "Dialogue editing", "ADR"], "common_mistakes": ["Switching to the lav without matching its tone to the boom, so the sound jumps.", "Forgetting that lavs pick up clothing rustle and mic bumps.", "Always favoring one mic instead of choosing per line for the best result."], "scenario_contexts": ["A wide shot where the boom is too far but the lav is close and clean.", "A noisy exterior where the lav rejects background better than the boom.", "Cutting between boom and lav within a scene to keep dialogue clear."]}, "933bb6a0-7810-491c-820d-2205668f3e86": {"definition": "A container in game-audio middleware that holds several child sounds and plays them together as simultaneous layers, so a single event outputs a blended, composite sound rather than one file.", "plain_english": "It is a holder that plays several sounds at once, stacked on top of each other. It is like layering a few tracks so they blend into one bigger sound.", "purpose_function": "It lets designers build one rich sound from stacked elements — such as a low rumble, a mid body and a high detail — and control or crossfade those layers together.", "practical_application": "A designer drops the sub, body and detail layers of an explosion into a layer container so they always trigger together and can be blended with one game parameter.", "category": "Interactive Audio", "related_terms": ["Sequence container", "Playlist container", "Hybrid layering", "Parameter-driven audio", "Sound asset"], "common_mistakes": ["Confusing a layer container (plays sounds together) with a sequence or random container (plays sounds one at a time).", "Stacking too many layers, wasting voices and muddying the sound.", "Leaving layers phase-misaligned, so combining them thins the sound instead of thickening it."], "scenario_contexts": ["Building a layered weapon or explosion sound from separate low, mid and high elements.", "Crossfading engine layers with RPM using one game parameter.", "Combining a base ambience with intermittent detail layers for a location."]}, "7a9f693c-2543-4dc6-99ce-7713e63ff57a": {"definition": "A Foley technique in which several separately performed and recorded sound layers (for example a footstep's heel impact, shoe scuff, and clothing rustle) are combined into a single richer, more realistic effect synchronized to on-screen action.", "plain_english": "Layered Foley means recording a sound in several parts and stacking them. For one footstep you might record the heel hit, the shoe scuff, and the clothes moving, then blend them so the step sounds full and real.", "purpose_function": "It lets the Foley team control each part of a sound on its own, so the finished effect sits believably with the picture and the mix.", "practical_application": "A Foley editor records separate passes for feet, cloth moves, and specific props, then layers and syncs them on the Foley stems for the dub mix.", "category": "Foley", "related_terms": ["Foley", "Foley stem", "Layered sound effect", "Spotting session", "Sound effects editing"], "common_mistakes": ["Recording all layers in one pass so they cannot be balanced separately", "Letting layers drift out of sync with picture", "Over-layering until the effect sounds cluttered and unnatural"], "scenario_contexts": ["Building a convincing footstep from heel, scuff and cloth layers on a Foley stage", "Beefing up a punch by layering a body impact, a whoosh and a cloth movement", "Recreating a character walking on gravel by combining several surface layers"]}, "923645d9-f9d9-4812-bab3-59a94c30f266": {"definition": "A sound effect built by combining two or more individual sound elements (recorded, synthesized, or library sounds) into a single composite that is fuller or more specific than any one source alone.", "plain_english": "A layered sound effect is one sound built from several sounds stacked together. A movie explosion might mix a deep boom, a sharp crack, and falling debris so it hits harder than any single recording.", "purpose_function": "Layering gives a sound designer control over the weight, brightness and detail of an effect, letting them build sounds that do not exist or need more impact than a raw recording.", "practical_application": "A sound designer stacks and tunes multiple clips in the DAW, often a low layer, a mid body layer and a high detail layer, to build effects like weapons, creatures or impacts.", "category": "Sound Effects", "related_terms": ["Layered Foley", "Library Effect", "Sound design", "Sweetening", "Sound effects editing"], "common_mistakes": ["Stacking too many layers so the effect turns to mush", "Not filtering overlapping layers, causing frequency buildup and clipping", "Leaving layers unsynced so the composite smears"], "scenario_contexts": ["Designing a sci-fi weapon from a real gunshot plus synth layers", "Building a monster roar from animal recordings and a pitched-down voice", "Creating a car crash from metal impacts, glass and debris layers"]}, "8f3c5b26-5265-463e-8694-7a2fad2cf43e": {"definition": "A pre-recorded sound effect selected from a commercial or in-house sound-effects library, rather than one custom-recorded or performed as Foley for the specific production.", "plain_english": "A library effect is a ready-made sound you pull from a big collection instead of recording it yourself. If a scene needs thunder, you can grab a thunder clip from a sound library rather than wait for a storm.", "purpose_function": "Libraries give editors fast, reliable access to a huge range of sounds, saving the time and cost of recording every effect from scratch.", "practical_application": "A sound-effects editor searches a library by keyword, auditions clips, then drops chosen effects onto the timeline and edits or layers them to fit picture.", "category": "Sound Effects", "related_terms": ["Layered sound effect", "Foley", "Sound effects editing", "Spotting session", "Metadata"], "common_mistakes": ["Using a recognizable stock sound (such as the Wilhelm scream) where it distracts the audience", "Ignoring library licensing terms and clearances", "Grabbing the first search result without auditioning for the right perspective or tone"], "scenario_contexts": ["Dropping a city ambience bed under a street scene from a library", "Pulling a specific car-by from a vehicle library to match the shot", "Filling in hard effects on a tight deadline using library gunshots"]}, "f9675f4f-c20f-4db5-a7fa-c0438c42ba0b": {"definition": "The post-production process of replacing a production's original-language dialogue with newly recorded dialogue, usually in another language, timed and performed so the new speech matches the actors' on-screen lip movements.", "plain_english": "Lip-sync dubbing swaps the actors' spoken words for a new recording, often in another language, matched to their mouth movements. It is how a French film can seem to speak English on screen.", "purpose_function": "It lets a production reach audiences who speak other languages while keeping the original picture, so the dialogue still appears to come from the on-screen actors.", "practical_application": "In a dubbing studio a voice actor watches picture and performs translated lines while the director and engineer adjust timing so the words land on the character's mouth movements.", "category": "Dialogue Replacement", "related_terms": ["ADR", "M&E stem", "Localization engineer", "Sync", "Dialogue editing"], "common_mistakes": ["Prioritizing an exact translation over matching lip movements, breaking sync", "Ignoring the M&E stem so original music and effects are lost under new dialogue", "Recording at a level or perspective that does not match the scene's acoustics"], "scenario_contexts": ["Creating a German-language version of a US series", "Re-voicing an animated feature for international release", "Replacing an actor's lines in the same language for an edited broadcast version"]}, "ee81a6df-77ba-4923-b871-3cb42ac047d9": {"definition": "In spatial and immersive audio, the direction a listener is facing relative to the reproduced sound field, which determines how left/right, front/back and height cues are perceived; in head-tracked binaural or VR it is updated in real time as the head turns.", "plain_english": "Listener orientation is which way the listener is facing inside a surround or 3D sound scene. Turn your head to the left and sounds that were in front now seem to come from your right.", "purpose_function": "Tracking orientation lets a system place sounds correctly around the listener, so directions stay convincing as the head or viewpoint moves.", "practical_application": "In VR and 360 audio, engineers feed head-tracking data so the mix rotates with the listener; in a mix room they check that the reference facing direction points at the center speaker and screen.", "category": "Spatial Audio", "related_terms": ["Listener position", "Binaural", "Ambisonics", "Head tracking", "Panning"], "common_mistakes": ["Confusing orientation (facing direction) with position (location)", "Mixing head-locked and head-tracked elements without deciding which should rotate", "Assuming everyone faces the screen when placing critical cues"], "scenario_contexts": ["Mixing a 360 video where sounds must stay put as the viewer looks around", "Setting the reference facing direction in an Atmos or ambisonic session", "Designing a VR game so audio rotates with the player's head"]}, "d6cc86b7-737e-4445-8262-5462053bbe0b": {"definition": "The location of the listener within a reproduction space or sound field, serving as the reference point (such as the surround sweet spot) for which a mix's levels, timing and imaging are optimized.", "plain_english": "Listener position is where the listener sits inside the speaker setup or 3D sound scene. Surround mixes are aimed at one main spot. Sit there and you hear the balance the mixer wanted.", "purpose_function": "Defining a reference position lets the mixer set levels and panning that image correctly, and lets playback systems calibrate around where people actually sit.", "practical_application": "Engineers mix from the sweet spot of a calibrated room, and in games or VR the listener position follows the player or camera so distances and panning update live.", "category": "Spatial Audio", "related_terms": ["Listener orientation", "Sweet spot", "Panning", "Surround sound", "Calibration"], "common_mistakes": ["Mixing while sitting off the sweet spot and misjudging the balance", "Ignoring how much the image degrades away from the reference position", "Confusing listener position with listener orientation"], "scenario_contexts": ["Calibrating a 5.1 room so the sweet spot matches the mix position per the ITU layout", "Setting the camera or player as the listener position in a game engine", "Explaining to a client why the surround image only locks in the center seat"]}, "034b1b03-adaa-4be8-b530-747c83382780": {"definition": "The real-time performance of Foley sound effects synchronized to picture or action as it happens, whether recorded live to picture on a Foley stage or performed live before an audience, as in radio drama, theatre, or live-cinema events.", "plain_english": "Live Foley performance means making sound effects by hand in real time while the action plays. A Foley artist might crunch cornstarch for footsteps in snow exactly as the character walks on screen.", "purpose_function": "Performing to picture in real time captures natural timing and human nuance that step-by-step editing can miss, and it can entertain an audience at live events.", "practical_application": "A Foley artist watches picture and performs props, feet and moves in sync while an engineer records; at live shows the same skills score a film or radio play on stage.", "category": "Foley", "related_terms": ["Layered Foley", "Foley", "Foley stage", "Spotting session", "Sync"], "common_mistakes": ["Watching your hands instead of the picture and drifting out of sync", "Performing too hard so levels clip or the prop sounds fake", "Forgetting that a live take still needs to fit the final mix perspective"], "scenario_contexts": ["Recording footsteps and props live to picture on a Foley stage", "Performing sound effects on stage for a live radio-drama show", "Scoring a silent film live with hand-made effects for an audience"]}, "db97cb95-f4eb-46e1-b043-479eb21d9d19": {"definition": "The person who oversees the creative side of adapting a production for another language or region: casting and directing dub voice actors, approving translated and adapted scripts, and guiding performances so the localized version matches the intent, timing and lip-sync of the original.", "plain_english": "A localization director leads the team that turns a film or game into another language. They pick and coach the new voice actors and make sure the translated version still feels like the original.", "purpose_function": "The role keeps a foreign-language version faithful and natural, protecting performance quality and lip-sync so localized audiences get the same experience as the original.", "practical_application": "On a dub project the localization director runs casting, sits in on record sessions to direct actors, and signs off that lines match picture and story before the mix.", "category": "Localization", "related_terms": ["Lip-sync dubbing", "Localization engineer", "ADR", "M&E stem", "Voice casting"], "common_mistakes": ["Confusing the localization director (creative lead) with the localization engineer (technical lead)", "Approving a literal translation that breaks lip-sync or tone", "Skipping M&E checks so the dub loses original music and effects"], "scenario_contexts": ["Directing the English dub of an anime series", "Overseeing multi-language versions of a streaming original", "Coaching voice actors to match the lead's on-screen emotion and timing"]}, "c778ce82-61b9-40b5-85a5-cd9f4d5e0a98": {"definition": "The technical specialist who handles the audio and deliverable side of adapting a production for other languages or regions: preparing and conforming M&E stems, recording and editing dubbed dialogue, and building localized mixes and deliverables to spec.", "plain_english": "A localization engineer is the tech person who makes the foreign-language versions of a soundtrack. They record the new voices. Then they mix them with the music and effects and prep the files each region needs.", "purpose_function": "The role turns creative dub decisions into correct, deliverable audio, making sure each localized version meets technical and format requirements without losing the original music and effects.", "practical_application": "The engineer conforms M&E stems, records and edits dub lines, mixes them to match the original, then exports localized deliverables to the distributor's spec.", "category": "Localization", "related_terms": ["Localization director", "Lip-sync dubbing", "M&E stem", "Deliverables", "ADR"], "common_mistakes": ["Confusing the engineer (technical) with the localization director (creative)", "Delivering a mix that does not match the original loudness or spec", "Mislabeling or misconfiguring M&E stems so effects drop out"], "scenario_contexts": ["Conforming M&E stems and mixing a Spanish dub to the original", "Preparing multi-language audio deliverables for a streaming platform", "Editing and syncing recorded dub dialogue before the localized mix"]}, "3c4f1845-72bc-4812-8c62-65d087b25370": {"definition": "A supervised listening and approval session in which a completed foreign-language (localized) version of a program's soundtrack is checked against the original mix for lip-sync, level balance, tonal match, and creative intent before the deliverable is approved.", "plain_english": "A check where people listen to a dubbed show and compare it to the original. They make sure the new voices line up with the picture and sound right. It is a bit like proofreading a translation, but for the soundtrack.", "purpose_function": "It confirms that the localized soundtrack faithfully recreates the original mix in a new language and meets the client's creative and technical standards before release.", "practical_application": "A localization mixer or supervisor plays the dubbed reels for a language director or client and notes any sync slips, level issues, or mismatched effects to fix in a revision pass.", "category": "Localization Workflow", "related_terms": ["Localization mixer", "M&E stem", "Localized dialogue stem", "Automated dialogue replacement (ADR)", "Quality control (QC)", "Re-recording mix"], "common_mistakes": ["Assuming the review only checks lip-sync and skipping level and tonal matching against the original mix.", "Reviewing against a low-quality reference instead of the approved original mix.", "Approving a version where original-language dialogue still leaks through the M&E."], "scenario_contexts": ["Signing off a Spanish dub of a series episode before delivery to a streaming platform.", "Comparing a localized feature mix to the original English mix on a dubbing stage.", "Flagging a scene where the dubbed line drifts out of sync with the actor's lips."]}, "7dea6a55-d6b0-4780-aab3-36057636fd0a": {"definition": "The re-recording mixer responsible for combining a program's original music-and-effects (M&E) stem with newly recorded target-language dialogue to produce a finished foreign-language (localized) mix that matches the original.", "plain_english": "The engineer who blends a show's music and sound effects with the new dubbed voices. The goal is to make the foreign-language version sound just like the original. It is a bit like a cook rebuilding a dish with one part swapped out.", "purpose_function": "It recreates the original soundtrack in another language by placing dubbed dialogue smoothly into the existing music and effects, keeping the same balance and feel.", "practical_application": "Working from the M&E and a dialogue guide, the mixer levels, EQs, and pans each dubbed line to sit like the original dialogue, then delivers the localized mix as stems or a printmaster.", "category": "Localization Workflow", "related_terms": ["M&E stem", "Localized dialogue stem", "Re-recording mix", "Localization mix review", "Automated dialogue replacement (ADR)", "Printmaster"], "common_mistakes": ["Placing dubbed dialogue without matching the original's reverb and room tone, so voices sound pasted on.", "Ignoring the original dialogue stem as a level and panning reference.", "UNSAFE: monitoring at excessive levels during long dubbing sessions instead of working at the calibrated reference level, risking hearing damage."], "scenario_contexts": ["Mixing a German-language version of a film from the supplied M&E and dub tracks.", "Rebalancing dubbed narration over a documentary's music and effects.", "Delivering localized dialogue, music, and effects stems for a streaming series."]}, "2d394a3c-af07-4357-b611-3ecbdb8ca4f8": {"definition": "The technical and creative inspection process that verifies a completed localized (foreign-language) soundtrack meets delivery specifications, checking sync, loudness, audio artifacts, channel assignments, and the absence of original-language dialogue before the version is accepted.", "plain_english": "The final checking step that makes sure a dubbed soundtrack is correct. Voices must be in sync, loudness must be on target, and there should be no glitches or leftover original speech. It is like inspecting a product before it ships.", "purpose_function": "It catches sync errors, level and loudness problems, artifacts, and mistakes before a localized version is delivered, protecting quality and meeting the client's specs.", "practical_application": "A QC operator screens the localized version end to end and logs timecoded issues such as dropped lines, off-sync dialogue, or loudness that fails the delivery target for correction.", "category": "Localization Workflow", "related_terms": ["Localization mix review", "Loudness normalization", "M&E stem", "Localized dialogue stem", "Deliverables", "Localization mixer"], "common_mistakes": ["Spot-checking only a few scenes instead of screening the entire program.", "Checking picture sync but not verifying integrated loudness against the delivery target.", "Missing original-language dialogue bleeding through because the M&E was not fully filled."], "scenario_contexts": ["QC of a French dub before delivery to a broadcaster.", "Rejecting a localized episode whose loudness fails the EBU R128 target.", "Logging a timecode where a dubbed line is missing from the dialogue stem."]}, "134c9158-91f1-4996-bc61-4c0584eb48f3": {"definition": "The studio recording session in which target-language performances, such as dubbed dialogue, narration, or group crowd voices, are captured to picture so they can replace the original-language content in a localized version.", "plain_english": "The studio session where actors record new voices in another language while watching the picture. This lets their lines replace the original speech. It is like re-voicing a cartoon in a different language.", "purpose_function": "It produces clean, in-sync target-language vocal recordings that the localization mixer can drop into the M&E to build the foreign-language soundtrack.", "practical_application": "In a dubbing booth, voice actors watch the picture and match their lines to the original timing while an engineer records each take for later editing and mixing.", "category": "Localization Workflow", "related_terms": ["Automated dialogue replacement (ADR)", "M&E stem", "Localized dialogue stem", "Localization mixer", "Group ADR", "Lip sync"], "common_mistakes": ["Recording without watching picture, so lines will not sync to the actors' mouths.", "Capturing dubbed dialogue with reverb or room tone baked in, limiting the mixer's control.", "Using inconsistent mic and level choices between sessions, making dialogue hard to match."], "scenario_contexts": ["Recording an Italian dub cast to picture in a dubbing studio.", "Capturing localized narration for a documentary's foreign version.", "Re-recording group crowd voices in the target language."]}, "2fc8ea1b-fa00-47d3-9825-a4a41a9c2c45": {"definition": "A final broadcast-ready mix of a program prepared for a specific language territory, in which the original dialogue has been replaced with target-language content over the original music and effects and delivered to that market's technical standards.", "plain_english": "This is a finished, ready-to-air version of a show. It is made for one country's language. Dubbed voices sit over the original music and effects. It also meets that broadcaster's loudness and format rules.", "purpose_function": "It supplies a broadcaster or platform in a given territory with an air-ready soundtrack in the local language that meets their loudness, channel, and format requirements.", "practical_application": "A mixer combines the M&E with the localized dialogue, then conforms the mix to the territory's loudness standard, such as EBU R128, and to the required channel layout before delivery.", "category": "Localization Workflow", "related_terms": ["M&E stem", "Localized dialogue stem", "Loudness normalization", "Localization mixer", "Deliverables", "Localization quality control"], "common_mistakes": ["Delivering at the wrong loudness target for the destination broadcaster.", "Forgetting to conform channel order or downmix for the target format.", "Leaving original-language dialogue in the M&E so it clashes with the dub."], "scenario_contexts": ["Delivering a localized episode to a European broadcaster at the R128 loudness target.", "Preparing a dubbed program for a regional feed.", "Conforming a foreign-language mix to a broadcaster's stereo delivery spec."]}, "fe0b15b1-1cf8-477e-8c70-c9d85086031a": {"definition": "A grouped submix containing a program's crowd or background voices (walla) re-performed in the target language, produced so that language-specific crowd content can replace the original when building a localized mix.", "plain_english": "A separate track of background crowd voices recorded in the new language. It makes the murmur of a crowd match the country the dub is for. Think of re-recording the chatter in a busy restaurant scene in another language.", "purpose_function": "It lets a localized mix carry recognizable, language-appropriate crowd voices instead of the original-language crowd, keeping backgrounds believable for the target audience.", "practical_application": "When intelligible crowd voices in the original would sound wrong in the dub, a loop group records new walla in the target language, which is mixed as its own stem alongside the M&E.", "category": "Localization Stem", "related_terms": ["Group ADR", "Walla", "Localized group ADR stem", "M&E stem", "Localized dialogue stem", "Loop group"], "common_mistakes": ["Confusing non-verbal crowd effects with intelligible walla that actually needs re-recording.", "Leaving original-language crowd voices in the M&E, so both languages are heard.", "Mixing new crowd voices too far forward, making them stand out from the original backgrounds."], "scenario_contexts": ["Re-recording restaurant background chatter in the target language for a dub.", "Replacing a stadium crowd's chants for a localized sports drama.", "Building a walla stem that matches the original crowd's density and perspective."]}, "a69f4f66-850d-4820-afc8-203dbc31b2dc": {"definition": "The dialogue submix of a localized version, containing the target-language dubbed lines mixed to match the original dialogue's level, perspective, and processing, delivered separately so it sums with the M&E to form the full foreign-language soundtrack.", "plain_english": "The track that holds just the dubbed voices for a show in the new language, balanced to sound like the original speech. It combines with the music and effects to make the complete dubbed soundtrack.", "purpose_function": "It carries the replacement dialogue for a language version as its own stem, so the mix can be rebuilt, revised, or re-delivered without touching the music and effects.", "practical_application": "The localization mixer edits and levels each dubbed line onto the dialogue stem, matching the original's EQ and reverb, then delivers it beside the M&E as part of the stem set.", "category": "Localization Stem", "related_terms": ["M&E stem", "Localized narration stem", "Automated dialogue replacement (ADR)", "Localization mixer", "DME stems", "Localized group ADR stem"], "common_mistakes": ["Delivering dubbed dialogue that does not sum correctly with the M&E to recreate the mix.", "Skipping reverb and room-tone matching so the dub sounds detached from the scene.", "Baking effects into the stem that should stay adjustable."], "scenario_contexts": ["Delivering a Portuguese dialogue stem alongside the M&E for a film.", "Revising a few dubbed lines by re-delivering only the dialogue stem.", "Matching dubbed dialogue perspective to an over-the-shoulder shot."]}, "e5128c69-9286-4883-881b-fb515746000c": {"definition": "A submix of group ADR, meaning loop-group crowd and background voices (walla) recorded to picture, performed in the target language and delivered as its own stem so language-specific group voices can replace the original in a localized mix.", "plain_english": "A track of background group voices, like a crowd or a busy room, re-recorded in the new language by a group of actors. It is kept separate so it can be swapped into the dubbed version.", "purpose_function": "It supplies target-language crowd and background dialogue as an isolated stem, keeping incidental voices believable and swappable in the localized soundtrack.", "practical_application": "A loop group records walla to picture in the target language, and the mixer places it on the group ADR stem to sit with the original backgrounds and M&E.", "category": "Localization Stem", "related_terms": ["Group ADR", "Walla", "Localized crowd stem", "Automated dialogue replacement (ADR)", "M&E stem", "Loop group"], "common_mistakes": ["Treating principal dialogue and group ADR as one stem, removing mix flexibility.", "Recording group ADR without picture, so reactions miss the on-screen action.", "Leaving the original-language group voices audible under the dub."], "scenario_contexts": ["Recording a target-language loop group for a hospital scene's background voices.", "Delivering a group ADR stem so a dub can replace intelligible crowd lines.", "Matching new walla density to the original background perspective."]}, "3dde0d73-7ae3-495b-9318-11addaa5b33b": {"definition": "The narration or voice-over submix of a localized version, containing the target-language narration mixed to match the original, delivered separately so it sums with the M&E to complete the foreign-language soundtrack.", "plain_english": "A track holding just the dubbed narrator's voice in the new language, balanced like the original. It joins the music and effects to make the full localized soundtrack.", "purpose_function": "It carries a program's translated voice-over as its own stem, letting the narration be revised or re-delivered without affecting the music and effects.", "practical_application": "For a documentary dub, the mixer places the target-language narration on its own stem, matches the original's level and tone, and delivers it with the M&E.", "category": "Localization Stem", "related_terms": ["M&E stem", "Localized dialogue stem", "Voice-over", "Localization mixer", "DME stems", "Localization recording"], "common_mistakes": ["Letting translated narration run longer than the original and drift off the picture.", "Not matching the narration's level and EQ to the original voice-over.", "Combining narration with dialogue so it cannot be revised on its own."], "scenario_contexts": ["Delivering a Japanese narration stem for a localized nature documentary.", "Re-delivering only the narration stem after a script correction.", "Matching dubbed narration loudness to the program's delivery target."]}, "7b6f9c39-cd03-4ac1-9764-df283680cd40": {"definition": "A near-field (home/consumer) re-recording of a program's soundtrack adapted for a specific language or territory, in which localized (dubbed) dialogue is combined with the original music-and-effects (M&E) and monitored at near-field/home reference level rather than at theatrical level.", "plain_english": "This is the home-video version of a show's sound, remade in another language. The new spoken lines are mixed with the original music and sound effects. It is checked on small studio speakers, like the ones people use at home.", "purpose_function": "It lets a program reach non-original-language home and broadcast audiences by swapping the dialogue while keeping the original musical and effects intent, optimized for consumer near-field playback.", "practical_application": "A re-recording mixer conforms the home mix by placing the dubbed language stem over the delivered M&E, checks balance and loudness on near-field monitors, and outputs the territory's consumer deliverable.", "category": "Localization Deliverable", "related_terms": ["Localized theatrical mix", "Localized streaming mix", "M&E stem", "Printmaster", "Near-field monitoring", "ADR"], "common_mistakes": ["Reusing the theatrical mix at home level without adjusting dialogue clarity and dynamics for near-field playback", "Failing to check that the localized dialogue sits correctly against the original M&E balance", "Delivering at the wrong integrated loudness target for the consumer platform"], "scenario_contexts": ["Preparing a French home-video mix of an English feature", "Creating a consumer or broadcast version after the theatrical mix is locked", "QC of a dubbed near-field deliverable before release"]}, "73277677-1986-4c0b-a29b-223dc4a84efa": {"definition": "A printmaster—the final, fully combined mix rendered to its delivery channel layout—prepared for a localized version of a program, in which the territory's dubbed dialogue is printed together with the original music-and-effects (M&E) stems.", "plain_english": "A printmaster is the finished, combined soundtrack that gets sent out. A localized one uses new dubbed voices in place of the first language. The music and sound effects stay the same.", "purpose_function": "It provides the ready-to-encode soundtrack for a specific language so distribution and mastering can proceed without re-opening the full mix session.", "practical_application": "Once the dubbed dialogue is approved, the mixer prints the combined dialogue and original M&E to the required channel layout, creating the localized printmaster used for encoding and QC.", "category": "Localization Deliverable", "related_terms": ["Printmaster", "M&E stem", "Localized theatrical mix", "Localized-delivery package", "ADR", "Stems"], "common_mistakes": ["Confusing a printmaster (fully combined) with stems (separated elements)", "Printing before the dubbed dialogue is fully approved, forcing costly re-prints", "Mismatching channel order or LFE routing versus the delivery spec"], "scenario_contexts": ["Rendering the German 5.1 printmaster of a series episode", "Handing a localized printmaster to mastering for DCP or file encoding", "Archiving language-specific printmasters for future re-release"]}, "49d8b964-9328-4f62-bc73-c3e682fdaea6": {"definition": "A streaming-platform deliverable of a program's mix adapted for a specific language or territory and conformed to that platform's channel-layout and loudness specifications, combining localized (dubbed) dialogue with the original music-and-effects (M&E).", "plain_english": "This is the sound version made for a streaming service in another language. It follows that service's rules for how loud the sound can be. New voices replace the first language, but the music and effects stay.", "purpose_function": "It delivers a language-specific mix that meets a streaming platform's technical and loudness requirements so it plays back correctly and consistently across consumer devices.", "practical_application": "The mixer conforms the dubbed mix to the platform's channel layout and loudness target, measures integrated loudness and true peak, and delivers the file for that territory.", "category": "Localization Deliverable", "related_terms": ["Localized nearfield mix", "Loudness normalization", "M&E stem", "Integrated loudness", "True peak", "ADR"], "common_mistakes": ["Missing the platform's integrated loudness or true-peak limits", "Assuming one loudness target fits every platform", "Not verifying dubbed dialogue intelligibility on small consumer speakers"], "scenario_contexts": ["Delivering a Spanish 5.1 mix to a streaming service at its loudness spec", "Re-versioning a title for several territories on one platform", "QC of true-peak and integrated loudness before upload"]}, "24571d7c-ab8e-4801-882c-7c77ceae9352": {"definition": "A theatrical (cinema) re-recording of a program's soundtrack adapted for a specific language or territory, calibrated to theatrical reference monitoring (about 85 dB SPL per channel with the cinema X-curve response) and combining dubbed dialogue with the original music-and-effects (M&E).", "plain_english": "This is the movie-theater version of the sound, redone in another language. It is set up to be loud and full for a big cinema room. New spoken lines sit over the original music and sound effects.", "purpose_function": "It recreates the cinema soundtrack in another language at theatrical standards so foreign-market audiences get the intended large-room presentation.", "practical_application": "On a calibrated dubbing stage, the mixer places dubbed dialogue over the original M&E and prints the localized theatrical version for DCP mastering.", "category": "Localization Deliverable", "related_terms": ["Localized printmaster", "M&E stem", "X-curve", "Dubbing stage", "Theatrical reference level", "ADR"], "common_mistakes": ["Mixing a theatrical-bound dub on near-field monitors instead of a calibrated stage", "Ignoring the X-curve and theatrical reference level when judging brightness and level", "Letting dubbed dialogue drift away from the original balance"], "scenario_contexts": ["Producing the Italian theatrical dub of a feature for cinema release", "Re-recording localized dialogue on a calibrated dubbing stage", "Delivering a localized DCP audio master"]}, "eac3b33a-5369-443e-aa9f-1d539e1845da": {"definition": "The complete set of audio deliverables assembled to release a program in a specific language or territory—typically the localized final mixes and printmasters, the music-and-effects (M&E) and stems, and the accompanying metadata and QC/configuration documentation.", "plain_english": "This is the full set of sound files sent out for one language or country. It holds the finished mixes, the music-and-effects track, and notes about each file. Studios use it so a show can be released in that place.", "purpose_function": "It bundles everything a distributor needs for one territory so the correct mixes, source stems, and documentation travel together and match the client's spec.", "practical_application": "A post supervisor assembles the localized printmasters/mixes, M&E, stems, and metadata into one organized package that conforms to the delivery specification.", "category": "Localization Deliverable", "related_terms": ["Localized printmaster", "M&E stem", "Deliverables specification", "Stems", "Metadata", "QC report"], "common_mistakes": ["Omitting the M&E or a required stem set from the package", "Inconsistent file naming or metadata versus the delivery spec", "Delivering the wrong channel layout or loudness variant for the territory"], "scenario_contexts": ["Compiling the French-territory audio package for a distributor", "Cross-checking a localized package against a studio delivery spec", "Archiving a per-territory package for later re-versioning"]}, "281f2319-25b3-4d4c-a6b9-0591c00250a9": {"definition": "A recorded ADR (automated dialogue replacement, historically called 'looping') element—an individual replacement line or a loop-group recording—delivered as a discrete, reusable media asset for dialogue editing and the final mix.", "plain_english": "Looping is when actors re-record their lines in a quiet studio. It is also called ADR. A looping asset is one of those recorded lines, saved as a file for the mix.", "purpose_function": "It supplies clean, controlled replacement dialogue to fix unusable production sound or add lines, giving editors and mixers reusable material.", "practical_application": "A dialogue editor imports the ADR or loop-group recordings, syncs each line to picture, and hands the assets to the re-recording mixer for the dialogue stem.", "category": "ADR / Dialogue", "related_terms": ["ADR", "Loop group", "Walla", "Dialogue editing", "Production dialogue", "M&E stem"], "common_mistakes": ["Assuming 'looping' and 'ADR' are different processes—they are the same", "Poor sync or mismatched room tone between the looping asset and the scene", "Not labeling assets by character and line, which slows the edit"], "scenario_contexts": ["Replacing a noisy on-set line with an ADR looping asset", "Adding loop-group crowd walla to a stadium scene", "Delivering character ADR takes to the dialogue editor"]}, "1c8d8401-ce86-463b-8603-66b774894330": {"definition": "The dedicated, band-limited low-frequency channel in a surround deliverable—the '.1' of formats such as 5.1 and 7.1—designated LFE (Low-Frequency Effects in film; also expanded 'low frequency enhancement' in ITU domestic-system terminology), carrying high-level low-frequency content of roughly 20–120 Hz reproduced by the subwoofer.", "plain_english": "This is the deep-bass channel in surround sound, the '.1' in 5.1. It carries the low rumble you feel, like explosions or thunder. A subwoofer plays it.", "purpose_function": "It carries high-level, band-limited bass on its own channel so the main channels are not overdriven and impactful low-frequency content is reproduced by a subwoofer.", "practical_application": "The mixer routes and meters LFE content within the format's band limit and level standard, and confirms bass management and channel order match the delivery spec.", "category": "Surround Channel", "related_terms": ["LFE", "Bass management", "5.1 surround", "Subwoofer", "Printmaster", "Channel layout"], "common_mistakes": ["Confusing the LFE (.1) channel with full-range low bass in the main channels", "Overloading LFE and exceeding the format's headroom and level standard", "Wrong channel-order mapping so LFE lands on the wrong track"], "scenario_contexts": ["Setting LFE level and low-pass for a 5.1 printmaster", "Checking bass management on the monitoring system", "Verifying LFE routing against a delivery channel map"]}, "5b915deb-4ffe-41b3-be9d-8c54e561abec": {"definition": "A calibrated, acoustically controlled listening room used to audition and quality-check finished masters and deliverables before release, with monitoring level and response aligned to the applicable delivery standard so evaluations are consistent and repeatable.", "plain_english": "This is a carefully set-up listening room. A team plays the finished sound here to check it before it ships. The speakers and volume are tuned to a set standard so everyone hears it the same way.", "purpose_function": "It provides a trusted, standardized listening environment so finished masters can be evaluated and approved with consistent, repeatable results.", "practical_application": "QC and mastering staff play back deliverables at calibrated level and response to catch loudness, sync, dropout, and channel errors before sign-off.", "category": "Facility / Monitoring", "related_terms": ["Calibration", "Reference level", "Monitoring", "QC report", "Printmaster", "Room acoustics"], "common_mistakes": ["Judging masters on uncalibrated speakers or at an inconsistent level", "Skipping full-length playback and missing dropouts or sync errors", "UNSAFE: Reviewing for long stretches at high SPL without breaks, risking noise-induced hearing loss (observe OSHA 1910.95 exposure limits)"], "scenario_contexts": ["Final QC of a feature's printmaster before delivery", "Comparing localized versions for level and balance consistency", "Signing off a master after calibrated playback"]}, "f6969d30-639f-466f-8e3b-c3cfa1201989": {"definition": "Foley footstep performances (or selected library steps) chosen and executed to match the surface material a character walks on—for example wood, concrete, gravel, grass, or metal—so the step sounds correspond to the on-screen ground.", "plain_english": "These are footstep sounds picked to match the ground on screen. A wood floor, gravel, and grass each sound different. Foley artists walk on the right surface so the steps fit the picture.", "purpose_function": "It makes footsteps believable by matching their timbre to the on-screen surface, reinforcing realism and a character's presence in the space.", "practical_application": "A Foley artist selects the right shoe and walks the performance on a matching surface pit (wood, concrete, gravel, and so on), recorded in sync to picture for the Foley/effects stem.", "category": "Foley", "related_terms": ["Foley", "Footsteps", "Foley pit", "M&E stem", "Sound effects editing", "Sync to picture"], "common_mistakes": ["Using one generic footstep sound regardless of the surface on screen", "Mismatched shoe or surface so the steps read as fake", "Poor sync between the step performance and the picture"], "scenario_contexts": ["Performing gravel footsteps for an exterior walking scene", "Building a Foley footstep pass across changing surfaces", "Delivering material-matched footsteps in the Foley stem for the M&E"]}, "d24ec90e-140f-47be-8925-e56fb7f533fe": {"definition": "In spatial or object-based audio, the maximum distance is the range from the listener beyond which a virtual sound source stops getting quieter, holding at a fixed floor level or being muted. It marks the outer end of a source's distance-attenuation curve, which otherwise follows the inverse-square falloff of sound with distance.", "plain_english": "It is the farthest point where a virtual sound still changes. Past this distance the sound stays at one low level or goes silent. It is like a speaker so far away that walking even farther makes no difference.", "purpose_function": "It caps how far a moving audio object stays audible, so distant sources do not clutter the mix or waste processing, and it defines the far end of a source's volume-versus-distance curve.", "practical_application": "A sound editor building an immersive or game mix sets each object's maximum distance so off-screen sources fade out cleanly and only nearby sounds stay audible.", "category": "Spatial Audio", "related_terms": ["Minimum distance", "Panning", "Object-based audio", "Inverse-square law", "Attenuation"], "common_mistakes": ["Setting the maximum distance so large that faraway sounds never fade and clutter the mix", "Confusing maximum distance with minimum distance, which sets where attenuation begins", "Assuming level keeps dropping past the maximum distance instead of holding or muting"], "scenario_contexts": ["Setting attenuation limits for audio objects in an immersive film mix", "Culling distant off-screen sources in a game or VR soundscape", "Automating a source's fade-out as it moves away from the listener"]}, "7adb8e91-b96e-4b41-b9be-ee5a365feb75": {"definition": "Metal footsteps are a Foley element in which footstep sounds are performed on a metal surface — such as steel stairs, grating, a catwalk, or a ship's deck — to match a character walking on metal on screen. They are performed on a dedicated feet track in sync with the picture.", "plain_english": "These are footstep sounds made on metal, like a metal staircase or walkway. A Foley artist steps on real metal in the studio so the movie matches what you see. It makes a hard, ringing clank instead of a soft thud.", "purpose_function": "They give a character's walk the correct hard, resonant character of a metal surface, adding realism and weight that production recordings often miss or that is lost when dialogue is cleaned up.", "practical_application": "A Foley artist watches the scene and steps on a metal plate or grating in the Foley pit, choosing shoes and pace to match the actor's movement on the metal set.", "category": "Foley", "related_terms": ["Movement layer", "Foley pit", "Feet track", "Surface", "Sync"], "common_mistakes": ["Using the wrong shoe or surface so the steps sound like wood or concrete instead of metal", "Ignoring the ring and resonance that real metal adds", "Failing to match the actor's step timing and weight to picture"], "scenario_contexts": ["Foleying a character climbing a steel fire escape or ship ladder", "Adding footsteps for a fight on a metal catwalk", "Replacing missing footstep sound on an industrial or factory set"]}, "489d2607-216a-4315-a6be-bf17905cfeba": {"definition": "A metal impact is a sound effect of a metal object striking or being struck — a clang, clank, or crash — created by hitting, dropping, or colliding metal items and usually layered and processed to fit the on-screen action. It may be produced as Foley or drawn from a sound-effects library.", "plain_english": "This is the sound of metal hitting something, like a clang or crash. Sound artists make it by banging or dropping metal objects. It is used for things like a car crash, a sword hit, or a dropped tool.", "purpose_function": "It supplies the hard, ringing collision sound that sells metal-on-metal or metal-on-hard-surface action, giving impacts weight and energy the picture alone cannot convey.", "practical_application": "A sound editor or Foley artist creates a metal impact by striking metal props, then layers and EQs the recording to match the size and material of the object on screen.", "category": "Sound Effects", "related_terms": ["Metal footsteps", "Foley", "Sound effects library", "Layering", "Hard effects"], "common_mistakes": ["Using one generic clang for every metal object regardless of size or material", "Forgetting to layer or pitch the impact to match a large versus small object", "Letting the metallic ring clash with dialogue or music in the mix"], "scenario_contexts": ["Building the crunch and clang of a car collision", "Adding sword or armor clashes in an action or fantasy scene", "Creating the sound of a heavy metal door slamming"]}, "9595112b-21c8-447a-ae2e-d83c34e3625f": {"definition": "A meter change is a shift from one metrical organization to another within a piece of music — for example moving from 4/4 to 3/4 or 6/8 — usually marked by a new time signature. It changes how beats are grouped and the pattern of strong and weak pulses.", "plain_english": "It is when the beat pattern of the music changes partway through. For example, it may switch from counting in fours to counting in threes. A new time signature tells the players about the change.", "purpose_function": "It lets a composer reshape the rhythmic feel, phrasing, or momentum of a passage, adding contrast or fitting the music to lyrics or on-screen action.", "practical_application": "A composer or music editor writes a new time signature at the bar where the feel changes, and musicians or a scoring mixer count the new grouping to stay in time.", "category": "Music Theory", "related_terms": ["Time signature", "Tempo", "Beat", "Bar", "Downbeat"], "common_mistakes": ["Confusing a meter change (beat grouping) with a tempo change (speed)", "Miscounting the first bar of the new meter and losing sync", "Assuming every meter change also changes the tempo"], "scenario_contexts": ["Scoring a film cue that shifts feel from 4/4 to 3/4", "Following a meter change while conducting or clicking a scoring session", "Notating an odd-meter passage in a song arrangement"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"96fe21ec-9f62-4335-a64f-987748af272e": {"definition": "In spatial or object-based audio, the minimum distance (or reference distance) is the range from the listener within which a virtual sound source plays at full level, with distance attenuation only beginning once the source moves beyond it. It sets the inner anchor of a source's distance-attenuation curve.", "plain_english": "It is the closest zone where a virtual sound stays at full volume. Inside this distance, moving the sound nearer does not make it louder. Only past this point does the sound start to fade with distance.", "purpose_function": "It stops a virtual source from becoming unrealistically loud when it sits very close to the listener, and it defines where the volume-versus-distance falloff begins.", "practical_application": "A sound editor sets each object's minimum distance so close sources hold a controlled full level and only begin to fade once they move away in an immersive or game scene.", "category": "Spatial Audio", "related_terms": ["Maximum distance", "Panning", "Object-based audio", "Inverse-square law", "Attenuation"], "common_mistakes": ["Setting the minimum distance so small that a nearby source jumps to extreme loudness", "Confusing minimum distance with maximum distance, which sets the outer fade limit", "Expecting attenuation to occur inside the minimum distance"], "scenario_contexts": ["Anchoring the full-level zone for audio objects in an immersive film mix", "Preventing volume spikes as a source passes close to the listener in VR", "Tuning distance falloff for a moving sound in a game engine"]}, "54a66e64-29fc-40de-881d-bd171322b243": {"definition": "A mixing theater (also called a dubbing stage or re-recording stage) is a purpose-built room where the final film or television soundtrack is mixed, sized and acoustically treated to represent a cinema and calibrated to a standard reference level and response. Dialogue, music, and effects stems are combined and balanced there for the finished mix.", "plain_english": "It is a room built like a small movie theater where the final soundtrack is mixed. It is set up to sound like the cinema where the film will play. Mixers blend the voices, music, and effects here so the movie sounds right everywhere.", "purpose_function": "It gives re-recording mixers a controlled, standardized listening environment so the mix they create translates predictably to real cinemas and other playback systems.", "practical_application": "Re-recording mixers combine the dialogue, music, and effects stems on the dubbing stage, monitoring at the calibrated reference level to build the final mix and deliverables.", "category": "Re-recording", "related_terms": ["Re-recording mixer", "Dubbing stage", "Reference level", "Stem", "Final mix"], "common_mistakes": ["Confusing the mixing theater with a music studio control room", "Mixing without confirming the room is calibrated to the standard reference level", "Assuming a home or small studio setup translates the same as a calibrated stage"], "scenario_contexts": ["Mixing a feature film's final soundtrack on a dubbing stage", "Calibrating the stage monitors to the cinema reference level before a mix", "Creating theatrical and near-field deliverables from the same mix session"]}, "3ed2ce86-6b51-409a-a4c0-242e52898115": {"definition": "Audio morphing is the gradual transformation of one sound into another so that intermediate stages blend features of both, typically by interpolating between their spectral or synthesis parameters over time. The result is a smooth transition rather than a simple crossfade.", "plain_english": "Morphing slowly turns one sound into a different sound. Along the way you hear a blend of both, not just one fading out while the other fades in. It is like a video that melts one face into another.", "purpose_function": "It creates smooth, seamless transitions and hybrid textures, letting a sound designer move between two sounds or build a new sound that shares qualities of each.", "practical_application": "A sound designer uses a morphing plug-in or synth to interpolate between two source sounds, automating the morph so a creature growl slowly becomes a machine hum.", "category": "Sound Design", "related_terms": ["Crossfade", "Spectral processing", "Synthesis", "Automation", "Sound design"], "common_mistakes": ["Thinking morphing is the same as a simple crossfade between two clips", "Morphing sounds with very different spectra and getting an unnatural result", "Forgetting to automate the morph amount over time"], "scenario_contexts": ["Transforming a human voice into a monster in a horror film", "Blending two textures into a new hybrid sound effect", "Creating an evolving transition riser between scenes"]}, "818e1a9f-1433-4c27-bedf-6b88b7625197": {"definition": "A motion-capture audio stage is the sound-recording setup on a motion- or performance-capture volume, where a production sound team records the performers' dialogue — usually as a guide or cue track — while keeping microphones, booms, and their shadows out of the cameras' capture area. The audio syncs the performance and typically guides later ADR rather than serving as the final track.", "plain_english": "It is the sound recording done on a stage where actors' movements are captured by cameras. The mics must stay out of the camera area, so the sound is often just a guide. Actors usually re-record their lines cleanly later.", "purpose_function": "It captures usable reference dialogue and timing during a capture session so editors can sync and cut the performance, even though the space and mic limits usually rule out final-quality audio.", "practical_application": "A production sound mixer rigs lavalier and boom mics that stay clear of the capture volume, records each take as a cue track, and logs it with timecode for later syncing and ADR.", "category": "Production Sound", "related_terms": ["Guide track", "ADR", "Boom microphone", "Lavalier microphone", "Timecode"], "common_mistakes": ["Expecting mocap-stage audio to be broadcast-quality final dialogue", "Letting a boom or mic shadow intrude into the camera capture volume", "Skipping timecode or logging so takes cannot be synced later"], "scenario_contexts": ["Recording guide dialogue during a video-game performance-capture session", "Capturing reference audio on a virtual-production mocap volume", "Providing synced cue tracks that drive later ADR for an animated feature"]}, "d51bc730-ae33-4995-a5cd-1e1194bd83b4": {"definition": "The movement layer (also called moves or cloth) is the Foley element that reproduces the sounds of a character's body movement and clothing — rustles, brushes, and shifts of fabric — performed in sync with the picture. It is one of the three main Foley categories, alongside footsteps and props.", "plain_english": "This is the Foley layer for the sounds of clothes and body movement. It is the rustle you hear when someone moves, shrugs, or reaches out. A Foley artist makes it by moving fabric in time with the actor.", "purpose_function": "It adds the subtle, constant cloth and movement sounds that make characters feel physically present, filling gaps left when production dialogue is replaced or cleaned up.", "practical_application": "A Foley artist wears or handles clothing matching the character and moves in sync with the scene to record the cloth and body-movement track.", "category": "Foley", "related_terms": ["Metal footsteps", "Foley", "Cloth pass", "Props", "Feet track"], "common_mistakes": ["Ignoring the movement layer and leaving characters sounding thin or lifeless", "Using clothing whose material does not match what the character wears", "Overplaying the cloth so rustles distract from dialogue"], "scenario_contexts": ["Adding cloth movement under a dialogue scene after ADR", "Foleying a fight or chase where bodies and clothing move a lot", "Filling movement sounds for a fully looped foreign-language version"]}, "d7f738ca-5405-4c19-b6a8-828fb535aebd": {"definition": "A Foley recording method in which the performance is built up in separate synchronized passes, each pass capturing one category of sound — typically footsteps, then cloth or body moves, then specific props — rather than performing every element at once. Each pass is recorded to its own track so elements can be balanced and edited independently.", "plain_english": "Foley is live sound effects made by watching the film and acting them out. In multi-pass Foley the artist records one type of sound at a time. First footsteps, then clothing rustle, then props. It is like drawing a picture one layer at a time so each part is easy to fix later.", "purpose_function": "Recording each element on its own pass and track gives the mixer independent control of level, EQ and perspective for footsteps, cloth and props, and lets one element be re-recorded or edited without disturbing the others.", "practical_application": "A Foley artist walks the scene for the footsteps pass, replays it to add cloth movement, then does a third pass for handled props, while the Foley mixer records each to separate tracks for the re-recording mixer.", "category": "Foley", "related_terms": ["Foley", "Spotting session", "ADR", "Sound effects editing", "Sync", "Re-recording mix"], "common_mistakes": ["Trying to perform footsteps, cloth and props in one pass, which makes it impossible to balance or fix them separately", "Recording all passes to a single track, losing the independent control multi-pass is meant to provide", "Not watching picture closely and drifting out of sync on the later passes", "Assuming multi-pass means multiple takes of the same sound rather than separate element categories"], "scenario_contexts": ["A Foley team covers a dialogue scene with a footsteps pass, a cloth-movement pass and a props pass for a feature film", "A TV episode needs full Foley for an international M&E deliverable, built up pass by pass", "A fight scene gets separate passes for footfalls, body impacts and clothing so the mixer can feature each element"]}, "fc042221-76b2-4d23-ae34-ef9e9e72b236": {"definition": "The process of editing an existing score or temp music so it matches a revised picture edit — cutting, sliding, trimming or re-timing cues so downbeats, hits and transitions still line up with the new cut. It uses a change list or EDL that records the added and removed frames.", "plain_english": "When the picture editor changes the length of a scene, the music no longer fits. A music conform reshapes the music so it still lines up with the new version of the picture. It is like taking in or letting out clothing so it fits after the body has changed shape.", "purpose_function": "It keeps music synchronized to picture after an edit change, so hits, tempo and cue endings stay aligned without re-scoring or re-recording the music from scratch.", "practical_application": "When the picture department issues a new cut, the music editor uses the change list or EDL to find the added and removed frames, then trims and slides the music cues in the DAW to restore sync.", "category": "Music editorial", "related_terms": ["Music reconform", "Music edit decision list", "Change list", "Picture lock", "Music editing", "Spotting session"], "common_mistakes": ["Confusing conform with reconform — conforming aligns music to a cut, reconforming updates it again after a further picture change", "Sliding a whole cue to fix one section and knocking every later hit out of sync", "Cutting mid-phrase without regard to musical phrasing, producing audible jumps", "Working without an accurate change list and guessing where frames were added or removed"], "scenario_contexts": ["A film's reel is re-cut after temp music was laid in, and the music editor conforms the cues to the new length", "A trailer's music must be conformed to a shortened edit before the mix", "Temp score is conformed to a new cut ahead of the composer's spotting session"]}, "10eaa3af-6dcf-4251-ac5b-fcd85ec4bab8": {"definition": "The task of laying a film's individual music cues into the editorial timeline at their correct start points against picture, and building each cue from its component stems or recorded sections into a finished, synchronized piece ready for the mix.", "plain_english": "A film score is written as many separate pieces called cues, each for a certain scene. Music cue assembly is placing every cue at the right spot in the film and building it from its recorded parts. It is like fitting puzzle pieces into the exact places they belong along the timeline.", "purpose_function": "It turns the composer's raw recorded materials into finished cues positioned correctly against picture, giving the re-recording mixer clean, synced music tracks to work with.", "practical_application": "After a scoring session the music editor imports the recorded stems, lines each cue up to its start frame using the cue sheet or streamers, and assembles the sections into complete cues in the DAW session.", "category": "Music editorial", "related_terms": ["Music editing", "Music editor session", "Music conform", "Cue sheet", "Stems", "Spotting session"], "common_mistakes": ["Placing a cue by ear instead of to its logged start frame, causing sync errors", "Assembling stems out of phase or with a mismatched sample rate", "Forgetting to document cue start and end points for the cue sheet and deliverables", "Treating assembly as final mixing rather than preparing tracks for the re-recording mixer"], "scenario_contexts": ["A music editor assembles orchestral stems recorded at a scoring stage into finished cues on the timeline", "Library cues are assembled into a documentary's timeline at their spotted positions", "A composer delivers cues as multitrack stems that the editor assembles and syncs before the dub"]}, "cc9d24e1-1f9a-4b58-bfca-75a2d856a343": {"definition": "A text-based edit decision list containing the music events of a program — each cue's source, its source in and out timecodes, and its position on the timeline — used to document music editorial and to rebuild or conform the music in another system.", "plain_english": "An edit decision list, or EDL, is a simple text list that records every edit: what clip, where it came from, and where it sits in the timeline. A music EDL is that list just for the music. It works like a recipe that lets someone rebuild the exact same music edit in another program.", "purpose_function": "It provides a machine-readable, human-readable record of the music edit so cues can be reconstructed, conformed to a new picture cut, or handed between systems and departments without loss.", "practical_application": "A music editor exports a music EDL to hand the score edit to the mix stage, or imports one to conform delivered cues to picture, letting the list's timecodes drive an auto-conform.", "category": "Music editorial", "related_terms": ["Edit decision list", "Music conform", "Music reconform", "Change list", "Timecode", "Cue sheet"], "common_mistakes": ["Confusing a music EDL (an edit list) with a cue sheet (a rights and usage log)", "Assuming an EDL carries the audio itself rather than just edit instructions and timecodes", "Ignoring frame-rate or timecode-format mismatches that break the conform", "Editing the raw EDL text carelessly and corrupting the event numbering"], "scenario_contexts": ["A music editor delivers a music EDL so the re-recording stage can auto-conform the cues", "An EDL is used to reconform the music after the picture department issues a change list", "Music edits are moved between two facilities using an EDL rather than a full session"]}, "ff750874-ba56-4689-ae20-0430a998ed1c": {"definition": "The craft of preparing and shaping music for a picture — selecting, cutting, timing, layering and conforming score or source music so it fits the edit, supports the story and meets deliverable requirements — without necessarily composing new material.", "plain_english": "Music editing is the job of shaping music so it fits a film or show. The music editor cuts, moves and times pieces of music so they match the scenes and hit the right moments. It is like arranging songs on a playlist so each one starts and ends exactly where you want.", "purpose_function": "It bridges the composer, the picture edit and the mix, making sure music lands in the right place, in sync, at the right length, and is prepared as clean tracks for the re-recording mixer.", "practical_application": "A music editor spots scenes for music, lays in temp tracks, conforms cues to picture changes, maintains the music editor session and prepares stems and cue sheets for the dub and deliverables.", "category": "Music editorial", "related_terms": ["Music editor session", "Music conform", "Music cue assembly", "Music edit decision list", "Spotting session", "Temp music"], "common_mistakes": ["Confusing music editing with music composition — the editor shapes and places music but does not necessarily write it", "Cutting music without regard to phrasing, tempo or key, producing audible seams", "Failing to keep music in sync after picture changes", "Not documenting edits, making later conforms and deliverables difficult"], "scenario_contexts": ["A music editor cuts temp music into a rough cut before the composer is hired", "Editing and conforming a delivered score to fit the final picture", "Preparing music stems and cue sheets for a film's final mix and deliverables"]}, "b9ab009f-7e3b-4353-970d-903f11907d72": {"definition": "The DAW session, commonly a Pro Tools session, maintained by the music editor that holds a program's music cues, temp tracks, stems and edits laid against picture, and from which music is conformed, prepared and delivered to the mix.", "plain_english": "A session is the working project file inside music software. The music editor session is that project holding all the film's music lined up to the picture. It is like a workbench where every piece of music for the film is laid out and organized.", "purpose_function": "It centralizes all music elements in sync with picture so the editor can conform, balance and organize cues, and hand a clean, ready-to-mix set of music tracks to the re-recording stage.", "practical_application": "The music editor keeps the session updated to the latest cut, imports new cues, conforms to change lists, and exports stems, EDLs and a mix-ready session for the dubbing stage.", "category": "Music editorial", "related_terms": ["Music editing", "Music cue assembly", "Music conform", "Music reconform", "Stems", "Re-recording mix"], "common_mistakes": ["Letting the session drift out of date with the picture cut", "Not organizing cues and tracks, making the handoff to the mix stage messy", "A mismatched sample rate or timecode start between the session and the picture reference", "Deleting rather than muting material, losing versions needed for later reconforms"], "scenario_contexts": ["A music editor delivers a mix-ready music editor session to the dubbing stage", "The session is updated cue by cue as the composer delivers new music", "The session is reconformed to a new picture version before the final mix"]}, "5f54940a-b26d-4a57-9282-c806c4fae040": {"definition": "A section of music, often one or a few bars, arranged to repeat seamlessly end-to-end so it can play continuously for as long as needed.", "plain_english": "A music loop is a short piece of music set up so its end joins smoothly back to its start. Played over and over, it sounds like one continuous piece. It is like a song section on repeat that you cannot hear restart.", "purpose_function": "Looping lets a short recorded passage fill a longer duration, provide a steady musical bed, or extend a cue without new recording, as long as the loop point is seamless.", "practical_application": "A music editor loops a few bars of a cue to underscore a long scene, or builds a loop from source music to cover a montage, tuning the loop point so no click or jump is heard.", "category": "Music editorial", "related_terms": ["Music loop extension", "Music editing", "Crossfade", "Tempo", "Source music", "Music conform"], "common_mistakes": ["Setting a loop point that is not on a musical beat, causing a rhythmic stumble", "Ignoring the reverb tail at the loop point so the join clicks or ducks", "Looping across a tempo or key change, breaking the musical flow", "Assuming any region loops seamlessly without editing the boundary"], "scenario_contexts": ["A short library track is looped to underscore a long dialogue scene", "An interactive or game piece needs seamless music loops of variable length", "A montage is covered by looping a few bars of a delivered cue"]}, "c68a4b91-d04a-4164-8a46-9bcd8fcd1618": {"definition": "The technique of lengthening a piece of music by looping or repeating internal sections so a cue covers a longer duration than originally recorded, while keeping tempo, phrasing and transitions musically seamless.", "plain_english": "Sometimes a scene runs longer than the music written for it. Music loop extension makes the music longer by repeating parts of it so it fills the whole scene. It is like adding extra verses to a song so it lasts until the scene ends.", "purpose_function": "It lets a music editor stretch an existing cue to fit a longer picture length without re-scoring, preserving the music's feel by repeating whole phrases or bars at musical boundaries.", "practical_application": "When a scene is extended, the music editor finds a repeatable section of the cue, copies it and crossfades the loop into place so the cue reaches the new out point without an audible seam.", "category": "Music editorial", "related_terms": ["Music loop", "Music conform", "Music editing", "Crossfade", "Tempo", "Music cue assembly"], "common_mistakes": ["Extending across a musical phrase boundary so the repeat sounds obvious", "Looping a section with a different tempo or dynamic than its surroundings", "Not crossfading the join, leaving a click or level jump", "Reaching for time-compression when a phrase loop would sound more natural"], "scenario_contexts": ["A cue must be extended after a scene is lengthened in a new cut", "A short piece of source music is extended to cover an entire sequence", "Temp music is loop-extended to fit a rough cut before the score is written"]}, "f567aa05-a313-4268-b692-5c3a87bc3139": {"definition": "Re-editing music that was already conformed to picture so it matches a further revised cut — applying a new change list to slide, trim or reinsert cues so they stay in sync after additional picture editorial changes.", "plain_english": "After the music is fitted to the picture, editors often change the picture again. A music reconform fits the music to that newer version. It is like altering the same suit a second time because the body changed again.", "purpose_function": "It keeps music in sync through repeated picture revisions, updating the already-conformed music to each new cut without starting the edit over.", "practical_application": "When a new cut and change list arrive, the music editor runs a reconform in the DAW so cues follow the added and removed frames, then checks every hit and transition against the new picture.", "category": "Music editorial", "related_terms": ["Music conform", "Change list", "Music edit decision list", "Picture lock", "Music editor session", "Music editing"], "common_mistakes": ["Confusing reconform with the first conform — reconform updates already-conformed music to a further change", "Reconforming without an accurate change list and knocking cues out of sync", "Assuming an automated reconform is perfect and skipping the manual sync check", "Losing earlier versions so a bad reconform cannot be rolled back"], "scenario_contexts": ["A film gets multiple cuts after temp music is laid in, each requiring a music reconform", "The music editor reconforms cues to a change list issued the night before the mix", "A streaming series episode is reconformed after notes change the picture edit"]}, "0656b2f2-6bc8-4e69-9d85-206316688cdb": {"definition": "An edit that joins two music cues or sections so they flow together musically, using techniques such as tempo and key matching, downbeat alignment, edits at bar or phrase boundaries, and crossfades to avoid an audible jump between the pieces.", "plain_english": "This is when an editor cuts and reshapes music so one piece flows into the next. It is like blending two songs so you barely notice where one ends and the other begins.", "purpose_function": "It bridges separate pieces of music, or sections of one cue, so score changes support the picture without a jarring seam that pulls the audience out of the story.", "practical_application": "A music editor conforms cues to the locked picture, then builds transitions at chosen edit points, hiding the seams under crossfades, musical hits, or scene changes.", "category": "Music Editing", "related_terms": ["Musical phrase edit", "Musical hit", "Music-editing suite", "Crossfade", "Music cue"], "common_mistakes": ["Cutting music without regard to tempo or downbeat, so the transition lurches out of time.", "Relying only on a fast fade to mask a bad edit instead of choosing a musical edit point.", "Ignoring a key change, leaving the two cues clashing harmonically across the join."], "scenario_contexts": ["Bridging two library tracks under a montage so they feel like one continuous piece.", "Smoothing the handoff from a source song to underscore as a scene shifts.", "Tightening a composer's cue to a re-cut scene without breaking the musical flow."]}, "273ef552-76fd-4b5b-82ba-e72de096a61e": {"definition": "A deliverable mix (M&E) containing all of a program's music and sound-effects and Foley, but excluding the original-language dialogue, supplied so foreign-language dubbing can replace only the voices; a 'fully-filled' M&E adds effects and Foley to cover any sound that was tied to the removed dialogue.", "plain_english": "This is a mix that has all the music and sound effects but no spoken words. Studios use it to add new voices in other languages, like Spanish or French.", "purpose_function": "It exists to enable localization: distributors dub the program into other languages by laying translated dialogue over the untouched music and effects.", "practical_application": "During the final mix the re-recording mixer prints the M&E stems alongside the domestic mix, and quality control checks that no dialogue leaks in and that effects fully cover the removed voices.", "category": "Deliverables", "related_terms": ["Stem", "Dialogue stem", "Foley", "Printmaster", "Dubbing"], "common_mistakes": ["Assuming the M&E includes dialogue; it deliberately leaves the original voices out.", "Leaving production effects that were tied to dialogue missing, so the dub has silent gaps where sounds should be.", "Failing to fully fill Foley and effects, forcing the dubbing stage to recreate them from scratch."], "scenario_contexts": ["Delivering a feature to a foreign broadcaster for French or Spanish dubbing.", "Meeting a streaming platform's delivery spec that requires a fully-filled M&E.", "Localizing a documentary where narration is replaced language by language."]}, "93090709-1f3d-4606-8c09-0846365482f4": {"definition": "A dedicated setup for music editing in post production—either the physical editing room or the integrated system—comprising a DAW, picture sync, monitoring, control surface and music libraries used to cut, conform and lay music to picture.", "plain_english": "This is a room and set of tools built for editing music for film and TV. Think of it as a workshop where the music editor shapes and syncs the score.", "purpose_function": "It gives the music editor the environment and tools to prepare, edit and sync score and source music against a locked picture before the final mix.", "practical_application": "A music editor works in the suite to spot cues, conform music to picture changes, build transitions, and prep organized sessions to hand to the mix stage.", "category": "Facilities", "related_terms": ["Music transition edit", "DAW", "Picture lock", "Spotting session", "Music cue"], "common_mistakes": ["Confusing the music-editing suite with the composer's writing room; the suite is for editing to picture.", "Working without proper picture sync, so edits slowly drift against the film.", "Skipping session prep, handing the mix stage disorganized music tracks."], "scenario_contexts": ["Conforming a score after the picture is re-cut.", "Preparing music stems and cues for the final mix.", "Editing source or needle-drop music to fit a scene."]}, "aaee7245-6e63-40fa-875b-362a8b9a930d": {"definition": "A point where music is composed or edited to accent a specific on-screen action or cut, landing an emphasized musical event—a chord, stinger or downbeat—precisely on that frame; also called a hit point or sync point.", "plain_english": "A musical hit is a moment where the music lands hard right on an action you see on screen. Like a loud chord that hits exactly when a door slams.", "purpose_function": "It ties music tightly to picture so a moment lands with dramatic or comedic emphasis, reinforcing what the audience is seeing.", "practical_application": "Composers and music editors mark hit points during the spotting session, then place or nudge the music so the accent lines up to the exact frame.", "category": "Music Editing", "related_terms": ["Spotting session", "Sync point", "Stinger", "Music transition edit", "Click track"], "common_mistakes": ["Placing the hit a frame or two late so it feels loose against the action.", "Overusing hits ('Mickey-Mousing') until the scoring feels cartoonish.", "Confusing a musical hit with a DAW transient 'hitpoint' used for tempo detection."], "scenario_contexts": ["Landing a chord exactly on a punch or a door slam.", "Accenting a title card or logo reveal.", "Syncing a stinger to a jump-scare cut in a thriller."]}, "06bbba43-3eda-402b-9f99-4fb42df03b94": {"definition": "An edit made at the boundaries of a musical phrase—so the cut falls at the natural start or end of a melodic or rhythmic unit—to shorten, lengthen or rearrange a cue without breaking its musical sense.", "plain_english": "This is editing music at the natural breaks between musical phrases. It is like cutting a sentence at a comma or period so it still reads right.", "purpose_function": "It lets an editor change a cue's length or structure to fit picture while keeping the music's grammar and flow intact.", "practical_application": "A music editor finds phrase boundaries, often at bar lines or cadences, then cuts and crossfades there to conform a cue to a new scene length.", "category": "Music Editing", "related_terms": ["Music transition edit", "Musical hit", "Crossfade", "Music cue", "Bar and beat"], "common_mistakes": ["Cutting mid-phrase, leaving a melody or chord unresolved.", "Ignoring the tempo grid so the reassembled phrases fall out of time.", "Forgetting reverb tails, which get chopped and expose the edit."], "scenario_contexts": ["Trimming a cue by a bar to match a tightened scene.", "Looping a section to extend music under a longer sequence.", "Rebuilding a song edit for a trailer from clean phrase points."]}, "9eed6006-78b8-4df6-8029-a14f78563491": {"definition": "A dedicated headphone or cue mix built for performers that includes a click (metronome) track—often alongside guide music, streamers and punches, or picture reference—so players record in tempo and in sync with the film.", "plain_english": "This is a headphone mix that gives players a steady click to keep time. It helps musicians stay in sync with the picture and each other.", "purpose_function": "It keeps live players locked to tempo and to picture during scoring or overdub sessions so their recordings edit together cleanly and sync to the film.", "practical_application": "On a scoring stage the engineer sends each musician a click mix—click plus guide and pre-records—over headphones, adjusting the click's level and sound to the player's taste.", "category": "Monitoring", "related_terms": ["Click track", "Cue mix", "Foldback", "Scoring session", "Streamers and punches"], "common_mistakes": ["Setting the click too quiet, so players drift off tempo.", "Bleeding click into live mics because the headphone level is too high.", "Giving one generic mix instead of the tailored balances players actually need."], "scenario_contexts": ["Recording an orchestra to picture on a scoring stage.", "Overdubbing a soloist who must lock to the existing tempo map.", "Tracking a band to a click so their parts edit cleanly later."]}, "7a6c1f31-f5de-4152-a080-47e4f7f4cdfa": {"definition": "Spoken narration or voice-over treated as a dialogue element—an off-screen narrator addressing the audience rather than characters speaking within the scene—edited and mixed on the dialogue side of a program.", "plain_english": "This is spoken narration, like a voice telling the story over the pictures. It is handled as its own kind of dialogue in the mix.", "purpose_function": "It carries storytelling information straight to the audience and is treated with dialogue-level clarity and consistency in the mix.", "practical_application": "A dialogue editor cuts narration onto its own tracks, cleans and levels it, and the mixer sits it clearly above music and effects so every word is intelligible.", "category": "Dialogue", "related_terms": ["Voice-over", "Dialogue stem", "ADR", "Production dialogue", "Dialogue editing"], "common_mistakes": ["Treating narration like sync dialogue and trying to match a room tone that is not there.", "Letting music bury the narration, hurting intelligibility.", "Leaving level and tone inconsistent across sessions recorded on different days."], "scenario_contexts": ["Voicing a documentary or nature film.", "Adding a character's inner-monologue voice-over to a drama.", "Recording and cutting an audio guide or corporate narration."]}, "371615e5-3be4-45ea-9433-efccf226fd61": {"definition": "Rendering a sound so it is perceived very close to the listener's head, reproducing the near-field acoustic cues—strong interaural level differences and distance parallax that grow as a source nears the ear—that distinguish nearby from distant sources in binaural or object-based 3D audio.", "plain_english": "This is placing a sound so it seems very close to your head. In surround and 3D audio, it makes something feel almost near enough to touch.", "purpose_function": "It creates a convincing sense that a sound is intimately close—inches from the listener—adding depth and immersion beyond simple left-right panning.", "practical_application": "In immersive mixing an engineer uses a spatial renderer to place an object very near the listener, relying on near-field distance cues rather than loudness alone.", "category": "Immersive Audio", "related_terms": ["Object-based audio", "HRTF", "Binaural rendering", "Dolby Atmos", "Panning"], "common_mistakes": ["Assuming loudness alone equals closeness; near-field cues are more than level.", "Ignoring that near-field cues are strongest at the sides and fade toward the front.", "Expecting the same effect over speakers as over headphones, where binaural near-field cues live."], "scenario_contexts": ["Placing a whisper right at the listener's ear in a VR or game scene.", "Mixing an immersive music track with an intimate, close vocal.", "Designing binaural audio where an insect buzzes past close to the head."]}, "0d3e3c56-3af6-4c2d-9381-8a761475e04c": {"definition": "A short, controlled segment of noise (typically white or pink) of brief duration, used either as a transient sound-design element or as a test and alignment signal—for example to check system output, timing and polarity, or to excite a room for a measurement.", "plain_english": "A noise burst is a short blast of noise. It can be a sound effect or a signal used to test speakers and timing.", "purpose_function": "Its broadband, short-duration content makes it useful both as a percussive effect and as an excitation signal for measuring or aligning a system quickly.", "practical_application": "A technician plays a noise burst to check a speaker's output, listen for timing or polarity, or feed an analyzer; a sound designer layers bursts to build effects such as static, impacts, or whooshes.", "category": "Test Signals", "related_terms": ["Pink noise", "White noise", "Test signal", "Impulse response", "Transient"], "common_mistakes": ["UNSAFE: Firing a loud full-range noise burst without lowering monitor or headphone level first, risking driver damage and hearing injury.", "Confusing an uncontrolled fault glitch with an intentional test burst.", "Assuming a single burst gives a reliable measurement instead of averaging several."], "scenario_contexts": ["Checking a PA channel's output and polarity during setup.", "Exciting a room for a quick timing or delay measurement.", "Building a synthetic sound effect such as static or an impact."]}, "37be77ba-a6ab-4a5a-b957-da33dfb4beae": {"definition": "A transitional sound-design element built largely from filtered or swept noise — such as a riser, whoosh or sweep — used to bridge two scenes, shots or sections and carry the ear across the cut.", "plain_english": "It is a whoosh or sweep sound made from noise that carries the viewer from one scene to the next. It smooths over the jump between shots.", "purpose_function": "It smooths and energises edits by giving the audience an audible bridge across a picture change, hiding the seam and building or releasing tension.", "practical_application": "An editor places a rising noise sweep a few frames before a hard cut so its peak lands on the new shot, gluing the transition together.", "category": "Sound Design", "related_terms": ["Hard sound effect", "Hybrid sound design", "Picture-change conform", "Hit point", "Impact tail"], "common_mistakes": ["Making the transition so loud it overwhelms the dialogue or music around the cut.", "Peaking the sweep at the wrong moment, so it fights rather than supports the picture change.", "Overusing noise whooshes until every edit sounds the same."], "scenario_contexts": ["Bridging a flashback with a filtered noise sweep in a trailer.", "Whooshing between locations in a fast montage.", "Adding a riser into a reveal or title card."]}, "87e33728-30c3-4bf9-88c7-1724faac91ce": {"definition": "An edit that targets an individual musical note within recorded audio or a MIDI performance, altering properties such as its pitch, timing, length, or level independently of the surrounding notes. Polyphonic-capable tools such as Celemony Melodyne (via Direct Note Access) detect discrete notes even inside chords, allowing each to be adjusted separately.", "plain_english": "It means changing just one note in a recording, such as its pitch or timing, without touching the notes around it. Think of fixing one wrong letter in a word instead of retyping the whole line.", "purpose_function": "It lets an editor correct or reshape a performance note by note, so tuning, timing, and phrasing can be fixed without re-recording. This gives fine control over both single-line and chord-based material.", "practical_application": "An editor loads a vocal or instrument take into a tool like Melodyne, then drags individual notes to correct pitch or nudge timing before the mix.", "category": "Audio Editing", "related_terms": ["Pitch correction", "Direct Note Access", "MIDI editing", "Quantization", "Comping", "Time stretching"], "common_mistakes": ["Over-correcting every note to perfect pitch, which strips natural expression and sounds robotic", "Assuming note-level editing only works on single-note lines, when polyphonic tools can separate chords", "Editing a note's pitch without checking that its timbre and formants still sound natural"], "scenario_contexts": ["Tuning a lead vocal note by note before a final mix", "Fixing one flat note inside a guitar chord using polyphonic detection", "Correcting the timing of individual notes in a keyboard part"]}, "b135965f-78ef-4fac-9217-389ffafa1964": {"definition": "A Foley or sound-effect element covering the sound of a character picking up or setting down a handled object — the contact, grip and material movement of the prop as it leaves or meets a surface.", "plain_english": "It is the sound of someone picking something up or putting it down. Think of the small clink and rustle when a hand grabs a cup off a table.", "purpose_function": "It adds tactile realism to on-screen handling, telling the audience an object has weight and material even when the production mic missed the contact.", "practical_application": "A Foley artist handles a matching prop in sync with the picture, capturing the pick-up and set-down contacts that the editor then places to frame.", "category": "Foley", "related_terms": ["Object placement", "Hand contact", "Paper handling", "Key jingle", "Pocket movement"], "common_mistakes": ["Using a generic clink for every object instead of matching the prop's real material and weight.", "Placing the pick-up sound off the frame where the hand actually grips the object.", "Forgetting the set-down sound, so objects seem to vanish rather than be placed."], "scenario_contexts": ["Adding the sound of a character picking up a coffee mug.", "Covering a character lifting and holstering a prop weapon.", "Selling the weight of a heavy box as it is lifted off the floor."]}, "2f3fb2b3-b004-4067-a98b-93e040cfd3e0": {"definition": "The positioning of an individual audio object within a three-dimensional sound field by assigning it spatial coordinates (and often size and movement) as metadata rather than routing it to fixed channels. In object-based systems such as Dolby Atmos, a renderer uses this placement data to reproduce the object at its intended location on whatever speaker layout is available.", "plain_english": "It means telling the system exactly where a sound should sit in the room, like putting a bird up and to the left. The playback system then sends that sound to the right speakers for wherever it plays.", "purpose_function": "It exists so a sound can be tied to a real point in space instead of a fixed speaker, letting the mix follow the picture and adapt to any speaker setup. This keeps localization accurate from a small soundbar to a full cinema.", "practical_application": "A re-recording mixer uses a panner to place a passing car as an object and automates its position so it moves across and above the audience.", "category": "Immersive Audio", "related_terms": ["Audio object", "Object-based audio", "Dolby Atmos", "Panner", "Bed", "Renderer"], "common_mistakes": ["Placing too many elements as moving objects, which clutters the field and can exceed the renderer's object count", "Forgetting that extreme positions may collapse toward the nearest speaker on smaller layouts", "Confusing object placement (position metadata) with hard-routing a sound to one specific speaker"], "scenario_contexts": ["Positioning a helicopter overhead in a Dolby Atmos film mix", "Automating a fly-by so an object moves front to back", "Placing dialogue as an object locked to a character's on-screen position"]}, "db681d7d-a6c2-44f3-8484-66a4bb2e7002": {"definition": "An integrated set of tools — software plugins and/or a dedicated mixing facility — for authoring, mixing, and monitoring object-based audio, in which sounds carry positional metadata instead of being fixed to channels. A typical suite includes a spatial panner, a renderer that maps objects to the monitoring layout, and metering and export tools for immersive deliverables.", "plain_english": "It is the set of tools used to build and check mixes where each sound has its own position in the room. Think of it as the full kit a mixer needs to place sounds anywhere and hear the result.", "purpose_function": "It exists to give a mixer everything needed to create, monitor, and deliver object-based mixes in one connected workflow. This keeps positioning, rendering, and export consistent from mixing through final delivery.", "practical_application": "A mixer runs a Dolby Atmos production suite — panner plugins feeding a renderer — to place objects, monitor the room, and print the immersive master.", "category": "Immersive Audio", "related_terms": ["Object-based audio", "Dolby Atmos", "Renderer", "Panner", "Immersive mixing", "Bed"], "common_mistakes": ["Assuming any DAW can output an immersive master without the required renderer and metadata tools", "Monitoring on a layout that does not match the delivery target, so the exported mix translates poorly", "Confusing the authoring suite with the final deliverable file it produces"], "scenario_contexts": ["Setting up a Dolby Atmos mixing room for a film's final mix", "Producing an immersive music master with a panner-and-renderer toolset", "Exporting object-based deliverables from an integrated immersive workflow"]}, "4999b6e2-9682-460a-82af-a4c33e68f42a": {"definition": "A spatial-audio condition in which an obstacle blocks the direct path between a sound source and the listener while the reflected or reverberant (indirect) sound can still reach the listener around it. It is treated by attenuating and low-pass filtering the dry/direct signal only, leaving the environmental (wet) send largely intact — distinguishing it from occlusion, which blocks both the direct and indirect paths.", "plain_english": "It is when something blocks the straight path to a sound while you stay in the same room. The direct sound gets muffled, but its echoes still reach you. It is like hearing someone talk from behind a pillar.", "purpose_function": "It exists to model how a partial barrier changes a sound so that spatial mixes and interactive scenes stay believable. Handling the direct and reflected paths separately makes a blocked source sound natural rather than simply quieter.", "practical_application": "In a game or immersive mix, a sound designer sets obstruction so a source behind a pillar is filtered on its direct path but still feeds the room reverb.", "category": "Spatial Audio", "related_terms": ["Occlusion", "Audio object", "Emitter", "Reverb send", "Low-pass filter", "Diffraction"], "common_mistakes": ["Confusing obstruction (direct path blocked, reflections open) with occlusion (both paths blocked)", "Applying obstruction filtering to the reverb/aux send, which removes the cue that the source is still in the room", "Using a hard volume cut instead of a low-pass filter, which sounds unnatural"], "scenario_contexts": ["A character speaking from behind a pillar in the same room", "A sound source partly hidden by furniture in an interactive scene", "Simulating a barrier that muffles direct sound but not room reflections"]}, "6fe5778e-be77-45f9-8cf0-74dedb760080": {"definition": "Dialogue spoken by a character or source that is not visible within the frame — just outside it, behind the camera, or elsewhere in the scene's space. It is diegetic (part of the story world) but has no visible speaker, and is typically given more distance, room tone, and reverb than on-screen lines to place it beyond the frame.", "plain_english": "It is talking from someone you cannot see in the shot, like a voice from the next room. The words still belong to the scene, but the speaker is out of frame.", "purpose_function": "It lets a scene use voices beyond what the camera shows, widening the world and carrying action off-screen. Editors use it to keep conversations flowing across cuts and to imply space outside the frame.", "practical_application": "A dialogue editor cuts an off-screen line and adds a little distance and room tone so it sits as if coming from beyond the frame.", "category": "Dialogue", "related_terms": ["On-screen dialogue", "Diegetic sound", "Room tone", "ADR", "Perspective", "Dialogue editing"], "common_mistakes": ["Mixing off-screen lines as close and dry as on-screen lines, which flattens the sense of space", "Confusing off-screen dialogue (diegetic, inside the scene) with narration or voice-over (outside the scene)", "Forgetting to match perspective and reverb to the character's implied distance"], "scenario_contexts": ["A character answering from another room while the camera stays on the listener", "A crowd voice heard from just outside the frame", "Continuing a conversation over a cutaway to a reaction shot"]}, "cac957c0-c91c-4c53-bd02-9a62ac339b75": {"definition": "In spatial and game audio, a sound source (emitter) that radiates its sound equally in all directions, with no directional cone or angle-dependent attenuation. Its level at the listener depends on distance and any obstruction, but not on the direction the source is 'facing.'", "plain_english": "It is a sound source that sends its sound out evenly in every direction, like a ringing bell. It does not point one way, so it sounds the same from any side.", "purpose_function": "It exists to model sounds that have no clear facing direction, such as a hum, an alarm, or ambience. Using it keeps a source consistent in tone as the listener moves around it.", "practical_application": "A sound designer sets a generator's emitter to omnidirectional so it stays steady in level as the player circles it, changing only with distance.", "category": "Spatial Audio", "related_terms": ["Emitter", "Audio object", "Directional emitter", "Attenuation", "Obstruction", "Spatial audio"], "common_mistakes": ["Using an omnidirectional emitter for a source that clearly faces one way, such as a speaker cabinet or a megaphone", "Assuming omnidirectional means no distance attenuation — level still falls off with distance", "Confusing an emitter's radiation pattern with a microphone's polar pattern"], "scenario_contexts": ["A buzzing light or generator that sounds the same from any angle", "An alarm placed as an omnidirectional source in a game level", "Ambient point sources that need no facing direction"]}, "764255d3-601c-41b2-8072-7f63e82b44a9": {"definition": "Dialogue spoken by a character or source that is visible within the frame at the moment it is heard. It is diegetic and is typically mixed close and anchored to the center of the picture, with perspective and reverb matched to the character's on-screen position and distance.", "plain_english": "It is talking by someone you can see in the shot. The sound is matched to where they are on screen, so their voice lines up with their lips.", "purpose_function": "It anchors speech to a visible speaker so the audience links voice to character clearly. Matching its perspective to the picture keeps dialogue believable and easy to follow.", "practical_application": "A dialogue editor syncs on-screen lines to the picture, and the mixer keeps them centered so the voice tracks the actor's position.", "category": "Dialogue", "related_terms": ["Off-screen dialogue", "Diegetic sound", "Sync", "Perspective", "Dialogue editing", "ADR"], "common_mistakes": ["Letting on-screen dialogue drift out of sync with the actor's lip movements", "Adding heavy reverb that does not match the visible space", "Panning on-screen dialogue wide instead of anchoring it to the center/screen"], "scenario_contexts": ["A close-up of an actor delivering a line", "Two visible characters talking in a shot-reverse-shot scene", "Syncing a replaced ADR line to an on-screen performance"]}, "19af0f9c-2929-4b2c-89ca-582ba09e243c": {"definition": "A one-shot asset is an audio sample or sound file set to play once through in full when triggered, rather than looping. In samplers, virtual instruments, and game audio it is used for discrete events such as hits, stabs, impacts, and single notes.", "plain_english": "A one-shot is a sound clip that plays all the way through once each time you fire it, instead of looping. Think of it like a doorbell: press it and you get one full 'ding,' not a sound that keeps repeating.", "purpose_function": "It provides a single, self-contained sound event that plays predictably from start to finish, so designers can trigger distinct hits and cues without managing loop points.", "practical_application": "A technician loads one-shot samples into a sampler or game-audio engine and maps them to keys or events so each trigger fires one complete sound, such as a gunshot, footstep, or drum hit.", "category": "Sample Assets", "related_terms": ["Sample", "Loop", "Sampler", "Trigger", "Velocity layer", "Sound design"], "common_mistakes": ["Confusing a one-shot with a loop and enabling loop playback, so the sound repeats or stutters instead of playing once.", "Leaving long silence or an unwanted tail baked into the file, which delays or muddies retriggering.", "Assuming a one-shot must be short; the term is about single playback, not duration."], "scenario_contexts": ["Mapping drum hits as one-shots in a sampler so each pad triggers one full note.", "Loading impact and whoosh one-shots into a game engine to fire on in-game events.", "Building a sound-effects library where each file is a discrete one-shot for editors to drop onto a timeline."]}, "4f79fea3-a9dc-44cc-adac-995a73e26d35": {"definition": "An optional-material stem is a delivered submix (stem) carrying non-essential or alternate audio content that a distributor may choose to include or omit, rather than a required element of the main mix. It is supplied alongside the core stems so downstream users can add, swap, or leave out that material.", "plain_english": "This is a separate audio track given to a client that holds extra sound they can use or skip. It is like serving a meal with the sauce on the side, so they can add it or leave it off.", "purpose_function": "It keeps optional or alternate content separate from the required mix so distributors, broadcasters, or clients can tailor the final soundtrack without re-opening the whole session.", "practical_application": "A post engineer exports optional-material stems, such as alternate music, optional narration, or extra effects, so an editor in another market can add or drop them during versioning.", "category": "Deliverables", "related_terms": ["Stem", "M&E", "DME", "Printmaster", "Deliverables", "Versioning"], "common_mistakes": ["Folding optional material into the main stems, so it can no longer be removed cleanly.", "Failing to label the stem clearly, leaving the client unsure what is optional versus required.", "Assuming an optional stem can be lower quality; it must still meet the full delivery spec."], "scenario_contexts": ["Delivering an alternate-music stem the network may swap in for a specific broadcast.", "Providing an optional-narration stem so a foreign version can include or omit voice-over.", "Supplying extra sound-effects material as a separate optional stem for a director's later choice."]}, "5482a965-6e92-4394-b292-cee9167b1ca7": {"definition": "Orchestra comping is the editing practice of assembling one composite orchestral performance by selecting and joining the best sections from multiple recorded takes. Editors cut between takes at musically and acoustically suitable points so the final track sounds like a single continuous, unified performance.", "plain_english": "Comping means building one great orchestra take out of the best bits of several takes. It is like making a photo album from many shots, keeping only the best moment from each.", "purpose_function": "It lets a music editor deliver the strongest possible performance, with the best notes, intonation, and feel, which matters because a full orchestra rarely repeats a flawless pass every time.", "practical_application": "Working from a session's multiple takes, a music editor auditions passages, marks the best ones, and crossfades between takes at bar lines or rests so the joins are inaudible across every microphone.", "category": "Orchestral Editing", "related_terms": ["Comping", "Take", "Crossfade", "Music editing", "Orchestra timing adjustment", "Orchestra phase alignment"], "common_mistakes": ["Cutting mid-note or mid-phrase, which creates audible jumps in the sustained orchestral sound.", "Comping only the close mics and ignoring the room and tree mics, so the ambience jumps or phases at edits.", "Choosing takes for one section without checking they still balance against the rest of the orchestra."], "scenario_contexts": ["Editing a film-score cue by joining the best string passages from three orchestral takes.", "Fixing a single wrong horn note by comping in the matching bar from an alternate take.", "Assembling a clean master take from a live orchestral session for album release."]}, "7455e349-e5c7-40ae-a700-5bc0ee185c6e": {"definition": "Orchestra phase alignment is the process of time-aligning the many microphones used to record an orchestra, including close (spot) mics, section mics, the main tree, and room mics, so their combined signals sum coherently instead of comb filtering or smearing. It compensates for the different arrival times of the same sound at each microphone position.", "plain_english": "In a big orchestra recording, many mics pick up the same sound at slightly different times. Phase alignment nudges those signals into step so they add up cleanly. Without it they can thin each other out, like rowers pulling out of time.", "purpose_function": "It preserves tone, punch, and a clear stereo image when many mics are mixed together, preventing the hollow, comb-filtered sound that results when overlapping signals arrive out of time.", "practical_application": "An engineer measures or ear-checks the delay between spot mics and the main tree, then applies small time delays or nudges tracks so each close mic lines up with the main pickup before balancing the mix.", "category": "Orchestral Recording", "related_terms": ["Phase alignment", "Comb filtering", "Spot microphone", "Decca tree", "Time alignment", "Polarity"], "common_mistakes": ["Confusing polarity (flipping +/-) with time alignment; flipping polarity does not fix arrival-time differences.", "Aligning by waveform alone and ignoring how it sounds, which can spoil the natural room blend.", "Over-delaying spot mics so they drift behind the main tree and smear transients."], "scenario_contexts": ["Time-aligning violin spot mics to the Decca tree before mixing a scoring session.", "Fixing a hollow, comb-filtered brass section caused by spot and room mics fighting.", "Aligning added close mics to the main pair when re-balancing an orchestral recording in the mix."]}, "e72ec58a-9973-4ecc-92ef-d7ae2a05cb99": {"definition": "Orchestra timing adjustment is the editing of an orchestral recording's timing—tightening or shifting notes, phrases, or whole sections—so the performance locks to a click, to picture, or to a desired feel. It uses nudging, time-stretching, or elastic-audio editing while preserving the ensemble's natural phrasing.", "plain_english": "This means moving parts of an orchestra recording a little earlier or later so they line up. They can match a click, match the video, or just feel tighter. It is like straightening a group photo so everyone stands in line.", "purpose_function": "It corrects small timing errors and syncs the music to a film's action or a tempo map, which matters when a cue must hit an on-screen moment or match an edited scene.", "practical_application": "A music editor slides or time-stretches sections so a downbeat lands on a cut, or tightens a slightly late entrance, checking that all mics move together to avoid phase problems.", "category": "Orchestral Editing", "related_terms": ["Time-stretching", "Elastic audio", "Music editing", "Click track", "Orchestra comping", "Sync point"], "common_mistakes": ["Time-stretching one mic while leaving the others, which throws the tracks out of phase.", "Quantizing an orchestra too hard, stripping the human feel that makes it sound live.", "Adjusting timing without watching picture, so a hit lands slightly off the on-screen action."], "scenario_contexts": ["Nudging an orchestral hit so it lands exactly on a scene cut.", "Tightening a late string entrance to match the click on a scoring stage.", "Stretching a cue slightly so it fits a re-timed picture edit."]}, "1bfa355c-c2f7-4066-8dba-aa7c18038d26": {"definition": "Organic sound design is the crafting of sounds that feel natural, living, and imperfect—typically built from recorded real-world (acoustic) sources or heavily processed field recordings—rather than from clean, static synthesis. The aim is a result that breathes and evolves like a real object or environment.", "plain_english": "This is designing sounds that feel real and alive instead of cold and electronic. Designers often build them from recordings of real things like water, cloth, or metal. The result feels natural, the way a handmade item feels different from plastic.", "purpose_function": "It gives films, games, and media sounds that feel believable and emotionally warm, helping audiences connect with a scene, object, or creature as if it were real.", "practical_application": "A sound designer records or layers real-world textures such as breath, foliage, or friction, then shapes them so a fantasy creature or interface still feels natural rather than obviously synthetic.", "category": "Sound Design", "related_terms": ["Sound design", "Field recording", "Foley", "Layering", "Texture", "Sample"], "common_mistakes": ["Assuming 'organic' means unprocessed; heavy processing of real-world sources is still common.", "Leaning on obvious synth presets, which breaks the natural feel.", "Layering so many sources that the sound turns to mush instead of feeling real."], "scenario_contexts": ["Building a natural-feeling creature voice from layered animal and human recordings.", "Designing an interface or UI sound that feels warm and hand-made rather than sterile.", "Creating ambience for a forest scene from real field recordings."]}, "e1dfbc0e-9b1e-4eba-8d41-8de9be0caa2e": {"definition": "In recording, a page turn is the act of a performer turning a page of their printed part or score during a session or performance. Because the movement and paper can produce audible noise picked up by nearby microphones, it is a recognized source of unwanted sound that engineers and editors anticipate and manage.", "plain_english": "A page turn is when a musician flips to the next page of their sheet music. The paper rustle can get caught by the mics. It is one of the small noises a team listens for and cleans up, like a cough or a chair squeak.", "purpose_function": "Naming it as a distinct event helps a team plan mic placement, take timing, and edits around it, keeping paper rustle out of the final recording.", "practical_application": "During a scoring session, an engineer notes where page turns fall and may capture clean coverage there, and an editor later cuts to a quiet take to hide any page-turn noise.", "category": "Session Practice", "related_terms": ["Spot microphone", "Room tone", "Noise floor", "Take", "Music editing", "Orchestra comping"], "common_mistakes": ["Ignoring page-turn noise until the mix, when it is far harder to remove.", "Placing spot mics so close that every paper rustle is captured.", "Assuming page turns only matter in quiet passages; open mics can catch them anywhere."], "scenario_contexts": ["Planning takes so a loud page turn falls during a rest in the music.", "Editing out a paper rustle by cutting to an alternate take at that bar.", "Advising players to pre-turn or stagger page turns on a scoring stage."]}, "cf3b6df7-e3ea-47c8-9aca-6920ec784691": {"definition": "A Foley category covering the sounds of manipulating paper materials — rustling, folding, crumpling, sorting and page movement — performed to match on-screen handling of documents, books, letters or packaging.", "plain_english": "It is the rustle and crinkle sound of someone handling paper. Like the noise a letter makes when it is unfolded or a stack of pages is shuffled.", "purpose_function": "It gives paper actions audible texture and weight, making documents, books and letters feel real and reinforcing the pace of the on-screen handling.", "practical_application": "A Foley artist rustles and folds matching paper stock in sync with the picture, choosing weight and stiffness to suit the document shown.", "category": "Foley", "related_terms": ["Page turn", "Object pickup", "Plastic movement", "Jacket movement", "Hand contact"], "common_mistakes": ["Using the wrong paper weight, so a thin note sounds like heavy cardstock.", "Over-performing rustles until routine handling sounds distractingly busy.", "Letting the paper sound drift off sync with the visible page or fold."], "scenario_contexts": ["Covering a character reading and folding a letter.", "Adding page rustles as someone flips through a report.", "Selling the handling of a newspaper or map in a dialogue scene."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"7500e313-7c3b-4359-8806-03dc14f57859": {"definition": "Parameter-driven audio is sound whose playback and behavior are controlled in real time by data values (parameters) rather than fixed to a linear timeline. In interactive media such as games and VR, engine parameters like speed, distance, health, or intensity drive volume, pitch, filtering, layering, and which sounds play.", "plain_english": "This is sound that changes based on live values instead of being one fixed clip. In a game, how fast a car goes can control its engine sound. The audio reacts to the action, like a dimmer switch tied to what you do.", "purpose_function": "It lets a soundtrack adapt to a user's actions and the state of a scene, so interactive experiences stay responsive and believable instead of replaying the same static clip.", "practical_application": "Using audio middleware, a technician maps game parameters to sound properties, for example linking vehicle speed to engine pitch and volume, so the mix responds automatically as the game state changes.", "category": "Interactive Audio", "related_terms": ["Interactive audio", "Adaptive audio", "Audio middleware", "Game audio", "Layering", "Automation"], "common_mistakes": ["Confusing parameter-driven audio with simple automation; here values change live from user actions, not from a fixed timeline.", "Mapping too many parameters at once, making the sound behave unpredictably.", "Forgetting to smooth parameter changes, causing audible zipper noise or jumps."], "scenario_contexts": ["Linking engine RPM to a car's engine-sound pitch and volume in a game.", "Driving reverb and filtering by a player's distance from a sound source.", "Blending music layers based on on-screen tension or intensity."]}, "2afb4481-27f5-4522-9b53-437f0a4524d7": {"definition": "A sound effect in which a source moves past the listener or camera, so its level rises as it approaches, peaks alongside, then falls as it recedes; a moving source also produces a Doppler pitch shift and a left-to-right pan. Common examples are car, train, and aircraft 'pass-bys' cut or recorded for sound editing.", "plain_english": "It is the sound of something moving past you, like a car whooshing by. It gets louder as it comes closer, then softer as it goes away. The pitch also drops a little as it passes.", "purpose_function": "It sells motion and space on screen, telling the audience a source is traveling through the scene rather than sitting still, and it adds energy and direction to action.", "practical_application": "A sound editor cuts or records vehicle and object pass-bys, then adds panning and a Doppler pitch bend so the effect tracks the on-screen movement.", "category": "Sound Effects", "related_terms": ["Doppler effect", "Panning", "Foley", "Sound effects editing", "Perspective"], "common_mistakes": ["Adding a Doppler pitch shift so extreme it sounds unnatural instead of a subtle drop as the source passes.", "Panning the pass-by faster or slower than the object actually moves on screen, breaking sync.", "Keeping the same brightness and level regardless of distance, so a far-off pass-by is as loud and bright as a close one."], "scenario_contexts": ["Cutting car pass-bys for a busy street scene so traffic moves believably across the screen.", "Adding an aircraft fly-over that travels from one speaker to the other in a surround mix.", "Recording a real vehicle pass-by on location to build a custom effects library."]}, "044efbf8-e986-4a1e-8d6e-ec0acf786236": {"definition": "In sound for picture, the deliberate heightening of a sound performance — Foley, effects, or voice — beyond literal reality so it reads as bigger, sharper, or more emphatic than the real event, supporting drama or point of view; a hyperreal approach to performed sound.", "plain_english": "It means making a sound bigger or bolder than real life to add punch. A movie punch, for example, is made to sound much heavier than a real one so the hit feels powerful.", "purpose_function": "It shapes how an audience feels a moment, using weightier or more detailed sound to add impact, emotion, or focus that a plain, realistic recording would miss.", "practical_application": "A sound designer or Foley artist performs and layers sounds with extra weight and detail — a heavier footstep, a meatier punch — to match the dramatic tone of the picture.", "category": "Sound Design", "related_terms": ["Hyperrealism", "Foley", "Sound design", "Sound effects editing", "Sweetening", "Perspective"], "common_mistakes": ["Exaggerating every sound, so nothing stands out and the whole mix becomes tiring.", "Pushing a sound so far it no longer matches the picture and pulls the viewer out of the story.", "Confusing exaggeration with simply raising the fader, instead of performing and layering for weight and detail."], "scenario_contexts": ["Building a larger-than-life punch or body-fall for a fight scene.", "Heightening creature or monster vocals so they feel threatening.", "Making a hero's footsteps heavier to add menace or importance."]}, "d52026b0-9574-4686-a2da-25a7c1384148": {"definition": "In dialogue replacement (ADR/looping), matching a re-recorded or replacement vocal take to the original on-screen performance in timing, pitch, energy, and emotional delivery so the new line is indistinguishable from the production sound.", "plain_english": "It means making a re-recorded line sound just like the actor's original take. The new words must have the same timing, feeling, and energy so no one can tell the line was replaced.", "purpose_function": "It keeps replaced dialogue believable and consistent with the picture, so the audience never notices that a line was recorded later in a studio instead of on set.", "practical_application": "During ADR, the recordist and editor guide the actor to hit the same rhythm and emotion as the guide track, then nudge and process the take to line up with the original.", "category": "Dialogue", "related_terms": ["ADR", "Lip sync", "Dialogue editing", "Guide track", "Production dialogue", "Performance synchronization"], "common_mistakes": ["Matching only the words and timing but missing the emotion, so the line feels flat next to the picture.", "Recording ADR with a very different mic or room and not matching the tone of the original set recording.", "Assuming volume alone makes a match, and ignoring rhythm and breath."], "scenario_contexts": ["Replacing a noisy on-set line with a clean ADR take that still sounds spontaneous.", "Re-recording dialogue for a scene shot near loud traffic.", "Matching a dubbed line to the original actor's delivery for a foreign-language version."]}, "d1ab2733-85fc-4904-a39b-98b49078faf1": {"definition": "The quality of a recorded, edited, or Foley performance sounding natural and believable within the world of the picture, so voices, footsteps, and actions read as genuine rather than staged or artificial.", "plain_english": "It is how true-to-life a performed sound feels. Good footsteps, for example, should sound like a real person walking in that room, not like someone tapping in a studio.", "purpose_function": "It keeps the audience inside the story by making performed sound feel like it truly belongs to the characters and spaces on screen.", "practical_application": "Foley artists and dialogue editors watch the picture and perform or edit to match the surface, weight, pace, and mood of the action so it feels lived-in.", "category": "Sound Design", "related_terms": ["Foley", "Dialogue editing", "Performance match", "ADR", "Sound design", "Perspective"], "common_mistakes": ["Performing sounds in perfect, even rhythm, when real actions are slightly uneven.", "Ignoring the room and surface, so footsteps or props do not match the space on screen.", "Over-cleaning dialogue until it sounds sterile and loses its natural life."], "scenario_contexts": ["Foley-walking a character across gravel so the steps feel real.", "Editing dialogue so pauses and breaths sound like natural speech.", "Balancing prop sounds so a busy kitchen scene feels genuine."]}, "50a04cf0-2827-45ec-a90e-6b2ea8cc1be7": {"definition": "A dialogue or audio edit that fixes flaws in a recorded performance — a fluffed or mispronounced word, an unwanted breath, a timing slip, or a weak take — by cutting, replacing, nudging, or blending material, ideally from the same production sound, without re-recording.", "plain_english": "It is fixing a mistake in a take by editing instead of recording again. You might swap a stumbled word for a clean one from another take so the line sounds right.", "purpose_function": "It saves a usable performance and avoids costly re-recording, keeping the actor's original delivery while removing distracting errors.", "practical_application": "A dialogue editor pulls a clean word or syllable from an alternate take and blends it in, matching level, tone, and room so the repair is invisible.", "category": "Dialogue", "related_terms": ["Dialogue editing", "ADR", "Alternate take", "Crossfade", "Room tone", "Performance match"], "common_mistakes": ["Splicing in a word from a take with different tone or room, so the repair is obvious.", "Cutting on a hard consonant or mid-breath, creating an audible click or gap.", "Forgetting to fill edits with matching room tone, leaving dead silence."], "scenario_contexts": ["Replacing a single mumbled word with a clearer version from another take.", "Removing a loud breath or lip smack between lines.", "Tightening a slow line by trimming a pause without changing the delivery."]}, "ae6bd55c-2dd6-4896-b671-d20d8597bd44": {"definition": "Aligning a recorded performance — an ADR line, a Foley pass, or a musical take — precisely to the picture so sound events coincide with the on-screen action, including lip-sync for voice and hit-point sync for effects and Foley.", "plain_english": "It means lining up a performed sound exactly with the picture. A footstep must land when the foot hits the ground, and spoken words must match the moving lips.", "purpose_function": "It makes sound and image feel like one event, so the audience believes the sound is really coming from what they see.", "practical_application": "Editors slide, stretch, or nudge takes against the picture and use timecode and sync references so every hit and word lands on the right frame.", "category": "Synchronization", "related_terms": ["Lip sync", "ADR", "Foley", "Timecode", "Sync point", "Frame rate"], "common_mistakes": ["Syncing the start of a word but letting the end drift, so lip-sync slips.", "Fixing sync by ear alone and ignoring the frame, causing small but visible offsets.", "Time-stretching a take so far to force sync that it sounds unnatural."], "scenario_contexts": ["Lining up an ADR line to an actor's lip movements.", "Placing Foley footsteps on each visible step.", "Syncing a re-recorded music performance to a filmed player's hands."]}, "56a1592d-ab3f-498e-9d22-75d58e434bd9": {"definition": "A head-related transfer function (HRTF) captured or estimated for one specific listener's own head, torso, and outer-ear (pinna) shape, rather than a generic or averaged HRTF, used to render binaural audio that localizes more accurately for that individual.", "plain_english": "An HRTF is a map of how your head and ears change a sound before you hear it. This map lets headphones place sounds all around you. A personalized one is measured for your own ears, so the 3D effect feels more real for you.", "purpose_function": "It improves binaural spatial audio by matching the rendering to a listener's own anatomy, reducing the front-back and up-down errors that generic HRTFs often cause.", "practical_application": "In immersive and VR audio work, a technician captures or derives a listener's HRTF — by measurement, photos, or ear scans — and loads it into a binaural renderer for headphone monitoring or delivery.", "category": "Immersive Audio", "related_terms": ["Head-related transfer function", "Binaural audio", "Spatial audio", "Pinna", "Interaural time difference", "Immersive audio"], "common_mistakes": ["Assuming one generic HRTF works equally well for every listener.", "Confusing a personalized HRTF with simple headphone EQ.", "Expecting perfect localization from headphones without head tracking."], "scenario_contexts": ["Setting up a personalized binaural mix for headphone delivery of an immersive project.", "Improving 3D audio in a VR experience for a specific user.", "Monitoring an object-based mix on headphones using a measured HRTF."]}, "cf5e5961-30f7-4ed2-a508-7ccc0b19bc5a": {"definition": "Dialogue reproduced as a phantom center image — equal, in-phase level in the left and right speakers — so the voice appears to come from a point between them, rather than from a discrete center channel; it is how mono-centered dialogue sits in a two-channel (stereo/LtRt) presentation.", "plain_english": "It is dialogue sent equally to the left and right speakers so the voice seems to float in the middle. There is no real center speaker; your ears just place the sound between the two.", "purpose_function": "It keeps a voice centered on screen in stereo playback, and it matters in deliverables because a phantom center is less stable than a real center channel and can shift or thin out when a listener moves off-center.", "practical_application": "When mixing or folding down to stereo, an engineer places dialogue in the phantom center and checks it off to one side, since surround mixes usually anchor dialogue in a discrete center speaker instead.", "category": "Mixing", "related_terms": ["Center channel", "Stereo imaging", "LtRt", "Fold-down", "Downmix", "Panning"], "common_mistakes": ["Assuming a phantom center sounds the same as a discrete center speaker for every seat in the room.", "Letting the two sides drift out of phase, which smears or hollows the centered voice.", "Forgetting to check the phantom-center dialogue after a stereo fold-down of a surround mix."], "scenario_contexts": ["Mixing dialogue for a stereo TV or web deliverable with no center channel.", "Checking a phantom-center voice from an off-center seat.", "Folding a 5.1 mix down to LtRt stereo and confirming the dialogue stays centered."]}, "91ce7bd6-fcb7-4feb-a5aa-9c90039d486c": {"definition": "A digital sound-synthesis technique in which the phase of a carrier oscillator is varied by a modulator oscillator, generating harmonic and inharmonic sidebands. It is closely related to, and for most patches mathematically equivalent to, frequency modulation (FM), and is the method used in Yamaha's DX-series synthesizers.", "plain_english": "It is a way of building sounds by using one wave to bend the timing of another. This creates many new tones from simple parts, which is how classic FM synths make their bright, metallic sounds.", "purpose_function": "It creates rich, evolving timbres — from bells and electric pianos to metallic and bass sounds — using only a few oscillators, making it an efficient way to synthesize complex spectra.", "practical_application": "A sound designer sets carrier and modulator operators, their frequency ratios, and envelope depths to dial in a patch, then plays it for score, sound design, or synth cues.", "category": "Synthesis", "related_terms": ["FM synthesis", "Operator", "Carrier", "Modulator", "Oscillator", "Sideband"], "common_mistakes": ["Believing phase modulation and FM are completely different, when they produce equivalent results for most patches.", "Expecting simple, predictable results, when small ratio changes can shift a tone from harmonic to clangy.", "Confusing the modulator's job with a filter, when it reshapes the harmonic content directly rather than removing it."], "scenario_contexts": ["Programming a DX-style electric piano for a music cue.", "Designing metallic or bell-like textures for sound design.", "Creating punchy synth bass with a phase-modulation instrument."]}, "d1fe76d3-96ec-4619-aff4-ee1a3a701b98": {"definition": "An approach to sound creation in which audio is generated or controlled in real time by a physical simulation, so that a sound's pitch, loudness, and timbre are computed from modeled physical events such as collisions, friction, and resonance rather than played back from fixed recordings.", "plain_english": "Sound that a computer builds on the fly by copying the laws of physics. When two things hit in the scene, the program works out what that crash would really sound like. It is like a video game making a fresh bounce noise each time a ball lands.", "purpose_function": "It lets sound respond on its own to on-screen or in-game action, which avoids the repetition and hand-syncing that come with a small set of fixed sound files.", "practical_application": "A technician sets up and tunes procedural or physical-modeling audio tools so that events in a game engine or animation trigger matching sounds, adjusting values like material, mass, and force.", "category": "Sound Synthesis", "related_terms": ["Procedural audio", "Physical modeling synthesis", "Sound design", "Pitch manipulation", "Sample playback"], "common_mistakes": ["Confusing physics-driven sound with simply attaching recorded effects to a physics scene.", "Assuming it removes the need for sound design; the models still need careful tuning.", "Believing it always sounds more realistic than well-recorded samples."], "scenario_contexts": ["Generating collision and impact sounds inside a game engine.", "Creating responsive audio for interactive installations or VR.", "Producing procedural rolling, scraping, or wind sounds for animation."]}, "f9689aa0-ec3e-4b33-9b76-444646a68b32": {"definition": "A precise moment in the edited picture — such as a cut, an impact, or a distinct character action — that a music cue or sound effect is timed to land exactly on for dramatic emphasis; also called a hit point.", "plain_english": "An exact spot in the video where a sound or a note is made to land. Picture a cartoon where the bonk sound hits the very frame a character gets bopped on the head.", "purpose_function": "It gives composers and sound editors a shared sync target so that music and effects reinforce key visual moments and feel deliberately timed.", "practical_application": "A technician marks picture hits with timeline markers so a composer or sound editor can align notes and effects to those exact frames.", "category": "Sync & Timing", "related_terms": ["Picture synchronization", "Hit point", "Spotting session", "Timecode", "Marker"], "common_mistakes": ["Confusing a single picture hit with the overall sync of a whole scene.", "Placing the hit a frame or two late so it feels loose.", "Overusing hits until the score feels like cartoon 'Mickey Mousing'."], "scenario_contexts": ["Scoring a trailer so musical stabs land on the cut points.", "Syncing a whoosh to a fast on-screen movement.", "Marking action beats during a spotting session."]}, "74ef7e31-341d-4a2d-a6aa-afbe93c18625": {"definition": "A video display in an audio-post, editing, or scoring room that shows the program picture locked in sync with the audio session, letting operators watch the image while cutting or mixing sound to it.", "plain_english": "The screen in a sound studio that plays the video while you work on its audio. It is like the TV a sound editor watches so their sounds match what is happening on screen.", "purpose_function": "It provides the reference image that all sound-to-picture work is timed against, so editors and mixers can judge sync and timing by eye.", "practical_application": "A technician feeds picture from the workstation or a video player to the monitor and confirms it stays locked in sync with the audio during playback.", "category": "Monitoring", "related_terms": ["Picture synchronization", "Timecode", "Genlock", "Video reference", "Studio monitor"], "common_mistakes": ["Ignoring display processing delay that pushes the picture behind the audio.", "Assuming any consumer TV is accurate enough for sync-critical work.", "Confusing the picture monitor with the audio studio monitor (loudspeaker)."], "scenario_contexts": ["Watching the cut on the picture monitor while editing dialogue.", "Checking lip sync during a final mix.", "Following the image while recording Foley."]}, "43382bcf-e463-45fc-afde-6caac2b251d6": {"definition": "The alignment of recorded or edited audio with its corresponding moving image so that each sound occurs on the correct picture frame, typically established and maintained using timecode and a shared sync reference.", "plain_english": "Making the sound line up with the video so words and actions match. It is why a person's lips and their voice happen at the same time.", "purpose_function": "It ensures dialogue, effects, and music land on the right frames, which is essential for believable and professional sound for picture.", "practical_application": "A technician locks the audio workstation to timecode and a video reference, then checks lip sync and effect timing throughout the program.", "category": "Sync & Timing", "related_terms": ["Timecode", "Genlock", "Lip sync", "Picture monitor", "Sample rate"], "common_mistakes": ["Confusing frame rate with sample rate when files drift out of sync.", "Forgetting that monitor display delay can fake a sync error.", "Assuming a clip that is in sync at the start stays in sync to the end."], "scenario_contexts": ["Locking a Pro Tools session to picture via timecode.", "Fixing lip-sync drift caused by a pull-up or pull-down frame-rate change.", "Syncing production sound to the camera picture in editorial."]}, "a8180264-f54d-4593-a190-dd6f8956d544": {"definition": "The process of updating an existing audio session to match a revised picture edit — moving, trimming, adding, or removing sound to follow every change between the old and new cut — usually guided by a change list or EDL.", "plain_english": "Fixing your sound session so it matches a new version of the video edit. When the picture editor moves or cuts scenes, you shift your sounds to keep them lined up.", "purpose_function": "It keeps sound work in sync as the picture keeps changing during post, so earlier editing and mixing are not lost when a new cut arrives.", "practical_application": "A technician imports a change list, then uses it to conform the session and verifies that every edit point still lines up with the new picture.", "category": "Conforming", "related_terms": ["Conform", "Change list", "EDL", "Reconform", "Picture synchronization", "Turnover"], "common_mistakes": ["Conforming by eye instead of using an accurate change list.", "Missing small internal trims that shift everything after them.", "Not backing up the session before applying a large conform."], "scenario_contexts": ["Reconforming a dialogue session after a new picture turnover.", "Updating effects and music to a revised cut before the mix.", "Applying a change list to a Pro Tools session with a conforming tool."]}, "1b643a46-491d-4c1a-8195-3d983dfb8033": {"definition": "The room and equipment where a film or program's picture is edited, typically built around a nonlinear editing system such as Avid Media Composer, from which the sound department receives its turnovers.", "plain_english": "The room where the video editor cuts the film together. It holds the editing computer that the sound team gets its footage and edit lists from.", "purpose_function": "It is where the edited cut is created and revised, providing the picture, timeline, and edit data that all later sound work depends on.", "practical_application": "A technician collects turnovers such as a reference video, an AAF or OMF, and change lists exported from the picture-editing suite to start or update the sound session.", "category": "Post Facilities", "related_terms": ["Nonlinear editing", "AAF", "OMF", "Turnover", "Change list", "Picture-change conform"], "common_mistakes": ["Assuming the rough audio settings in the picture-editing suite are accurate for mixing.", "Confusing the picture-editing suite with the sound-editing or mix room.", "Trusting temp audio from the suite instead of the original source recordings."], "scenario_contexts": ["Receiving an AAF and reference movie exported from the editing suite.", "Coordinating turnovers between picture editorial and sound.", "Checking a locked cut before spotting sound."]}, "fdcccbe5-1cd0-434e-ac35-9f5a9b67babb": {"definition": "The deliberate raising or lowering of the perceived pitch of recorded audio — either tied to playback speed or independent of it through time/pitch processing — for creative or corrective purposes.", "plain_english": "Changing how high or low a sound is. You can make a voice deeper or squeakier, like slowing down or speeding up a record. Modern tools can do it without changing the speed.", "purpose_function": "It lets editors design new sounds, fix out-of-tune or mismatched material, and shift sounds to fit a scene without re-recording them.", "practical_application": "A technician uses pitch-shifting or elastic-audio tools to tune dialogue, build creature or effect sounds, or match a sound to picture.", "category": "Audio Processing", "related_terms": ["Pitch shifting", "Time stretching", "Formant", "Sample rate", "Sound design", "Vari-speed"], "common_mistakes": ["Confusing pitch shifting with time stretching.", "Shifting pitch so far that unmanaged formants make a voice sound unnatural.", "Forgetting that changing sample-rate playback shifts both pitch and speed together."], "scenario_contexts": ["Lowering a voice to create a monster or giant.", "Tuning a hummed note or an off-pitch line.", "Pitching an effect up to make it feel smaller and faster."]}, "23298695-4a13-4892-a927-67fc14d70482": {"definition": "A Foley movement category covering the crinkle, creak and rustle of plastic materials — bags, packaging, rain gear, tarps and hard plastic props — performed to match on-screen handling or body movement.", "plain_english": "It is the crinkle and creak sound of plastic being moved. Like the noise a shopping bag or a raincoat makes when someone shifts around.", "purpose_function": "It adds material-specific texture to movement, distinguishing plastic from cloth or leather and reinforcing what a character is wearing or handling.", "practical_application": "A Foley artist manipulates matching plastic — a bag, a tarp or a raincoat — in sync with the actor, layering it under footsteps or handling as needed.", "category": "Foley", "related_terms": ["Jacket movement", "Pocket movement", "Paper handling", "Jewelry movement", "Object pickup"], "common_mistakes": ["Choosing plastic with the wrong stiffness, so soft film sounds like a rigid crate.", "Performing plastic crinkle louder than the scene warrants, pulling focus from dialogue.", "Reusing the same plastic rustle for every material instead of matching the prop."], "scenario_contexts": ["Adding raincoat crinkle to a character walking in a storm.", "Covering the handling of a plastic shopping bag.", "Layering tarp movement over a construction-site scene."]}, "21a5d546-e93d-49e7-a7ad-d3d1841ba54e": {"definition": "How an audio file, session, or system reproduces its content when played — whether it plays at the correct speed and pitch, stays locked to picture and timecode, and responds correctly to transport, looping, and triggering settings.", "plain_english": "How a sound file or setup acts when you press play. Does it play at the right speed, stay lined up with the video, and loop or stop the way it should?", "purpose_function": "Knowing the expected playback behavior lets a technician predict and verify how audio will perform on a target system, so deliverables play back correctly for the client.", "practical_application": "A technician checks playback behavior during quality control, confirming a file plays at the right sample rate, level, speed, and sync before it is delivered.", "category": "Playback", "related_terms": ["Sample rate", "Timecode", "Picture synchronization", "Transport", "Loop", "Quality control"], "common_mistakes": ["Assuming a file that plays fine on one system will behave the same on another.", "Ignoring a sample-rate mismatch that changes speed and pitch on playback.", "Confusing a looping or one-shot setting error with a corrupt file."], "scenario_contexts": ["QC-checking a delivered mix for correct speed and sync.", "Testing how a sample loops or one-shots in a session.", "Confirming a file plays back at the specified sample rate and level."]}, "4c0a419a-56e9-4877-80a1-ce535eb4f7a0": {"definition": "In audio middleware and game sound engines, a playback instance is a single runtime occurrence of a sound or event actually being played, created each time its source asset is triggered. It is distinct from the source definition, can be individually positioned, controlled, and stopped, and it counts against the engine's voice and instance limits.", "plain_english": "A playback instance is one single time a sound is actually playing. If the same footstep sound plays five times at once, that is five instances. Think of it like five copies of one song playing on five phones. Each one can be controlled on its own.", "purpose_function": "It lets the engine track and manage each sounding voice separately, so the system can position, mix, prioritize, and cap concurrent sounds without changing the shared source asset.", "practical_application": "A sound designer watches active instance counts and sets per-sound instance limits so repeated triggers like gunfire or footsteps do not exhaust voices or cause phasing and clipping.", "category": "Interactive Audio", "related_terms": ["Positional audio", "Playlist container", "Procedural ambience", "Voice management", "Sound event"], "common_mistakes": ["Confusing the source sound asset with a single playback instance of it", "Forgetting to set instance limits, so repeated triggers stack up and steal voices or overload the mix", "Assuming that stopping the event stops every instance when instances may be scoped to individual game objects"], "scenario_contexts": ["Limiting how many footstep instances can play at once in a busy game scene", "Debugging why a looping ambience keeps stacking new instances instead of reusing one", "Positioning each active instance of a crowd voice at a different location"]}, "3d263996-f5a3-49b6-9a0c-11f595cf6f86": {"definition": "A playlist container is a structural object in an audio engine's interactive-music or sound hierarchy that holds a set of child objects, such as music segments or sounds, and defines both the order — sequence or random — and the play mode — step (one child played per trigger) or continuous (children played back-to-back) — by which they are played back.", "plain_english": "A playlist container is a folder that holds several sound or music pieces and decides what plays and in what order. It can play them in a set order or shuffle them. It works like a playlist app told to go in order or on random. This keeps game music from sounding the same every time.", "purpose_function": "It exists to sequence and vary musical or ambient material at runtime, letting one container re-order or randomize its contents so audio stays fresh and adapts to gameplay.", "practical_application": "A game composer places music segments in a playlist container and sets it to random-continuous so the score reshuffles sections instead of repeating one fixed loop.", "category": "Interactive Music", "related_terms": ["Playback instance", "Procedural ambience", "Positional audio", "Music segment", "Random container"], "common_mistakes": ["Setting the play mode to sequence when random variation was intended", "Nesting containers without checking how parent and child play logic interact", "Forgetting to define transition or loop rules, which causes gaps or hard cuts between segments"], "scenario_contexts": ["Re-sequencing music segments so a level's theme varies on each loop", "Randomizing several ambience beds so a location never sounds identical twice", "Building a combat music system that steps through intensity segments"]}, "877217d2-623f-4778-9bc4-ead06c0afc1e": {"definition": "A Foley movement element covering the sound of a hand entering or leaving a pocket and its contents shifting inside — fabric friction plus the muted rattle of keys, coins or a phone.", "plain_english": "It is the sound of a hand going into a pocket and the stuff inside moving. Like the soft jingle and rustle when someone reaches for their keys.", "purpose_function": "It adds a small but telling layer of realism to a character's movement and business, cueing the audience that something is being reached for or stowed.", "practical_application": "A Foley artist performs the reach into a matching garment pocket, adding coin or key content to sync with the actor's hand action.", "category": "Foley", "related_terms": ["Jacket movement", "Key jingle", "Plastic movement", "Hand contact", "Object pickup"], "common_mistakes": ["Adding a loud coin rattle when the character's pocket should be empty.", "Letting the pocket sound sit off sync with the visible hand movement.", "Using the same content rattle regardless of what the character carries."], "scenario_contexts": ["Covering a character reaching for keys or a phone.", "Adding fabric and content movement as someone pockets an object.", "Layering pocket business under a walking shot to build character."]}, "97f28548-f92f-4e8c-912a-10668bd7686f": {"definition": "Portal-based audio is a spatial-audio approach in which openings between adjacent acoustic spaces — portals such as doors and windows — are modeled explicitly, so the engine can propagate reverberation, sound transmission, and diffraction from one room into the next through those openings.", "plain_english": "Portal-based audio treats doorways and windows as the paths sound travels between rooms. When you stand in a hallway, noise from the next room leaks in through its open door, and the engine copies that. As you move past the doorway, the sound bends and fades to match. It makes indoor spaces feel connected and real.", "purpose_function": "It exists to make virtual environments sound believable by routing a room's reverb and sound energy through its actual openings, instead of treating every space as fully sealed or fully open.", "practical_application": "A game audio programmer places portal shapes in doorways so a noisy machine room bleeds through to the corridor and smoothly opens up as the player walks through.", "category": "Spatial Audio", "related_terms": ["Positional audio", "Playback instance", "Procedural ambience", "Reverb zone", "Diffraction"], "common_mistakes": ["Misplacing or mis-sizing portal geometry so sound leaks where there is no real opening", "Forgetting that closing a door should change the portal's transmission, not just mute the sound", "Relying on portals alone and ignoring occlusion for solid walls"], "scenario_contexts": ["Letting reverb from a large hall spill into a connected corridor through its doorway", "Simulating muffled music leaking through a closed door as a player approaches", "Blending two rooms' acoustics as a character walks through an open threshold"]}, "ca362dae-daef-49dd-be38-241de3a0ecc6": {"definition": "Positional audio is the rendering of sound so that each source is perceived to come from a specific location in three-dimensional space relative to the listener, achieved through panning, inter-aural level and time differences, distance-based attenuation and filtering, and, for headphones, head-related transfer functions.", "plain_english": "Positional audio makes each sound seem to come from a real spot around you. A sound on your left is louder in your left ear, and a far-off sound is quieter and duller. It is how a game lets you hear that footsteps are behind you. This helps you locate things by ear.", "purpose_function": "It exists to give listeners directional and distance cues, so players or viewers can locate sound sources and feel immersed in a 3D scene.", "practical_application": "A game sound designer assigns 3D attenuation curves and spatialization to a source so its volume, pan, and tone shift correctly as the player moves around it.", "category": "Spatial Audio", "related_terms": ["Portal-based audio", "Playback instance", "Procedural ambience", "Attenuation", "Binaural audio"], "common_mistakes": ["Leaving important sounds 2D so they do not move with the scene", "Setting attenuation ranges too short or too long, making sources vanish or never fade", "Assuming stereo panning alone gives full 3D cues without distance filtering or elevation"], "scenario_contexts": ["Making an enemy's gunfire come from its actual direction in a shooter", "Fading and filtering a river's sound as the player walks away from it", "Delivering headphone spatialization so VR sounds track head movement"]}, "b71dd1e1-700f-47c4-be65-81966251172e": {"definition": "A post-production facility is a commercial establishment equipped with the rooms, systems, and staff to complete film, television, or media projects after shooting, typically housing multiple editing suites, mixing or dubbing stages, machine and server rooms, and often ADR and Foley stages.", "plain_english": "A post-production facility is a building where movies and shows are finished after filming. It holds many rooms for editing, mixing sound, and adding effects. Think of it as a workshop where raw footage is polished into the final product. Big projects rent time there.", "purpose_function": "It exists to gather the specialized rooms, gear, and technical staff needed for finishing work in one managed place, so productions can edit, mix, and master without building their own studios.", "practical_application": "A supervising sound editor books time at a post-production facility to cut dialogue and effects in its edit suites and then final-mix on its dubbing stage.", "category": "Post Facilities", "related_terms": ["Post-production suite", "Pre-roll click", "Playback instance", "Dubbing stage", "ADR"], "common_mistakes": ["Confusing the whole facility with a single suite or room inside it", "Underbooking stage time and running past the scheduled mix slot", "Assuming every facility supports the required delivery format without checking its calibration and monitoring"], "scenario_contexts": ["Scheduling picture and sound editorial across several suites in one facility", "Booking a certified dubbing stage for a theatrical final mix", "Choosing a facility because it is calibrated to the target loudness and monitoring standard"]}, "5cc88b22-9cd9-4d1e-b043-aa681bda6d1c": {"definition": "A post-production suite is a single self-contained room and workstation environment within a facility, configured for a specific finishing task such as a picture edit suite, sound editing suite, or mix suite, with its own monitoring, control surface, and processing gear.", "plain_english": "A post-production suite is one room set up for a single finishing job, like editing or mixing. It has its own screen, speakers, and gear. Think of it as one workstation in a larger workshop. An editor can work there without disturbing other rooms.", "purpose_function": "It exists to give one editor or mixer a controlled, properly monitored space for focused finishing work, isolated from other rooms in the facility.", "practical_application": "A dialogue editor works in an editing suite to clean and sync tracks, then hands the session to a mixer in a separate mix suite.", "category": "Post Facilities", "related_terms": ["Post-production facility", "Pre-roll click", "Playlist container", "Mix stage", "Editing bay"], "common_mistakes": ["Treating a small editing suite as a calibrated mix room for critical loudness decisions", "Ignoring room acoustics and monitor calibration, so mixes do not translate elsewhere", "Confusing a suite with the entire facility that contains it"], "scenario_contexts": ["Editing sound effects in a dedicated suite before the final mix", "Recording ADR lines in a suite equipped for voice", "Reviewing a cut with a client in a small screening suite"]}, "e1ee7e3c-a4ff-4bbc-9545-9c1cba618050": {"definition": "A pre-roll click is the metronome click sounded during the pre-roll or count-off period immediately before the record punch-in point, giving performers the session tempo and a rhythmic reference beat before recording actually begins.", "plain_english": "A pre-roll click is a metronome beat you hear just before recording starts. It counts you in so you come in on time and in tempo. It works like a drummer clicking sticks 'one, two, three, four' before a song. Then recording begins on the next beat.", "purpose_function": "It exists to lock the performer to the session tempo and grid before the take starts, so the first recorded notes land in time rather than drifting.", "practical_application": "A recording engineer sets a two-bar count-off click so a singer or drummer hears the tempo and enters cleanly at the punch-in.", "category": "Session Recording", "related_terms": ["Post-production suite", "Playback instance", "Click track", "Punch-in", "Tempo map"], "common_mistakes": ["Setting the pre-roll too short, so the performer cannot lock in before the take", "Leaving the click routed into the recorded bus so it bleeds onto the track", "Assuming the count-off click will be recorded when it usually is not"], "scenario_contexts": ["Counting a vocalist in before a punch-in on the chorus", "Giving a drummer a two-bar click before tracking to a tempo map", "Setting count-off in a session so overdubs enter on the correct beat"]}, "1dac7fee-e89a-40e9-8876-e90e32b410df": {"definition": "Procedural ambience is background or atmospheric sound generated algorithmically at runtime from rules, parameters, and modular audio building blocks, rather than played back as a fixed pre-recorded loop, so the ambience varies over time and can respond to changing conditions.", "plain_english": "Procedural ambience is background sound a computer builds on the fly instead of playing one recorded loop. It mixes small pieces by rules, so a forest never sounds exactly the same twice. Think of it like a cook making a dish fresh from ingredients each time. It also reacts to things like weather or time of day.", "purpose_function": "It exists to provide non-repeating, adaptive backgrounds that react to the game state, avoiding the obvious looping and memory cost of long fixed recordings.", "practical_application": "A game sound designer sets up rules that trigger scattered bird calls, wind gusts, and insect layers at random intervals so a forest bed feels alive and never loops audibly.", "category": "Procedural Audio", "related_terms": ["Playlist container", "Playback instance", "Positional audio", "Sound bed", "Randomization"], "common_mistakes": ["Confusing procedural ambience with a single long looped recording", "Under-randomizing timing or pitch so the bed still audibly repeats", "Letting too many random one-shots trigger at once and overloading voices"], "scenario_contexts": ["Building a forest bed that shifts between day and night sounds", "Generating city traffic ambience that thickens as the player nears a busy street", "Creating weather ambience that responds to wind and rain parameters"]}, "f6937775-08fb-45f6-bc38-4aa8a3622dde": {"definition": "Footstep sounds generated in real time by an algorithm that responds to a character's movement, speed, and walking surface, rather than by playing back pre-recorded Foley or fixed samples. It is used mainly in games and other interactive media so each step can vary with the action.", "plain_english": "Footstep sounds a computer builds on the fly as a character walks, matching the ground and the pace. It is like a machine making each step to order instead of replaying the same clip again and again.", "purpose_function": "It creates step sounds that follow gameplay moment to moment, which saves memory and avoids the obvious repetition you get from a small set of recorded samples.", "practical_application": "A game sound designer builds models and rules so footsteps change with the surface, such as grass, metal, or gravel, and with walk or run speed as the player moves.", "category": "Procedural Audio", "related_terms": ["Foley footsteps", "Procedural weapon sound", "Sample playback", "Surface type", "Game audio middleware"], "common_mistakes": ["Thinking procedural footsteps are just randomly triggered recorded samples rather than sounds built by a model", "Assuming they replace Foley in film, when film usually still uses recorded Foley footsteps", "Forgetting to map different surfaces, so every step ends up sounding the same"], "scenario_contexts": ["A game character walking from a wooden floor onto gravel", "A VR scene where step sounds must react to the user's pace", "A game engine producing step sounds for many characters at once"]}, "75c64bae-844a-4677-b0e9-18f9b0e15269": {"definition": "A weapon sound assembled in real time from layered component models and rules, such as the mechanical action, the shot, and the tail, rather than from one fixed sample, so it can vary with rate of fire, ammunition, and space. It is common in games and interactive media.", "plain_english": "A gun sound the computer puts together as it fires. It mixes parts like the click, the bang, and the echo, so no two shots are quite alike. It is like building each shot from small pieces instead of replaying one clip.", "purpose_function": "It lets a weapon react to how and where it is fired, which keeps rapid firing from sounding like the same clip pasted over and over.", "practical_application": "A game audio designer layers component sounds and sets rules so a rifle changes with fire rate, distance, and whether the scene is indoors or outdoors.", "category": "Procedural Audio", "related_terms": ["Procedural footsteps", "Sound synthesis", "Sample playback", "Layering", "Game audio middleware"], "common_mistakes": ["Believing one recorded shot can cover fast automatic fire without sounding repetitive", "Skipping the tail or reflections, so the shot has no sense of space", "Confusing procedural weapon sound with simply randomizing the pitch of one sample"], "scenario_contexts": ["A first-person game where a rifle fires at different rates", "A gunfight that must sound different indoors and outdoors", "An interactive scene where many weapons fire at once"]}, "4a6fd7c1-b699-4799-be53-71442d7c59f0": {"definition": "The craft of matching and combining the original production dialogue recorded on set with edited pieces, alternate takes, and ADR so the finished dialogue plays as one continuous, natural performance in a consistent space.", "plain_english": "Making the words recorded on set blend smoothly with any lines fixed or re-recorded later, so the audience never hears the joins. It is like patching a wall so well that you cannot find where the new piece meets the old.", "purpose_function": "It keeps the dialogue track sounding believable and seamless, so edits and replaced lines do not draw attention or break the scene.", "practical_application": "A dialogue editor matches level, tone, and room sound across takes and adds fill or room tone so cuts between production lines and ADR are hidden.", "category": "Dialogue Editing", "related_terms": ["Production dialogue", "ADR", "Room tone", "Dialogue editing", "Production-to-ADR match"], "common_mistakes": ["Cutting between takes without matching room tone, leaving audible gaps or shifts", "Ignoring level and tone differences between microphones on the same scene", "Assuming ADR will blend without matching its perspective to the production sound"], "scenario_contexts": ["Joining a boom take and a lav take of the same line", "Dropping an ADR line into the middle of a production performance", "Smoothing edits across a scene shot over several days"]}, "fca2d57f-1e4e-461b-af74-a7a04a86a93a": {"definition": "Editing and processing ADR, which is dialogue re-recorded in a studio, so its tone, timing, perspective, and room character match the surrounding production dialogue, making the replaced line hard to tell apart from the on-set recording.", "plain_english": "Tweaking studio-recorded lines so they sound like they were really spoken on set, matching the room and the mood. It is like color-matching new paint to an old wall so you cannot spot the touch-up.", "purpose_function": "It hides the fact that a line was replaced, so the audience hears one consistent performance instead of a noticeable studio insert.", "practical_application": "An editor adjusts timing, equalization, reverb, and level, and adds matching room tone, so an ADR line sits in the same space as the production dialogue around it.", "category": "Dialogue Editing", "related_terms": ["ADR", "Production dialogue", "Room tone", "Perspective matching", "Production-dialogue blend"], "common_mistakes": ["Leaving ADR too clean and close, so it sounds unlike the on-set recording", "Forgetting to match the room reverb and background of the original scene", "Slipping sync slightly, so the replaced line no longer fits the lip movement"], "scenario_contexts": ["Replacing an unusable on-set line because of noise", "Cleaning up profanity or a script change with an ADR line", "Matching a studio line to dialogue recorded outdoors"]}, "47aa3a6c-ea1a-49fd-bd27-2561be5fa789": {"definition": "Oversight during dialogue recording, ADR, or dubbing to ensure actors pronounce names, foreign words, technical terms, and localized lines correctly and consistently against an agreed reference.", "plain_english": "Making sure actors say every name and tricky word correctly, and the same way each time, while recording lines. It is like an editor checking spelling, but for how words are spoken.", "purpose_function": "It protects clarity and credibility by catching mispronunciations before they are locked into the final track, and keeps pronunciation consistent across scenes and episodes.", "practical_application": "A dialogue or ADR supervisor keeps a reference list of correct pronunciations and coaches or flags actors during sessions, especially for foreign names and specialist jargon.", "category": "Dialogue / ADR", "related_terms": ["ADR", "Dubbing", "Dialogue editing", "Localization", "Loop group"], "common_mistakes": ["Assuming the actor always knows the correct pronunciation of names or foreign terms", "Failing to keep pronunciation consistent across different recording days", "Confusing pronunciation supervision with accent or dialect coaching, which is a broader performance role"], "scenario_contexts": ["Recording ADR for a drama full of foreign place names", "Dubbing a series and keeping character-name pronunciation consistent", "A documentary with scientific terms that must be said correctly"]}, "f20cdbf4-1bb6-4329-bf12-e46101747132": {"definition": "A Foley performance of the sound made when a character catches or receives a thrown or handed object, recorded in sync with picture to sell the moment of contact.", "plain_english": "The Foley sound of someone catching an object, made by an artist grabbing a matching prop in time with the picture. It is like adding the smack of a caught ball after the scene is filmed.", "purpose_function": "It gives a catch on screen a believable physical sound, adding weight and impact that the original recording may not have captured.", "practical_application": "A Foley artist watches the picture and catches a matching prop at the exact frame of contact, choosing an object whose sound fits the item shown.", "category": "Foley", "related_terms": ["Foley props", "Prop toss", "Prop synchronization", "Foley stage", "Spotting session"], "common_mistakes": ["Missing the frame of contact, so the sound lands early or late", "Using a prop whose material sounds wrong for the object shown", "Overplaying the catch, so it sounds louder and heavier than the action"], "scenario_contexts": ["A character catching keys tossed across a room", "A sports scene where a ball is caught", "A hand-off of a bag or tool between two people"]}, "e29cf8a1-443b-4fc0-aa13-05f2abdd2b4c": {"definition": "Deadening or muffling a Foley prop with cloth, foam, tape, or the hand to reduce unwanted ring, rattle, or resonance so the recorded sound matches the on-screen object.", "plain_english": "Muffling a Foley prop so it does not ring or rattle too much, using cloth, foam, or your hand. It is like resting your hand on a cymbal to stop it ringing.", "purpose_function": "It controls a prop's natural resonance so the recorded sound stays tight and believable instead of ringing longer than the real object would.", "practical_application": "A Foley artist wraps or holds part of a prop, or packs it, to kill stray rattle before performing an action such as a set-down or an impact.", "category": "Foley", "related_terms": ["Foley props", "Prop synchronization", "Resonance", "Foley stage", "Prop catch"], "common_mistakes": ["Leaving a prop undamped, so it rings longer than the real object would", "Over-damping until the sound loses the character it needs", "Forgetting that the recording room itself can add unwanted ring"], "scenario_contexts": ["Stopping a metal prop from ringing after it is set down", "Muffling a rattling box so only the needed sound remains", "Controlling a resonant object in a live-sounding Foley room"]}, "0a1820d1-39d0-4513-8b79-0d893a2ec080": {"definition": "Aligning performed or recorded prop sounds precisely to the on-screen action so each handle, set-down, or impact lands exactly on the picture frame where it happens.", "plain_english": "Lining up prop sounds so they hit exactly when the object moves or lands on screen. It is like making sure a clap sound matches the moment two hands meet in a video.", "purpose_function": "It ties the added prop sound to the picture so the action feels real, since a sound even a frame off can look and feel wrong.", "practical_application": "A Foley artist performs to picture, and an editor then nudges the recorded sound frame by frame to lock it to the on-screen movement.", "category": "Foley", "related_terms": ["Foley props", "Sync to picture", "Prop catch", "Prop toss", "Spotting session"], "common_mistakes": ["Judging sync by feel alone instead of checking against the frame of contact", "Letting sound drift out of sync across a long take", "Assuming loose sync is fine, when even one frame off is noticeable"], "scenario_contexts": ["Locking a set-down sound to the frame a cup touches the table", "Syncing many small prop handles across a busy scene", "Fixing a Foley pass that plays slightly ahead of picture"]}, "99473c8c-26ed-4f95-b36e-e0d0d672f33e": {"definition": "A Foley performance of the sound of throwing or tossing an object, capturing the release, movement, and any handling noise in sync with the on-screen throw.", "plain_english": "The Foley sound of throwing an object, made by an artist tossing or moving a matching prop in time with the picture. It is like adding the swish and release sound when someone throws keys on screen.", "purpose_function": "It gives a throw on screen a believable sound of release and motion, adding energy the original recording may not have captured.", "practical_application": "A Foley artist performs the throw with a matching prop, timing the release to picture, sometimes recording it separately from the later catch.", "category": "Foley", "related_terms": ["Foley props", "Prop catch", "Prop synchronization", "Foley stage", "Spotting session"], "common_mistakes": ["Timing the release to the wrong frame, so the throw feels off", "Choosing a prop whose weight or material sounds wrong for the object", "Playing the toss too loud, so it does not match the on-screen effort"], "scenario_contexts": ["A character tossing keys onto a table", "Throwing a bag across a room", "Sports action where an object is thrown"]}, "bbee0332-a904-400d-9332-8ce9d9e731a9": {"definition": "The deliberate signal processing of a recorded voice so it sounds as though it is emerging from a public-address (PA) loudspeaker system, typically by band-limiting the audio, adding midrange coloration and distortion, and layering room reverberation. It is a form of 'futz' processing used in film and television sound to place a voice in an amplified, announced space.", "plain_english": "This means treating a voice so it sounds like it is coming out of a loudspeaker in a station or a stadium. You cut the highs and lows, add a bit of grit and echo, and the voice feels announced over a big room.", "purpose_function": "It sells the illusion that a voice is broadcast over a venue's speaker system rather than spoken directly on set, matching the tinny, reverberant character audiences expect from real PA horns.", "practical_application": "A dialogue editor applies EQ, distortion and reverb, or a dedicated futz plug-in, to a clean announcer take so it reads as a train-station or arena announcement in the final mix.", "category": "Dialogue Processing", "related_terms": ["Radio voice processing", "Futz", "Worldizing", "Dialogue editing", "Reverberation"], "common_mistakes": ["Over-processing the line until the announcement is unintelligible", "Omitting the PA reverb tail that places the voice inside the venue", "Reusing one futz preset for every space regardless of the room's size"], "scenario_contexts": ["A train-station announcement heard by characters on a platform", "A stadium announcer's voice under a crowd scene", "An airport gate call in the background of a terminal scene"]}, "28b07fc8-fb5a-47a9-94d8-2d59e5c822ed": {"definition": "A dedicated, calibrated review environment in a post-production or broadcast facility where finished audio and video deliverables are checked against technical and creative specifications before delivery. QC operators verify loudness, channel assignment, sync, and the absence of clicks, dropouts and other faults to confirm the master meets the delivery standard.", "plain_english": "This is a special room where a finished show is checked before it is sent out. A trained person watches and listens on trusted gear to catch problems like wrong loudness, bad sync, or clicks, so the client gets a clean copy.", "purpose_function": "It exists to catch technical and content errors before a master ships, protecting the facility from costly rejected deliveries and ensuring the program meets broadcast or streaming specifications.", "practical_application": "Before a finished episode is uploaded to a network, a QC operator plays it in the QC room, confirms loudness meets the spec, checks channel mapping and lip-sync, and logs any faults for the mixers to fix.", "category": "Deliverables QC", "related_terms": ["Loudness normalization", "Delivery specification", "Lip sync", "Channel mapping", "Master"], "common_mistakes": ["Assuming an automated QC pass replaces a trained human reviewer", "Running QC on uncalibrated speakers so real faults go unnoticed", "Skipping loudness verification against the target delivery spec"], "scenario_contexts": ["Checking a feature mix against a streaming platform's delivery spec", "Verifying a broadcast promo for loudness and channel assignment", "Catching a dropout in a stereo downmix before delivery"]}, "d1b8e884-17b1-4fcf-9b40-f915f19cfbc1": {"definition": "Foley performance and recording of subtle, low-level sounds such as cloth movement, gentle prop handling, and soft footsteps, captured at close range on a quiet stage so delicate on-screen action reads clearly in the mix. It is the detail end of Foley work, distinct from loud, impact-heavy cues.", "plain_english": "This is Foley for the small, soft sounds in a scene, like clothes rustling or a hand touching a cup. The artist works close to a quiet mic so these tiny sounds come through clearly.", "purpose_function": "It adds the quiet, intimate details that make a performance feel real and present, filling the gaps left when a scene has little dialogue or music.", "practical_application": "A Foley artist performs cloth rustles and soft object handling in sync with picture on a treated stage, recording at low levels so the editor can place them under intimate dialogue scenes.", "category": "Foley", "related_terms": ["Foley", "Foley stage", "Footsteps", "Props", "Ambience"], "common_mistakes": ["Recording quiet Foley in a noisy room so the noise floor swamps the detail", "Performing too heavily so subtle actions sound exaggerated", "Treating quiet Foley as optional and skipping it in intimate scenes"], "scenario_contexts": ["Cloth movement under a whispered bedroom conversation", "The soft handling of a letter being opened", "Gentle footsteps of a character sneaking through a house"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"7aaf9b7e-0008-482c-a26d-8fe045a2f270": {"definition": "Signal processing applied to a recorded voice so it sounds as though it is received over a two-way radio, walkie-talkie or broadcast receiver, characteristically narrow-band and midrange-heavy with added distortion, compression, and often squelch, static or transmission artifacts. It is a 'futz' technique widely used in film, television and game dialogue.", "plain_english": "This treats a voice so it sounds like it is coming through a walkie-talkie or radio. You make it thin and crackly, cut the deep and high tones, and add static, so it feels transmitted, not spoken in the room.", "purpose_function": "It signals to the audience that a character is speaking over a radio link rather than in person, using the limited bandwidth and noise of real radios to make the transmission believable.", "practical_application": "A dialogue editor runs a clean line through band-pass EQ, distortion and a radio-futz plug-in, adding squelch clicks so a pilot's or dispatcher's line reads as a radio call in the mix.", "category": "Dialogue Processing", "related_terms": ["Public-address voice processing", "Futz", "Band-pass filter", "Dialogue editing", "Worldizing"], "common_mistakes": ["Narrowing the band so far the line becomes unintelligible", "Omitting radio artifacts like squelch and mic clicks that sell the effect", "Applying radio futz to a voice that is meant to be present in the room"], "scenario_contexts": ["A soldier's line heard over a squad radio", "Air-traffic control talking to a cockpit", "A police dispatcher calling units over the radio"]}, "8b1e133b-f79f-4426-9b3e-97cfe05e4e1d": {"definition": "In audio middleware such as Wwise, a Random Container is a parent object that holds several child sounds and, each time it is triggered, plays one child chosen at random. It supports 'standard' random, where any child may be chosen with possible immediate repeats, and 'shuffle' random, where each child plays once before any repeats, making it the primary tool for varying repeated sounds.", "plain_english": "This is a folder in game-audio software that holds several versions of a sound. Every time the game asks for that sound, the folder picks one at random, so a repeated action does not use the exact same clip each time.", "purpose_function": "It exists to stop repeated sounds like footsteps, gunshots and impacts from sounding identical and robotic, by automatically rotating through a pool of variations.", "practical_application": "A game sound designer drops ten footstep recordings into a Random Container set to shuffle, so a walking character cycles through all ten before any repeats.", "category": "Game Audio", "related_terms": ["Randomized playback", "Sequence container", "Audio middleware", "Sound bank", "Footsteps"], "common_mistakes": ["Confusing a Random Container (random order) with a Sequence Container (fixed order)", "Leaving it on standard random so the same clip can repeat back-to-back", "Loading only two variations, so the repetition is still obvious"], "scenario_contexts": ["Varying footstep sounds as a character walks", "Randomizing gunshot samples on a weapon", "Rotating impact sounds when objects collide in a game"]}, "e05f3d16-356f-4421-aa53-d7438d4ed1da": {"definition": "A playback strategy in which sample selection or sound properties are varied at random each time a sound is triggered, commonly randomizing which sample of a set plays plus small random offsets to pitch, volume or timing, in order to avoid audible repetition. It is fundamental to interactive and game audio, where a single event may fire thousands of times.", "plain_english": "This means letting software change a sound a little each time it plays. It might pick a different clip, or shift the pitch and volume slightly, so the same action never sounds exactly the same twice.", "purpose_function": "It keeps frequently repeated sounds from becoming a noticeable, fatiguing loop by adding natural-sounding variation without the designer hand-placing every instance.", "practical_application": "A designer enables random pitch and volume ranges on a footstep sound and pulls samples from a random pool, so a long walking sequence stays lively and believable.", "category": "Game Audio", "related_terms": ["Random container", "Sample variation", "Pitch randomization", "Audio middleware", "Round robin"], "common_mistakes": ["Setting randomization ranges so wide the sound loses its identity", "Randomizing pitch on tonal sounds so they drift out of tune", "Relying on randomization instead of recording enough source variations"], "scenario_contexts": ["Footsteps that vary as a character runs", "Bullet impacts that differ shot to shot", "UI clicks that vary slightly on each press"]}, "6500b382-ffb4-487c-8db3-ca65faa7a283": {"definition": "The generation or processing of an audio signal fast enough to be delivered as it is heard, with latency low enough for live monitoring or interactive response, as opposed to offline rendering to a file. Every sample must be produced within its playback deadline, so the processing load must fit the available time budget.", "plain_english": "This means the computer makes or changes the sound at the same moment you hear it, with almost no delay. It has to keep up with playback, unlike offline work where it can take its time and save a file.", "purpose_function": "It lets performers, mixers and games hear effects and mixes instantly, which is essential for live monitoring, interactive media, and any situation where the audio must respond to the moment.", "practical_application": "A mixer runs plug-ins in real time to monitor a session live, while a game engine renders and mixes sound effects on the fly as the player moves.", "category": "Audio Processing", "related_terms": ["Real-time reverberation", "Latency", "Offline rendering", "Buffer size", "DSP"], "common_mistakes": ["Loading too many plug-ins so the CPU cannot meet the real-time deadline, causing dropouts", "Confusing real-time rendering with an offline bounce", "Setting the buffer so low that the system glitches"], "scenario_contexts": ["Monitoring effects live while tracking a vocal", "A game mixing sound effects as the player moves", "Live processing of a broadcast feed"]}, "f4d29aa1-9279-4599-8210-3b339c342eb1": {"definition": "Reverberation generated on the fly by an algorithmic or convolution reverb processor as the source signal passes through it, producing the reverb tail live rather than from a pre-rendered file. It lets the reverberant character of a space be applied and adjusted during monitoring, mixing or live performance.", "plain_english": "This is echo and room sound added to audio instantly as it plays, using software or hardware. You can hear and tweak the 'room' live, instead of baking it in ahead of time.", "purpose_function": "It places a voice or instrument in a believable space in real time, so engineers and performers can hear the ambience immediately and adjust it while they work.", "practical_application": "A mixer patches a real-time reverb across a dialogue stem to match a scene's room, hearing the change instantly and automating the amount to picture.", "category": "Audio Processing", "related_terms": ["Real-time audio rendering", "Convolution reverb", "Algorithmic reverb", "Reverberation time", "Latency"], "common_mistakes": ["Printing heavy real-time reverb while tracking so it is permanently baked in", "Ignoring the latency a convolution reverb adds to the signal path", "Using one reverb for every space instead of matching the room's size"], "scenario_contexts": ["Placing ADR lines in the acoustic of the original scene", "Adding live reverb to a vocal during tracking for the singer's monitor", "Matching reverb on a Foley pass to the on-screen room"]}, "eee50eb2-4644-4923-b47d-dd155e90ae57": {"definition": "Dialogue re-recorded in a studio to replace original production audio that is unusable or needs changing, with the actor performing lines in sync to picture. Also called ADR (automated dialogue replacement) or looping, it is used when location recordings are too noisy, poorly performed, or altered for creative or censorship reasons.", "plain_english": "This is new dialogue an actor records in a studio to swap out lines that did not work on set. Watching the film, they match their voice to their lip movements so it fits the picture.", "purpose_function": "It rescues scenes whose original dialogue is unusable, too noisy, mumbled, or changed in the edit, by providing clean, controllable lines that match the performance on screen.", "practical_application": "In an ADR session, an actor watches a scene loop and re-performs each line in sync while the mixer records clean takes to replace the noisy location track.", "category": "Dialogue", "related_terms": ["Lip sync", "Dialogue editing", "Production sound", "Foley", "Looping"], "common_mistakes": ["Recording ADR out of sync with the actor's lip movements", "Not matching the mic and perspective of the original scene so the line stands out", "Assuming ADR can fix any take, ignoring differences in performance energy"], "scenario_contexts": ["Replacing a line ruined by traffic noise on location", "Re-recording dialogue changed during the edit", "Cleaning up a mumbled line for clarity"]}, "6ae9edbe-5896-43a8-b2e0-130321f52627": {"definition": "The process of analyzing an existing sound to extract its underlying parameters — such as the frequencies, amplitudes and time-envelopes of its partials — and then regenerating the sound synthetically from that analysis, so those parameters can be edited independently.", "plain_english": "Resynthesis means a computer listens to a sound and works out what it is made of. Then it builds the sound again from scratch. Because it now knows the parts, you can change the pitch or tone without wrecking the rest.", "purpose_function": "It separates a recorded sound into editable building blocks, letting an engineer reshape pitch, timbre, and timing that would be impossible to touch in the raw waveform.", "practical_application": "A sound editor loads a recording into a spectral or additive tool such as Melodyne or a resynthesis synth, then retunes notes, stretches time, or morphs the timbre for a design or repair task.", "category": "Synthesis", "related_terms": ["Additive synthesis", "Spectral processing", "Vocoder", "Time-stretching", "Granular synthesis", "Pitch correction"], "common_mistakes": ["Confusing resynthesis with simple sample playback; resynthesis rebuilds the sound from analysis data rather than replaying the original file", "Assuming resynthesis is always transparent, when heavy edits can add smearing or metallic artifacts", "Thinking it only means turning audio into MIDI notes, ignoring spectral and additive approaches"], "scenario_contexts": ["Retuning and time-aligning dialogue or a vocal without audible artifacts", "Creating an evolving sound-design texture by morphing the analyzed partials of a real recording", "Cleaning or reshaping a problem sound effect that ordinary EQ cannot fix"]}, "ba5cb220-3c4b-41d5-b2d4-4f10ae31effc": {"definition": "A defined spatial region within a virtual environment or game world that applies a specific reverberation profile to sounds when the listener enters it, so a scene's acoustics change automatically with the listener's position.", "plain_english": "A reverb zone is an area inside a video game world. When your character walks into it, sounds pick up the echo of that space. It is like moving from a small hallway into a big stone church and hearing the room change.", "purpose_function": "It makes interactive audio feel real by matching the echo of each space to where the player is, without an engineer mixing every location by hand.", "practical_application": "A game or interactive audio designer places reverb zones in an engine such as Unity or through middleware, setting each zone's decay and size so footsteps and voices react to caves, rooms, and open areas.", "category": "Game Audio", "related_terms": ["Convolution reverb", "Impulse response", "Ambience", "Spatial audio", "Send effect", "Audio middleware"], "common_mistakes": ["Overlapping zones with clashing settings, causing sudden jumps in reverb as the player crosses a boundary", "Setting decay times far too long for the space, which muddies dialogue and effects", "Treating a reverb zone as a fixed global reverb instead of a position-based one"], "scenario_contexts": ["Adding cave, corridor, and open-field acoustics to a game level", "Blending between two rooms so reverb transitions smoothly at a doorway", "Matching the reverb of an interactive scene to its on-screen environment"]}, "10e23563-ea94-495d-990c-b5db2bc27724": {"definition": "A production effect made by reversing a recorded cymbal crash so its natural decay plays backward, producing a swelling 'whoosh' that rises from silence and cuts off, typically leading into a downbeat or new section.", "plain_english": "This is a cymbal crash played backwards. Instead of a sharp hit that fades away, you hear a soft sound that grows louder and then stops dead. Producers use it to lead the listener into a new part of a song or scene.", "purpose_function": "It gives a build-up and sense of anticipation, smoothing the join between sections or cueing an entrance.", "practical_application": "An editor reverses a cymbal sample, trims its swell so the peak lands exactly on the target beat, and uses it as a transition before a chorus, cut, or reveal.", "category": "Production Effect", "related_terms": ["Reverse playback", "Reverse reverb", "Reverse swell", "Transition effect", "Riser"], "common_mistakes": ["Not aligning the swell's peak to the downbeat, so the effect lands early or late", "Leaving the reversed crash too loud, which buries the following section's onset", "Forgetting that a reversed cymbal has no natural attack, so it needs the following hit to feel resolved"], "scenario_contexts": ["Building tension before a chorus or drop", "Smoothing a hard scene change in a film or trailer cut", "Adding lift into a musical fill or transition"]}, "34bbf6c4-8bdd-4250-8949-43f068c55c4f": {"definition": "A production effect in which a recorded piano note or chord is played backward, so the natural decay becomes a rising swell that ends abruptly where the original strike began, giving an unnatural, atmospheric character.", "plain_english": "This is a piano note recorded and then played backwards. The sound swells up from nothing and then cuts off, instead of starting with a clear strike. It gives a dreamy, floating feeling.", "purpose_function": "It turns a familiar instrument into an atmospheric or transitional texture, useful where a normal piano attack would feel too plain.", "practical_application": "A sound designer reverses a piano chord and lines its swell up to a cue point, using it as an intro flourish, a mood bed, or a lead-in under picture.", "category": "Production Effect", "related_terms": ["Reverse playback", "Reverse swell", "Reverse reverb", "Sound design", "Transition effect"], "common_mistakes": ["Expecting the reversed note to keep a clear pitch attack, which it loses because the strike is now at the end", "Not trimming the swell to a musical or visual cue, so timing feels loose", "Over-processing until the source is unrecognizable when a subtle effect was wanted"], "scenario_contexts": ["Creating a dreamy intro before a song or scene", "Under-scoring a flashback or transition in picture", "Adding an atmospheric swell into a downbeat"]}, "9d3d4102-7a77-4a21-845c-0fc2024ca39f": {"definition": "Playing back a recorded audio segment in reverse, so its samples run from end to start; the sound's natural decay becomes a rising onset and its attack becomes the ending.", "plain_english": "Reverse playback means playing a recording backwards. It is like running a video in rewind, but for sound. A note that normally fades out now grows louder and then stops.", "purpose_function": "It is the basic operation behind reverse effects, letting an editor turn familiar sounds into swells, whooshes, and unusual textures.", "practical_application": "In a DAW the editor selects a clip and applies a reverse function, then uses the result as a transition, a special effect, or the first step of a reverse-processing chain.", "category": "Editing Technique", "related_terms": ["Reverse cymbal", "Reverse vocal", "Reverse processing", "Reverse reverb", "Sample manipulation"], "common_mistakes": ["UNSAFE: cranking monitor level to hear a quiet reversed tail, then being caught by a sudden loud transient — set a safe level first to protect hearing and speakers", "Reversing a clip with a hard edit at the start or end, which creates an audible click", "Forgetting that reversing also flips fades, so a fade-out becomes a fade-in"], "scenario_contexts": ["Turning a crash or chord into a build-up swell", "Creating backward vocals or effects for a dream or eerie moment", "First step before applying reverse reverb or reverse delay"]}, "e137395e-6bac-415a-8220-9d6149104181": {"definition": "A technique in which an audio segment is reversed, an effect such as reverb or delay is printed onto it, and the result is reversed again, so the effect tail now builds up before the original sound instead of trailing after it.", "plain_english": "Here you flip a sound backwards, add an effect like echo or reverb, then flip it back the right way round. The trick makes the effect build up before the sound instead of after it. That is how the 'sucking-in' reverse-reverb sound is made.", "purpose_function": "It creates pre-swelling effects that draw the listener toward a word, hit, or image, which a normal forward effect cannot do.", "practical_application": "An engineer reverses a vocal or hit, records reverb onto it, reverses that back, then places the swelling tail so it leads into the original sound on the target cue.", "category": "Production Effect", "related_terms": ["Reverse reverb", "Reverse playback", "Reverse swell", "Send effect", "Automation"], "common_mistakes": ["Skipping the final reverse, which leaves the effect trailing normally instead of building up first", "Not printing a long enough tail, so the pre-swell is too short to be heard", "Losing sync between the swell and the source after the second reverse"], "scenario_contexts": ["Making a reverse-reverb swell that pulls into a vocal line", "Building a lead-in effect before a hard cut or reveal in picture", "Designing anticipation before a musical or sound-effect accent"]}, "d17458dd-7699-4709-bb14-32e7661f6837": {"definition": "A rising crescendo effect produced by reversing audio so a sound's natural decay is heard as a gradual build from quiet to loud that ends abruptly, commonly used as a lead-in to a beat, cut, or image.", "plain_english": "A reverse swell is a sound that grows from quiet to loud and then suddenly stops. It is made by playing audio backwards, so the fade-out turns into a build-up. It pulls your ear toward whatever comes next.", "purpose_function": "It builds anticipation and glues sections together by creating a smooth rise into a target point.", "practical_application": "An editor reverses a sustained sound or reverb tail, shapes its rise, and times the peak to land on the downbeat or picture cut it is meant to introduce.", "category": "Production Effect", "related_terms": ["Reverse cymbal", "Reverse reverb", "Reverse processing", "Crescendo", "Transition effect"], "common_mistakes": ["Misaligning the peak so the swell resolves before or after the target moment", "Making the swell too long, which dilutes the sense of build", "Confusing a reverse swell with a simple volume fade-in, which lacks the reversed tail's character"], "scenario_contexts": ["Leading into a chorus, drop, or new scene", "Under-scoring a rising reveal in picture", "Smoothing the join between two contrasting sections"]}, "dc27d66e-f02c-4f82-8de6-3e07576cc74b": {"definition": "A vocal recording played in reverse, so words and phrasing run backward; used as a special effect, transition, or atmospheric texture rather than for intelligible lyrics.", "plain_english": "This is singing or speech played backwards. It sounds strange and dreamy because the words come out in reverse. Producers use it as a special effect or to lead into a new part.", "purpose_function": "It adds an unnatural, ear-catching texture and can act as a transition or mood element where a normal vocal would feel too clear.", "practical_application": "An editor reverses a vocal phrase or a copy of a lead line, then layers it low in the mix, uses it as a lead-in swell, or scores an eerie or dream moment in picture.", "category": "Production Effect", "related_terms": ["Reverse playback", "Reverse processing", "Reverse reverb", "Backmasking", "Transition effect"], "common_mistakes": ["Expecting reversed lyrics to stay intelligible, when the point is the texture, not the words", "Placing a reversed vocal too loud so it distracts from the lead", "Reversing a clip with clicks at the edits instead of cleaning the boundaries first"], "scenario_contexts": ["Creating an eerie or dream-like moment in a film scene", "Adding a lead-in swell before a vocal entrance", "Layering backward texture under a chorus or breakdown"]}, "618228b2-1afa-4e50-a5ad-e3549e023587": {"definition": "A calibrated listening and viewing space in post-production where mixes and picture are played back for review and client approval; it is monitored to reference standards but is typically smaller than a full dubbing stage or scoring stage.", "plain_english": "A review room is a small, carefully tuned room where the team watches and listens to a film mix. It uses the same sound and picture standards as the main mixing stage. They use it to check the work and get the client's sign-off before it is finished.", "purpose_function": "It provides a trusted, standards-referenced environment for approving a mix so decisions made there translate correctly to cinemas and other playback systems.", "practical_application": "A supervising editor or re-recording mixer screens a near-final mix in the review room with the director or client, taking notes on changes before returning to the stage for revisions.", "category": "Post Facility", "related_terms": ["Dubbing stage", "Reference level", "Monitoring calibration", "Final mix", "Deliverables", "Screening room"], "common_mistakes": ["Approving a mix in a room that is not calibrated to reference level, so loudness and balance shift on the real stage or in cinemas", "Assuming a small review room reproduces low-frequency and surround detail identically to a large stage", "Confusing a review room with a mixing/dubbing stage where the mix is actually built"], "scenario_contexts": ["Screening a near-final mix for director and client sign-off", "Checking picture-and-sound sync before a deliverable is exported", "Reviewing revisions between mixing sessions on the dubbing stage"]}, "88666424-c910-4efa-958c-7ecf7517e5d0": {"definition": "A designed transitional sound that gradually increases in pitch, brightness, level, and/or density over several seconds to build tension and lead into an impact, downbeat, or scene change. Common realizations include filtered noise sweeps, upward-glissando synth tones, and reverse-cymbal swells, usually resolving on a hit or cut.", "plain_english": "It is a whooshing sound that slowly gets higher and louder to build excitement, then drops you into the next moment. It works like a drumroll right before something big happens.", "purpose_function": "It signals that something is coming and pulls the audience's attention forward, smoothing an edit and adding energy across a transition.", "practical_application": "A sound designer places a riser under the last few seconds before a cut, title reveal, or music drop, timing its peak to land exactly on the impact.", "category": "Sound design element", "related_terms": ["Whoosh", "Impact hit", "Sweetener", "Reverse reverb", "Transition effect"], "common_mistakes": ["Letting the riser peak before or after the impact instead of exactly on it, which weakens the payoff", "Overusing risers so every transition sounds the same and loses its punch", "Letting a loud riser mask dialogue or important sounds underneath it"], "scenario_contexts": ["Building tension before a title card or logo reveal in a trailer", "Leading into a music drop or chorus in a promo edit", "Smoothing a hard picture cut between two scenes"]}, "52d4cb8d-9832-49cf-94ba-c380c55b9542": {"definition": "A portion of a tempo map that encodes a ritardando — a gradual, controlled decrease in tempo across a passage — as a series of descending tempo values or a curved tempo ramp, so a sequencer or notation program plays back and displays the slowdown accurately.", "plain_english": "It is a set of tempo markers that tells the software to slow the music down bit by bit, instead of all at once. It is like easing off the gas pedal so a car slows smoothly.", "purpose_function": "It keeps a slowing passage locked to a grid so the click track, MIDI parts, and edits all follow the same smooth deceleration and still line up with picture.", "practical_application": "A composer or music editor enters or draws descending tempo values in the DAW's tempo track so the click and sequenced parts slow together toward a picture cue.", "category": "Scoring & tempo", "related_terms": ["Tempo map", "Click track", "Accelerando", "Rubato cue", "Hit point"], "common_mistakes": ["Using one sudden tempo drop instead of many small steps, which sounds like a stumble rather than a smooth slow-down", "Forgetting that the click track slows too, so live players lose the beat if they are not warned", "Not checking that the slowdown still lands on the intended picture point after the tempo change"], "scenario_contexts": ["Scoring a film ending where the music gently slows to a stop", "Setting up a click track so musicians can record a rallentando in time", "Conforming a live-performed slowdown to a grid so edits stay in sync"]}, "e8187731-5a05-4089-a233-599f48a98b70": {"definition": "The graphed shape describing how a filter attenuates signal level as frequency moves past its cutoff, typically expressed as a slope in decibels per octave (e.g., 6, 12, 18, or 24 dB/octave); by extension, any curve showing progressive level reduction versus frequency.", "plain_english": "It is a line on a graph that shows how fast a filter turns down the sounds above or below a set point. A steeper line means the unwanted frequencies fade out more quickly.", "purpose_function": "It tells you how gently or aggressively a high-pass, low-pass, or shelving filter removes unwanted frequencies, which shapes tone and controls rumble, hiss, or harshness.", "practical_application": "A mixer picks a filter's rolloff slope — a gentle 6 dB/octave or a steep 24 dB/octave — when high-passing a dialogue track to cut rumble without thinning the voice.", "category": "Filtering", "related_terms": ["Cutoff frequency", "High-pass filter", "Low-pass filter", "Filter slope", "Shelving filter"], "common_mistakes": ["Confusing the cutoff frequency (where attenuation begins) with the rolloff rate (how fast level falls beyond it)", "Assuming a filter blocks everything past cutoff, when it actually attenuates gradually along the curve", "Using an overly steep rolloff and adding phase shift or ringing near the cutoff"], "scenario_contexts": ["Choosing a high-pass slope to remove stage rumble from a vocal mic", "Setting a subwoofer crossover's rolloff to blend with the main speakers", "Reading a microphone's published low-frequency rolloff on its datasheet"]}, "97eba954-db5a-41d5-889b-37b2d135932b": {"definition": "A spatial-audio modeling approach in game-audio middleware in which enclosed acoustic spaces are defined as 'rooms' (each with its own reverb and properties) connected by 'portals' (openings such as doors or windows) that control how sound propagates, is occluded, diffracts, and transmits reverb between adjacent rooms as the listener and sources move.", "plain_english": "In a game, each area is a 'room' with its own echo. Doorways are 'portals' that decide how sound leaks from one room to the next. It copies how a noisy kitchen turns quiet when you step out and shut the door.", "purpose_function": "It makes interactive spaces sound believable by changing reverb and muffling in real time based on where the listener and sound sources sit relative to walls and openings.", "practical_application": "A game audio designer places room volumes and portal shapes in a level so a sound in one room is heard — filtered and delayed — through the doorway of the next.", "category": "Game audio", "related_terms": ["Occlusion", "Obstruction", "Diffraction", "Reverb zone", "Spatial audio"], "common_mistakes": ["Confusing rooms (the enclosed spaces) with portals (the openings that connect them)", "Leaving gaps between room boundaries so the listener falls into 'no room' and reverb drops out", "Making a portal too large or mis-oriented, so sound leaks in ways that break the illusion"], "scenario_contexts": ["Setting up reverb transitions as a player walks from a hallway into a large hall", "Muffling gunfire heard through a closed door in a shooter", "Modeling how ambience spills between connected rooms in a building"]}, "a4f5d1ee-fcac-4b3b-a148-e416b4b96091": {"definition": "A musical cue performed or written with rubato — expressive, flexible timing in which the tempo pushes and pulls rather than staying locked to a strict metronomic pulse — so its beats do not fall on a fixed grid.", "plain_english": "It is a piece of music played with loose, expressive timing, speeding up and slowing down for feeling instead of following a strict beat. It is like a singer stretching a phrase for emotion instead of marching in step.", "purpose_function": "Rubato gives a cue human, emotional phrasing, but its free timing means it cannot rely on a steady click and needs special handling to sync to picture or other tracks.", "practical_application": "A music editor conforming a rubato cue maps its shifting bar lines by hand or builds a variable tempo map so edits, MIDI, and hit points still land where intended.", "category": "Scoring & tempo", "related_terms": ["Tempo map", "Ritardando map", "Click track", "Music cue", "Hit point"], "common_mistakes": ["Forcing a rubato cue onto a fixed grid, which flattens its expressive timing", "Assuming a rubato cue can be beat-matched to a click without a variable tempo map", "Editing a rubato cue at arbitrary points and breaking its musical phrasing"], "scenario_contexts": ["Syncing a freely played solo piano cue to a scene's emotional beats", "Building a tempo map so a rubato orchestral cue can be clicked and re-recorded", "Editing a rubato source recording to fit a re-cut picture"]}, "eb4d20db-38b9-4140-9cc2-01fb32b5ff8e": {"definition": "A sound-effects or Foley category consisting of the impact sound made when a rubber object strikes or is struck against a surface — a dull, damped thud with little sustain or ring — used to represent tires, balls, boots, bumpers, and similar rubbery materials on screen.", "plain_english": "It is the dull thud a rubber thing makes when it hits something, like a bouncing ball or a car tire. It has almost no ring because rubber soaks up the energy of the hit.", "purpose_function": "It gives rubbery on-screen objects a matching material sound, adding weight and realism to hits, bounces, and collisions.", "practical_application": "A Foley artist or sound editor chooses or records a rubber impact to sync with a ball bounce, a boot stomp, or a car bumper collision.", "category": "Sound effects", "related_terms": ["Foley", "Impact hit", "Hard effects", "Sweetener", "Sync point"], "common_mistakes": ["Using a hard, ringing impact for rubber, which sounds like metal or wood instead", "Failing to match the impact's weight and softness to the size of the object on screen", "Placing the impact off the exact frame of contact so it looks out of sync"], "scenario_contexts": ["Adding the thud of a basketball hitting the court", "Syncing a rubber boot stepping onto a hard floor in Foley", "Building a car bumper or tire collision from layered rubber impacts"]}, "6f53aeb7-a545-4d40-9ed9-7be294d3bc3c": {"definition": "A Foley or sound-effects element consisting of footstep sounds performed and recorded at a running pace — faster, heavier, and more forceful than a walk — matched to a character's stride, footwear, and walking surface on screen.", "plain_english": "It is the sound of feet hitting the ground fast, made to match someone running on screen. A Foley artist usually performs them in time with the picture, stepping on the same kind of surface.", "purpose_function": "They give a running character believable movement and weight, and help sell speed, effort, and which surface the character is on.", "practical_application": "A Foley artist watches the picture and performs running footsteps in sync, choosing shoes and a surface — gravel, wood, concrete — that match the shot.", "category": "Foley", "related_terms": ["Foley", "Footsteps", "Foley pit", "Surface", "Sync point"], "common_mistakes": ["Performing footsteps out of sync with the on-screen foot contacts", "Using the wrong shoe or surface so the steps do not match the picture", "Keeping every step the same volume and weight instead of varying them as in real running"], "scenario_contexts": ["Foleying a character sprinting down a hallway", "Replacing noisy production-sound footsteps in a chase scene", "Layering many running footsteps for a crowd stampede"]}, "82e7b2fc-aa1f-4437-9f1f-c7900d1763d5": {"definition": "Audio that is generated, processed, and rendered in real time while a program — typically a game or interactive application — is running, rather than being pre-rendered to a fixed file, and assembled on the fly by an audio engine from samples, parameters, and program state.", "plain_english": "It is sound that a game builds live while you play, instead of playing a finished recording. Because it is made on the spot, it can change with whatever you do in the game.", "purpose_function": "It lets interactive media adapt sound to player actions and changing conditions, so the audio responds moment to moment instead of being a fixed, unchanging track.", "practical_application": "A game audio designer authors sounds and rules in middleware so the engine chooses, layers, and processes them at runtime as the player moves and events fire.", "category": "Game audio", "related_terms": ["Runtime mixing", "Middleware", "RTPC", "Audio engine", "Interactive audio"], "common_mistakes": ["Confusing runtime audio with a pre-rendered (baked) audio file that never changes", "Ignoring CPU and voice-count limits, so heavy runtime processing causes dropouts", "Assuming a mix that sounds right in the authoring tool will sound identical once assembled at runtime"], "scenario_contexts": ["Layering engine sounds that change with a car's speed as you drive", "Triggering footstep sounds that vary by surface as a character walks", "Blending music layers that shift with combat intensity"]}, "6acbf4ec-d4d3-45e1-92a9-b8c7c84c21af": {"definition": "The practice of balancing and processing an interactive soundscape dynamically at runtime, in which the audio engine adjusts levels, effects, and routing in response to program state using tools such as states/snapshots, real-time parameter controls (RTPCs), ducking, and priority/voice management — rather than committing to a single fixed mix.", "plain_english": "It is setting up the sound balance so a game mixes itself live, turning things up or down as the action changes. It is like an automatic engineer riding the faders while you play.", "purpose_function": "It keeps the most important sounds clear and the overall balance right as scenes and player actions change, which a single pre-set mix cannot do in interactive media.", "practical_application": "A game audio designer builds mixer snapshots and parameter rules so, for example, music and ambience duck under dialogue or intensify during combat automatically.", "category": "Game audio", "related_terms": ["Runtime audio", "Mixer snapshot", "Ducking", "RTPC", "Middleware"], "common_mistakes": ["Setting static levels only and expecting a good balance in every game situation", "Stacking too many snapshots or ducking rules so the mix pumps or fights itself", "Testing the mix only in the authoring tool instead of across real gameplay"], "scenario_contexts": ["Ducking music and ambience under important dialogue during a cutscene", "Raising combat music and impact levels when a fight starts", "Prioritizing nearby, important sounds when many sources play at once"]}, "a46fafe3-eb3e-4f1b-87d7-e169d57e2b68": {"definition": "The process of altering a recorded audio sample by changing properties such as pitch, duration, playback speed, or direction, or by slicing and rearranging it, using a sampler or DAW editing tools. In post-production it lets an editor reshape source recordings or designed elements to fit the picture and the creative intent.", "plain_english": "This means changing a recorded sound to make it work better. You can raise or lower its pitch, make it longer or shorter, play it backward, or cut it into pieces. It is a bit like editing a photo, but for sound.", "purpose_function": "It lets a technician reshape existing recordings instead of capturing new ones, so sounds can be tuned, retimed, or transformed to match a scene.", "practical_application": "A sound editor might pitch a door slam down to feel heavier, stretch a sustained tone to cover a longer shot, or slice a loop and rearrange the hits.", "category": "Audio Editing", "related_terms": ["Time-stretching", "Pitch shifting", "Sampler", "Sound design", "Editing"], "common_mistakes": ["Stretching a sample too far, which creates obvious artifacts and a smeared, unnatural sound", "Forgetting that large pitch shifts also change a sample's length and character unless formant or time settings are used", "Working on the original file instead of a copy, which loses the source recording"], "scenario_contexts": ["Lowering the pitch of a recorded animal sound to create a monster voice", "Time-stretching a musical note to fill a longer scene", "Chopping a drum loop into slices and rearranging them into a new rhythm"]}, "9a3fd867-8ad2-4210-8798-ffc8372b43e6": {"definition": "The dialogue-editing practice of keeping a character's recorded voice consistent in level, tone, room ambience, and perspective as the picture cuts from one shot, angle, or setup to another. It smooths differences between takes, microphones, or locations so dialogue does not jump audibly at an edit.", "plain_english": "This means making a person's voice sound the same from one shot to the next. Different takes can be louder, quieter, or recorded in a different room. The editor matches them so the voice does not suddenly change when the picture cuts.", "purpose_function": "It keeps dialogue seamless and believable so the audience follows the story instead of noticing changes in the sound between shots.", "practical_application": "An editor compares clips across a cut and adjusts level, EQ, and room tone, sometimes swapping in a better take, so two lines recorded on different mics blend smoothly.", "category": "Dialogue Editing", "related_terms": ["Room tone", "Dialogue editing", "ADR", "Perspective", "Continuity"], "common_mistakes": ["Matching only the volume while ignoring differences in room tone or EQ, so the space around the voice still jumps", "Not laying matching room tone under a quiet take, which leaves an audible hole at the cut", "Over-processing one clip until it no longer matches the natural takes around it"], "scenario_contexts": ["Two angles of the same conversation were shot with different mics and must sound identical", "A line from a wide shot is quieter and roomier than the close-up next to it", "A pickup line recorded weeks later must match the original scene"]}, "16ac7c1e-6215-43a1-a224-3799bd86fdc7": {"definition": "The music-editing task of laying recorded score cues into the edit at their correct sync points, organized by reel and timeline, to build the complete music track for the mix. It brings individual recorded or delivered cues together in the session ready for the re-recording mix.", "plain_english": "This means putting all the recorded music pieces into the timeline in the right spots. Each piece of music, called a cue, has to start at the right moment. The music editor lines them all up to build the full music track.", "purpose_function": "It organizes every music cue at frame-accurate sync so the mixer receives a complete, correctly placed music track for the film.", "practical_application": "After a scoring session, the music editor imports the mixed cues, places each at its start frame on the timeline, and splits them across reels for delivery to the dub stage.", "category": "Music Editing", "related_terms": ["Cue", "Music editor", "Reel", "Stems", "Re-recording mix"], "common_mistakes": ["Placing a cue a frame or two off its sync point so it no longer hits the action", "Losing track of which take or version of a cue is the approved one", "Not labeling cues clearly by reel and cue number, which causes confusion at the mix"], "scenario_contexts": ["Building the full music track from cues after an orchestral scoring session", "Placing delivered synth cues at their sync points before the dub", "Organizing cues by reel for handoff to the re-recording mixer"]}, "30a10a74-bdd3-4d20-93f1-ea3a639afd9e": {"definition": "The music-editing process of assembling a composite score performance from multiple recorded takes, choosing the best sections of each and editing them together into one seamless cue. It is the film-scoring equivalent of comping a lead vocal from several passes.", "plain_english": "This means building the best version of a music cue from many takes. The players record a section several times. The editor picks the best parts from each and joins them into one smooth performance.", "purpose_function": "It delivers the strongest possible musical performance by combining the best moments from every take into a single clean cue.", "practical_application": "Working from session takes, the music editor cuts the best phrasing from one take and the best ending from another, matching the edits at bar lines so the joins are inaudible.", "category": "Music Editing", "related_terms": ["Comping", "Take", "Cue", "Score pickup edit", "Music editor"], "common_mistakes": ["Editing between takes where tempo or dynamics differ, which makes the join obvious", "Cutting mid-note instead of at a natural boundary such as a bar line or rest", "Choosing a take for one instrument that clashes with the leakage on the other mics"], "scenario_contexts": ["Combining the best sections of three orchestral takes into one cue", "Fixing a flubbed note by dropping in the same bar from another take", "Building a clean solo from several recorded passes"]}, "d4083fda-1e5a-496c-8558-6c327c4966f8": {"definition": "The process of adjusting an existing score edit to match changes in the picture, trimming, expanding, or repositioning cues so the music stays in sync after the film has been re-cut. It is typically driven by comparing the old and new change lists or EDLs.", "plain_english": "This means fixing the music after the picture gets re-edited. When shots are added, cut, or moved, the music no longer lines up. The editor shifts and trims the cues so the music matches the new picture again.", "purpose_function": "It preserves the existing music edit when the picture changes, so cues stay locked to the action without rebuilding them from scratch.", "practical_application": "Given a change list for a new cut, the music editor moves and trims each affected cue, then checks that the musical hit points still land on the action.", "category": "Music Editing", "related_terms": ["Conform", "Change list", "EDL", "Hit point", "Score edit"], "common_mistakes": ["Conforming picture changes by eye instead of using the change list, so cues drift out of sync", "Forgetting to re-check musical hit points after moving a cue", "Applying a change list to the wrong version of the session"], "scenario_contexts": ["Updating cues after the editor adds several seconds to a scene", "Reconforming the score when a reel is re-cut before the final mix", "Matching temp or final music to a new version of the picture"]}, "6f050142-e6fb-4431-8c1f-01a686603117": {"definition": "A general term for editing a piece of recorded or delivered score, cutting, lengthening, shortening, or rearranging the music so it fits the scene's length, structure, and emotional beats. It covers any edit the music editor makes within or between cues to serve the picture.", "plain_english": "This means changing a piece of music so it fits the scene. The editor can make it shorter, longer, or move parts around. The goal is to make the music match what happens on screen.", "purpose_function": "It shapes existing music to the exact length and structure a scene needs, so a cue lands its emotional and timing beats.", "practical_application": "To fit a cue to a shorter scene, the music editor removes a repeated section at a musically clean point so the piece still feels whole.", "category": "Music Editing", "related_terms": ["Cue", "Music editor", "Score conform", "Hit point", "Temp music"], "common_mistakes": ["Cutting in the middle of a phrase instead of at a musical boundary, which breaks the flow", "Ignoring tempo or key so two joined sections clash", "Editing to length without checking that key hits still line up with the action"], "scenario_contexts": ["Shortening a long cue to fit a trimmed scene", "Extending a piece of music to cover an added shot", "Reworking a temp cue so it fits a new edit"]}, "ca5e4b82-7d5c-43a5-af74-96e67ab664ec": {"definition": "The music-editing task of cutting recorded pickup takes, short re-recorded sections captured to fix or replace part of a cue, into the assembled score in place of the flawed material. Pickups are recorded at or after the scoring session to correct performance or note errors.", "plain_english": "This means fixing a music cue with small re-recordings. If part of a take had a wrong note, the players record just that part again. The editor drops the new piece into the cue in place of the mistake.", "purpose_function": "It repairs a flawed section of a cue with a freshly recorded fix so the whole take does not have to be re-performed.", "practical_application": "When a horn cracks a note in an approved take, the editor cuts in the pickup of those bars, matching the edit at bar lines and blending the room sound.", "category": "Music Editing", "related_terms": ["Pickup", "Take", "Score comping", "Cue", "Music editor"], "common_mistakes": ["Dropping in a pickup without matching its level or room tone to the surrounding take", "Editing at a point where the pickup's tempo differs from the original take", "Losing track of which bars the pickup was meant to replace"], "scenario_contexts": ["Replacing a cracked brass note with a pickup take of the same bars", "Cutting in a re-recorded ending after the conductor requested another pass", "Fixing an ensemble timing slip with a pickup of that phrase"]}, "4f76f8bd-29db-4b34-b962-666cfe706b0f": {"definition": "The correction of tuning or intonation problems in a recorded score performance using pitch-processing tools, so notes sit in tune without re-recording. It targets individual instruments or sections that drifted flat or sharp.", "plain_english": "This means fixing out-of-tune notes in recorded music. Sometimes a player or singer lands a little flat or sharp. Software nudges those notes back in tune so the music sounds right.", "purpose_function": "It rescues an otherwise good take that has minor tuning issues, saving the performance without another recording session.", "practical_application": "The music editor isolates a slightly sharp violin line and uses pitch-correction software to pull it into tune while keeping its natural vibrato and tone.", "category": "Music Editing", "related_terms": ["Pitch correction", "Intonation", "Score comping", "Take", "Music editor"], "common_mistakes": ["Over-correcting until the performance sounds robotic and loses its natural vibrato", "Trying to tune a full ensemble mic where notes overlap, which causes artifacts", "Treating pitch repair as a fix for a poorly recorded or badly performed take"], "scenario_contexts": ["Nudging a flat sustained note back into tune", "Correcting an intonation slip in an exposed solo line", "Tightening tuning on a section before the final mix"]}, "66e6b4cc-f3be-4f5d-a6fd-d18e832dd244": {"definition": "A music edit that adjusts the timing of a score so events land on the intended moments in the picture, by shifting the cue, altering tempo, or micro-editing beats to align musical hits with visual action. It targets synchronization rather than musical content.", "plain_english": "This means changing the timing of the music so it lands with the action. A big musical hit should match a big moment on screen. The editor nudges or stretches the music until they line up.", "purpose_function": "It locks musical accents to on-screen events so the score feels tied to the picture rather than drifting against it.", "practical_application": "To make a cymbal crash land on a door slam, the music editor shifts the cue or subtly adjusts the tempo so the accent hits the exact frame.", "category": "Music Editing", "related_terms": ["Hit point", "Sync", "Tempo map", "Score conform", "Click track"], "common_mistakes": ["Shifting a whole cue to fix one hit, which throws every other hit out of sync", "Time-stretching so aggressively that the music develops audible artifacts", "Chasing a hit point the composer never intended, which fights the music"], "scenario_contexts": ["Aligning a musical accent with an on-screen impact", "Tightening a cue that drifts a few frames late against the action", "Adjusting tempo so a phrase resolves exactly on a cut"]}, "e8926e44-34a3-44f8-92a9-538630fa0e7f": {"definition": "A verification that a score's music lines up exactly with the picture at its intended sync points — hit points, scene edits, and downbeats — confirmed against timecode during or after the scoring session using tools such as click tracks, streamers, and punches.", "plain_english": "A check that the music matches the film at the right moments. Editors line up each musical hit with the action on screen, like matching a drum hit to a door slam.", "purpose_function": "It confirms the music supports the picture as the composer intended, so emotional beats and on-screen actions land on the right frame.", "practical_application": "In the scoring session or the DAW, the music editor aligns cues to timecode and confirms each hit point falls on the correct frame before the final mix.", "category": "Music Post", "related_terms": ["Timecode", "Hit point", "Click track", "Spotting session", "Music editor"], "common_mistakes": ["Assuming the composer's DAW tempo map alone guarantees sync without checking against picture timecode", "Confusing frame rate or pull-up/pull-down settings so the music drifts against picture over a reel", "Only checking sync at hit points and missing gradual drift across a long cue"], "scenario_contexts": ["Confirming a recorded orchestral cue lands its hits on the exact frames before the final dub", "Catching a tempo or frame-rate mismatch that makes music drift late by the end of a reel", "A music editor conforming cues after a picture change to re-verify sync"]}, "1fec133f-b618-4393-b712-ad0e6c3c4d55": {"definition": "A dedicated, acoustically controlled theater used in film and television post-production to view and evaluate picture and sound together — dailies, edited cuts, and mixes — under conditions that approximate a target exhibition environment such as a cinema.", "plain_english": "A small private cinema used to watch and judge a film during editing. It is set up to look and sound like a real theater so the team can check their work.", "purpose_function": "It lets filmmakers and sound crews review the film in controlled conditions, so picture and sound choices are judged the way an audience will experience them.", "practical_application": "A re-recording mixer or supervising sound editor plays the reel in a screening room to spot problems and get director or client approval before final delivery.", "category": "Post Facilities", "related_terms": ["Dailies", "Re-recording mix", "Dub stage", "Reference monitor", "Calibration"], "common_mistakes": ["Confusing a screening room with a dub stage; the dub stage is built for mixing while a screening room is built for review", "Assuming any conference room with a screen counts, ignoring the need for calibrated level and acoustics", "Judging a theatrical mix on near-field speakers instead of in a properly calibrated room"], "scenario_contexts": ["Reviewing a temp mix with the director before the final dub", "Checking a finished feature in a calibrated room to confirm dialogue clarity and levels", "Screening dailies so the team can flag sound problems early"]}, "83509a3d-c12c-49d3-af63-e41dc21b91bf": {"definition": "Assembling a single best composite take for one part or section by selecting and joining the strongest portions of multiple recorded takes, as when combining several passes of a string or vocal section into one clean, continuous performance.", "plain_english": "Building one good take by picking the best bits from several tries. Like making a photo album from many shots, an editor keeps the best part of each pass and joins them.", "purpose_function": "It produces one clean, continuous performance from several imperfect takes, saving re-recording and giving the editor control over phrasing and timing.", "practical_application": "The editor lays takes on playlists or lanes, auditions each phrase, and pulls the best segments into a comp for the section before further editing or mixing.", "category": "Editing", "related_terms": ["Comping", "Playlist", "Take", "Crossfade", "Punch-in"], "common_mistakes": ["Forgetting to crossfade edit points, leaving clicks or level jumps between segments", "Comping for the best single moments while losing the natural flow of the whole phrase", "Not keeping the original takes, so the comp cannot be revised later"], "scenario_contexts": ["Combining three string-section passes into one clean take", "Comping a backing-vocal section from several recorded tries", "Fixing a few flubbed notes in a section by dropping in a better take"]}, "bd0544e8-79ed-4196-82c0-ae52af462aff": {"definition": "In audio middleware such as Audiokinetic Wwise, a container object that plays its child sound objects one after another in a defined order — either the authored step order or a set sequence — in contrast to a Random Container, which selects children at random.", "plain_english": "A folder of sounds that plays them one after another in a set order. It works like a playlist that always plays its tracks in the same sequence.", "purpose_function": "It lets sound designers build ordered patterns — such as a footstep cycle or a reload sequence — from separate sound files without scripting each step in the game engine.", "practical_application": "A game audio designer drops several footstep samples into a Sequence Container so they trigger in order each time the character walks.", "category": "Game Audio", "related_terms": ["Random container", "Switch container", "Blend container", "Sound bank", "Audio middleware"], "common_mistakes": ["Confusing a Sequence Container with a Random Container, which plays children in random order", "Expecting variety from a sequence, which repeats the same order and can sound mechanical", "Forgetting to set the step or continuous play mode, changing how the sequence advances"], "scenario_contexts": ["Building a repeating footstep cycle in Wwise", "Sequencing a multi-part weapon reload sound", "Playing an ordered set of dialogue lines as a short exchange"]}, "5e97c695-5fe9-40ef-98e7-d5086b74c6f5": {"definition": "A randomized playback mode in which a container or playlist selects its child sounds in random order but does not repeat any element until all have played, avoiding immediate repetition while still varying the sequence.", "plain_english": "It is a random play mode that mixes up the order of sounds but will not repeat one until all have played. It works like shuffling a deck of cards before dealing.", "purpose_function": "It exists to keep repeated sounds — footsteps, gunshots, impacts — from sounding mechanically identical while still ensuring every variation is used before any repeats.", "practical_application": "An implementer sets a random container of footstep variations to shuffle so consecutive steps never reuse the same sample, reducing the machine-gun effect.", "category": "Interactive Audio", "related_terms": ["Playlist container", "Sequence container", "Layer container", "Sound asset", "Playback behavior"], "common_mistakes": ["Confusing shuffle (no repeat until all have played) with pure random, which can repeat the same sound back-to-back.", "Loading too few variations, so even shuffled playback becomes obvious.", "Assuming shuffle randomizes pitch or volume — it only randomizes selection order."], "scenario_contexts": ["Varying footstep samples so a character's walk never machine-guns.", "Cycling weapon-fire variations during sustained shooting.", "Playing ambient one-shots like bird calls in a non-repeating random order."]}, "47e52eeb-87c8-452c-8db0-d5e422a35805": {"definition": "A Foley recording approach in which a cue's movements — typically footsteps or cloth and prop moves — are performed and captured in one continuous take synced to picture, rather than being built up from multiple layered passes.", "plain_english": "Recording a Foley sound in one go while watching the scene, instead of layering it up in several takes. The artist moves in time with the picture and captures the whole action at once.", "purpose_function": "It captures a natural, connected performance in a single take, saving editing time and keeping the timing and feel of the moves consistent.", "practical_application": "A Foley artist watches the scene and performs all of a character's footsteps for the shot in one synced pass, then moves on to the next cue.", "category": "Foley", "related_terms": ["Foley", "Footsteps", "Cloth pass", "Foley pit", "Spotting"], "common_mistakes": ["Trying to capture too many separate sounds in one pass, so nothing is clean enough to use", "Poor sync because the artist watches the meters instead of the picture", "Assuming one pass always works; dense scenes may still need layered passes"], "scenario_contexts": ["Recording a character's walk across a room in a single synced take", "Performing a full cloth move for a costume change in one pass", "Laying down straightforward footsteps quickly on a tight schedule"]}, "246f6a79-3ba5-4374-87b7-060f07f0435c": {"definition": "A Foley footstep performance category representing quiet, careful, stealthy steps, performed with reduced weight and controlled foot contact to match a character moving silently on screen.", "plain_english": "Soft, careful footsteps made for a character trying to move without being heard. The Foley artist steps gently and slowly to match the sneaky action on screen.", "purpose_function": "It gives a sneaking character believable, tension-building footsteps that read as quiet and cautious rather than a normal walk.", "practical_application": "The Foley artist lightens each step and rolls the foot to keep it soft, matching a character tiptoeing past a threat on screen.", "category": "Foley", "related_terms": ["Footsteps", "Heel-toe", "Foley", "Foley walker", "Surface"], "common_mistakes": ["Making sneaks too loud or too even, which reads as a normal walk", "Ignoring the surface, so the sneak lacks the right quiet texture", "Forgetting the pauses and shifts in weight that sell caution"], "scenario_contexts": ["A character creeping down a hallway to avoid being caught", "Footsteps for a burglar moving through a dark house", "A soldier advancing quietly in a tense scene"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"3afaf5a7-d129-48cb-b4ae-86e56753e1e4": {"definition": "Foley footsteps that recreate the crunch of walking on snow, traditionally produced by squeezing a pouch of cornstarch (or a similar granular material such as salt) in rhythm with the on-screen steps.", "plain_english": "The crunchy sound of walking on snow, made in a Foley studio. The artist often squeezes a bag of cornstarch in time with the steps, because it crunches just like packed snow.", "purpose_function": "It supplies the distinctive crunch that real snow makes underfoot, which is hard to record on location, so winter scenes sound convincing.", "practical_application": "A Foley artist squeezes a cornstarch-filled pouch or bag in sync with each step to create fresh or packed snow footsteps for a winter scene.", "category": "Foley", "related_terms": ["Footsteps", "Foley", "Surface", "Foley prop", "Single-pass Foley"], "common_mistakes": ["Using loose sand or gravel, which sounds too hard and lacks the soft snow crunch", "Squeezing out of time with the picture, so the crunch does not match the steps", "Overdoing the crunch so it sounds fake instead of subtle"], "scenario_contexts": ["Footsteps for a character trudging through deep snow", "Creating crunch for a snowball or boot-in-snow shot", "Adding winter footsteps a location mic could not capture cleanly"]}, "a185d9ab-7b78-4f5e-b6db-523c769da2d1": {"definition": "An individual sound element — such as a recorded file, sound effect, music cue, or dialogue clip — that is managed, catalogued, and reused as a discrete unit within a production's audio library or session.", "plain_english": "A single sound file used in a project, like one sound effect or one music clip. Teams store and label these so they can find and reuse them easily.", "purpose_function": "Treating each sound as a named, tracked asset lets teams organize, search, share, and reuse audio across a project without losing or duplicating work.", "practical_application": "An editor pulls a labeled sound asset from the library, drops it into the session, and relinks it later during conform or delivery.", "category": "Asset Management", "related_terms": ["Sound library", "Metadata", "Session", "Stem", "Conform"], "common_mistakes": ["Saving assets without clear names or metadata, making them impossible to find later", "Editing the master asset instead of a copy, corrupting the original", "Losing track of which asset version is in the current cut"], "scenario_contexts": ["Searching a sound library for a specific effect by its metadata", "Handing off labeled assets to another editor or facility", "Relinking assets during a conform before final delivery"]}, "f39e8124-843a-468e-82ee-b4a6fd1f2c05": {"definition": "A sound-design technique in which one sound is gradually transformed into another so that intermediate stages carry features of both, typically by interpolating spectral, pitch, and amplitude characteristics over time.", "plain_english": "This is when one sound slowly changes into a totally different sound. It works like a photo that melts from a cat into a dog, but with sound instead of pictures.", "purpose_function": "It lets a sound designer create smooth, unnatural transitions or hybrid textures that a single recording cannot capture, which is useful for transformation effects seen on screen.", "practical_application": "A designer might morph a human voice into an animal growl to score a creature changing shape, using a morphing plug-in or a spectral editor.", "category": "Sound Design", "related_terms": ["Source manipulation", "Sound-design session", "Pitch shifting", "Spectral editing", "Layering"], "common_mistakes": ["Confusing morphing with a simple crossfade, which only overlaps two sounds instead of blending their inner features.", "Expecting a convincing morph from sounds with very different spectral content without matching pitch and formants first.", "Over-processing until the result sounds artificial and loses both source identities."], "scenario_contexts": ["Scoring an on-screen creature transformation in a fantasy film.", "Building a hybrid vehicle that shifts from a mechanical to an electric engine.", "Designing a magical transition whoosh for a title sequence."]}, "237b9e5c-9d8c-4e18-a0e4-720fe8e822bb": {"definition": "An alternate rendition of a sound effect that differs slightly in timing, pitch, level, or timbre, used to avoid audible repetition when the same action recurs on screen.", "plain_english": "This is another version of the same sound, changed a little so it does not sound the same each time. Footsteps use many small variations so they do not sound fake.", "purpose_function": "Variations keep repeated events such as footsteps, gunshots, or punches sounding natural rather than obviously looped.", "practical_application": "An editor lays down several footstep variations across a walking shot so that no two steps sound identical.", "category": "Sound Design", "related_terms": ["Sound-effects editing", "Source library", "Sound-effect stem", "Foley", "Layering"], "common_mistakes": ["Reusing one identical file for every repeat, which produces the obvious 'machine-gun' effect.", "Making variations so different that they no longer feel like the same source.", "Varying only the file but forgetting to vary level and pitch as well."], "scenario_contexts": ["Cutting footsteps for a long walking scene.", "Editing repeated gunfire in an action sequence.", "Building a crowd from many single-voice variations."]}, "ffb6294a-187b-4432-9163-14fd47da3e65": {"definition": "The DAW project and its associated media in which a sound designer builds, processes, and arranges custom effects, kept separate from the editorial and mix sessions.", "plain_english": "This is the computer project where a sound designer builds new sounds. It holds all the clips, edits, and effects for that work in one place.", "purpose_function": "It gives the designer a dedicated workspace to experiment and render finished effects without disturbing the main edit or the mix.", "practical_application": "A designer opens a sound-design session to layer and process a custom explosion, then exports the finished effect into the editorial session.", "category": "Sound Design", "related_terms": ["Sound-design suite", "Source manipulation", "Sound-effects editing", "Sound morphing", "Bounce"], "common_mistakes": ["Working directly in the mix session and cluttering it with design experiments.", "Not consolidating or backing up media, so rendered effects break when files move.", "Failing to label and organize tracks, making the session hard to revisit later."], "scenario_contexts": ["Building a signature weapon sound for a film or game.", "Designing a sci-fi user-interface sound palette.", "Prepping custom effects before handing them to the effects editor."]}, "6709d952-f861-4d98-97a9-97b98ee2b5ef": {"definition": "A room and its equipment configured for sound-design work, typically a DAW, monitoring, and processing tools in an acoustically treated space separate from the mix stage.", "plain_english": "This is the room set up for making and shaping sounds. It has speakers, a computer, and tools in a quiet, treated space.", "purpose_function": "It provides a controlled listening environment and toolset so a designer can create and check effects accurately before they reach the final mix.", "practical_application": "A designer books time in the sound-design suite to build effects on calibrated monitors before delivering them to the dub stage.", "category": "Post Facility", "related_terms": ["Sound-design session", "Dub stage", "Monitoring", "Room calibration", "Source manipulation"], "common_mistakes": ["Assuming any office room works and ignoring acoustic treatment and monitor calibration.", "Confusing the design suite with the mix stage, which is set up for final mixing at a reference level.", "Mixing final deliverables in a suite that is not calibrated to delivery standards."], "scenario_contexts": ["A designer creating effects ahead of a feature mix.", "A facility renting rooms for sound-design work.", "A game studio's dedicated audio design room."]}, "ab93d484-1243-453b-bf8f-ee1ed49a0149": {"definition": "A submix deliverable containing only the sound-effects elements of a mix, printed as a discrete stem so effects can be re-balanced, replaced, or re-versioned independently of dialogue and music.", "plain_english": "This is a mix that holds just the sound effects, kept apart from voices and music. Keeping it separate lets people change the effects later without redoing the whole mix.", "purpose_function": "Separate effects stems support re-mixing, foreign-language versions, trailers, and archiving by letting each element be adjusted on its own.", "practical_application": "For delivery, the re-recording mixer prints dialogue, music, and effects stems so the studio can build an M&E or a trailer later.", "category": "Deliverables", "related_terms": ["Sound-effects premix", "M&E", "Dialogue stem", "Music stem", "Final mix"], "common_mistakes": ["Confusing a stem with a single track; a stem is a full submix of many effects tracks.", "Printing stems that do not sum back to the approved final mix.", "Leaving Foley or backgrounds out of the effects stem when the delivery spec requires them."], "scenario_contexts": ["Delivering split stems to a distributor.", "Building an M&E for foreign-language dubbing.", "Re-versioning effects for a shorter trailer cut."]}, "3790c53d-8b33-4077-ab6e-4d4aef765fff": {"definition": "The editorial process of selecting, cutting, syncing, and organizing hard effects, backgrounds, and designed sounds to picture, preparing them for the premix and final mix.", "plain_english": "This is the job of picking sound effects and lining them up with the picture. The editor cuts each sound to hit the right moment on screen.", "purpose_function": "It builds the effects side of a soundtrack and gives the mixer clean, synced, well-organized material to balance.", "practical_application": "An effects editor cuts door slams, car passes, and ambiences to the locked picture, then hands off organized tracks for the premix.", "category": "Editorial", "related_terms": ["Sound-effects premix", "Sound-effect stem", "Source library", "Foley", "Backgrounds"], "common_mistakes": ["Placing effects a frame or two off sync so they feel disconnected from the action.", "Delivering messy, unlabeled tracks that slow the mix.", "Ignoring perspective and room tone, so effects do not match the shot."], "scenario_contexts": ["Cutting hard effects for an action scene.", "Laying in backgrounds for a quiet dialogue scene.", "Prepping effects tracks before a mix session."]}, "89d44675-a8ac-4903-a85e-45c164da19d3": {"definition": "An intermediate mix pass in which the many sound-effects tracks are balanced, processed, and combined into a smaller, manageable set of subgroups before the final mix.", "plain_english": "This is a first mix of just the sound effects. It blends many effects tracks down to a few, so the final mix is easier to handle.", "purpose_function": "Premixing lowers the track count and sets internal balances so the final mix can focus on blending effects with dialogue and music.", "practical_application": "A mixer premixes dozens of backgrounds and hard-effects tracks into a handful of subgroups before the final dub.", "category": "Mixing", "related_terms": ["Sound-effects editing", "Sound-effect stem", "Final mix", "Dub stage", "Subgroup"], "common_mistakes": ["Baking in heavy processing that cannot be undone if the final mix needs changes.", "Premixing at the wrong level so the final balance is hard to reach.", "Grouping too aggressively and losing needed separation between effects."], "scenario_contexts": ["Reducing a large effects session before the final mix.", "Preparing effects subgroups for a dub stage.", "Balancing dense action effects ahead of the final pass."]}, "8786545d-4d7a-474d-8431-1626284fc7c3": {"definition": "An organized collection of raw recordings and sound-effects files, commercial or self-recorded, from which a designer or editor draws material to build a soundtrack.", "plain_english": "This is a big, sorted collection of sound recordings to pick from. It works like a stock-photo site, but for sounds instead of pictures.", "purpose_function": "It gives editors fast access to a wide range of sounds so they can find or build effects without recording everything from scratch.", "practical_application": "An editor searches the source library by keyword to pull a matching car-by before deciding whether to record a custom one.", "category": "Assets", "related_terms": ["Source manipulation", "Sound-effects editing", "Sound variation", "Metadata", "Field recording"], "common_mistakes": ["Using library files without checking their license for the project.", "Grabbing the first search hit instead of auditioning options for the best fit.", "Poor metadata or naming, which makes the library hard to search later."], "scenario_contexts": ["Pulling ambiences for a location the crew could not record.", "Finding a rare vehicle or animal sound.", "Building a personal library from field recordings."]}, "88601211-99ee-4beb-92e4-3bb2f4b84f8b": {"definition": "The processing and transformation of a recorded source sound, through pitch, time, spectral, and other treatments, to create a new sound whose origin is no longer obvious.", "plain_english": "This is changing a recorded sound to make something new. A slowed, deepened lion roar can become the base of a monster, so you cannot tell where it started.", "purpose_function": "It lets designers build original, believable effects from real recordings, giving screen elements that have no natural sound a convincing voice.", "practical_application": "A designer pitches down and stretches an animal recording to build a creature vocal, hiding the original source.", "category": "Sound Design", "related_terms": ["Sound morphing", "Source library", "Sound-design session", "Pitch shifting", "Layering"], "common_mistakes": ["Over-processing until the sound becomes thin or full of artifacts.", "Starting from a low-quality recording that falls apart when stretched or pitched.", "Relying on one process instead of layering several treated sources."], "scenario_contexts": ["Turning animal recordings into a creature voice.", "Building a sci-fi engine from a processed real motor.", "Designing a weapon sound from manipulated household recordings."]}, "cc0cea8c-1edd-4fab-a958-1d4f26907d3d": {"definition": "In object-based and spatial audio, the directional facing of a sound source within a 3D scene, describing how a directional (non-omnidirectional) emitter is aimed relative to the listener and room. Together with the source's position, orientation shapes how the object's directivity pattern projects energy into the soundfield.", "plain_english": "It is the way a 3D sound is turned to face, like which way a speaker points. If a sound is aimed at you it feels direct; if it faces away it sounds duller and farther off.", "purpose_function": "It lets a spatial mix control not just where a sound sits but which way it faces, so directional sources project realistically into the room or headphone soundfield.", "practical_application": "A mixer sets a source's orientation in an object or ambisonic panner so an on-screen loudspeaker or voice aims correctly as the action or camera moves.", "category": "Spatial Audio", "related_terms": ["Spatial emitter", "Spatial blend", "Object-based audio", "Ambisonics", "Panning", "Directivity"], "common_mistakes": ["Confusing source orientation (which way it faces) with source position (where it is).", "Assuming orientation matters for omnidirectional sources, which radiate equally in all directions.", "Forgetting that orientation is only audible when the source or renderer models directivity."], "scenario_contexts": ["Aiming a diegetic on-screen speaker in a Dolby Atmos object mix.", "Setting emitter facing in a VR or 360 ambisonic scene.", "Rotating a directional source in a game-audio spatial scene."]}, "8d7c3e8c-cf83-4023-9fe3-9d851ff59178": {"definition": "The original audio captured at the time of shooting or in the field — production dialogue, effects, or ambience — that serves as the primary, unprocessed material from which the post-production soundtrack is edited and mixed.", "plain_english": "It is the original sound recorded on set or in the field, before anyone edits it. Think of it as the raw ingredients a cook starts with before making the meal.", "purpose_function": "It provides the authentic, primary audio, especially production dialogue, that the whole post soundtrack is built from and cut against.", "practical_application": "A dialogue editor pulls the source recordings from the field mixer's files, syncs them to picture, and picks the best takes to cut.", "category": "Post Workflow", "related_terms": ["Source Sound", "Production sound", "Field recording", "Dialogue editing", "Room tone", "ADR"], "common_mistakes": ["Editing or processing the only copy instead of working on a duplicate of the source.", "Assuming the source recording is one track when field mixers often deliver multitrack isos plus a mix.", "Ignoring embedded timecode and metadata that keep source recordings synced to picture."], "scenario_contexts": ["Importing a location mixer's poly-WAV files into the DAW.", "Choosing between iso mic tracks and the mixdown within a source recording.", "Cleaning up a noisy source recording before the mix."]}, "773b9dfb-bac8-420e-bc03-4aa19c727916": {"definition": "The original sound produced by a real, identifiable source — a voice, instrument, prop, or environment — as captured or used before it is edited, processed, or transformed. In post it denotes the raw sonic material that later design and effects are built from.", "plain_english": "It is the real sound a thing actually makes, before anyone changes it. Like the plain sound of a door slam before you add echo or make it louder.", "purpose_function": "It is the starting point of the soundtrack: the honest recorded sound that gives design and mixing a believable base.", "practical_application": "A sound designer starts with a source sound, say a real engine recording, then layers and processes it into the final vehicle effect.", "category": "Post Workflow", "related_terms": ["Source Recording", "Source transformation", "Foley", "Sound design", "Field recording", "Sample library"], "common_mistakes": ["Confusing source sound (the raw captured sound) with the finished, processed effect.", "Assuming any library sample is a clean source when many are already processed.", "Overlooking that a strong source sound reduces how much processing is needed later."], "scenario_contexts": ["Recording a real prop as the source sound for a designed effect.", "Auditioning library source sounds to build a creature vocalization.", "Comparing a source sound to its transformed version in the mix."]}, "91edcf3b-ce32-41d9-b250-690cdbe3d6ae": {"definition": "The sound-design process of taking a recorded source sound and reshaping it — through pitch, time, spectral, and effects processing — into new material whose origin is no longer literally recognizable. It is a core method for creating effects that cannot be recorded directly.", "plain_english": "It means taking a real recorded sound and changing it a lot to make something new. Like slowing and stretching a tiger's growl until it becomes a monster's roar.", "purpose_function": "It lets designers build impossible or larger-than-life sounds from believable real recordings, keeping an organic quality that synthesis alone struggles to give.", "practical_application": "A designer transforms a source recording with pitch-shifting, time-stretching, and spectral tools to turn everyday sounds into sci-fi or creature effects.", "category": "Sound Design", "related_terms": ["Source Sound", "Source Recording", "Pitch shifting", "Time stretching", "Spectral processing", "Sound design"], "common_mistakes": ["Transforming so heavily that the result loses realism and detail.", "Working destructively instead of keeping the untouched source for later.", "Expecting one plug-in to do what layered, staged processing achieves."], "scenario_contexts": ["Turning an animal recording into a monster voice.", "Building a spaceship pass-by from processed vehicle recordings.", "Designing a weapon effect by transforming mechanical source sounds."]}, "6da698f9-6a09-4360-86b6-f6de16ed4678": {"definition": "The relative balance between spatialized (positioned, immersive) and non-spatialized (stereo or mono, all-around) treatment of a source in a mix, controlling how strongly it locks to a point in 3D space versus a flat, enveloping presence. In some tools it is an explicit parameter that morphs a source from 2D to fully 3D positioning.", "plain_english": "It sets how 3D a sound is, from coming at you from all around to pinned to one exact spot. Like a dial between 'everywhere' and 'right over there.'", "purpose_function": "It lets a mixer decide how strongly each element locks to a position in an immersive field, trading envelopment against clear localization.", "practical_application": "In an immersive mix or game engine, an engineer sets spatial blend so ambience stays wide and enveloping while key effects snap to a precise 3D location.", "category": "Spatial Audio", "related_terms": ["Spatial emitter", "Source orientation", "Object-based audio", "Bed (immersive audio)", "Panning", "Immersive mix"], "common_mistakes": ["Making every element fully 3D, which collapses the sense of a stable, wide background.", "Confusing spatial blend with simple left-right pan.", "Assuming a fully spatialized source always translates cleanly to a stereo fold-down."], "scenario_contexts": ["Setting the 2D-versus-3D behavior of a source in a game-audio engine.", "Balancing enveloping beds against pin-point objects in a Dolby Atmos mix.", "Deciding how localized dialogue should be in an immersive presentation."]}, "36886468-f10f-4fb7-8079-dcc4c2469501": {"definition": "A discrete sound-source object placed at a defined position, and often orientation, within a 3D spatial audio scene, from which audio is rendered to the listener according to direction, distance, and directivity. In object-based and interactive audio it is the fundamental positioned element the renderer localizes.", "plain_english": "It is a single sound placed at a spot in a 3D scene, like a tiny speaker sitting somewhere in the room. The system works out how it should sound from where you are.", "purpose_function": "It gives the renderer a positioned point source to localize, so sounds appear to come from specific places around the listener.", "practical_application": "In a VR or game scene, a designer attaches a spatial emitter to an object so its sound tracks that object's position as the listener moves.", "category": "Spatial Audio", "related_terms": ["Source orientation", "Spatial blend", "Object-based audio", "Ambisonics", "Renderer", "Panning"], "common_mistakes": ["Confusing an emitter (a positioned source) with a channel or bed that has no single position.", "Placing too many emitters and overloading the spatial renderer.", "Forgetting to set distance attenuation, so far emitters stay unrealistically loud."], "scenario_contexts": ["Placing emitters on props in a VR ambisonic scene.", "Assigning game objects as emitters in audio middleware.", "Rendering positioned emitters to binaural for headphone delivery."]}, "3617e1f4-0d27-45f1-b8f3-fa616b6b1cbd": {"definition": "A monitoring room configured and calibrated for producing and reviewing spatial or immersive audio, using a multichannel loudspeaker layout (for example a 7.1.4 Dolby Atmos array with height speakers), controlled acoustics, and level and time alignment to a defined reference. It provides an accurate, standards-based environment for mixing immersive deliverables.", "plain_english": "It is a mixing room set up with speakers all around and overhead so you can hear 3D sound properly. It is carefully tuned so what you hear matches how it should sound elsewhere.", "purpose_function": "It gives engineers a trustworthy, calibrated space to place and judge sounds in three dimensions, so immersive mixes translate to other rooms and devices.", "practical_application": "A studio builds a spatial-audio room to a 7.1.4 layout and calibrates each speaker to reference level before mixing Atmos deliverables.", "category": "Post Workflow", "related_terms": ["Dolby Atmos", "Immersive mix", "Monitoring", "Speaker calibration", "Reference level", "Bed (immersive audio)"], "common_mistakes": ["Adding height speakers without calibrating their level and timing to reference.", "Assuming any surround room is Atmos-ready without the correct layout.", "Ignoring room acoustics, which corrupt localization in immersive playback."], "scenario_contexts": ["Certifying a room to Dolby Atmos music or home specifications.", "Calibrating a 7.1.4 array to reference SPL.", "Mixing an immersive deliverable in a purpose-built spatial-audio room."]}, "3741b2ac-f2db-437d-8ecd-402869880951": {"definition": "A signal-processing technique that gradually blends the spectral content (the frequency-and-amplitude, and often phase, makeup) of one sound into that of another, so one timbre is heard smoothly transforming into a different one. It is typically achieved with frequency-domain (FFT / phase-vocoder) analysis and resynthesis.", "plain_english": "It slowly turns the tone of one sound into the tone of another, like one voice melting into a different one. It works on the mix of pitches inside a sound, not just its volume.", "purpose_function": "It lets designers create smooth, otherworldly transitions between two timbres that plain crossfading or EQ cannot produce.", "practical_application": "A designer uses a spectral or FFT morphing tool to morph a human voice into an animal call for an on-screen transformation.", "category": "Signal Processing", "related_terms": ["Spectral processing", "Source transformation", "FFT", "Phase vocoder", "Cross synthesis", "Time stretching"], "common_mistakes": ["Confusing a spectral morph with a simple volume crossfade between two clips.", "Morphing sounds with very different pitch or rhythm, which smears the result.", "Ignoring FFT window and size settings that cause artifacts."], "scenario_contexts": ["Morphing a voice into a creature for a transformation scene.", "Blending two instrument timbres into a hybrid for a score.", "Designing a smooth transition between two ambiences."]}, "56fd3046-ddfd-41dc-9370-7e23bf4c9cdd": {"definition": "Audio processing carried out in the frequency domain, where a signal is analyzed into its spectrum (typically via the short-time Fourier transform / FFT), individual frequency components are edited or modified, and the result is resynthesized back into audio. It underlies tools for noise reduction, spectral repair, and spectral effects.", "plain_english": "It works on sound by its separate frequencies instead of just its overall loudness. It is like editing a photo pixel by pixel, so you can fix or change tiny parts of the sound.", "purpose_function": "It lets an engineer see and change specific frequencies over time, so unwanted sounds can be removed or textures reshaped with surgical precision.", "practical_application": "A dialogue editor uses a spectral editor to paint out a cough or beep from a take without dulling the surrounding speech.", "category": "Signal Processing", "related_terms": ["Spectral morphing", "FFT", "Spectrogram", "Noise reduction", "Phase vocoder", "De-noising"], "common_mistakes": ["Over-processing until speech sounds watery or full of artifacts.", "Treating spectral repair as a substitute for recording a clean source in the first place.", "Ignoring the FFT resolution trade-off between frequency detail and time detail."], "scenario_contexts": ["Removing a phone ring from a dialogue take with a spectral editor.", "Reducing steady broadband noise from a location recording.", "Isolating and reshaping a specific frequency band in a design element."]}, "8615abfd-3192-45a1-8760-b56a9a8d3bf7": {"definition": "In audio post and DAW work, the speed parameter is the control that sets the playback rate of recorded audio. Operated in a linked, tape-style (varispeed) mode it also raises or lowers pitch in proportion to the rate change, so a faster speed sounds higher; it is used for varispeed effects and for film-to-video frame-rate pull-up/pull-down conversions.", "plain_english": "It is the control that decides how fast a recording plays back. In its basic mode, speeding it up also makes the sound higher, like playing a record at the wrong speed.", "purpose_function": "It lets an editor stretch or compress the timing of audio to match picture or a new frame rate, and gives a quick way to shift pitch when speed and pitch are linked.", "practical_application": "A post editor nudges the speed parameter to conform a 24 fps mix to a 25 fps PAL deliverable, or to slow a sound effect for a slow-motion shot.", "category": "Time & Pitch", "related_terms": ["Varispeed", "Stretch processing", "Pull-up/pull-down", "Sample rate conversion", "Pitch shifting", "Frame rate"], "common_mistakes": ["Assuming the speed parameter changes only timing; in linked varispeed mode it also shifts pitch.", "Confusing varispeed (speed and pitch linked) with time-stretch (timing changed, pitch preserved).", "Applying a speed change and forgetting it moves sync against picture."], "scenario_contexts": ["Converting a 24 fps mix to 25 fps for a PAL deliverable using a 4% pull-up.", "Slowing a recorded effect to match a slow-motion visual.", "Creating a classic tape-style varispeed effect on a vocal or effect."]}, "51b5d6e0-0d0b-4558-88c2-5217bb7da55d": {"definition": "A spotting script is the working document produced during a spotting session that lists every place in a film or program where music or sound is to start and stop, each identified by timecode and annotated with notes on its purpose and character.", "plain_english": "It is a list made while watching the film that marks where each piece of music or sound should begin and end. Think of it as a map of the soundtrack, with timecodes as the street signs.", "purpose_function": "It captures the director's and editor's decisions in one reference so composers and sound editors know exactly what to create and where it belongs.", "practical_application": "After a spotting session, a music editor writes up the spotting script and hands timecoded cue starts and stops to the composer and the recording team.", "category": "Spotting & Prep", "related_terms": ["Spotting session", "Cue sheet", "Timecode", "Music editor", "Streamer", "Sound design"], "common_mistakes": ["Confusing a spotting script with the final cue sheet used for music licensing and royalties.", "Leaving out precise timecodes, so cues cannot be placed accurately.", "Treating early spotting notes as final when directors often revise cue decisions."], "scenario_contexts": ["A composer and director spot a drama and produce a script marking each music cue.", "A supervising sound editor spots reels to log where key effects and backgrounds are needed.", "A music editor updates the spotting script after a picture re-edit changes cue timings."]}, "2df2838f-6cf2-4dfc-8638-93bc4fecf830": {"definition": "State-driven audio is interactive game audio whose playback and mix are controlled by the game's current state, such as level, health, or combat status. It is typically implemented as global \"States\" in audio middleware that switch or blend sounds and mix settings as the state changes.", "plain_english": "It is game sound that changes with what is happening in the game. When you enter combat or your health drops, the music and effects shift to match, like a mood that follows the action.", "purpose_function": "It lets a game's soundtrack and mix react to broad situations automatically, keeping the audio in step with gameplay without hand-triggering every change.", "practical_application": "A game sound designer sets States like \"Exploring\" and \"Combat\" in Wwise or FMOD so the score and ambience cross-fade when the player is detected by enemies.", "category": "Interactive Audio", "related_terms": ["Audio middleware", "Switch", "RTPC", "Adaptive music", "Game state", "Interactive mix"], "common_mistakes": ["Confusing States (broad, global situations) with Switches (per-object variations like surface type).", "Forgetting to set transition times, causing abrupt jumps when the state changes.", "Assuming state logic lives in the audio files rather than in the middleware and game code."], "scenario_contexts": ["Music shifts from calm to tense when the player enters a combat state.", "Ambience changes as the player moves from an indoor to an outdoor state.", "The whole mix ducks and filters when a paused or underwater state is active."]}, "92d7219b-7809-47d9-8c0f-0233da7bb640": {"definition": "A sting ending is the technique of closing a scene, cue, or program segment with a sting, a short and sharp musical or sound accent that punctuates the moment, rather than fading or resolving gradually.", "plain_english": "It is finishing a scene or piece of music with a quick, punchy hit instead of a slow fade. It is the sharp \"ta-da\" that snaps a moment shut.", "purpose_function": "It gives a firm, attention-grabbing button to a segment, marking the end clearly for the audience and setting up a cut, reveal, or transition.", "practical_application": "A music editor places a sting ending on the last frame of a title card or dramatic reveal so the cue lands exactly on the hit point.", "category": "Music Editing", "related_terms": ["Sting", "Stinger", "Hit point", "Button", "Cue", "Streamer"], "common_mistakes": ["Confusing a sting ending (short punctuating accent) with a full musical cadence or fade-out.", "Missing the exact hit frame so the sting lands early or late against picture.", "Overusing stings until they lose their impact."], "scenario_contexts": ["Ending a TV drama act on a sharp musical sting before a commercial break.", "Punctuating a comedic beat with a quick sting.", "Landing a sting on a logo reveal at the end of a trailer."]}, "0c62361c-e69d-4974-aae4-1b909818fe1b": {"definition": "In ADR and music scoring, a streamer is a visual cue consisting of a vertical line that travels across the screen from left to right over a set number of frames, reaching the right edge at the exact sync point to signal a performer when to begin.", "plain_english": "It is a moving line that sweeps across the screen to warn a performer that their cue is coming. When it reaches the far side, that is the moment to start, like a countdown you can see.", "purpose_function": "It gives actors during ADR, or musicians recording to picture, a clear visual warning and precise start point so their performance lands in sync with the image.", "practical_application": "In an ADR session the mixer sets a three-second streamer before each line so the actor knows exactly when to speak in time with their lips on screen.", "category": "ADR Cueing", "related_terms": ["Punch", "Streamer-and-punch system", "ADR", "Three-beep", "Sync point", "Timecode"], "common_mistakes": ["Confusing the streamer (the moving warning line) with the punch (the flash at the hit point).", "Setting the streamer too short, giving the performer no time to prepare.", "Assuming the sync point is when the streamer starts rather than when it reaches the screen edge."], "scenario_contexts": ["Cueing an actor's ADR line with a streamer running up to the sync point.", "Guiding a musician to hit a downbeat in sync with a film action.", "Traditional film work where streamers were physically scribed onto the release print."]}, "07bcc8db-8621-4256-a887-a78804b07a16": {"definition": "The streamer-and-punch system is a visual cueing method for ADR and scoring to picture that combines a streamer, a line sweeping across the screen, with one or more punches, brief flashes on a single frame. The streamer provides the run-up while the final punch marks the precise hit point where the performer or conductor must land.", "plain_english": "It is a two-part visual countdown for performers working to picture. A line slides across the screen to warn them, then a flash marks the exact instant to hit, so their timing lands on the right frame.", "purpose_function": "It lets actors and musicians achieve frame-accurate timing to picture without hearing a click, by giving both an advance warning and a precise trigger point.", "practical_application": "A recordist enables streamer-and-punch cues in ADR software so each take gives the actor a moving line followed by a flash on the exact frame the line should reach.", "category": "ADR Cueing", "related_terms": ["Streamer", "Punch", "ADR", "Click track", "Sync point", "Music editor"], "common_mistakes": ["Thinking the system replaces good rehearsal; performers still need the warning to prepare.", "Confusing streamers (moving lines) with punches (single-frame flashes).", "Relying only on punches with no streamer, leaving performers no advance warning."], "scenario_contexts": ["Cueing ADR takes in Pro Tools with software streamers and punches.", "Recording an orchestra to picture using punches and streamers instead of a click.", "Restoring traditional grease-pencil streamer-and-punch cues for a scoring session."]}, "839ed4d3-a517-4fa3-9b8d-5079b358d053": {"definition": "Stretch processing, or time-stretching, is digital audio processing that changes the duration of a recording without altering its pitch, or that changes pitch independently of duration, by re-synthesizing the signal rather than simply changing its playback speed.", "plain_english": "It is a way to make a recording longer or shorter without making it sound higher or lower. Unlike speeding up a record, the pitch stays the same while the timing changes.", "purpose_function": "It lets editors fit audio to a new length, matching music to a scene or lining up dialogue, while keeping the pitch and tone natural.", "practical_application": "An editor uses stretch processing to fit a 28-second music cue into a 30-second gap, or to tighten a sound effect, without the pitch shifting.", "category": "Time & Pitch", "related_terms": ["Time stretching", "Pitch shifting", "Speed parameter", "Elastic Audio", "Warp", "Varispeed"], "common_mistakes": ["Confusing stretch processing (pitch preserved) with varispeed (speed and pitch move together).", "Stretching audio too far, which adds smearing or artifacts.", "Using the wrong algorithm for the material, such as a monophonic mode on a full mix."], "scenario_contexts": ["Fitting a music cue to an exact scene length without changing its key.", "Slowing a dialogue line slightly to match a new picture edit.", "Time-aligning a sound effect to on-screen action."]}, "4deb4d2d-c1f0-4837-9c2c-b13e269f14c3": {"definition": "A subdivision click is a click track that sounds not only the main beats but also their smaller divisions, such as eighth or sixteenth notes, giving performers a finer grid to lock to when recording music to picture.", "plain_english": "It is a metronome click that ticks between the main beats, not just on them. The extra ticks give players a tighter guide, like small lines drawn between the big marks on a ruler.", "purpose_function": "It helps musicians and conductors stay precisely in time, especially at slow tempos or on syncopated parts, by filling in the gaps between main beats.", "practical_application": "A composer adds a subdivision click on the eighths for a slow cue so the players can hit synchronised points accurately.", "category": "Click Tracks", "related_terms": ["Click track", "Tempo map", "Streamer-and-punch system", "Downbeat", "Metronome", "Sync point"], "common_mistakes": ["Setting subdivisions so dense that the click becomes distracting.", "Confusing a subdivision click with a tempo change; the tempo is the same, only the click grid is finer.", "Forgetting to lower or mute the click so it does not bleed into microphones."], "scenario_contexts": ["Recording a slow film cue where players need eighth-note clicks to stay together.", "Locking a percussive hit to picture using a sixteenth-note subdivision.", "Guiding a conductor through a slow passage with a subdivided click."]}, "25230ae9-816c-485e-8d59-542420b8c280": {"definition": "Subharmonic enhancement is a processing technique that synthesizes and adds new low-frequency content one octave below existing bass frequencies in a signal, reinforcing the perceived low end rather than simply boosting the original bass with EQ.", "plain_english": "It is a way to make the low end sound deeper by creating brand-new bass notes an octave below what is already there. Instead of just turning up the bass, it adds lower tones that were not in the original.", "purpose_function": "It adds weight and impact to the low end for effects, music, or a full mix, giving fuller bass on large systems while staying more controlled than a broad EQ boost.", "practical_application": "A re-recording mixer uses subharmonic enhancement to add sub-bass thump to an explosion or impact for the LFE channel in a theatrical mix.", "category": "Signal Processing", "related_terms": ["LFE", "Low-pass filter", "Equalization", "Bass management", "Harmonic distortion", "Sub-bass"], "common_mistakes": ["Adding too much subharmonic content, which muddies the mix and overloads subwoofers.", "Confusing generated subharmonics with a simple EQ bass boost of existing frequencies.", "UNSAFE: Driving subwoofers and amplifiers with excessive sub-bass energy and no high-pass protection, risking driver and amplifier damage."], "scenario_contexts": ["Reinforcing the LFE channel under an explosion in a film mix.", "Adding depth to a kick drum or bass synth in a music mix.", "Extending low end on program material for a cinema or club playback system."]}, "00535974-edfc-4a3f-9296-53bae2ff770f": {"definition": "Foley performed at a quiet, understated level — the small, incidental body and prop sounds such as light footsteps, cloth movement, and gentle handling — recorded to blend naturally beneath dialogue and key effects rather than to draw attention.", "plain_english": "Foley is when an artist re-creates everyday sounds in time with the picture. Subtle Foley means the very quiet ones, like soft steps or rustling clothes, that you feel more than you notice.", "purpose_function": "It adds realism and a sense of presence by filling in the tiny human and object sounds in a scene, without competing with dialogue or the main effects.", "practical_application": "A Foley artist walks and handles props gently in sync with the actor, and the mixer keeps these tracks low so they support the scene rather than stand out.", "category": "Foley", "related_terms": ["Foley", "Surface-based footsteps", "Cloth movement", "Spot effects", "Ambience", "Dialogue"], "common_mistakes": ["Performing subtle Foley too loudly so it distracts from the dialogue", "Skipping quiet Foley entirely and leaving scenes feeling lifeless and empty", "Failing to match the timing of small movements to the actor on screen"], "scenario_contexts": ["Recording soft footsteps and cloth rustle for a quiet dialogue scene", "Adding gentle prop handling under a tense, whispered conversation", "Filling in body-movement sounds after the production dialogue has been cleaned up"]}, "87c849c7-79a7-4255-9a0a-552f9642290c": {"definition": "In Foley and footstep work, the point at which a character moves from one walking surface to another — for example wood to gravel — requiring the performer or editor to switch to the matching surface material so the footstep sound changes with the ground.", "plain_english": "It is the moment a character steps from one kind of ground onto another, like moving off a tiled floor onto grass. The footstep sounds have to change to match the new surface.", "purpose_function": "Matching the footstep sound to each surface keeps the scene believable and helps tell the audience where the character is walking.", "practical_application": "A Foley artist swaps to the correct surface, such as a gravel tray, at the exact frame the actor's foot lands on the new ground.", "category": "Foley", "related_terms": ["Surface-based footsteps", "Foley", "Switch container", "Surface damping", "Subtle Foley"], "common_mistakes": ["Continuing the old surface sound after the character has clearly changed ground", "Mistiming the change so the switch happens on the wrong step", "Using a surface sound that does not match what is shown on screen"], "scenario_contexts": ["A character walks from a wooden porch down onto a gravel path", "Footsteps move from a carpeted room out onto a tiled hallway", "A game character crosses from grass onto a metal walkway"]}, "3774135d-b355-425f-bb51-be59c7f99969": {"definition": "The reduction of unwanted vibration or resonance in a surface by adding a lossy or absorbent material, lowering the amplitude and ring-out of the sound the surface produces when struck or excited.", "plain_english": "Damping means stopping a surface from ringing after it is hit. You add a soft or heavy material so the vibration dies away fast, like resting a hand on a cymbal to quiet it.", "purpose_function": "It controls resonance and unwanted ringing so a surface or object produces a cleaner, shorter, more controlled sound.", "practical_application": "A Foley artist may damp a Foley table or prop with foam or tape to remove a hollow ring before recording footsteps or impacts.", "category": "Acoustics", "related_terms": ["Surface-based footsteps", "Foley", "Resonance", "Reverberation", "Ambience"], "common_mistakes": ["Confusing damping with soundproofing when it only shortens a surface's ring", "Over-damping so the sound becomes dull and lifeless", "Ignoring a resonant table or prop that colors every recorded hit"], "scenario_contexts": ["Deadening a hollow Foley table so footsteps do not ring", "Adding foam to a metal prop to remove an unwanted resonant tone", "Damping a panel that rattles when nearby impacts are performed"]}, "5a25f34b-2cfb-4c9d-8a87-89eed081ba92": {"definition": "Footstep sounds organized, selected, or generated according to the surface a character walks on — such as concrete, wood, grass, metal, or water — so that the correct material sound plays for each step.", "plain_english": "These are footstep sounds sorted by the type of ground. On wood you hear wood steps, and on gravel you hear gravel, so each surface has its own set of sounds.", "purpose_function": "Matching footsteps to the surface underfoot makes movement sound real and helps the audience or player sense the environment.", "practical_application": "In game audio, footstep sounds are split into surface groups and triggered by the ground type under the character; in Foley, artists record a separate pass for each surface.", "category": "Foley", "related_terms": ["Surface change", "Footsteps", "Switch container", "Foley", "Subtle Foley"], "common_mistakes": ["Playing the wrong surface set so footsteps do not match the ground on screen", "Recording only one surface and reusing it everywhere", "Forgetting to cover every surface a character actually walks on"], "scenario_contexts": ["Building separate footstep sets for wood, gravel, and metal in a game", "Recording per-surface Foley passes for a chase across mixed terrain", "Assigning surface footstep groups to a character's movement in middleware"]}, "037c50b1-55f6-4dcb-82d7-11b8b313d015": {"definition": "An additional sound layered onto an existing effect or recording to enhance, thicken, or add impact — for example a low boom or metallic ring placed under a gunshot or impact to make it more powerful.", "plain_english": "A sweetener is an extra sound added on top of another to make it bigger or better. It is like adding a deep boom under a punch so the hit feels much stronger.", "purpose_function": "It builds a richer, more dramatic sound by combining layers, giving effects more weight or excitement than a single recording can provide.", "practical_application": "A sound editor layers a sweetener, such as an added whoosh or a sub-bass thump, under a key action moment to give it more impact in the mix.", "category": "Sound Design", "related_terms": ["Sound design", "Layering", "Sub-bass", "Spot effects", "Sound effects"], "common_mistakes": ["Adding so many sweeteners that the effect becomes cluttered and muddy", "Leaving a sweetener out of sync with the main sound it supports", "Using a sweetener that does not fit the object or action being enhanced"], "scenario_contexts": ["Adding a sub-bass layer under an explosion for more weight", "Placing a metallic ring under a sword clash to make it sharper", "Layering a whoosh under a fast camera move or title reveal"]}, "c80a62f1-96b1-4ac5-8b2c-edf0c60ec9ad": {"definition": "In interactive audio middleware such as Wwise, a container that holds several sound objects or groups and plays the one assigned to the currently active switch state — commonly used so that, for example, footstep sounds change with the ground surface.", "plain_english": "It is a container in game sound tools that holds several versions of a sound and plays the right one for the current setting. For footsteps, that setting could be the ground type, so the matching surface sound plays.", "purpose_function": "It lets a single event automatically pick the correct sound for the current game state, so audio responds to changing conditions without extra scripting.", "practical_application": "A game sound designer places wood, gravel, and metal footstep sets in a switch container tied to a surface switch, and the engine plays the right set as the character moves.", "category": "Game Audio", "related_terms": ["Surface-based footsteps", "Surface change", "Random container", "Event", "Middleware"], "common_mistakes": ["Forgetting to set a default so an unmapped switch state plays nothing", "Assigning sounds to the wrong switch state so the wrong surface plays", "Confusing a switch container with a random container that varies sound by chance"], "scenario_contexts": ["Driving footstep surface changes from the ground type in a game", "Swapping weapon-handling sounds by the currently equipped weapon", "Changing an ambience bed based on the player's current area"]}, "41d2b1d9-bcfb-495d-8c7c-ee0b2d098d8f": {"definition": "A checking pass in which an editor or QC operator reviews a program to confirm that sound aligns correctly with picture — dialogue lip-sync, effects, and music hits all landing on the right frames — before delivery.", "plain_english": "It is a check to make sure the sound lines up with the picture. You watch and listen for lips matching speech and sounds hitting at the right moment before the project is sent out.", "purpose_function": "It catches timing errors and drift so a finished program does not go out with sound that is out of step with the picture.", "practical_application": "During quality control, an operator watches the cut and flags any spots where dialogue, effects, or music slip out of sync so they can be fixed before delivery.", "category": "Quality Control", "related_terms": ["Lip sync", "Timecode", "Synchronization display", "Deliverables", "Quality control"], "common_mistakes": ["Checking sync on only one scene instead of the whole program", "Missing slow drift that builds up over a long reel", "Reviewing on a system whose own delay hides real sync errors"], "scenario_contexts": ["Watching a full episode for lip-sync before it is delivered", "Confirming effects and music hits land on frame after a re-conform", "Spot-checking sync at reel changes in a feature mix"]}, "8f2233c1-0156-4049-9cae-ab89af627630": {"definition": "An on-screen readout that shows synchronization information — such as matching timecode, frame position, or lock status between audio and video devices — so an operator can confirm that sources are running in step.", "plain_english": "It is a screen or readout that shows whether the sound and picture are locked together. It displays things like timecode so you can see at a glance that everything is running in step.", "purpose_function": "It gives the operator a clear sign that devices are synchronized, or that they are not, helping catch a loss of lock before it affects the work.", "practical_application": "An engineer watches the sync or timecode display on a deck or interface to confirm audio and video are locked to the same reference before recording or playback.", "category": "Synchronization", "related_terms": ["Timecode", "Genlock", "Sync-quality review", "Word clock", "Lip sync"], "common_mistakes": ["Assuming a running display means locked when it only shows free-running numbers", "Ignoring a dropped-lock warning during playback", "Reading the display but not confirming both devices share one reference"], "scenario_contexts": ["Confirming a recorder is locked to timecode before a take", "Watching for loss of lock during a layback to picture", "Verifying two decks share the same reference before capture"]}, "d990e2c3-549d-466d-8424-4d5305cc0e17": {"definition": "A specific moment where a sound or musical accent is deliberately aligned to a visual action or cut on screen — a hit point — so the audio lands exactly with the on-picture event.", "plain_english": "It is a point where a sound or music note is timed to strike exactly with something on screen, like a stinger landing as a door slams. The sound and the picture hit at the same moment.", "purpose_function": "Placing hits on key visual moments strengthens the emotional or dramatic impact and ties the sound tightly to the picture.", "practical_application": "A composer or sound editor marks hit points on the timeline and lines up accents or effects so they land on the exact frame of an action.", "category": "Synchronization", "related_terms": ["Hit point", "Spotting", "Sync point", "Scoring", "Spot effects"], "common_mistakes": ["Landing the hit a frame or two late so it feels loose", "Overusing hits until the score feels cartoonish", "Marking hit points to a picture cut that later moves and not updating them"], "scenario_contexts": ["Timing a music stinger to a sudden on-screen reveal", "Landing an impact effect on the frame a punch connects", "Aligning an accent to a title card or hard cut"]}, "f7508a4d-65eb-47ae-8907-a8fe997552dd": {"definition": "The creation of sound effects and textures from synthesized or electronically generated signals — oscillators, samplers, modular or software synths and signal processing — rather than from recorded real-world sources, used to build sounds that do not exist in nature or that need a stylized, designed character.", "plain_english": "You make sound effects from scratch on a synth, not by recording real objects. It is like drawing a made-up monster instead of taking a photo of a real animal.", "purpose_function": "It lets sound editors create sounds that cannot be recorded, such as spaceships, force fields or laser weapons, with full control over pitch, movement and tone. It exists because many on-screen elements have no real-world sound to capture.", "practical_application": "A designer patches oscillators or a soft-synth, shapes the sound with filters and envelopes, then layers it with processing to score a robot, laser or magic effect for a film or game.", "category": "Sound Design", "related_terms": ["Synthesizer", "Sound effects editing", "Layering", "Foley", "Sampling", "Sweetening"], "common_mistakes": ["Assuming synthetic design means only sci-fi sounds, when it also builds risers, whooshes and textures for any genre", "Relying on a single synth patch instead of layering several sources for depth", "Ignoring how the synthetic sound sits against dialogue and music in the final mix", "Leaving the sound static with no movement, so it reads as obviously artificial"], "scenario_contexts": ["Building a laser-blast sound for a science-fiction feature", "Creating UI beeps and alerts for a video game menu", "Designing an abstract riser to build tension before a scene change", "Generating a fantasy magic-spell effect that has no real-world recording"]}, "6f56c7da-0b89-490c-858e-d5d3d3683e9f": {"definition": "An impact sound effect of an object, hand or body striking a tabletop or similar hard surface, used as a hard effect or Foley cue synced to an on-screen hit on a table.", "plain_english": "The sound of something hitting a table, added so an on-screen bang matches the picture. Think of a fist slamming down or a mug set down hard on a table.", "purpose_function": "It sells the moment of contact between an actor or prop and a table, adding weight and realism that the production recording often does not capture cleanly.", "practical_application": "An editor pulls a table-impact from a library or Foley-records one, then trims and syncs it to the exact frame where the hit lands, adjusting level and low end for the desired force.", "category": "Sound Effects", "related_terms": ["Foley", "Hard effects", "Impact", "Sound effects editing", "Sync", "Sweetening"], "common_mistakes": ["Placing the impact a frame or two off the visible hit so it feels loose", "Using a boomy library hit that is too big for a light tap", "Forgetting to match the room tone or reverb of the scene", "Layering so many hits that the moment sounds unnatural"], "scenario_contexts": ["Syncing a fist slam to a heated argument scene", "Adding weight to a mug being slammed onto a bar", "Covering a prop dropped on a desk in an office scene", "Reinforcing a body being shoved onto a table in a fight"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"d80883d5-f71d-4a5c-84bb-649748866f68": {"definition": "Lengthening the natural decay or tail at the end of a sound — a reverb, room tone, note or effect — by adding reverb, time-stretching, or overlapping material so it fades out smoothly instead of cutting off abruptly.", "plain_english": "Making the fade-out at the end of a sound last longer so it does not stop suddenly. It is like letting a bell ring out instead of muting it right away.", "purpose_function": "It smooths edits and transitions and keeps a sound or ambience from ending unnaturally, which matters when a clip is cut short or needs to bridge into the next scene.", "practical_application": "An editor adds reverb or copies and crossfades the end of a region to stretch its decay, often to fill a gap left after trimming dialogue, music or an effect.", "category": "Editing Technique", "related_terms": ["Reverb tail", "Crossfade", "Room tone", "Fade", "Decay", "Time stretching"], "common_mistakes": ["Extending a tail so far it drags and muddies the next cue", "Using a reverb that does not match the space of the scene", "Creating an obvious loop point when copying the tail", "Forgetting that a longer tail can bleed over a hard picture cut"], "scenario_contexts": ["Extending a music cue's final chord to land on a fade to black", "Smoothing the end of a trimmed sound effect so it does not click", "Filling a gap after shortening a line of dialogue", "Letting a reverb wash carry from one scene into the next"]}, "503fbc5d-03c8-4eb0-97c7-b780323642a5": {"definition": "The process of selecting and joining the best portions of multiple recorded takes into a single continuous performance — in dialogue, ADR or music editing — choosing lines or phrases from different takes and editing them together seamlessly.", "plain_english": "Building one clean performance by picking the best bits from several recorded tries and joining them. It is like making one great photo by combining the best parts of several shots.", "purpose_function": "It produces the strongest possible performance and technical quality from all available takes, fixing flubs, noises or timing issues by swapping in a better version of a word or line.", "practical_application": "A dialogue or ADR editor auditions each take, marks the best words or phrases, and cuts them together at natural breaths and edit points, matching level and tone so the joins are inaudible.", "category": "Editing Technique", "related_terms": ["ADR", "Dialogue editing", "Comping", "Take", "Crossfade", "Room tone"], "common_mistakes": ["Cutting mid-word instead of at a breath or consonant, making the join audible", "Assembling takes with different mic distances or tone that do not match", "Ignoring changes in background noise between takes", "Choosing a technically clean take over the better-acted one"], "scenario_contexts": ["Comping a lead actor's ADR from six recorded takes", "Joining the best half of two dialogue takes to remove a cough", "Assembling a voiceover from multiple reads for a documentary", "Building a final music vocal from several studio passes"]}, "7c407a54-ba32-455a-af82-f307be15918b": {"definition": "A specialist, most common in game audio, who implements sound into an interactive engine or middleware — building the systems, scripting and logic that trigger and modulate audio in real time — bridging creative sound design and software or engine programming.", "plain_english": "A sound person who is also part programmer, making sounds play correctly inside a game engine. They set the rules for when and how each sound triggers as the player moves and acts.", "purpose_function": "The role exists because interactive media need audio that responds to gameplay, so someone must connect creative sounds to the code and middleware to play at the right time, place and intensity.", "practical_application": "Using tools such as Wwise or FMOD, they build audio events, mix states and parameter controls, script triggers, and profile performance so sounds behave correctly and stay within memory and CPU budgets.", "category": "Role", "related_terms": ["Sound designer", "Game audio", "Middleware", "Audio implementation", "Interactive audio", "Foley"], "common_mistakes": ["Confusing the role with a pure sound designer who only creates sounds, not implementation", "Overlooking CPU, memory and voice-count budgets when building audio systems", "Assuming middleware skills alone are enough without creative sound judgment", "Not testing how sounds behave across the full range of gameplay states"], "scenario_contexts": ["Implementing footstep systems that change with surface in a game engine", "Setting up an interactive music system in Wwise or FMOD", "Debugging why a weapon sound fails to trigger during gameplay", "Optimizing an audio build to fit a console's memory budget"]}, "fe2103cd-5cdc-48b0-a52c-44f7ce03de19": {"definition": "Processing a voice to sound as if heard through a telephone, radio or intercom — typically a narrow bandpass filter around 300 Hz to 3.4 kHz, plus added distortion, compression and sometimes codec artifacts — commonly called futzing.", "plain_english": "Filtering a voice so it sounds like it is coming through a phone or radio. It cuts the deep lows and airy highs and adds a bit of grit, the way a real phone squeezes a voice.", "purpose_function": "It makes a caller or a voice over a speaker sound believable and separate from voices in the room, selling the storytelling of an off-screen or transmitted line.", "practical_application": "An editor inserts a bandpass EQ or a dedicated phone or futz plugin on the dialogue clip, tuning the band and distortion so the line reads as a phone, walkie or PA without losing clarity.", "category": "Dialogue Processing", "related_terms": ["Futz", "Bandpass filter", "EQ", "Dialogue editing", "Worldizing", "Codec"], "common_mistakes": ["Filtering so hard the words become hard to understand", "Using the same phone preset for every device instead of matching phone, radio or PA", "Forgetting to remove real room reverb before adding the effect", "Applying it to a full stereo mix instead of just the transmitted voice"], "scenario_contexts": ["Making one side of a phone conversation sound like it is on the line", "Creating a police-radio voice for a dispatch scene", "Processing a PA announcement heard across a station", "Adding an intercom effect to a spaceship crew call"]}, "d3dbf6eb-cc71-4a61-8bd3-3a0a6b8107e8": {"definition": "The craft of preparing, placing and adjusting music — score and licensed songs — to picture for television, including spotting cues, editing them to fit scene timing, handling fast revisions, and delivering conformed music tracks and cue sheets.", "plain_english": "Fitting music to the pictures in a TV show, choosing where each piece starts and stops and trimming it to match the scene. It is like a puzzle of matching songs and score to what is on screen.", "purpose_function": "It ensures music supports the story and hits the right moments while meeting broadcast timing and paperwork rules, freeing the composer and keeping the episode on a fast delivery schedule.", "practical_application": "A music editor spots episodes with the producers, cuts and conforms cues to picture changes in a DAW, builds temp music, and prepares cue sheets for licensing and royalty reporting.", "category": "Music Editing", "related_terms": ["Spotting session", "Music editor", "Cue sheet", "Temp music", "Conform", "Source music"], "common_mistakes": ["Editing a cue so the join breaks the musical phrasing or beat", "Forgetting to reconform music after a picture change", "Neglecting accurate cue sheets needed for royalties", "Letting music levels fight the dialogue in the mix"], "scenario_contexts": ["Spotting music for an hour-long drama episode", "Recutting a score cue after the picture edit changes", "Building temp music for a comedy before the composer scores it", "Preparing a cue sheet for a broadcast network"]}, "dbeafe8f-c966-4f68-a9a3-dba1bea421d3": {"definition": "A metronomic click, or click track, set to a defined tempo and often a bar and beat structure, that musicians and editors follow to keep performance and edits locked to a steady beat, frequently referenced to picture and timecode when scoring to film or television.", "plain_english": "A steady clicking beat, like a metronome, that players hear to stay in time. It is the same idea as tapping your foot so everyone keeps the same speed.", "purpose_function": "It keeps a performance or edit at a steady tempo so parts line up with each other and with picture hits, making it possible to sync music to on-screen action.", "practical_application": "A composer or editor sets the session tempo, generates a click, and has players record to it in headphones, or uses it to align edits and hit points when cutting music to picture.", "category": "Music Editing", "related_terms": ["Click track", "Tempo map", "Metronome", "Timecode", "Hit point", "Bars and beats"], "common_mistakes": ["Recording to a click set to the wrong tempo or time signature", "Making the click so loud it bleeds into the recorded mics", "Ignoring tempo changes needed to hit picture cues", "Assuming a rigid click suits music that should breathe or use rubato"], "scenario_contexts": ["Recording an orchestra to a click while scoring to picture", "Setting a click so a drummer stays locked to the grid", "Aligning a music edit to bars and beats in a DAW", "Following a variable click that speeds up to hit an on-screen action"]}, "5d4d4d1a-c40d-4452-9439-caab3d095d79": {"definition": "The on-screen readout in a DAW, sequencer or metronome showing the current tempo in beats per minute, and often the time signature and bar and beat position, so the user can see and set the session's timing.", "plain_english": "The part of the screen that shows the current speed of the music in beats per minute. It is like a speedometer for the song, telling you how fast the beat is going.", "purpose_function": "It lets the user read and set the project tempo at a glance, which is needed to keep recordings, edits and clicks in sync and to match music to picture.", "practical_application": "An editor reads the tempo display to confirm the BPM before recording to a click, typing in or tapping a new value and watching it update as tempo changes occur along the timeline.", "category": "Music Editing", "related_terms": ["Tempo", "BPM", "Tempo map", "Click track", "Transport", "Time signature"], "common_mistakes": ["Misreading the displayed tempo and recording at the wrong speed", "Not noticing the display reflects a tempo map that changes over time", "Confusing displayed BPM with the project's frame rate or timecode", "Assuming tap-tempo entry is exact without checking the value"], "scenario_contexts": ["Checking the BPM readout before setting up a click track", "Watching the tempo display update through a slowing tempo map", "Typing a new tempo into the transport for a remix", "Confirming a song's tempo to match a licensed track"]}, "a9143cd2-f86a-4c66-bd5d-e9330c2929bb": {"definition": "A discrete entry in a sequence's tempo map that sets the playback tempo, in beats per minute, from a specific timeline position onward. In a Standard MIDI File it is stored as a Set Tempo meta event expressing the tempo as microseconds per quarter note.", "plain_english": "A marker on the timeline that tells the software how fast to play from that point on. It works like a speed sign that sets the pace until the next one.", "purpose_function": "It defines the musical pulse at a given point so a DAW or sequencer can align beats, bars, and grid to clock time. It exists so tempo can be stored, edited, and reproduced exactly.", "practical_application": "An editor inserts or edits tempo events in the tempo track so the metronome, MIDI parts, and bar grid line up with a cue or with picture.", "category": "Tempo & Sync", "related_terms": ["Tempo ramp", "Tempo-map conform", "Beats per minute", "Time signature", "Click track"], "common_mistakes": ["Confusing a tempo event with a time signature (meter) event; one sets speed, the other sets beats per bar.", "Moving beat markers but forgetting to insert a matching tempo event, so playback drifts.", "Assuming one tempo event covers a whole piece when the music changes tempo in sections."], "scenario_contexts": ["Setting a fixed session tempo so the metronome and MIDI parts lock to the bar grid.", "Adding tempo events at each section change of a cue to follow the composer's map.", "Reading tempo events from an imported MIDI file to rebuild a click track."]}, "7c6ad9da-6c48-4b29-8cb1-c56e50d36cdf": {"definition": "A gradual, continuous change in tempo between two values across a span of the timeline, producing an accelerando or ritardando rather than an instantaneous jump. It is represented in a tempo map as an interpolated curve between tempo events.", "plain_english": "A smooth speed-up or slow-down in the beat, not a sudden jump. It is like a car easing onto the gas instead of flooring it at once.", "purpose_function": "It lets tempo change musically over time so click, MIDI, and grid follow a natural rise or fall in pace. It exists to model performances that speed up or slow down instead of stepping between fixed tempos.", "practical_application": "An editor draws a ramp between two tempo events so the click accelerates or decelerates smoothly under a scene or musical phrase.", "category": "Tempo & Sync", "related_terms": ["Tempo event", "Tempo-map conform", "Click track", "Beats per minute", "Metronome"], "common_mistakes": ["Using a single stepped tempo change where a smooth ramp is needed, causing an audible jump.", "Placing the ramp's start and end points on the wrong bars so the change finishes off the beat.", "Forgetting that a ramp shifts the timing of later bars, which can break downstream sync."], "scenario_contexts": ["Writing a gradual accelerando into a building chase-scene cue.", "Slowing the click smoothly into a final ritardando at a piece's ending.", "Matching a live take that naturally speeds up by drawing a tempo ramp."]}, "bbc23283-0739-404a-937b-255f903ca543": {"definition": "The process of adjusting a project's tempo map so its bars and beats realign with a reference such as a re-edited picture or a new cut, keeping the musical grid and events in sync after timeline changes.", "plain_english": "Fixing the tempo track so the beats line up again after the video or edit is changed. You slide and stretch the beat map to match the new cut.", "purpose_function": "It restores the relationship between the musical grid and picture after editorial changes, so MIDI, click, and score markers still fall where they should. It exists to keep music timing valid through repeated re-edits.", "practical_application": "After picture editorial delivers a new cut, a music editor conforms the tempo map so the bar/beat grid, click, and MIDI follow the revised timeline.", "category": "Tempo & Sync", "related_terms": ["Tempo event", "Tempo ramp", "Conform", "Bar/beat grid", "Picture lock"], "common_mistakes": ["Conforming the audio edits but leaving the old tempo map, so bars no longer match the new cut.", "Assuming conform fixes musical timing automatically when the tempo map must be updated by hand.", "Not sending the revised tempo map back to the composer or music editor after conforming."], "scenario_contexts": ["Updating the tempo track after picture editorial delivers a new cut.", "Aligning a borrowed or temp music tempo map to a re-timed scene.", "Rebuilding the bar/beat grid so MIDI and click follow the conformed timeline."]}, "612aafec-0e88-468d-8c0d-87253cb42962": {"definition": "A delivery set of program picture elements supplied without any burned-in text, such as clean backgrounds free of titles, credits, subtitles, and lower thirds, provided so localized or replacement text can be added for other territories and versions.", "plain_english": "Clean video shots with no words printed on them. They are sent so other countries can add their own titles and captions.", "purpose_function": "It lets distributors localize a program by laying translated titles and captions over clean backgrounds, avoiding re-shooting or re-rendering. It exists so one master can serve many territories.", "practical_application": "The post team renders or pulls every shot that carries burned-in text and delivers clean versions alongside the finished master to the versioning or localization house.", "category": "Deliverables", "related_terms": ["Master", "M&E", "Localization", "Deliverables", "Lower third"], "common_mistakes": ["Delivering only the finished picture and forgetting the clean textless backgrounds.", "Supplying textless shots that are the wrong length or color grade versus the final master.", "Assuming subtitles are exempt; burned-in text of any kind must be removed."], "scenario_contexts": ["Preparing a feature for foreign-language title and credit replacement.", "Delivering clean lower-third backgrounds for a documentary's international cut.", "Supplying textless main and end titles to a streaming platform's delivery spec."]}, "276acfbe-e9f7-4e91-9e2b-ea524f468109": {"definition": "A supporting sound-design or music layer that adds tonal color, movement, or atmosphere beneath the primary elements of a mix, filling sonic space without carrying the main melodic, dialogue, or narrative content.", "plain_english": "A background sound layer that adds color and mood under the main sounds. It fills out the space, like the soft wash of strings behind a singer.", "purpose_function": "It adds depth, warmth, and continuity by occupying frequency and stereo space that lead elements leave open. It exists to shape mood and help glue a mix together.", "practical_application": "A sound designer or composer layers subtle pads, tones, drones, or ambiences under dialogue and effects to support emotion without drawing attention.", "category": "Sound Design", "related_terms": ["Ambience layer", "Sound bed", "Room tone", "Sound design", "Layering"], "common_mistakes": ["Mixing texture layers too loud so they mask dialogue or the lead line.", "Stacking many textures until they clutter the low-mids and muddy the mix.", "Forgetting to high-pass textures, letting rumble and low-end build up."], "scenario_contexts": ["Adding a low drone under a tense scene.", "Layering room tone and soft pads to smooth transitions between shots.", "Building a bed of textures beneath a trailer's impact hits."]}, "1f047744-337f-4dd3-a0a7-2704e7426c61": {"definition": "A calibrated re-recording environment, or dubbing stage, designed and aligned for cinema playback, with monitoring set to the standardized B-chain electroacoustic response and reference level used in theaters so that a mix translates predictably to the auditorium.", "plain_english": "A movie sound mixing room set up to sound like a real cinema. It is tuned to an agreed standard so the mix plays back the same way in theaters.", "purpose_function": "It gives re-recording mixers a controlled reference that predicts how the mix will sound in a real cinema, so level and tone translate to the auditorium. It exists to standardize monitoring from stage to stage.", "practical_application": "Mixers calibrate the room's B-chain response and reference monitoring level to the theatrical standard, then mix the film knowing it will play back consistently across theaters.", "category": "Mix Environment", "related_terms": ["Dubbing stage", "Re-recording mixer", "X-curve", "Reference level", "B-chain"], "common_mistakes": ["Assuming a small near-field studio translates to a large theater without theatrical calibration.", "Mixing at a level other than the calibrated reference, so theatrical playback ends up too loud or too soft.", "Judging tone on an uncalibrated system instead of the standardized room response."], "scenario_contexts": ["Final re-recording mix of a feature for cinema release.", "Calibrating a dubbing stage to the theatrical playback standard before a session.", "Checking a near-field mix against the room's theatrical B-chain response."]}, "2a0e0a9b-072e-49c8-82e4-b29611fa0f26": {"definition": "Interactive audio that positions sounds in three-dimensional space around the listener and updates them in real time as the player and objects move, using techniques such as positional panning, distance attenuation, and head-related transfer function (HRTF) binaural rendering.", "plain_english": "Game sound that seems to come from all around you and moves as you play. If you turn away from a sound, it shifts to match, so the world feels real.", "purpose_function": "It makes a game world believable and helps players locate action by placing sounds in space and updating them with player movement. It exists to support immersion and give gameplay cues.", "practical_application": "A game audio designer authors sounds in an engine with 3D positioning, distance rolloff, and often HRTF binaural rendering so audio responds to the player in real time.", "category": "Game Audio", "related_terms": ["Spatial audio", "Binaural rendering", "HRTF", "Object-based audio", "Distance attenuation"], "common_mistakes": ["Treating game audio like a fixed linear film mix instead of a real-time interactive system.", "Applying full 3D to sounds that should stay 2D, such as music or UI beeps.", "Ignoring distance attenuation so far-off sounds stay unrealistically loud."], "scenario_contexts": ["Placing footsteps and gunfire around a player in a first-person shooter.", "Rendering binaural 3D audio for a VR headset.", "Cueing an off-screen enemy by its position in the sound field."]}, "20d3fb28-60e5-4e5a-b508-da24a4da2f3d": {"definition": "The broad category of editing and processing techniques that alter the temporal characteristics of audio, including time stretching or compression, varispeed, and reversal, changing a clip's duration or timing without necessarily changing its other properties.", "plain_english": "Changing the timing or speed of a sound with editing tools. You can make it longer, shorter, faster, slower, or play it backward.", "purpose_function": "It lets editors fit audio to a new duration, correct timing, or create effects without re-recording. It exists to give flexible control over when and how fast sound plays.", "practical_application": "An editor time-stretches a line to fit a shortened scene, or reverses a hit for a whoosh, using a DAW's time-editing and processing tools.", "category": "Editing & Processing", "related_terms": ["Time stretching", "Time reversal", "Varispeed", "Pitch shifting", "Elastic audio"], "common_mistakes": ["Stretching audio too far so it sounds warbly or full of artifacts.", "Expecting a stretch to hold pitch when varispeed changes both speed and pitch together.", "Forgetting that stretching changes region length and can break downstream sync."], "scenario_contexts": ["Fitting a voice-over to an exact shot length.", "Slowing a sound effect to match a slow-motion shot.", "Reversing a cymbal to build a transition swell."]}, "d92bc7a1-29a7-4742-97eb-3ea04873a6ad": {"definition": "A process that plays or renders an audio segment backwards so its samples run from end to start, reversing the waveform and its amplitude envelope in time.", "plain_english": "Playing a sound backward, from the end to the start. It is like running a tape or video in reverse.", "purpose_function": "It creates rising swells, whooshes, and unnatural effects, or restores a clip that was reversed by mistake. It exists as a simple way to flip a sound's shape in time.", "practical_application": "An editor applies a reverse process to a clip so a reverb tail builds up into a hit, or so a sound leads smoothly into a cut.", "category": "Editing & Processing", "related_terms": ["Time manipulation", "Reverse reverb", "AudioSuite", "Transition effect", "Sound design"], "common_mistakes": ["Reversing a clip but forgetting to render or commit it, so playback stays forward.", "Expecting reversal alone to make a smooth swell without adding reverb or a fade.", "Setting the wrong region boundaries so the reversed effect starts or ends off the beat."], "scenario_contexts": ["Making a reverse-reverb lead-in before a big story moment.", "Creating a whoosh for a scene transition.", "Designing a sci-fi effect from a reversed metallic hit."]}, "9f0f2f96-0f00-4294-8541-b0a415bd8026": {"definition": "A production or post-production script in which each line of dialogue, narration, or action is annotated with the SMPTE timecode of the picture at which it occurs. It lets sound and localization teams locate exact frames for ADR, dubbing, subtitling, and editorial reference.", "plain_english": "A time-coded script is a copy of the script with a time stamp next to each line. The time stamp shows the exact point in the video where that line is spoken, so the team can jump straight to it.", "purpose_function": "It ties spoken and on-screen events to precise picture time so dialogue replacement, foreign-language dubbing, captioning, and cueing can be planned and matched frame-accurately.", "practical_application": "An ADR or dubbing editor uses it to spot lines, cue the recording system to each timecode, and check that new takes line up with the original picture.", "category": "Post-production document", "related_terms": ["Timecode", "ADR", "Spotting session", "Dubbing", "Subtitle"], "common_mistakes": ["Assuming the listed timecodes always match the delivered picture; they must be re-referenced when the edit or start time changes.", "Confusing frame rates (e.g. 23.976 vs 24 or 25) so the listed timecodes drift against the video.", "Treating a plain shooting script as time-coded when it carries no frame references."], "scenario_contexts": ["Preparing an ADR list for a scene where lines must be re-recorded.", "Handing a translator a time-coded dialogue script for foreign-language dubbing.", "Timing subtitles or captions to match on-screen speech."]}, "168af508-dd89-4e0c-af3e-ac60d43c4d9f": {"definition": "A point in a musical score where the meter changes from one time signature to another (for example from 4/4 to 3/4), altering the number and/or value of beats grouped in each bar from that point onward.", "plain_english": "A time signature tells you how many beats are in each bar of music. A time-signature change is the moment the music switches to a new count, like going from four beats a bar to three.", "purpose_function": "It notates a shift in the metric pulse or grouping of a piece so performers, conductors, and sequencers regroup beats correctly and stay aligned with the music.", "practical_application": "A composer or engineer enters time-signature changes on a DAW's tempo/meter track so the metronome, bar lines, and grid follow the music through mixed-meter passages.", "category": "Rhythm & meter", "related_terms": ["Time signature", "Tempo map", "Bar", "Beat", "Conductor track"], "common_mistakes": ["Confusing a time-signature change (beat grouping) with a tempo change (beat speed); they are independent.", "Forgetting to enter the meter change on the DAW tempo/conductor track, so the click and grid drift from the score.", "Assuming the beat length changes when only the grouping does; the quarter note usually stays the same from 4/4 to 3/4."], "scenario_contexts": ["Scoring a film cue that moves between 4/4 and 7/8 to match the action.", "Building a click track for musicians recording a mixed-meter song.", "Aligning a DAW grid to a live performance that shifts meter."]}, "5c01409a-8ab5-4482-912d-8e988e40fd4e": {"definition": "A readout, either hardware or on-screen, that shows the current SMPTE/EBU timecode value in hours:minutes:seconds:frames, indicating the position of audio or video against a timeline or synchronization reference.", "plain_english": "A timecode display is a clock-style readout that shows exactly where you are in a video or recording, counting in hours, minutes, seconds, and frames. It lets everyone name and find the same exact spot.", "purpose_function": "It gives operators a precise, frame-level position reference so recorders, players, and DAWs can be lined up, logged, and synchronized to the same moment.", "practical_application": "An engineer reads the timecode display to confirm devices are locked to the same code, to note the timecode of an event, or to cue a machine to an exact frame.", "category": "Timecode & sync", "related_terms": ["Timecode", "Frame rate", "Drop-frame timecode", "Genlock", "Time-coded script"], "common_mistakes": ["Misreading drop-frame (semicolon) versus non-drop-frame (colon) timecode as if they count the same.", "Reading the display without checking its frame rate, so it doesn't match the picture.", "Assuming a running display means devices are locked together, when the code may be free-running and not synchronized."], "scenario_contexts": ["Checking that a field recorder and camera show matching timecode before a take.", "Logging the timecode of a sound event for the edit notes.", "Cueing a playback machine to an exact frame during a mix."]}, "e349b673-a62e-4ef4-832b-ec1df23b27a4": {"definition": "In footstep sound, the impact produced when the toe or ball of the foot contacts the ground, typically the second component of a normal walking step after the heel strike. In Foley it is performed and recorded as a distinct part of a footstep.", "plain_english": "When you walk, your heel lands first and then the front of your foot slaps down. That second sound, made by the ball and toe of the foot, is the toe strike. Foley artists copy it to match footsteps on screen.", "purpose_function": "It supplies the trailing half of a realistic footstep, giving weight, surface, and gait cues that sell a character's movement to the audience.", "practical_application": "A Foley artist steps heel-then-toe on a matched surface, timing the toe strike to the actor's foot on screen and adjusting shoes or surface for the right texture.", "category": "Foley", "related_terms": ["Heel strike", "Foley", "Footsteps", "Foley surface", "Sync-to-picture"], "common_mistakes": ["Recording a single flat stomp instead of a heel-then-toe motion, so steps sound unnatural.", "Ignoring the walking surface, so the toe strike doesn't match the on-screen floor.", "Letting the toe strike fall out of sync with the actor's foot contact on screen."], "scenario_contexts": ["Performing footsteps for a character walking across a wooden floor.", "Rebuilding footsteps for a scene where production sound is unusable.", "Adding weight to a heavy character's walk by emphasizing the toe strike."]}, "85d99013-d277-4b01-8c66-d1e9b9c8c41f": {"definition": "A sound effect or test signal that glides continuously in pitch or frequency over time, producing a smooth rising or falling tone rather than a fixed note. In sound design it is commonly used as a pitched riser or transition element.", "plain_english": "A tonal sweep is a note that slides smoothly up or down in pitch instead of staying still, a bit like a slide whistle. In film sound it is often used to build tension into a cut or big moment.", "purpose_function": "It creates a sense of motion, rising tension, or release that guides the listener's attention into or out of a scene change or impact.", "practical_application": "An editor drops a tonal sweep before a cut or reveal, tuning its pitch, length, and direction so it lands on the edit and works with the score's key.", "category": "Sound design", "related_terms": ["Riser", "Whoosh", "Trailer hit", "Transient sweetener", "Pitch automation"], "common_mistakes": ["Letting the sweep clash with the musical key of the scene so it sounds out of tune.", "Making the sweep too long or loud so it overwhelms dialogue.", "Mistiming the peak so it doesn't land on the cut or impact."], "scenario_contexts": ["Building tension into a trailer before a title card.", "Smoothing a hard scene cut with a pitched riser.", "Leading into a big reveal or impact."]}, "c4b89614-1211-4e62-b3c7-77f64c7d22b9": {"definition": "In sound for picture, a tonal transition is a scene-to-scene transition built from a pitched or sustained tonal element - such as a drone, held note, riser, or resolving chord - rather than a broadband noise effect, used to smooth or emotionally bridge a picture edit.", "plain_english": "It is a smooth scene change made with a musical, pitched sound like a held note or drone. The tone carries you from one shot to the next instead of a whoosh.", "purpose_function": "It bridges two scenes or sections with harmonically coherent sound, guiding the listener's emotion across the cut and masking an abrupt change in picture or ambience.", "practical_application": "An editor places a rising synth pad or sustained tone under a scene change so the cut feels connected, then automates its level to hand off into the next scene's ambience.", "category": "Transitions & Effects", "related_terms": ["Tonal sweep", "Transitional effect", "Transition parameter", "Trailer hit", "Transient sweetener"], "common_mistakes": ["Confusing a tonal transition (pitched, sustained material) with a noise-based whoosh or riser", "Letting the transition tone clash harmonically with the underscore or the next cue", "Overusing tonal transitions so every scene change sounds the same"], "scenario_contexts": ["Bridging two dialogue scenes with a sustained drone in a documentary", "Using a resolving chord to move from a tense scene into a calm one", "Covering an ambience mismatch between two locations with a held tone"]}, "c4431a31-323d-4836-928b-cc11825bdab5": {"definition": "A short, powerful percussive or synthesized accent, often a deep boom or braaam, used in film trailers and promos to punctuate a cut, title card, or dramatic beat. Also called a hit, impact, or boom.", "plain_english": "A trailer hit is a big, punchy boom sound you hear in movie trailers, usually landing on a hard cut or when the title flashes up. It grabs attention and adds drama.", "purpose_function": "It emphasizes a visual beat and drives momentum, giving trailers their punchy, high-impact rhythm and marking key moments for the audience.", "practical_application": "A trailer editor or sound designer places hits on cuts and title cards, layering low-end boom with a sharp transient, then balancing level so they hit hard without distorting.", "category": "Sound design", "related_terms": ["Impact", "Riser", "Whoosh", "Tonal sweep", "Sub-bass"], "common_mistakes": ["Overusing hits so they lose impact and clutter the mix.", "UNSAFE: reviewing sub-heavy hits at very high monitoring levels risks hearing damage and speaker abuse; keep listening within safe exposure limits (e.g. OSHA 29 CFR 1910.95) and leave headroom.", "Placing hits off the picture cut so they feel disconnected from the image."], "scenario_contexts": ["Cutting a teaser where hits land on each title-card flash.", "Punctuating a montage of quick action shots.", "Marking the logo sting at the end of a trailer."]}, "9e52e7d8-56bc-4253-b14f-d0b171533329": {"definition": "A short added sound layered onto an effect to reinforce its attack, the initial transient, making an impact, footstep, or hit read as sharper, punchier, or more present. It is a specialized use of sweetening, the practice of adding supplementary sounds to enhance an effect.", "plain_english": "A transient sweetener is a tiny extra sound you add to the very start of an effect to give it more snap. It is like adding a click to a punch so it hits harder on screen.", "purpose_function": "It strengthens the attack of a layered sound so the effect cuts through the mix and feels more impactful without changing its body or tail.", "practical_application": "A sound designer layers a short click or crack tight to the attack of a hit or footstep, aligning it sample-accurately and blending its level so it adds punch without sounding separate.", "category": "Sound design", "related_terms": ["Sweetening", "Layering", "Transient", "Trailer hit", "Attack"], "common_mistakes": ["Placing the sweetener slightly off the main attack so it flams or doubles instead of reinforcing.", "Adding too much so the sweetener is heard as its own separate sound.", "Choosing a sweetener with the wrong tone or character so it doesn't match the effect."], "scenario_contexts": ["Giving a punch or kick more crack in an action scene.", "Sharpening a footstep that lacks definition.", "Adding snap to a trailer hit or impact."]}, "030b2df5-7600-4e99-b127-86e79da9b97e": {"definition": "A transition parameter is any adjustable setting that controls how one audio clip or scene gives way to another - for example crossfade length, fade-curve shape, overlap amount, or the timing offset of a transition effect.", "plain_english": "It is a setting that controls how one sound blends into the next. Things like how long a fade lasts or what shape it takes are transition parameters.", "purpose_function": "It gives the editor precise control over the speed, shape, and timing of a transition so edits sound smooth and intentional rather than abrupt or clumsy.", "practical_application": "When crossfading two ambiences, a technician adjusts the transition parameters - fade length and curve - in the DAW until the seam between the clips is inaudible.", "category": "Transitions & Effects", "related_terms": ["Transitional effect", "Tonal transition", "Tonal sweep", "Trailer hit"], "common_mistakes": ["Assuming the default crossfade length works for every edit instead of setting it per transition", "Choosing a linear fade curve where an equal-power curve is needed, causing a level dip", "Adjusting only fade length while ignoring fade-curve shape"], "scenario_contexts": ["Setting crossfade length and curve when joining two room-tone clips", "Adjusting an effect's transition time so a whoosh lands exactly on the picture cut", "Tuning fade parameters to remove a click at an edit point"]}, "b413e050-e674-475f-b5b0-aafd4e3b496e": {"definition": "A designed sound element—commonly a whoosh, riser, swell, or impact—placed at a picture cut or scene change to smooth or emphasize the visual transition and carry the audience from one shot, scene, or segment to the next.", "plain_english": "A sound, like a whoosh, played right when the picture cuts to a new scene. It helps the change feel smooth. Think of a page-turn sound telling you the story has moved on.", "purpose_function": "It bridges edits so scene or segment changes feel intentional and fluid, and it can build energy or signal a shift in time, place, or mood.", "practical_application": "An editor drops a whoosh or riser on the cut between segments in a trailer, promo, or documentary, timing its peak to the exact frame of the visual change.", "category": "Sound Design", "related_terms": ["Sound effect", "Whoosh", "Riser", "Sweetener", "Sound design", "Crossfade"], "common_mistakes": ["Placing the effect's peak off the actual picture cut so it feels disconnected from the edit", "Overusing transitional whooshes until they lose impact and clutter the mix", "Failing to match the effect's tone and length to the pace and genre of the piece"], "scenario_contexts": ["Adding whooshes between shots in a fast-cut promo or trailer", "Bridging chapter or segment changes in a documentary or corporate video", "Marking a flashback or time jump in a scripted scene"]}, "afadec72-f740-4126-a8a9-fbd3004a5c8d": {"definition": "A version of a program's dialogue and narration rendered into a target language, used as the source text for dubbing, voice-over, or subtitle creation during localization.", "plain_english": "The show's spoken words written out in another language. Voice actors and subtitle makers work from it, like a recipe translated so cooks in another country can make the same dish.", "purpose_function": "It gives the dubbing director, voice talent, and subtitlers an accurate, timing-aware text so the localized version matches the original meaning and screen action.", "practical_application": "A localization team receives the translated script and records replacement dialogue or builds subtitle files from it, checking that lines fit the on-screen timing and lip movement.", "category": "Localization", "related_terms": ["Dubbing", "Subtitle", "UN-style voice-over", "Localization", "ADR", "Voice-over"], "common_mistakes": ["Translating word-for-word instead of adapting lines to fit timing and lip sync", "Ignoring on-screen text and context that the translation must account for", "Assuming one translated script serves both dubbing and subtitles without adaptation"], "scenario_contexts": ["Preparing a foreign-language dub of a film for international release", "Creating subtitles for a streaming series in several languages", "Recording a UN-style voice-over for a documentary interview"]}, "66db68d7-cd00-4295-b35f-bef3d6ea05cc": {"definition": "A quality-control step in localization where a qualified reviewer checks that a translated script, dub, or subtitle correctly conveys the meaning, tone, and context of the original before the deliverable is approved.", "plain_english": "A check to make sure the translation really says the same thing as the original. It is like having a second person proofread your work in another language before you hand it in.", "purpose_function": "It catches mistranslations, missing context, and tone errors so the localized version stays faithful to the original and meets client or broadcaster standards.", "practical_application": "Before final delivery, a reviewer compares the translated subtitles or dub against the source, flags errors, and sends corrections back to the translator or dubbing team.", "category": "Localization", "related_terms": ["Translated script", "Quality control", "Subtitle", "Dubbing", "Localization", "Deliverable"], "common_mistakes": ["Reviewing only the words without watching the picture for context and on-screen action", "Skipping the review to save time, letting errors reach final delivery", "Treating personal style preferences as genuine accuracy errors"], "scenario_contexts": ["Signing off subtitles before a streaming platform delivery", "Checking a dubbed episode's script against the original for a broadcaster", "Verifying a translated voice-over for a corporate or training video"]}, "e37cad22-5a7d-4f34-9382-cc2b8b654e75": {"definition": "In immersive sound for picture, a two-dimensional-to-three-dimensional blend is the balance or control that mixes flat, planar (stereo or surround, 2D) content with height-bearing, object-based (3D/immersive) content, letting a source or bed sit anywhere between a horizontal plane and the full three-dimensional sound field.", "plain_english": "It sets how much a sound stays flat around you versus wrapping fully above and around you. You dial between plain stereo-style sound and full 3D sound.", "purpose_function": "It lets mixers move material between legacy 2D formats and immersive 3D formats and control how much height and envelopment a sound has, so one mix can serve both flat and immersive deliverables.", "practical_application": "Preparing a Dolby Atmos deliverable, a mixer blends a 2D music stem with 3D object placement, adjusting how far elements lift off the horizontal plane into the height speakers.", "category": "Immersive & Spatial", "related_terms": ["Virtual-reality audio room", "Object divergence", "Binaural rendering", "Ambisonics"], "common_mistakes": ["Assuming a 2D-to-3D blend is a true upmix - it controls placement and height balance, not added source separation", "Pushing everything into 3D height so the mix loses a solid front image and dialogue anchor", "Forgetting to check the 2D fold-down, so the stereo or surround deliverable sounds wrong"], "scenario_contexts": ["Balancing a stereo music bed against object-based effects in a Dolby Atmos film mix", "Deciding how much ambience lifts into height channels for an immersive trailer", "Creating both a 5.1 and an immersive deliverable from one session"]}, "19e407fd-74b8-4ad1-be65-ff1406655455": {"definition": "A localization technique in which the original speech is kept audible at a low level while a translated voice-over is laid over it, so the audience hears both the source voice and the translation; it is widely used for documentary and news interviews.", "plain_english": "You still hear the first speaker quietly underneath. A new voice reads the translation over the top. It is the style you often hear in TV news interviews with guests from other countries.", "purpose_function": "It preserves the authenticity and identity of the original speaker while making the content understandable to a new-language audience, unlike full dubbing which replaces the voice entirely.", "practical_application": "A post mixer lowers the original interview audio by several dB and rides the translated voice-over on top, usually starting the translation a beat after the original begins.", "category": "Localization", "related_terms": ["Voice-over", "Dubbing", "Translated script", "Localization", "Narration", "Subtitle"], "common_mistakes": ["Muting the original voice completely, which defeats the purpose of the style", "Starting the translation at the exact same instant so the speaker's identity is lost", "Setting the original too loud so the translation is hard to follow"], "scenario_contexts": ["Translating an on-camera interview in a documentary", "Localizing eyewitness testimony in a news package", "Voicing a foreign-language speaker in a corporate or factual program"]}, "b71f193f-5108-44c4-8711-fb04484010b5": {"definition": "A short designed sound that gives audible feedback for an interaction with a device, app, or on-screen interface—such as a button press, notification, error, or menu move—confirming that an action registered.", "plain_english": "The little beep or click a phone or app makes when you tap a button or get a message. It tells your ears the device noticed what you did, like a doorbell confirming someone pressed it.", "purpose_function": "It confirms user actions and signals system state without the user needing to look, which improves usability and accessibility.", "practical_application": "A sound designer creates and edits sets of clicks, chimes, and alerts for an app, game menu, or product, matching each to its interface event and level-matching them to be noticeable but not annoying.", "category": "Sound Design", "related_terms": ["Sound effect", "Notification sound", "Foley", "Sound design", "Game audio", "Sweetener"], "common_mistakes": ["Making UI sounds too loud or harsh so they annoy the user", "Reusing one generic sound for actions that should feel different", "Relying on the sound as the only feedback, ignoring accessibility"], "scenario_contexts": ["Designing button and menu sounds for a mobile app", "Creating alert and notification tones for a product or device", "Adding on-screen interface sounds to a game's menus"]}, "1f050ce8-3eff-4d7b-acba-8fa2293217f2": {"definition": "A metronome guide for scoring to picture whose tempo changes over time according to a tempo map, letting musical beats and downbeats line up with specific picture hit points instead of staying at one fixed tempo.", "plain_english": "A count-in click for musicians that speeds up or slows down on purpose. Its tempo shifts so the music lands exactly on key moments in the film, like a drummer changing pace to match the action.", "purpose_function": "It lets a composer and players hit precise on-screen events—a punch, a door slam, a cut—while staying in time, by mapping tempo changes to those cue points.", "practical_application": "A composer builds a tempo map in a DAW with tempo changes and streamers or punches, then musicians perform to that variable click so downbeats align with the picture.", "category": "Music & Scoring", "related_terms": ["Click track", "Tempo map", "Spotting", "Streamers and punches", "Scoring to picture", "Hit point"], "common_mistakes": ["Confusing a variable click with a fixed-tempo click that never changes", "Placing tempo changes carelessly so hits land off the picture", "Not warning players before a tempo change so they fall out of time"], "scenario_contexts": ["Recording an orchestral film cue that must hit several action beats", "Scoring a scene where the music must slow for an emotional moment", "Syncing a live ensemble to picture on a scoring stage"]}, "fd794144-134b-4d2b-8cfc-34c46be1c855": {"definition": "A category of sound effect covering the noises made by cars, trucks, motorcycles, and other vehicles—engine, tires, doors, brakes, pass-bys—recorded or designed and edited to match on-screen vehicles.", "plain_english": "The sounds a car or other vehicle makes on screen, like the engine, tires, and doors. Editors add or replace them so the vehicle you see matches the vehicle you hear.", "purpose_function": "It gives on-screen vehicles believable, matched sound, supporting realism and storytelling—a roaring engine for a chase, a quiet idle for tension.", "practical_application": "A sound editor cuts recorded engine, tire, and door sounds, or library effects, to picture, syncing starts, stops, gear changes, and pass-bys to the vehicle's action.", "category": "Sound Design", "related_terms": ["Sound effect", "Foley", "Backgrounds", "Hard effects", "Sound library", "Sound design"], "common_mistakes": ["Using an engine sound that does not match the type of vehicle on screen", "Ignoring perspective, so a distant car sounds as loud as a close one", "Forgetting the Doppler pitch shift on fast pass-bys"], "scenario_contexts": ["Cutting engine and tire sounds for a car-chase scene", "Adding a car door and start for a character driving off", "Building traffic backgrounds for a city street scene"]}, "7b43e0ac-cbdf-4281-837c-41491c6a30c8": {"definition": "A virtual-reality audio room is a software-simulated acoustic environment - with modeled room geometry, reflections, and reverberation plus head-tracked 3D source positioning - in which a sound designer auditions, places, and mixes spatial audio for VR or other immersive content.", "plain_english": "It is a pretend room inside software where you place sounds in 3D and hear them as they would sound in VR. You can move your head and the sound moves with the scene.", "purpose_function": "It lets creators design and check how audio will behave inside a head-tracked virtual space before release, so sources sit in the right place and the room's echoes match the visual environment.", "practical_application": "A VR sound designer loads a scene into a virtual-reality audio room, positions ambiences and effects around the listener, and monitors on head-tracked headphones to confirm the mix holds up as the viewer looks around.", "category": "Immersive & Spatial", "related_terms": ["Two-dimensional-to-three-dimensional blend", "Binaural rendering", "Ambisonics", "Head tracking", "Object divergence"], "common_mistakes": ["Mixing only on speakers and skipping head-tracked headphone checks, so the VR experience differs from the mix", "Ignoring the modeled room's reverb so sound does not match the visual space", "Placing sources without checking behind and above the listener"], "scenario_contexts": ["Positioning ambisonic ambience for a 360 video in a virtual room", "Auditioning a VR game scene's audio with head tracking before build", "Matching modeled room reverb to a virtual environment's size and materials"]}, "2838e532-e396-45a9-8bb7-5f0f76153328": {"definition": "A visual reference point in the picture used to align a sound precisely with the image, such as a clapperboard slate mark, a frame-accurate flash frame, or the streamers and punches that count a performer into an ADR or Foley take. It gives the editor and performer an exact frame at which a sound must occur.", "plain_english": "A visual marker that shows the exact moment a sound should line up with the picture. It works like a countdown, so the sound lands on the right frame.", "purpose_function": "It provides a frame-accurate anchor so dialogue, effects, and music stay locked to the picture. Without it, replaced sounds would drift out of sync with the image.", "practical_application": "An editor lays streamers and punches ahead of an ADR line so the actor speaks in exact sync, or uses the clapper mark to line up production sound with the picture.", "category": "Synchronization", "related_terms": ["ADR", "Streamers and punches", "Clapperboard", "Lip sync", "Two-pop", "Sync point"], "common_mistakes": ["Confusing the visual cue with the audible beep countdown often used alongside it", "Ignoring the project frame rate, so cues land on the wrong frame", "Relying on eyeballed sync instead of a precise cue mark"], "scenario_contexts": ["Cueing an actor into an ADR line with streamers and punches", "Lining up a clapper slate to sync dailies", "Placing punch marks for a Foley artist to hit a footstep"]}, "3ff86cbd-5483-40d8-9e39-468d69364b11": {"definition": "A signal-processing technique that analyzes the changing spectral envelope of one sound (the modulator, such as a voice) and imposes it onto a second sound (the carrier, such as a synth) through a bank of matched filters, so the carrier appears to speak or sing. It is used to create robotic, harmonized, and otherworldly vocal effects.", "plain_english": "An effect that stamps the shape of your voice onto another sound, like a synth. It makes the synth seem to talk, giving that classic robot-voice sound.", "purpose_function": "It transfers the tone and syllables of a voice onto a musical or synthetic sound to create expressive or robotic voices. It exists to blend the clarity of speech with the character of another instrument.", "practical_application": "A sound designer routes a spoken line as the modulator and a synth pad as the carrier to build a talking-robot or alien voice for a film or track.", "category": "Voice Processing", "related_terms": ["Carrier signal", "Modulator", "Formant", "Talk box", "Synthesizer", "Sidechain"], "common_mistakes": ["Confusing a vocoder with auto-tune, which corrects pitch instead", "Confusing vocoding with a talk box, which shapes sound acoustically in the mouth", "Feeding a carrier with too few harmonics, so the speech is unintelligible", "Forgetting the carrier must sound continuously for words to come through"], "scenario_contexts": ["Creating a robot voice for a sci-fi character", "Making a synth 'sing' lyrics in a music production", "Designing an alien or computer voice for a game"]}, "a48d2f34-43a7-43d1-91c7-fa049503ac92": {"definition": "The process of selecting and hiring voice performers whose vocal quality, range, and delivery suit a character or narration in animation, dubbing, games, or advertising. It matches a voice to the role's age, personality, and tone.", "plain_english": "Choosing the right voice actor for a character or ad. It is like casting an on-screen actor, but the job is judged by the voice, not the face.", "purpose_function": "It ensures each character or narration is voiced by a performer who fits the role and the project's audience. It exists to make characters believable and consistent across a production.", "practical_application": "A casting director auditions actors, reviews demo reels, and selects voices for an animated series or a dubbed foreign release.", "category": "Dialogue Production", "related_terms": ["Voice-over dialogue", "Dubbing", "Voice matching", "ADR", "Narration", "Demo reel"], "common_mistakes": ["Casting on a single line instead of the character's full emotional range", "Ignoring how the voice will fit lip movements when the work is dubbed", "Assuming a famous voice always suits the role"], "scenario_contexts": ["Selecting voices for characters in an animated feature", "Casting a narrator for a documentary", "Choosing dub actors to match the original cast for a foreign release"]}, "8842538e-eb19-4148-865d-d560a6d87726": {"definition": "Applying a limiter to a voice or dialogue signal to cap peaks at a set ceiling, preventing overloads and holding the loudest moments in check without changing the overall level much. It keeps dialogue from clipping and helps meet delivery loudness and true-peak limits.", "plain_english": "Using a tool that stops a voice from getting too loud. It puts a ceiling on the loudest peaks so the sound never overloads or distorts.", "purpose_function": "It protects against clipping and holds dialogue peaks under broadcast or streaming limits. It exists to keep speech clean and within delivery specs.", "practical_application": "A dialogue mixer places a limiter on the voice bus to catch sudden plosives or shouts before they clip the mix or breach the true-peak spec.", "category": "Dynamics Processing", "related_terms": ["Limiter", "Compression", "True peak", "Loudness (LUFS)", "Dialogue mixing", "Clipping"], "common_mistakes": ["Setting the threshold so low that the voice sounds squashed and lifeless", "Confusing limiting with compression, which acts more gently over a range", "Relying on a limiter instead of setting a sensible recording level", "Ignoring true-peak limiting, so inter-sample peaks still clip on playback"], "scenario_contexts": ["Catching plosive peaks on a narration track", "Keeping dialogue under a broadcast true-peak ceiling", "Taming sudden shouts in a film dialogue mix"]}, "342f667c-fb73-47c6-9af2-cfa7205dce24": {"definition": "The craft of selecting and directing a substitute performer (or processing a voice) so it closely resembles an original actor's voice for replacement dialogue, dubbing, or continuity when the original performer is unavailable. The goal is a seamless match in timbre, accent, and delivery.", "plain_english": "Making one person's voice sound like another actor's voice. It is used when the first actor cannot record, so a new voice blends in without anyone noticing.", "purpose_function": "It keeps a character's voice consistent when the original actor cannot perform the lines. It exists to preserve continuity so audiences do not notice the swap.", "practical_application": "A supervisor casts and coaches a sound-alike to record ADR lines a lead actor could not complete, matching accent, tone, and pace.", "category": "Dialogue", "related_terms": ["ADR", "Voice casting", "Dubbing", "Voice-over dialogue", "Dialogue replacement", "Continuity"], "common_mistakes": ["Matching timbre but ignoring the original's rhythm and accent", "Forgetting to match the room tone and mic sound of the original recording", "Assuming EQ alone can turn one voice into another"], "scenario_contexts": ["Replacing lines for an actor who has become unavailable", "Dubbing a returning character with a new performer", "Completing pickups when a lead cannot attend an ADR session"]}, "9a04efbf-5461-4221-b88d-62fec27a032f": {"definition": "Recorded speech, such as narration or a character's unseen commentary, that is heard over the picture without the speaker's lips being seen on screen. It includes documentary narration, internal monologue, and off-camera storytelling.", "plain_english": "Speech you hear over a scene when you cannot see the person talking. Think of a narrator telling a story, or a character's thoughts spoken out loud.", "purpose_function": "It delivers narration, story information, or inner thoughts without an on-screen speaker. It exists to guide, explain, or add a voice the picture alone cannot show.", "practical_application": "A mixer records and places a narrator's track above the music and effects, keeping it clear and free of sync-sensitive lip timing.", "category": "Dialogue", "related_terms": ["Narration", "Voice casting", "Voice-over translation", "Dialogue", "ADR", "Walla"], "common_mistakes": ["Confusing voice-over with sync dialogue that must match on-screen lips", "Mixing the narration too low to hear under music and effects", "Recording the VO in a room with a tone that clashes with picture scenes"], "scenario_contexts": ["Recording narration for a documentary", "Adding a character's inner monologue over a scene", "Voicing a commercial over on-screen visuals"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"23c75105-a098-40e2-bcbe-35d4afda6103": {"definition": "A form of language transfer in which a translated spoken track is recorded over the original dialogue, which stays faintly audible underneath, rather than fully replacing it as in lip-sync dubbing. It is common for documentaries, news, and interviews in many markets.", "plain_english": "This translates a show by speaking the new language over the original voice. You can still hear the first voice quietly underneath. It is often used for interviews and news.", "purpose_function": "It makes foreign-language content understandable while keeping the original voice audible for authenticity. It exists as a faster, cheaper option than full lip-sync dubbing.", "practical_application": "A mixer lowers the original interview audio and lays the translated read on top, leaving a moment of original voice at the start for authenticity.", "category": "Localization", "related_terms": ["Dubbing", "Subtitling", "Voice-over dialogue", "Localization", "M&E track", "Voice casting"], "common_mistakes": ["Confusing voice-over translation with lip-sync dubbing", "Ducking the original voice so far that it disappears entirely", "Starting the translation over the first words, losing the original's opening"], "scenario_contexts": ["Translating a foreign news interview for broadcast", "Localizing a documentary with a narrator-style read", "Making a foreign reality show understandable without full dubbing"]}, "0c9f0fe2-0aa7-49ec-b214-48193c3239e0": {"definition": "Foley footstep sounds performed and recorded in sync with a character's steps on screen, matched to the surface, footwear, weight, and pace of the movement. They replace or reinforce footstep sounds that are missing or weak in the production track.", "plain_english": "The sound of footsteps added to match a character walking on screen. A Foley artist walks in time with the picture, using the right shoes and floor to make it real.", "purpose_function": "They restore believable, sync-accurate footsteps that the production recording often lacks. They exist to ground characters in the scene and support the sense of space and movement.", "practical_application": "A Foley artist watches the picture and walks on a matching surface, using different shoes and pace to fit each character's steps.", "category": "Foley", "related_terms": ["Foley", "Foley artist", "Sync point", "Sound effects", "Ambience", "Prop foley"], "common_mistakes": ["Using the wrong surface or shoe, so the steps do not match the picture", "Performing the steps out of sync with the character's pace", "Recording the footsteps too loud relative to the scene"], "scenario_contexts": ["Adding footsteps for a character crossing a wooden floor", "Replacing missing footstep sound in a dialogue-only production track", "Matching heavy boots to a soldier marching on gravel"]}, "0683d37d-6c6d-408c-a110-b188dca8d729": {"definition": "Designed or recorded sound effects representing firearms, blades, or other weapons, typically built from layered elements such as the mechanical action, the report or impact, and the tail or reverberation. In post they are edited in sync with the on-screen weapon action.", "plain_english": "The sound made for guns, swords, or other weapons in a film or game. It is usually built from several layered sounds to feel powerful and real.", "purpose_function": "It gives on-screen weapons a convincing, impactful sound that supports the action. It exists because real or production-recorded weapon sounds are often unusable or missing.", "practical_application": "A sound designer layers a mechanical click, a body, and a reverb tail, then syncs each shot to the muzzle flash on screen.", "category": "Sound Design", "related_terms": ["Sound design", "Layering", "Foley", "Sync point", "Sound effects", "Reverb tail"], "common_mistakes": ["Using one flat gunshot for every shot instead of varied takes", "Ignoring the space, so a shot has no matching reverb tail", "Placing the report out of sync with the muzzle flash"], "scenario_contexts": ["Designing gunfire for an action scene", "Adding a sword 'shing' for a fight sequence", "Creating a sci-fi blaster from layered synths and recordings"]}, "0cc78330-bf40-4aa7-9872-c2677fd15652": {"definition": "In sound design, the practice of giving a recorded or synthesized sound a convincing sense of physical mass and force, chiefly by adding low-frequency energy, sub-bass layers, slower attack transients, and low-end resonance so an on-screen object or creature reads as heavy.", "plain_english": "This means making a sound feel big and heavy. Sound designers add deep, low tones under a sound so a thing on screen seems to have real weight, like a huge door or a giant's footstep.", "purpose_function": "It sells the size and mass of on-screen objects or creatures whose recorded sounds are too thin, so the audience feels the impact and believes what they see.", "practical_application": "A designer layers a sub-bass boom or low rumble under a sword swing, punch, or creature step, then shapes the low end with EQ so the hit lands with felt weight in the room.", "category": "Sound Design", "related_terms": ["Sub layer", "Impact design", "Low-frequency effects (LFE)", "Layering", "Sweetening", "Wood impact"], "common_mistakes": ["Adding so much sub-bass that the mix turns muddy and masks dialogue.", "Relying only on low end and forgetting the mid and high crack that gives a hit definition.", "Ignoring bass management limits, so weight that felt good in one room overloads or vanishes on other systems.", "Using the same low-end layer on every object, so nothing feels distinct."], "scenario_contexts": ["Making a CG creature's footsteps feel massive in a fantasy film.", "Beefing up a car-door slam that was recorded too thin.", "Giving a punch or body impact felt force in an action scene."]}, "c781bc04-bb18-4b42-a3f4-16416459877c": {"definition": "A playback method, common in interactive and game audio engines, in which the system randomly selects one sound from a group of variations each time a cue fires, with each variation given a probability weight so more-likely versions play more often than others.", "plain_english": "This is a way to stop a sound from getting boring. The computer keeps a small set of versions of a sound and picks one at random each time, but you can make some versions come up more often than others.", "purpose_function": "It prevents the machine-gun effect of hearing the exact same sample over and over, adding natural variety while still letting the designer favour certain versions.", "practical_application": "In tools like Wwise or FMOD, a designer drops several footstep or gunshot takes into a random container and sets weights so common variants play often and rare ones only now and then.", "category": "Interactive Audio", "related_terms": ["Random container", "Sample variation", "Round-robin", "Middleware", "Footsteps", "Sound library"], "common_mistakes": ["Thinking equal weights and true random are the same, when weighting changes how often each version plays.", "Using too few variations, so repetition is still obvious.", "Setting one weight so high the other versions almost never play, which defeats the point.", "Forgetting to also randomize pitch or volume, so the variants still sound cloned."], "scenario_contexts": ["Randomizing footstep samples so a character's walk never sounds looped.", "Varying gunfire or impact hits in a game so they feel alive.", "Cycling ambient bird or insect calls in a game environment."]}, "432af313-0204-4ca7-a217-dbdb924bad49": {"definition": "A designed sound effect marked by a fast rising-and-falling swish of broadband, filtered noise or air-like tone, used to accent rapid motion, transitions, reveals, and fast camera or object moves.", "plain_english": "A whoosh is that fast swish sound you hear when something flies past or a title zooms onto the screen. Designers often build it from shaped noise or the sound of moving air.", "purpose_function": "It draws the ear to speed and movement, smooths cuts and transitions, and adds energy to moments the picture alone cannot fully sell.", "practical_application": "An editor lays a whoosh on a swinging sword, a fast whip-pan, or a logo sting, often pitch-bending or Doppler-processing noise or recorded air to match the on-screen speed.", "category": "Sound Design", "related_terms": ["Whip-pan", "Transition effect", "Doppler effect", "Riser", "Sweetener", "Wind pass"], "common_mistakes": ["Overusing whooshes so every cut has one, which tires the audience.", "Leaving the whoosh too loud, so it fights dialogue or music.", "Not matching the whoosh timing and direction to the on-screen move.", "Using a stock whoosh that clashes with the scene's tone."], "scenario_contexts": ["Accenting a fast camera move or whip-pan.", "Adding motion to a title or logo animation.", "Emphasizing a fast swing, throw, or punch in an action scene."]}, "b7749c96-d21b-447f-8b81-dea826048eb2": {"definition": "In sound editorial and design, a work pass dedicated solely to the wind element of a scene: building, performing, or editing the layer of moving-air, gust, and breeze sounds separately from dialogue, Foley, and other effects.", "plain_english": "This is when a sound editor focuses on just the wind for a scene. They build or record the moving-air and gust sounds on their own layer, apart from all the other sounds.", "purpose_function": "Handling wind on its own pass lets the team place, shape, and mix gusts precisely, so the weather feels right without covering dialogue or other effects.", "practical_application": "For an outdoor scene, an editor makes a wind pass, laying in steady breeze beds and timed gusts that swell on wide shots and ease back under close dialogue.", "category": "Sound Editorial", "related_terms": ["Ambience", "Backgrounds (BG)", "Layering", "Foley pass", "Whoosh effect", "Sweetening"], "common_mistakes": ["Letting wind cover dialogue instead of easing it under speech.", "Using one static wind loop with no gusts, so it sounds fake and flat.", "Not matching wind level and motion to what the picture shows, such as trees, hair, or dust.", "Building wind so busy that it clashes with music and other effects."], "scenario_contexts": ["Creating weather for an outdoor dialogue scene.", "Adding gusts to a storm or desert sequence.", "Building an eerie wind bed for a tense, empty location."]}, "8200d520-6432-4025-801c-e46fbb8038ba": {"definition": "A Foley or spot sound effect reproducing the sound of a window being shut: typically the slide or swing of the sash, the contact with the frame, and the final thud or rattle of glass and hardware settling.", "plain_english": "This is the sound effect of a window being closed. It usually includes the slide of the window, the bump as it meets the frame, and a small rattle of the glass.", "purpose_function": "It syncs a believable sound to the on-screen action of shutting a window, grounding the moment and supporting continuity and a sense of space.", "practical_application": "A Foley artist performs the move on a matching window prop, or an editor cuts a library window-close effect, timing the frame contact exactly to the picture.", "category": "Foley", "related_terms": ["Foley", "Spot effects", "Window opening", "Window latch", "Props", "Sync"], "common_mistakes": ["Missing sync, so the sound lands before or after the sash actually meets the frame.", "Using a heavy slam when the picture shows a gentle close, or the reverse.", "Forgetting the small glass or latch rattle that makes it read as a window, not a door.", "Ignoring the room's acoustics, so the effect sits outside the scene's space."], "scenario_contexts": ["Covering an actor shutting a window in a drama.", "Sealing off street noise before a quiet interior scene.", "Marking a character closing off from the outside world."]}, "353dc5f7-edf1-49ef-86f2-beee30b9c15f": {"definition": "A Foley or spot sound effect reproducing the operation of a window's fastening mechanism: the click, snap, or metallic clunk of the latch or lock engaging or releasing.", "plain_english": "This is the small click or clunk of a window latch, the catch that locks a window shut. It is the sound of that catch snapping open or closed.", "purpose_function": "It adds a precise mechanical detail that confirms a window is being secured or freed, reinforcing the action and the character's intent.", "practical_application": "A Foley artist works a real latch or a stand-in metal prop to picture, or an editor cuts a library latch click, placing it exactly on the hand movement.", "category": "Foley", "related_terms": ["Foley", "Window opening", "Window closing", "Spot effects", "Props", "Hardware"], "common_mistakes": ["Placing the click off the exact frame of the hand action.", "Using a latch that sounds too large or heavy for the window shown.", "Skipping the latch detail, so the window action feels incomplete.", "Letting the click sit too loud and jump out of the scene."], "scenario_contexts": ["A character locking a window before leaving a room.", "Building tension as someone quietly unlatches a window to sneak in.", "Detailing a period window's hardware in a drama."]}, "1a8bd478-6d68-4e6b-8185-b0a7ac9a80b1": {"definition": "A Foley or spot sound effect reproducing the sound of a window being opened: the release of the latch, the slide or swing of the sash, frame friction, and any squeak or glass movement.", "plain_english": "This is the sound effect of a window being opened. It can include the latch letting go, the window sliding or swinging up, and a squeak or rattle as it moves.", "purpose_function": "It matches sound to the on-screen act of opening a window and often cues a change in space, such as outside air, noise, or light entering.", "practical_application": "A Foley artist performs the slide and friction on a window prop, or an editor cuts a library effect, then may bring up exterior ambience as the window opens.", "category": "Foley", "related_terms": ["Foley", "Window closing", "Window latch", "Ambience", "Spot effects", "Props"], "common_mistakes": ["Not raising the outside ambience as the window opens, so the space does not change.", "Mismatching a sliding-window sound to a swinging casement window, or the reverse.", "Poor sync between the squeak or slide and the picture.", "Overplaying the squeak, so it distracts from the scene."], "scenario_contexts": ["A character opening a window to let in air or listen outside.", "Revealing street or nature sounds as a window opens.", "Building suspense as someone slowly opens a window to escape or intrude."]}, "2b169d2f-099f-4087-815e-d5236adab63d": {"definition": "A hard sound effect of wood striking another surface: a sharp, resonant knock, crack, or thud whose tone depends on the wood's size, density, and hollowness, used for hits, collisions, and breaks.", "plain_english": "This is the sound of wood hitting something, a knock, crack, or thud. How it sounds depends on how big, hard, or hollow the wood is.", "purpose_function": "It gives on-screen wooden collisions, blows, and breaks a believable, weighty hit, and is often layered to build bigger crashes and destruction.", "practical_application": "A designer or Foley artist records or cuts wood knocks and cracks, then may layer and pitch them under a fight hit, a falling crate, or a splintering door.", "category": "Sound Effects", "related_terms": ["Hard effects", "Impact design", "Weight simulation", "Layering", "Foley", "Crash"], "common_mistakes": ["Using a hollow, light knock where the picture shows heavy, solid timber.", "Forgetting to layer low end when a big, weighty impact is needed.", "Reusing the same wood hit repeatedly, so it sounds fake.", "Sync drift between the visible contact and the hit."], "scenario_contexts": ["A fist or body hitting a wooden door or table in a fight.", "A wooden crate or piece of furniture falling and landing.", "Building a splintering, breaking-wood effect for destruction."]}, "5a97ecda-095c-450a-a1cc-ca29b6fc9bee": {"definition": "Foley footsteps performed or edited to match a character walking on a wood floor: the firm, slightly resonant, sometimes creaky footfalls whose tone reflects solid or hollow boards underfoot.", "plain_english": "These are footstep sounds made to match someone walking on a wooden floor. They sound firm and a little hollow, and sometimes the boards creak.", "purpose_function": "They match a character's movement to the wood surface shown on screen, keeping footsteps in sync and grounding the character in a believable space.", "practical_application": "A Foley artist walks on a wood surface in the studio, matching each step to the actor's weight and shoes, or an editor cuts wood-floor footstep library takes to picture.", "category": "Foley", "related_terms": ["Foley", "Footsteps", "Surfaces", "Wood impact", "Sync", "Heel-toe"], "common_mistakes": ["Steps that drift out of sync with the actor's feet.", "Using a hard shoe sound when the character is barefoot or in soft shoes.", "Matching a hollow, boomy floor to a shot that shows solid ground, or the reverse.", "Even, robotic steps that ignore the actor's real weight and rhythm."], "scenario_contexts": ["Covering an actor walking across a wooden room in a drama.", "Adding creaky steps to build tension in a quiet house.", "Matching footstep tone to a period wooden interior."]}, "6116fafa-872e-4e56-a7f7-3706c7d2f202": {"definition": "The practice of capturing real-world sounds on location with portable recording equipment so they can be used as sound effects in film, television, games, and other media. It covers specific effects such as vehicles, doors, footsteps, and weather, as well as backgrounds and ambiences gathered away from the studio.", "plain_english": "It means going out to record real sounds where they happen, like traffic, rain, or a slamming door. A sound person captures them on a portable recorder so editors can add them to a film or game later.", "purpose_function": "It builds a library of authentic, high-quality sounds that are hard to fake in a studio, giving sound editors and designers real material to enhance or replace the audio heard on screen.", "practical_application": "A recordist brings a portable recorder with a shotgun or stereo microphone to a location, captures several clean takes of each sound away from unwanted noise, monitors on headphones, and logs metadata so the files can be found and edited in post.", "category": "Field Recording", "related_terms": ["Wild sound", "Room tone", "Ambience", "Foley", "Shotgun microphone", "Sound library"], "common_mistakes": ["Recording only one short take instead of several long, usable takes of each sound.", "Skipping metadata (location, mic, notes), which makes sounds hard to find and edit later.", "Letting wind, handling noise, or distant traffic ruin takes by not using a windscreen or not monitoring on headphones.", "Setting record levels too hot and clipping, which cannot be repaired afterward."], "scenario_contexts": ["A sound recordist spends a day capturing city ambiences and passing vehicles to build a stock library.", "A game audio designer records door slams, gravel footsteps, and metal impacts on location for a sound-effects library.", "A documentary team records regional wildlife and weather to layer under edited scenes in post-production."]}, "418079a9-4dd6-4cc2-a93c-4ff32dd12f18": {"definition": "A mixing space set up around near-field monitors, small loudspeakers placed close to the engineer (typically about 1 to 1.5 m, forming an equilateral triangle with the head) so the direct sound dominates and the effect of room reflections and acoustics is reduced.", "plain_english": "It is a mixing room where the speakers sit close to you, about an arm's reach away. Because you hear the speakers directly, the room's echoes matter less, so a good mix should still sound right on other systems.", "purpose_function": "Placing the monitors close lets the engineer hear mostly the direct sound from the speakers rather than the room, giving a more consistent, portable reference for judging balance, tone, and level.", "practical_application": "An engineer sets two near-field monitors an equal distance from each ear at ear height, angles them inward toward the listening spot, and mixes at moderate levels to make decisions that carry over to other playback systems.", "category": "Monitoring", "related_terms": ["Near-field monitor", "Control room", "Monitor placement", "Room acoustics", "Reference monitor", "Far-field monitor"], "common_mistakes": ["Sitting too close or too far so the monitors are not an equal distance from each ear, smearing the stereo image.", "Assuming near-field placement removes any need for room treatment, when early reflections off the desk and walls still color the sound.", "Judging tone at very high levels, which tires the ears and skews decisions.", "UNSAFE: Prolonged mixing at high monitoring levels can cause permanent hearing damage; keep levels moderate and take regular breaks."], "scenario_contexts": ["A project studio uses near-field monitors on stands behind the console to mix in a room that is only lightly treated.", "A mixing engineer checks a mix on near-fields for balance before referencing it on headphones and consumer speakers.", "A mobile recording rig relies on near-field monitors in an untreated location room to make monitoring decisions on set."]}, "92e09153-e833-4598-883e-3fc0c3619d5b": {"definition": "A re-recording stage is a large, acoustically calibrated mixing theater used in film and television post-production, where re-recording mixers combine the edited dialogue, music, and sound-effects stems into the final soundtrack. It is tuned to a standardized monitoring reference so the finished mix translates predictably to the target venue such as a cinema.", "plain_english": "A re-recording stage is a room built like a small movie theater. It is where the final movie sound gets mixed. Engineers blend the talking, the music, and the sound effects into one soundtrack there. The room is set up so the mix will sound right in a real cinema.", "purpose_function": "It provides a calibrated, venue-representative listening space so the final blend of dialogue, music, and effects can be judged accurately. This lets the mix translate reliably to cinemas or broadcast playback instead of sounding correct only in one room.", "practical_application": "A re-recording mixer works at the console on the stage, riding levels and balancing the premixed stems while the picture plays, to deliver the approved final mix. The same room is used to produce the separate stem and print-master deliverables the distributor requires.", "category": "Post-Production", "related_terms": ["Final mix", "Stems", "Re-recording mixer", "Dialogue premix", "Foley", "Dubbing"], "common_mistakes": ["Thinking 're-recording' means performing or recording material again; it actually means combining and mixing already-recorded elements.", "Confusing the re-recording stage with a tracking studio; it is a calibrated mixing theater, not a room for recording live performances.", "Assuming any control room qualifies, when a true re-recording stage is calibrated to a monitoring standard and sized to represent the final playback venue."], "scenario_contexts": ["Mixing a feature film by combining the dialogue, music, and effects stems into the final soundtrack on the dubbing stage.", "Balancing a television episode to its target loudness in a calibrated re-recording theater before delivery.", "Checking how the mix translates from the large-room stage monitors to smaller playback before signing off on the final master."]}, "05478a31-f321-4808-b96f-344f3a9f470e": {"definition": "A searchable index or database that records every archived session and media asset along with its metadata and physical or logical storage location, so items can be found and retrieved without reading the archive media itself.", "plain_english": "It is like a library card catalog for your saved projects. Instead of digging through every tape or drive, you look up a project in the list. It tells you exactly where that project is kept.", "purpose_function": "It lets a facility find and pull any archived project fast, and track what exists across many storage media without mounting each one.", "practical_application": "An engineer searches the catalog by client, date, or title to find which tape or drive holds an old session before pulling it for a recall.", "category": "Archiving & Backup", "related_terms": ["Cold storage archive", "Archive migration plan", "Backup verification", "Cloud replication", "Automatic session backup"], "common_mistakes": ["Treating the catalog as a backup itself, when it is only an index that points to where the real data lives.", "Letting the catalog fall out of date so it lists media that were moved, relabeled, or destroyed.", "Recording too little metadata, so entries cannot be found later by any useful search."], "scenario_contexts": ["A post house looking up which archive tape holds a two-year-old mix for a client re-edit.", "Auditing a tape library to confirm every catalog entry still matches a real, readable volume.", "Handing a project archive to a new facility using the catalog as the inventory list."]}, "7b8290c2-329f-4a53-852f-feb3cd8b9908": {"definition": "A documented strategy for moving archived audio data from aging storage media or file formats onto current ones before the old media or formats become unreadable or unsupported.", "plain_english": "It is a written plan for copying old saved projects onto newer storage before the old tapes or discs wear out. Storage formats go out of date, so you move the files while you can still read them.", "purpose_function": "It protects long-term archives from loss caused by media decay and format obsolescence by scheduling regular, verified transfers to fresh media.", "practical_application": "A facility on a set cycle uses the plan to copy an older tape generation onto the newest one, verifying each transfer before retiring the old tapes.", "category": "Archiving & Backup", "related_terms": ["Archive catalog", "Cold storage archive", "Backup verification", "Cloud replication", "Automatic session backup"], "common_mistakes": ["Assuming a tape or drive will stay readable forever and skipping planned migration.", "Migrating files but not verifying them, so silent copy errors ruin the new archive.", "Forgetting to migrate the software or format needed to open the sessions, not just the raw files."], "scenario_contexts": ["Moving a whole tape library to a new LTO generation as the old drives reach end of life.", "Converting sessions from a discontinued DAW format to a current interchange format like AAF.", "Planning a shift from local tape to a cloud archive over several months."]}, "ce43e4d3-a5cf-47fc-b56e-656127c6839e": {"definition": "A DAW feature that periodically saves timestamped backup copies of the current session file without user action, so recent work can be recovered after a crash, power loss, or file corruption.", "plain_english": "It is a setting that saves spare copies of your project on its own every few minutes. If the program crashes, you can open a recent copy instead of losing your work.", "purpose_function": "It guards against losing work between manual saves by keeping a rolling set of recent session snapshots the user can fall back on.", "practical_application": "An engineer enables auto backup in the DAW preferences and, after a crash, opens the newest file from the backups folder to pick up near where they left off.", "category": "Archiving & Backup", "related_terms": ["Backup verification", "Cloud replication", "Archive catalog", "Bounce / Export", "Cold storage archive"], "common_mistakes": ["Confusing automatic session backups with a real archive; they usually cover only the session file, not all the media.", "Storing backups on the same drive as the session, so one drive failure loses both.", "Setting the backup interval too long, losing many minutes of work between saves."], "scenario_contexts": ["Recovering a session after the DAW crashes mid-mix.", "Rolling back to an earlier snapshot after an edit went wrong.", "Setting a short backup interval before a long, unattended tracking session."]}, "c8e0df68-ed2c-4371-9983-c9b2790e7c1a": {"definition": "The process of confirming that a backup is complete, uncorrupted, and actually restorable, typically by comparing checksums against the source or by performing a test restore.", "plain_english": "It means checking that a backup really worked and can be opened again. A copy that looks fine but is broken is useless, so you test it before you trust it.", "purpose_function": "It ensures a backup can be relied on in an emergency, catching silent copy errors or bad media before the original is ever needed.", "practical_application": "After archiving a project to tape, a technician runs a checksum compare or test-restores a few files to confirm the copy matches the source before deleting the originals.", "category": "Archiving & Backup", "related_terms": ["Automatic session backup", "Cold storage archive", "Archive catalog", "Cloud replication", "Archive migration plan"], "common_mistakes": ["Assuming a backup is good just because the copy finished without an error message.", "Deleting the only original before confirming the backup can actually be restored.", "Never test-restoring, so a corrupt or unreadable backup is only discovered when it is too late."], "scenario_contexts": ["Comparing checksums after copying a session to an archive drive.", "Test-restoring a random file from last night's backup during a monthly integrity check.", "Confirming a cloud upload finished intact before clearing local storage."]}, "31eac4da-a479-4aec-9a3c-6b98dd828ba7": {"definition": "The process of rendering some or all tracks of a DAW session, with their processing and automation applied, into one or more new audio files such as a stereo mix or individual stems.", "plain_english": "It means turning your multi-track project into a finished audio file you can share or play anywhere. The computer plays the mix and records it into a single file like a WAV or MP3.", "purpose_function": "It converts an editable session into deliverable audio files for distribution, mastering, or transfer between systems.", "practical_application": "At the end of a mix, an engineer bounces a stereo master and a set of stems, choosing the file format, bit depth, and sample rate the next stage needs.", "category": "File Operations", "related_terms": ["Stems", "Sample rate", "Bit depth", "Dithering", "Automatic session backup"], "common_mistakes": ["Bouncing with the wrong sample rate or bit depth for the delivery target.", "Leaving a solo, mute, or bypassed plugin engaged, so the bounce does not match the intended mix.", "Clipping the master output during the bounce and not noticing until later.", "Exporting a lossy MP3 as the archive master instead of a lossless file."], "scenario_contexts": ["Rendering a stereo master to send to a mastering engineer.", "Exporting individual stems for a live backing-track rig.", "Bouncing a rough mix to MP3 for a client to review on their phone."]}, "bef9894e-c47a-4c7e-a5a3-ce86800cbad6": {"definition": "An operating mode in which a device or monitoring system produces or passes a known reference signal so that levels and gain can be aligned to a defined standard, such as setting monitor gain so a reference tone reads a target sound-pressure level.", "plain_english": "It is a special mode that plays a steady test signal so you can line up your levels to a set standard. It is like using a tuning fork so everything is matched to the same reference point.", "purpose_function": "It gives a repeatable reference so meters, monitor levels, and signal chains can be matched to a defined standard across rooms and sessions.", "practical_application": "An engineer switches a monitor controller into calibration mode, plays reference pink noise at a set level, and adjusts monitor gain until an SPL meter reads the target for the room.", "category": "Monitoring & Calibration", "related_terms": ["Reference level", "Pink noise", "SPL", "Monitor controller", "Bounce / Export"], "common_mistakes": ["Confusing the calibration reference level with normal listening level and forgetting to leave calibration mode.", "Measuring SPL with the wrong meter weighting or response setting, giving a false calibration.", "Calibrating the two monitors unevenly, so left and right levels do not match."], "scenario_contexts": ["Calibrating a mix room's monitors to a standard SPL for a known signal level.", "Aligning meters and monitoring before a film re-recording session.", "Matching monitor levels between two studios so mixes translate."]}, "bec87957-6a9d-4468-b1ff-c079f7c79f44": {"definition": "A MIDI channel-voice message that transmits a single pressure value representing how hard keys are pressed after the initial note-on, applied uniformly to all notes sounding on that channel; also called channel pressure.", "plain_english": "It is a MIDI message that senses how hard you press the keys after you have already played them. Pressing harder can add things like vibrato, but the same amount goes to every note you are holding.", "purpose_function": "It lets a player add expression to held notes in real time; unlike polyphonic aftertouch it sends one value for the whole channel, which is simpler and uses less data.", "practical_application": "A keyboardist assigns channel aftertouch in the DAW to control filter cutoff or vibrato depth on a synth, adding movement by leaning into held chords.", "category": "MIDI", "related_terms": ["Polyphonic aftertouch", "MIDI CC", "Note-on velocity", "Pitch bend", "Modulation wheel"], "common_mistakes": ["Confusing channel aftertouch, which is one value for the whole channel, with polyphonic aftertouch, which is per note.", "Recording heavy aftertouch data that clogs the MIDI stream or triggers unwanted modulation.", "Assuming every keyboard sends aftertouch, when many budget controllers do not."], "scenario_contexts": ["Mapping aftertouch to vibrato on a synth pad while playing sustained chords.", "Filtering or thinning aftertouch data in a MIDI editor to clean up a performance.", "Troubleshooting why a controller's key pressure has no effect on a soft synth."]}, "dd17c832-2569-43a5-8d02-ed777251bf51": {"definition": "The practice of copying session and media data to remote cloud storage, often keeping multiple synchronized copies across data centers, to provide off-site redundancy and geographic protection against local failure or disaster.", "plain_english": "It means keeping copies of your projects on internet storage, not just on drives in your building. If a fire or theft hits the studio, the work still exists somewhere far away.", "purpose_function": "It protects data against site-level loss and enables access or collaboration from multiple locations by maintaining off-site copies.", "practical_application": "A studio configures automatic sync so each day's session folders replicate to a cloud service, giving an off-site copy in case the local drives fail.", "category": "Archiving & Backup", "related_terms": ["Automatic session backup", "Cold storage archive", "Backup verification", "Archive catalog", "Archive migration plan"], "common_mistakes": ["Treating a live sync as a backup, when a deletion or corruption can replicate to the cloud too.", "Assuming files are safe before the upload has actually finished and been verified.", "Ignoring upload time and bandwidth limits when replicating large multitrack sessions."], "scenario_contexts": ["Setting nightly off-site replication of active projects for disaster recovery.", "Sharing a replicated project folder between two studios in different cities.", "Restoring a session from the cloud after a local drive failure."]}, "4b484597-0978-44c2-875b-4823ad0a9b04": {"definition": "A long-term archive kept on offline or rarely-accessed, low-cost media such as LTO tape or a cold cloud tier, used for data that must be retained but is seldom retrieved and can tolerate slow access.", "plain_english": "It is long-term storage for projects you rarely need but must keep. It is cheap and safe but slow to reach, like putting boxes in a storage unit across town instead of your closet.", "purpose_function": "It preserves finished projects affordably and durably for the long term, trading fast access for lower cost and stable, offline media.", "practical_application": "After a project is delivered and signed off, an engineer writes it to LTO tape for cold storage and logs it in the archive catalog for future recall.", "category": "Archiving & Backup", "related_terms": ["Archive catalog", "Archive migration plan", "Cloud replication", "Backup verification", "Automatic session backup"], "common_mistakes": ["Expecting instant access from cold storage, when retrieval can take hours or require loading media.", "Keeping only one cold copy with no verification or migration plan as the media age.", "Confusing a cold archive with an active backup used for day-to-day recovery."], "scenario_contexts": ["Writing a delivered album project to LTO tape for permanent retention.", "Moving completed projects off fast working drives to free space.", "Retrieving a years-old session from tape for a reissue or remix."]}, "5047ed1c-6712-4e1c-a187-9b560614a6a9": {"definition": "MIDI Control Change messages that carry continuously variable control values (0-127) on any of 128 controller numbers, used to transmit and automate performance parameters such as modulation, expression, volume, pan, and pedal position rather than note events.", "plain_english": "This is a stream of MIDI messages that carry changing control values. A good example is how far you push a mod wheel or press a pedal. It tells an instrument or plug-in to change things like volume or tone over time. It does not play a note by itself.", "purpose_function": "It lets expressive, changing controls such as volume, pan, modulation, and pedal position be recorded, edited, and played back with the notes, so MIDI performances can move and breathe rather than stay static.", "practical_application": "A technician captures continuous controller data from a keyboard's wheels, faders, or pedals, then edits it as automation lanes or breakpoints in the DAW to fine-tune a MIDI part.", "category": "MIDI Data", "related_terms": ["MIDI", "Automation", "Modulation wheel", "Pitch bend", "Control surface", "Program change"], "common_mistakes": ["Confusing continuous controller data with note data; CC messages shape parameters, they do not trigger notes.", "Assuming a controller number means the same thing on every synth; only some numbers are standardized.", "Recording overly dense CC streams that clog the MIDI track and are hard to edit.", "Treating the sustain pedal (CC64) as a smooth continuous control when many devices read it as simple on/off."], "scenario_contexts": ["Recording mod-wheel movement to add vibrato to a virtual string patch.", "Drawing a volume (CC7) or expression (CC11) curve in the piano roll to shape a MIDI horn line.", "Mapping a control-surface fader to a synth filter cutoff and capturing the sweep as CC data."]}, "ad82bb78-5611-4c34-94d0-f27e6f0eae8b": {"definition": "A DAW transport feature that sounds a set number of metronome clicks, typically one or two bars, before recording or playback begins, establishing tempo and the starting point for the performer.", "plain_english": "A count-in plays a few metronome clicks before recording starts. It works like a drummer counting '1, 2, 3, 4' before a song. Those clicks give you the tempo so you come in on time.", "purpose_function": "It gives the performer the tempo and the downbeat before recording reaches the start point, so takes begin cleanly and stay locked to the grid.", "practical_application": "An engineer sets a one- or two-bar count-in before each take so the artist can hear the click and enter in time.", "category": "Transport", "related_terms": ["Metronome", "Click track", "Tempo", "Pre-roll", "Punch-in", "Transport"], "common_mistakes": ["Turning the count-in off and starting a take before the performer is ready.", "Confusing count-in with pre-roll; a count-in adds clicks before bar one, while pre-roll plays existing audio before the punch point.", "Setting a count-in so short that the player cannot lock to the tempo."], "scenario_contexts": ["Giving a vocalist two bars of clicks before the punch so they enter in time.", "Setting a one-bar count-in for a drummer tracking to a click.", "Using a count-off in the studio so the whole band starts together on the downbeat."]}, "d2a2079d-7c70-42e1-ab8f-be7ebe866274": {"definition": "A DAW transport mode that continuously repeats playback or recording of a defined region between two locator points; called Cycle in Logic Pro and Cubase and Loop in many other DAWs.", "plain_english": "Cycle mode makes the DAW loop the same section over and over. You set a start and end point, and playback keeps repeating between them. It is handy for practicing a part or recording many takes of one spot.", "purpose_function": "It repeats a chosen section automatically so an engineer can rehearse, audition, comp, or record repeated takes of one passage without resetting the transport each time.", "practical_application": "An engineer sets locators around a chorus and enables Cycle to loop it for comping takes or to keep playback repeating while tweaking a mix.", "category": "Transport", "related_terms": ["Loop", "Locators", "Loop recording", "Punch-in", "Transport", "Playback"], "common_mistakes": ["Confusing cycle playback with loop recording; playback just repeats, while loop recording captures a take on each pass.", "Leaving Cycle enabled by accident so the transport never moves past the loop.", "Setting the locator points slightly off the beat, so the loop stutters or drifts."], "scenario_contexts": ["Looping an eight-bar chorus to comp several vocal takes.", "Cycling a tricky guitar passage to rehearse it before recording.", "Setting Cycle over a two-bar drum groove to audition different sounds."]}, "7116419b-fff8-4b45-b3f7-fe1298962d25": {"definition": "The practice of deliberately maintaining more than one copy of data across separate drives, media, or locations so that the failure of any single storage device does not result in loss of the data.", "plain_english": "Data redundancy means keeping more than one copy of your files. If one drive dies, another copy still has your work. It is like keeping a spare key so you are not locked out.", "purpose_function": "It protects against data loss by ensuring more than one copy of critical files exists, so a single drive or media failure does not destroy the only copy.", "practical_application": "A studio mirrors its record drives or keeps duplicate session copies so work can continue if one drive fails.", "category": "Data Management", "related_terms": ["RAID", "Backup", "Differential backup", "Disaster recovery plan", "Data scrubbing", "Archive"], "common_mistakes": ["Thinking redundancy replaces backups; mirrored drives copy deletions and mistakes instantly, so you still need separate backups.", "Assuming a single external drive counts as redundancy; one copy is not redundant.", "Believing RAID protects against fire, theft, or ransomware; it does not replace off-site copies."], "scenario_contexts": ["Mirroring session drives (RAID 1) so a single drive failure does not stop a session.", "Keeping a project on both the working drive and a second drive during a long recording.", "Storing duplicate copies of master files on separate media before archiving."]}, "2656b83f-3f9c-4baf-acac-2c8f586ca52f": {"definition": "A background storage-integrity process that periodically reads stored data, verifies it against checksums or parity, and repairs detected errors from redundant copies to prevent silent corruption (bit rot) from accumulating.", "plain_english": "Data scrubbing is a background check that reads your stored files to catch errors early. When it finds a bad spot, it repairs it using a spare copy. It is like a librarian checking books for damage before pages fall out.", "purpose_function": "It maintains long-term data integrity by periodically reading stored data, detecting corruption or bit rot, and repairing it from redundancy before the damage spreads or a file is needed.", "practical_application": "A studio schedules regular scrubs on its RAID array or NAS so archived sessions stay readable and errors are fixed before a restore is required.", "category": "Data Management", "related_terms": ["Data redundancy", "RAID", "Checksum", "Backup", "Archive", "Disaster recovery plan"], "common_mistakes": ["Confusing storage data scrubbing with audio 'scrubbing' (dragging the playhead to hear audio).", "Assuming scrubbing can fix errors without redundancy; it needs a good copy or parity to repair from.", "Never scheduling scrubs, so silent bit rot goes unnoticed until a file will not open."], "scenario_contexts": ["Scheduling a monthly scrub on a studio RAID array to catch bit rot early.", "A NAS automatically verifying archived sessions against stored checksums.", "Detecting and repairing a corrupted block in a backup before it is needed for a restore."]}, "ef887c03-8ab2-4711-aff5-748662b304d2": {"definition": "A Pro Tools recording mode that writes new audio directly onto the existing audio file, permanently overwriting the previously recorded audio at that location with no undo.", "plain_english": "Destructive Record permanently writes new audio over the old audio in the file. The sound you replace is gone for good, with no undo. It is like taping over a cassette, so the old take is erased.", "purpose_function": "It records directly onto the existing audio file, permanently replacing the previous audio, which saves disk space and avoids creating extra takes or regions.", "practical_application": "An engineer uses Destructive Record to overwrite a section directly in the file when extra takes are not wanted, knowing the old audio cannot be recovered.", "category": "Recording", "related_terms": ["Non-destructive editing", "Punch-in", "DestructivePunch", "Take", "Waveform", "Transport"], "common_mistakes": ["Recording destructively over a take you want to keep; the original audio is permanently overwritten with no undo.", "Assuming Undo will bring back destructively recorded audio; the file on disk is already changed.", "Using Destructive Record when non-destructive recording would keep every take safely."], "scenario_contexts": ["Using Destructive Record to overwrite noise or a bad section directly in the audio file.", "Committing a final take destructively when disk space is tight and extra takes are not wanted.", "Working in legacy sessions that require recording directly onto the existing file."]}, "78e6251b-d681-4eab-b312-2b219f8a434d": {"definition": "A Pro Tools HD recording mode for fast, repeated punch-ins on long-format tracks in which recorded audio destructively replaces the existing audio in the underlying file, without creating new files or regions.", "plain_english": "DestructivePunch lets you drop in and fix parts of a long recording without making new files. When you punch in, the new audio replaces the old audio in place. It suits long sessions where you do not want piles of extra takes.", "purpose_function": "It allows fast, in-place punch recording on long tracks so corrections overwrite the existing audio file rather than spawning many new files and regions, keeping long sessions manageable.", "practical_application": "On a Pro Tools HD system, an engineer primes the tracks and uses DestructivePunch to fix sections of a long continuous recording while keeping one contiguous file.", "category": "Recording", "related_terms": ["Destructive Record", "Punch-in", "QuickPunch", "Pre-roll", "Loop recording", "Transport"], "common_mistakes": ["Confusing DestructivePunch with normal non-destructive punch recording; DestructivePunch overwrites the audio file in place.", "Forgetting that tracks must be prepared or 'primed' before DestructivePunch will engage.", "Punching over a good take, permanently replacing audio you still needed."], "scenario_contexts": ["Tracking a long live concert to picture and punching fixes in place without new files.", "Overdubbing corrections into a long-form recording on a Pro Tools HD system.", "Replacing a flubbed phrase in a continuous take while keeping one contiguous audio file."]}, "336edb18-ae34-4520-8bd5-c094ffa2b28e": {"definition": "A backup method that copies only the data changed since the last full backup; each successive differential grows until the next full backup, and a restore requires the full backup plus the most recent differential.", "plain_english": "A differential backup saves only the files that changed since the last full backup. This makes each backup faster and smaller than copying everything. To restore, you need the full backup plus the newest differential one.", "purpose_function": "It shortens backup time and saves storage by copying only what changed since the last full backup, while still allowing a full restore from just two sets: the full backup and the latest differential.", "practical_application": "A studio schedules periodic full backups with differential backups in between, so daily protection is quick and a restore needs only the full backup plus the newest differential.", "category": "Data Management", "related_terms": ["Full backup", "Incremental backup", "Data redundancy", "Disaster recovery plan", "Archive", "Backup"], "common_mistakes": ["Confusing differential with incremental backups; incremental saves changes since the last backup of any kind, while differential saves changes since the last full backup.", "Deleting the full backup and keeping only differentials; a differential is useless without its full backup.", "Assuming differentials keep shrinking; they grow until the next full backup is made."], "scenario_contexts": ["Running a weekly full backup with nightly differential backups of active sessions.", "Restoring a lost project from the last full backup plus the latest differential.", "Backing up only changed session files to save time and space between full backups."]}, "8b01f9d0-d028-4f71-9828-1e49522a237a": {"definition": "A documented set of procedures for restoring data and resuming operations after a loss event such as drive failure, theft, fire, or flood, typically specifying backups, off-site copies, restore steps, and responsibilities.", "plain_english": "A disaster recovery plan is a written set of steps for getting back to work after data is lost. It covers events like a dead drive, theft, fire, or flood. Having it ready means less panic and faster recovery when trouble hits.", "purpose_function": "It defines in advance how to restore data and resume work after a failure, theft, or disaster, reducing downtime and the risk of permanent loss.", "practical_application": "A facility documents backup locations, restore steps, and responsibilities, then periodically tests a full restore to confirm the plan actually works.", "category": "Data Management", "related_terms": ["Backup", "Data redundancy", "Differential backup", "Data scrubbing", "Archive", "Off-site backup"], "common_mistakes": ["Writing a plan but never testing a restore, so no one knows if the backups actually work.", "Keeping the only recovery copy in the same room as the gear it is meant to protect.", "Assuming RAID or redundancy alone is a recovery plan; a plan also covers people, steps, and off-site copies."], "scenario_contexts": ["Following written steps to restore sessions after a studio drive fails mid-project.", "Recovering client masters from off-site copies after a fire or flood.", "Testing the recovery plan by performing a full restore to spare hardware."]}, "e65cf940-e50d-4c01-8b3c-bafb65df8e45": {"definition": "A Steinberg Cubase/Nuendo transport mode that decouples the project cursor and cycle range from the play/stop state, so the cursor can be repositioned and the left/right locators moved freely while playback keeps running.", "plain_english": "A play mode in Cubase that lets you jump the playback line to a new spot without stopping the music. It is like being able to skip around a song while it keeps playing.", "purpose_function": "It removes the stop-and-restart step from looping and auditioning, so an engineer can move the cursor or resize a loop on the fly and hear the change right away.", "practical_application": "An engineer turns it on to reposition the cursor or resize the cycle range while a track keeps playing, quickly checking edits or comping takes without halting playback.", "category": "Transport & Playback", "related_terms": ["Transport controls", "Cycle / loop playback", "Locators", "Playhead", "Grid / Snap Value"], "common_mistakes": ["Confusing Dynamic Transport with normal transport, then being surprised that the cursor moves without stopping playback", "Assuming it is a Pro Tools or Logic feature; it is specific to Steinberg Cubase and Nuendo", "Leaving it enabled and accidentally repositioning the cursor in the middle of a take"], "scenario_contexts": ["Auditioning several sections of a mix in a row without stopping playback", "Adjusting a loop range on the fly while comping vocal takes", "Jumping quickly between song sections during an editing session in Cubase"]}, "ef65dcb8-6e0e-41df-b4d5-d3ea10aa31d7": {"definition": "A list-style DAW editor that shows each recorded event, such as MIDI notes, controllers, program changes or automation points, as a separate line so the exact numeric properties of any single event, including position, type, pitch, velocity and value, can be inspected and edited.", "plain_english": "A tool that shows every note and control message in your track as a list you can edit. It is like a spreadsheet of everything the music does, with one row per event.", "purpose_function": "It gives precise numeric control over individual events that are hard to grab accurately in a graphical view, such as fixing one note's timing or a single controller value.", "practical_application": "A technician opens it to correct an exact note length, delete a stray controller message, or change one event's velocity that would be fiddly to edit by dragging in the piano roll.", "category": "MIDI Editing", "related_terms": ["Piano roll", "List editor", "MIDI editing", "Velocity", "Quantization"], "common_mistakes": ["Confusing the event editor with the piano roll; both change the same data but in different views", "Editing raw controller numbers without knowing which controller number does what", "Deleting note-off or controller events and leaving stuck notes or hanging values"], "scenario_contexts": ["Fixing the exact start position of a single MIDI note", "Removing a duplicate program-change message from a track", "Checking the precise velocity values of a recorded drum part"]}, "33d8c023-27c9-4fe0-9928-4193195c8bc3": {"definition": "The stream of MIDI Continuous Controller messages a moving expression pedal produces, most commonly Controller 11 (Expression) but often assignable to other controllers, carrying values from 0 to 127 that a DAW records and plays back as controller or automation data.", "plain_english": "The control messages a foot pedal sends as you rock it, usually to change volume or an effect. Your DAW saves this as a moving value from 0 to 127, like a dimmer for sound.", "purpose_function": "It lets a performer shape a sound continuously with the foot, freeing the hands, and gives the DAW a recordable controller stream for expression such as volume swells, wah or effect depth.", "practical_application": "A technician assigns the pedal to the correct controller, records its moves along with a performance, then edits the resulting controller lane to smooth or fix the expression.", "category": "MIDI Data", "related_terms": ["MIDI control change", "Controller lane", "Automation", "Sustain pedal data", "Event editor"], "common_mistakes": ["Assuming every expression pedal sends Controller 11; many are assignable and may default to a different controller", "Confusing an expression pedal, which is a variable controller, with a sustain footswitch, which is on/off", "Recording jumpy data from a mis-calibrated pedal and not smoothing it afterward"], "scenario_contexts": ["Recording volume swells on a synth pad with a foot pedal", "Controlling wah or filter cutoff hands-free during a guitar or keyboard take", "Mapping a pedal to a plug-in parameter and capturing its movement as automation"]}, "0bda4ada-0c9d-4c60-a51f-9d3dfa5b0d53": {"definition": "The practice of streaming recorded audio to a hard disk drive housed outside the computer and connected by an interface such as USB, Thunderbolt or FireWire, keeping the record media separate from the system/boot drive.", "plain_english": "Recording your audio onto a separate hard drive that plugs into your computer, instead of the built-in drive. This gives the recording its own space, so the computer runs more smoothly.", "purpose_function": "It separates audio streaming from the operating-system and application load, which cuts disk contention, supports reliable track counts, and makes a whole project portable between systems.", "practical_application": "An engineer records and plays back sessions from a dedicated external drive, then unplugs it to move the full project to another studio or keep it as a working copy.", "category": "Storage & Media", "related_terms": ["External SSD recording", "Full backup", "Disk streaming", "Buffer size", "Sample rate"], "common_mistakes": ["Recording large sessions to a slow, bus-powered USB drive and hitting audio dropouts", "Using one drive for both the system and audio, overloading the disk on high track counts", "Treating the working external drive as a backup; a working drive is not a backup"], "scenario_contexts": ["Tracking a live multitrack session to a dedicated external drive", "Carrying a project between two studios on one portable drive", "Freeing the internal drive by streaming audio playback from an external disk"]}, "86800d2a-16c3-4905-8efe-73bd089c18c5": {"definition": "Streaming recorded audio to a solid-state drive connected outside the computer, typically over USB 3, USB-C or Thunderbolt, which has no moving parts and offers high sustained transfer rates and low access latency for large track counts.", "plain_english": "Recording your audio onto an external solid-state drive, which has no spinning parts and is very fast. It is like swapping a slow disk for quick flash memory, so many tracks record without stutter.", "purpose_function": "It provides fast, shock-resistant, low-latency storage for recording and playback, supporting higher track counts and denser sessions than a spinning disk while keeping media off the system drive.", "practical_application": "An engineer uses a bus-powered external SSD to track high-channel-count sessions on location, knowing it tolerates movement far better than a hard disk during transport.", "category": "Storage & Media", "related_terms": ["External hard-drive recording", "Full backup", "Disk streaming", "Buffer size", "Track count"], "common_mistakes": ["Assuming any USB enclosure delivers full SSD speed; a slow bridge chip or a USB 2 port throttles it", "Running the SSD nearly full, which can slow sustained write speed during recording", "Trusting a single SSD as the only copy of a session, since flash failure can be sudden; always keep a backup"], "scenario_contexts": ["Recording a large location session onto a rugged bus-powered SSD", "Running a high-track-count mix directly from an external SSD", "Choosing an SSD over a hard drive for reliable playback during a mobile shoot"]}, "7ca5d946-0817-4757-af6b-61407cfe7d73": {"definition": "The process of identifying audio, MIDI or session files whose data has been damaged or altered, for example by incomplete writes, media faults or transfer errors, typically by comparing a stored checksum or hash against a freshly computed one or by a program's own file-validation routines flagging unreadable data.", "plain_english": "Checking whether a saved file has been damaged and can no longer be read correctly. It works like a fingerprint: if the file's fingerprint changes, you know something went wrong.", "purpose_function": "It catches damaged files early, before a corrupt take or session is trusted in a project or archive, so the file can be replaced from a backup while a good copy still exists.", "practical_application": "A technician runs a checksum or a DAW's verify function after copying a session, and if a file fails the check they restore it from another copy instead of opening the bad file.", "category": "Data Integrity & Backup", "related_terms": ["File integrity monitoring", "Checksum", "Full backup", "Session archiving", "Data redundancy"], "common_mistakes": ["Assuming a file that copied without an error message is intact; only a checksum or verify pass proves it", "Detecting corruption but having no backup to restore the file from", "Ignoring early read errors on a drive until more files are lost"], "scenario_contexts": ["Verifying a session after copying it to an archive drive", "Tracking down why one audio file plays back as noise or silence", "Checking delivered files against supplied checksums before a mastering session"]}, "ad3fe46b-d938-4104-a585-06519ca4b5d6": {"definition": "The ongoing checking of stored files over time to confirm they have not changed or degraded, done by periodically recomputing each file's checksum and comparing it to a recorded value (a fixity check), so that silent corruption or accidental modification is detected.", "plain_english": "Regularly re-checking your stored files to make sure they have not changed or gone bad over time. If a file's fingerprint no longer matches, you know it needs restoring from a backup.", "purpose_function": "It catches silent data rot and accidental or unauthorized changes in an archive, so long-term project and master files stay trustworthy across years of storage.", "practical_application": "A technician keeps a checksum manifest of an archived project and re-runs fixity checks on a schedule, restoring any file that fails from a redundant copy.", "category": "Data Integrity & Backup", "related_terms": ["File corruption detection", "Checksum", "Full backup", "Session archiving", "Data redundancy"], "common_mistakes": ["Confusing a one-time copy verification with ongoing monitoring; integrity must be re-checked over time", "Storing the checksum list on the same drive as the files, so one drive failure loses both", "Assuming a single archive copy is safe without periodic checks and a second copy"], "scenario_contexts": ["Maintaining a long-term archive of finished album masters", "Scheduling periodic fixity checks on a studio's project library", "Detecting bit rot on aging backup drives before a restore is needed"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"06a1c11e-1de7-4c7c-9770-9cc87b1e3a1c": {"definition": "A backup that copies the complete set of selected data, all files in a session, project or drive, in a single operation, as opposed to an incremental or differential backup that copies only what has changed since a previous backup.", "plain_english": "A backup that copies everything at once, not just the parts that changed. It is like photocopying a whole notebook instead of only the newest page.", "purpose_function": "It provides one self-contained copy from which everything can be restored, simplifying recovery because no earlier backups are needed to rebuild the data set.", "practical_application": "An engineer makes a full backup of a finished project to an archive drive, so the entire session can be restored later from that single copy.", "category": "Data Integrity & Backup", "related_terms": ["Incremental backup", "External hard-drive recording", "File integrity monitoring", "Session archiving", "Data redundancy"], "common_mistakes": ["Confusing a full backup with an incremental one and assuming a partial copy holds everything", "Keeping the only full backup on a drive stored next to the original, so one accident destroys both", "Never testing a restore, then finding the backup is incomplete or unreadable when it is needed"], "scenario_contexts": ["Archiving a completed album project to two separate drives", "Making a complete copy of a session before a major edit or plug-in change", "Backing up an entire working drive before reformatting or upgrading a system"]}, "bb2209e8-6c43-4f0e-9fe7-7437452490b9": {"definition": "The timing resolution to which edits and moves align in a DAW timeline, such as bars, beats, note divisions like 1/4, 1/8 or 1/16, or absolute units like frames or milliseconds, so that when snapping is enabled events jump to the nearest point on this grid.", "plain_english": "This setting decides where your edits snap to on the timeline. It can be every beat, or every 1/16 note. It works like the lines on ruled paper. Your edits stay lined up instead of landing anywhere.", "purpose_function": "It keeps edits musically and rhythmically aligned, so cutting, moving and looping stay in time with the project tempo without constant manual nudging.", "practical_application": "An engineer sets the snap value to match the task, using a coarse value like 1/4 for arranging blocks, a fine value like 1/16 for detailed edits, or turning it off for free placement.", "category": "Editing", "related_terms": ["Snap", "Quantization", "Tempo / BPM", "Bars and beats", "Event editor"], "common_mistakes": ["Leaving snap on a coarse value and wondering why edits jump away from where they were dropped", "Confusing the grid/snap value with quantize; snap constrains manual edits, while quantize moves recorded notes", "Editing freely played material to the grid until it feels stiff and mechanical"], "scenario_contexts": ["Setting snap to 1/16 to line up a chopped drum loop", "Turning snap off to nudge a clip into a natural-feeling spot", "Using bar snapping to move whole song sections cleanly"]}, "d9afcdf7-7ca6-4371-a106-2e707269229e": {"definition": "The process of analyzing a piece of audio or MIDI to capture its timing and, in some tools, its accent pattern, and saving that information as a reusable groove (quantize) template. That template can then be applied to other tracks so they follow the same feel.", "plain_english": "This means pulling the timing 'feel' out of one part and saving it as a pattern. You can then place that same pattern onto other parts so they all lock together. It is like tracing the beat of a great drum take and using the tracing to line up the rest of the song.", "purpose_function": "It lets an engineer transfer the natural push-and-pull of a good performance onto other material instead of using stiff, robotic grid timing. This keeps a mix feeling human while still tightening how parts line up.", "practical_application": "A technician might extract the groove from a live drum loop and apply it to a programmed bass line so the two sit together. In Cubase, Logic, and Pro Tools this is done by dragging a part to create a groove template and then quantizing other tracks to it.", "category": "Editing & Timing", "related_terms": ["Quantization", "Groove template", "Swing", "MIDI editing", "Elastic Audio", "Transient detection"], "common_mistakes": ["Extracting a groove from audio with poorly placed transient markers, which captures the wrong timing points", "Applying 100% strength so the target follows the template exactly and loses its own feel", "Assuming groove extraction fixes wrong notes; it only affects timing, not pitch or content", "Extracting from a sloppy source take and spreading its timing errors across the whole session"], "scenario_contexts": ["Matching a programmed hi-hat pattern to the feel of a recorded live drummer", "Tightening a doubled guitar part to the groove of the main rhythm track", "Building a custom groove library from a favorite drum break for reuse across projects", "Making quantized MIDI drums feel less mechanical by applying an extracted human groove"]}, "3f7f337f-4d62-4452-90f8-f2691b85d1ed": {"definition": "A transport mode that plays back or records material at half the normal sample-clock or tape speed, dropping pitch by one octave and doubling the apparent duration. It is used to slow fast passages for learning or precise editing, or to record a difficult part slowly so it plays back at correct speed and pitch.", "plain_english": "This slows the audio down to half speed so it is easier to follow. When you slow it down, the sound also drops one octave lower. Musicians slow it down to hear and learn a fast part more easily. Or they record a fast part at half speed so that, played back at full speed, it lands at the right pitch and tempo.", "purpose_function": "It gives an engineer or player a way to handle passages that are too fast to hear clearly or perform cleanly. Slowing the transport makes fine editing and tricky takes far more accurate.", "practical_application": "A technician may set half-speed playback to place edit points inside a rapid drum fill, or record a fast solo at half speed so it lands perfectly when returned to normal speed. On tape machines this used a mechanical speed switch; in a DAW it is a transport or varispeed setting.", "category": "Transport & Recording", "related_terms": ["Varispeed", "Transport controls", "Tape machine", "Sample rate", "Punch recording", "Time stretching"], "common_mistakes": ["Forgetting that half-speed drops recorded pitch an octave, then being surprised by the octave shift at full speed", "Confusing half-speed transport with time stretching, which changes length without changing pitch", "Not checking that plugins and monitoring track the speed change, causing tuning or timing errors", "Assuming half-speed mastering and half-speed practice playback are the same feature"], "scenario_contexts": ["Slowing a rapid passage to identify and edit a single wrong note", "Recording a very fast instrumental line at half speed for a cleaner take", "Learning a complex part by ear at a manageable speed", "Placing precise crossfade or edit points inside dense fast material"]}, "1bf3e8b6-738b-4856-ada4-4905a9e5bb89": {"definition": "Storage devices, drive bays, or enclosures designed to be connected or removed while the host system remains powered on and running, without a shutdown or reboot. This relies on interfaces and controllers that support safe surprise insertion and removal.", "plain_english": "This is a drive you can plug in or pull out while the computer stays on. You do not have to shut down first. It is like changing a battery in a toy that keeps running while you swap it.", "purpose_function": "It keeps a session or system available while media is changed, so recording and playback do not have to stop for a hardware swap. This matters where downtime is costly, such as long sessions or continuous operation.", "practical_application": "A technician might swap a full project drive for an empty one between sessions without powering down the rig, using the operating system's eject or unmount step first. Hot-swap bays are common in RAID enclosures and rackmount recorders.", "category": "Storage & Backup", "related_terms": ["Incremental backup", "Immutable backup", "RAID", "Session archiving", "External drive", "Data redundancy"], "common_mistakes": ["Pulling a drive without first ejecting or unmounting it, which can corrupt open files", "Assuming every USB or drive bay is hot-swappable when the interface or slot is not rated for it", "Removing a drive while the DAW is still writing to it, losing the current take", "Confusing hot-swap capability with data safety; a hot-swap drive still needs a backup"], "scenario_contexts": ["Changing project drives between clients without shutting down the studio computer", "Replacing a failed disk in a hot-swap RAID array while the system stays online", "Rotating removable backup drives on a recorder during a long event", "Handing a client their finished session on a caddy pulled from a hot-swap bay"]}, "53da4cca-a3cf-4bfe-9da8-6ca991f375a5": {"definition": "A backup copy stored so that it cannot be modified, overwritten, or deleted for a defined retention period, typically using write-once-read-many (WORM) storage or object-lock settings. This protects the data against accidental changes, ransomware, and tampering.", "plain_english": "This is a saved copy that no one can change or erase until a set time passes. Once it is written, it is locked. It is like sealing a document in a safe with a timer, so it stays exactly as saved.", "purpose_function": "It guarantees that a known-good copy of a session or archive survives even if the main system is attacked or files are altered by mistake. This gives a reliable point to restore from.", "practical_application": "A studio might push finished project archives to object-locked cloud or WORM storage so a locked master copy cannot be encrypted by ransomware or overwritten. The technician sets a retention period during which deletion is blocked.", "category": "Storage & Backup", "related_terms": ["Incremental backup", "Session archiving", "Data redundancy", "Hot-swappable storage", "Cloud backup", "Version control"], "common_mistakes": ["Treating any offline copy as immutable when it can still be overwritten or deleted", "Setting a retention period too short to be useful for recovery", "Assuming immutability replaces having multiple copies in different locations", "Locking a huge working set immutably and running out of storage before the period ends"], "scenario_contexts": ["Protecting delivered master files against ransomware in a commercial facility", "Archiving legal or contractual session deliverables that must not be altered", "Keeping a tamper-proof copy of raw multitrack recordings for a client", "Meeting a client or label requirement for locked, unchangeable project backups"]}, "20a2f513-7f1e-4392-9e47-1d1165a51b9f": {"definition": "A backup method that copies only the data that has changed since the most recent previous backup (full or incremental), rather than copying everything each time. Restoring requires the last full backup plus every incremental made since it.", "plain_english": "This kind of backup saves only what changed since the last backup. It is faster and uses less space than copying everything again. It is like adding just today's new pages to a folder instead of recopying the whole folder each day.", "purpose_function": "It lets a system back up frequently without the time and storage cost of repeated full copies. This makes regular protection of an active session practical.", "practical_application": "A studio backup tool might run a full backup weekly and short incrementals nightly so each day's edits are captured quickly. To restore, the technician applies the full backup and then each incremental in order.", "category": "Storage & Backup", "related_terms": ["Immutable backup", "Session archiving", "Data redundancy", "Hot-swappable storage", "Cloud backup", "Full backup"], "common_mistakes": ["Losing one incremental in the chain and being unable to fully restore", "Confusing incremental with differential backup, which copies changes since the last full backup", "Relying on incrementals without ever verifying that a restore actually works", "Never taking a fresh full backup, leaving an impractically long incremental chain"], "scenario_contexts": ["Backing up a large session nightly while capturing only the day's changes", "Protecting an ongoing mix project without long full-backup windows", "Keeping storage use low while still backing up often", "Restoring a session to a specific day by applying the full plus that day's incrementals"]}, "252db885-fa67-4a71-a140-7ed5d0747a9f": {"definition": "The assignment of incoming signals, such as audio interface inputs or MIDI ports, to specific tracks, channels, or buses within a DAW or console so they are recorded or processed in the intended place. It defines the path each source takes from input to destination.", "plain_english": "This is choosing which incoming signal goes to which track. It tells the system where each microphone or instrument should land. It is like deciding which mailbox each letter drops into before it is delivered.", "purpose_function": "It ensures each source is captured on the correct track or channel, which is the foundation of an organized multitrack recording. Without correct input routing, sources record to the wrong place or not at all.", "practical_application": "Before tracking a band, a technician assigns interface input 1 to the kick track, input 2 to snare, and so on, then arms those tracks. In a DAW this is set in each track's input selector; on a console it is the channel input patching.", "category": "Signal Flow", "related_terms": ["Signal flow", "Bus routing", "Track arming", "Audio interface", "Patchbay", "Monitoring"], "common_mistakes": ["Assigning two tracks to the same input and missing a source entirely", "Confusing input routing with output routing and monitoring the wrong signal", "Forgetting to arm a track after routing, so nothing records", "Mismatching mono and stereo input assignments, capturing only one side"], "scenario_contexts": ["Setting up a multitrack drum session with each mic on its own track", "Patching a synth's MIDI and audio into the correct DAW tracks", "Reassigning inputs when a source is moved to a different interface channel", "Routing a talkback or reference input to a separate monitoring track"]}, "074900d7-ace9-4b5d-ba7c-182c575462f6": {"definition": "A MIDI editing view that displays events as a scrollable text-and-number list, showing each event's position, type, pitch or controller, value, and length rather than a graphical piano roll. It allows precise numeric inspection and editing of individual MIDI events.", "plain_english": "This shows MIDI notes and controls as a written list instead of a picture. Each line gives one event and its exact numbers. It is like reading a spreadsheet of every note instead of looking at a drawing of them.", "purpose_function": "It lets an editor find and correct exact values that are hard to grab in a graphical view, such as a single stray controller message or an off-position note. This gives fine, precise control over MIDI data.", "practical_application": "A technician uses the list editor to delete a stuck sustain-pedal message or nudge one note to an exact tick position. It appears in DAWs such as Cubase and Logic as an alternative to the piano-roll editor.", "category": "MIDI Editing", "related_terms": ["Piano roll", "MIDI editing", "Quantization", "Control change", "Velocity", "Event"], "common_mistakes": ["Editing a value in the list without noticing it belongs to a different event type", "Overlooking non-note events like controllers or program changes that the list also shows", "Assuming the list editor changes audio; it only affects MIDI data", "Deleting an event by value alone and removing more than intended"], "scenario_contexts": ["Removing a stuck note or hung sustain message from a MIDI part", "Setting a note to an exact bar, beat, and tick position", "Cleaning up unwanted controller data recorded from a keyboard", "Inspecting the precise velocity of individual notes in a phrase"]}, "a8148b08-be34-4b42-87e3-46a391220741": {"definition": "A recording mode in which the transport repeats a defined loop range and captures a new take on each pass, stacking the takes so the best one can be chosen or comped later. Each pass is preserved rather than overwritten.", "plain_english": "This records the same section over and over, saving each pass as a separate take. You can loop a part many times, then pick the best version. It is like doing several tries of one line and keeping all of them to choose from.", "purpose_function": "It lets a performer keep playing a tricky section while the DAW collects multiple takes automatically, without stopping to reset. This makes it easy to gather options for later comping.", "practical_application": "A technician sets a loop around a chorus vocal and enables loop record so the singer runs it several times, then comps the strongest phrases. In Pro Tools and Logic this is a loop or cycle record mode with take management.", "category": "Transport & Recording", "related_terms": ["Comping", "Take", "Punch recording", "Cycle mode", "Track arming", "Playlist"], "common_mistakes": ["Leaving loop record off and overwriting the previous take on each pass", "Not enabling take stacking, so only the last pass is kept", "Setting loop points loosely and cutting off the start or end of the phrase", "Confusing loop record with looping playback, which does not capture takes"], "scenario_contexts": ["Capturing several vocal passes of a chorus for later comping", "Recording repeated attempts at a difficult solo without stopping", "Building a take pool for a short instrumental phrase", "Letting a drummer run a fill several times to pick the best pass"]}, "2a11fb89-4bda-43b2-92e8-6f2f22e62be3": {"definition": "A monitoring approach that minimizes the delay between a performer's input and what they hear, either by routing the input directly through the interface hardware or by using a low-latency path that bypasses or limits latency-inducing plugins. It keeps the audible delay small enough not to disturb performance.", "plain_english": "This keeps the delay between playing and hearing yourself very short. A long delay makes it hard to perform in time, so the signal is sent back almost instantly. It is like hearing your own voice with no echo lagging behind you.", "purpose_function": "It lets a musician perform comfortably in time, because even a small round-trip delay through the computer can throw off timing and feel. Reducing that delay is essential during tracking.", "practical_application": "A technician enables direct hardware monitoring on the audio interface or a low-latency mode in the DAW while a vocalist records, so the singer hears themselves without distracting delay. Buffer size and monitoring path are adjusted to control latency.", "category": "Monitoring", "related_terms": ["Latency", "Buffer size", "Direct monitoring", "Audio interface", "Input Routing", "ASIO"], "common_mistakes": ["Setting the buffer size very large during tracking, which raises monitoring latency", "Using both DAW software monitoring and hardware direct monitoring at once, causing doubling or comb filtering", "Blaming the interface for latency caused by heavy plugins in the monitoring path", "Ignoring that very low buffers can overload the CPU and cause audio dropouts"], "scenario_contexts": ["Tracking a vocalist who needs to hear themselves without distracting delay", "Recording a guitarist through amp-sim plugins while keeping monitoring tight", "Using an interface's direct monitoring for a live overdub", "Balancing buffer size for low latency while tracking versus stability while mixing"]}, "659fa61f-b0a3-444d-942a-c32de54e3197": {"definition": "An LTO (Linear Tape-Open) archive is a long-term backup of session or project data written to Linear Tape-Open magnetic tape cartridges, an open-standard sequential storage format widely used in post-production and broadcast for high-capacity, long-life, low-cost data retention.", "plain_english": "An LTO archive stores finished projects on magnetic tape for the long haul. Tape is cheap and lasts for years, so studios use it to keep old sessions safe after a job is done.", "purpose_function": "It provides durable, high-capacity offline storage so completed sessions can be kept for years at a low cost per terabyte and cleared off expensive working drives.", "practical_application": "An engineer copies a finished session to an LTO cartridge with archiving software, verifies the write, labels the cartridge, and stores it offline as the long-term master backup.", "category": "Storage & Archiving", "related_terms": ["Session backup", "Bounce / Export", "Consolidate media", "Project archive", "Sample rate"], "common_mistakes": ["Assuming a single tape copy is safe, when archives should be verified and ideally duplicated because tapes can fail.", "Forgetting that LTO drives read back only a limited number of generations, so very old tapes can become unreadable.", "Skipping write verification, so a corrupt archive is not discovered until the data is actually needed."], "scenario_contexts": ["Archiving a completed album's session files after final delivery.", "A post house backing up finished film audio to tape for long-term storage.", "Freeing studio drive space by moving old projects onto LTO cartridges."]}, "cdc12441-ae06-4bd4-a838-2dfaa3553afc": {"definition": "A metronome, or click track, is a steady audible pulse generated by the DAW at the session tempo, sounding on each beat and often on subdivisions, to give performers and the editor a consistent timing reference.", "plain_english": "A metronome is a steady beep set to the song's tempo. Musicians play along to it so everything stays in time and lines up neatly.", "purpose_function": "It exists to keep a performance locked to the project tempo and grid, so recorded parts line up with the bars and beats for editing, quantizing, and overdubbing.", "practical_application": "Before tracking, the engineer sets the tempo, enables the click, and sends it to the performer's headphones so the take stays on the grid.", "category": "Timing & Tempo", "related_terms": ["Tempo", "Bar / Beat grid", "Quantize", "Count-in", "Time signature"], "common_mistakes": ["Setting the wrong tempo before recording, so the click fights the performance.", "Letting the click bleed into a recording through the wrong output or open headphones near a mic.", "Expecting a player to catch the tempo without a count-in to set it first."], "scenario_contexts": ["Recording a drummer to a click so the track can be edited to the grid.", "Overdubbing a bass part that must line up with existing tracks.", "Tracking to a fixed tempo so parts can be quantized later."]}, "19eea428-52fc-49e6-9c7f-c05fb8434595": {"definition": "A MIDI articulation map (also called an expression map or articulation set) is a configuration that links a DAW's key-switch or notation commands to the different playing styles of a sampled or virtual instrument, such as legato, staccato, pizzicato, or tremolo, so the correct articulation is triggered during playback.", "plain_english": "An articulation map tells a sampled instrument which playing style to use, like smooth, short, or plucked. It swaps between those styles for you as the music plays.", "purpose_function": "It exists to automate switching between an instrument's many playing styles, letting one MIDI track sound realistic without manually reloading patches or memorizing every key switch.", "practical_application": "A composer assigns articulations in the map so key switches or notation marks automatically call up legato, spiccato, or pizzicato from a large orchestral sample library.", "category": "MIDI Editing", "related_terms": ["Key switch", "Virtual instrument", "MIDI note editing", "MIDI controller lane", "Sample library"], "common_mistakes": ["Building the map for the wrong library, so its key-switch layout does not match and the wrong articulation plays.", "Placing key-switch notes in the audible range, so they sound instead of only switching.", "Assuming articulation maps transfer between DAWs, when each program uses its own format."], "scenario_contexts": ["Scoring strings that move between legato and staccato phrases.", "Setting up a brass library so notation marks trigger the right articulation.", "Building an orchestral template that recalls articulations for a full mockup."]}, "227d44b9-9f4e-4be1-958b-a06e1d9acea7": {"definition": "A MIDI controller lane is an editor sub-track, usually shown beneath the piano roll, that displays and lets you edit continuous controller (CC) data over time, such as modulation (CC1), expression (CC11), sustain (CC64), or pitch bend.", "plain_english": "A controller lane is a strip under the notes where you draw changes like volume swells or vibrato. It shows those moves as a shape you can edit.", "purpose_function": "It exists to let an editor view and shape the continuous MIDI messages that add expression and movement to a part, separately from the notes themselves.", "practical_application": "An editor opens the modulation lane and draws a rising curve to swell a string pad, or fixes sustain-pedal data on a recorded piano in its own lane.", "category": "MIDI Editing", "related_terms": ["Continuous controller (CC)", "MIDI note editing", "Automation lane", "Pitch bend", "MIDI articulation map"], "common_mistakes": ["Confusing MIDI CC lanes with mixer automation, since CC data lives inside the MIDI part, not the track automation.", "Editing the wrong CC number, so the intended parameter never moves.", "Leaving stray or stuck controller values that carry over and affect later notes."], "scenario_contexts": ["Drawing modulation to add vibrato to a synth lead.", "Fixing sustain-pedal data on a recorded piano performance.", "Automating expression on an orchestral instrument for a crescendo."]}, "4b96b6dc-3366-474f-b7b1-fecb7a3f34a3": {"definition": "MIDI editing is the process of viewing and altering recorded or programmed MIDI data, including notes, velocities, timing, and controller messages, within a DAW using tools such as a piano-roll, event list, or score editor.", "plain_english": "MIDI editing means changing the note data after you record it. You can fix wrong notes, adjust timing, or change how hard each note was hit.", "purpose_function": "It exists so a performance captured as MIDI can be corrected and shaped after the fact, because MIDI stores playback instructions rather than fixed audio.", "practical_application": "After recording a keyboard take, the engineer opens the piano roll to fix wrong notes, tighten timing, and adjust velocities before finalizing the part.", "category": "MIDI Editing", "related_terms": ["MIDI note editing", "Quantize", "Velocity", "Piano roll", "MIDI controller lane"], "common_mistakes": ["Over-quantizing until the part sounds stiff and loses its feel.", "Editing the MIDI but forgetting the virtual instrument patch also shapes the final sound.", "Confusing MIDI editing, which changes instructions, with audio editing, which changes a recorded waveform."], "scenario_contexts": ["Cleaning up a programmed drum pattern.", "Correcting a few wrong notes in a recorded synth line.", "Adjusting note timing and velocity so a part grooves."]}, "de7701fd-544b-4fc6-9deb-5815945894dc": {"definition": "MIDI filtering is the selective blocking or passing of specific MIDI message types, such as aftertouch, pitch bend, program change, or particular controllers, at an input, track, or port so unwanted data is not recorded, transmitted, or played back.", "plain_english": "MIDI filtering blocks the kinds of MIDI messages you do not want. For example, you can stop extra data like aftertouch from being recorded.", "purpose_function": "It exists to keep unneeded or problematic MIDI messages out of the data stream, cutting clutter, avoiding conflicts, and saving processing or bandwidth.", "practical_application": "An engineer switches on an input filter to strip aftertouch from a controller that sends it heavily, keeping the recorded part clean.", "category": "MIDI Editing", "related_terms": ["MIDI message", "Aftertouch", "Continuous controller (CC)", "MIDI editing", "Program change"], "common_mistakes": ["Filtering out a message type you actually need, so expression data goes missing.", "Forgetting an input filter is active, then wondering why data will not record.", "Confusing input filtering with deleting data already recorded in the part."], "scenario_contexts": ["Blocking noisy aftertouch from a keyboard that oversends it.", "Stopping program-change messages from switching patches unexpectedly.", "Cleaning a MIDI input so only notes and modulation are recorded."]}, "22bf2c10-9927-436c-bec8-5207cd3e8582": {"definition": "MIDI note editing is the manipulation of individual note events in a MIDI part, changing pitch, start position, length, and velocity, usually in a piano-roll editor.", "plain_english": "MIDI note editing means changing single notes after recording. You can move a note, make it longer, change its pitch, or set how loud it is.", "purpose_function": "It exists to correct and refine a MIDI performance note by note, since each MIDI note is a separate, editable event rather than fixed audio.", "practical_application": "In the piano roll, the engineer drags a flat note up to the right pitch, trims its length, and raises its velocity so it sits in the part.", "category": "MIDI Editing", "related_terms": ["Piano roll", "Velocity", "Quantize", "MIDI editing", "Note length"], "common_mistakes": ["Moving a note's pitch when meaning to move its timing, or the reverse.", "Overlapping notes on the same pitch, causing stuck or cut-off notes.", "Ignoring velocity, so edited notes jump out or disappear in the mix."], "scenario_contexts": ["Fixing a wrong note in a recorded melody.", "Tightening the timing of a programmed bassline.", "Adjusting note lengths so chords ring or stop cleanly."]}, "ffc444b8-01be-4511-b674-f1582571f4b9": {"definition": "MIDI programming is the creation of a musical part by entering MIDI data directly, drawing or step-inputting notes and controllers rather than performing it live, to drive virtual or hardware instruments.", "plain_english": "MIDI programming means building a part by placing notes by hand instead of playing it. You add each note and its details on a grid.", "purpose_function": "It exists so parts can be composed precisely without a live performance, which helps with tight drums, fast passages, or ideas the programmer cannot play in real time.", "practical_application": "A producer step-enters a drum pattern and hi-hat rolls in the piano roll, then tweaks velocities so the programmed beat feels more human.", "category": "MIDI Editing", "related_terms": ["Step input", "Piano roll", "Quantize", "MIDI editing", "Virtual instrument"], "common_mistakes": ["Leaving every note at the same velocity, so the part sounds robotic.", "Programming parts a real instrument could never play, which breaks the illusion.", "Forgetting to set note lengths, so sustained parts sound choppy."], "scenario_contexts": ["Building a drum beat from scratch in the piano roll.", "Programming a fast synth arpeggio too quick to play by hand.", "Laying out a bassline note by note for a demo."]}, "ff62866c-a030-4b3f-8f21-aeb84d2161b2": {"definition": "MIDI randomization is the application of controlled random variation to MIDI parameters such as timing, velocity, or note length, used to loosen mechanically precise data so programmed parts sound more natural, an effect often called humanizing.", "plain_english": "MIDI randomization adds small random changes to things like timing or loudness. It stops programmed parts from sounding too perfect and machine-like.", "purpose_function": "It exists to add back the subtle, natural unevenness of human playing to rigidly quantized or step-programmed MIDI, so parts feel less mechanical.", "practical_application": "After quantizing a drum pattern, the engineer applies a small random offset to velocity and timing so the groove breathes instead of sounding stiff.", "category": "MIDI Editing", "related_terms": ["Humanize", "Quantize", "Velocity", "MIDI editing", "Groove template"], "common_mistakes": ["Applying too much randomization, so timing sounds sloppy instead of natural.", "Randomizing velocity on an instrument with velocity layers, which triggers unwanted sample changes.", "Confusing randomization with quantizing, since one loosens timing and the other tightens it."], "scenario_contexts": ["Humanizing a quantized hi-hat pattern.", "Adding subtle velocity variation to a programmed piano part.", "Loosening a stiff MIDI string section so it sounds more played."]}, "5eecded3-7c1d-4d04-abe8-70f726d9351d": {"definition": "The process of recording, editing, and arranging MIDI event data (notes, controllers, and timing) on a timeline so a sequencer or DAW can play it back through instruments. It captures performance instructions rather than audio, so pitch, timing, velocity, and instrument choice can all be changed after the fact.", "plain_english": "MIDI sequencing records the notes you play as data, not as sound. It is like writing down music the computer can play back on any instrument you pick, and you can fix mistakes later.", "purpose_function": "It lets a player capture a performance as editable data, so timing, pitch, and sounds can be reshaped freely and replayed precisely. It exists because storing performance instructions is far more flexible than recording finished audio.", "practical_application": "A technician records a keyboard part into the DAW's piano roll, quantizes its timing, then assigns a virtual instrument to play it back.", "category": "MIDI", "related_terms": ["MIDI transform", "MIDI transpose", "Modulation-wheel data", "Quantize", "Piano roll", "Virtual instrument"], "common_mistakes": ["Confusing MIDI data with audio; MIDI carries no sound, only instructions for an instrument.", "Forgetting to load or assign an instrument, so the sequenced part plays nothing.", "Over-quantizing until the performance loses its natural feel.", "Assuming velocity and pitch cannot be edited after recording."], "scenario_contexts": ["Building a drum pattern by drawing notes into the piano roll.", "Recording a synth line from a keyboard and quantizing its timing.", "Editing a captured part's velocities to shape its dynamics."]}, "957b3922-d282-4aa8-a19d-edc164dc642c": {"definition": "An editing function in a DAW or sequencer that applies user-defined rules to select and modify MIDI events in batch, changing properties such as pitch, velocity, length, or position. Common implementations include Logic's Transform window and Cubase's Logical Editor.", "plain_english": "MIDI transform changes many notes at once using rules you set. It is like find-and-replace for your notes, so you can reshape a whole part in one step.", "purpose_function": "It automates repetitive or conditional edits across many events, so a technician can reshape data quickly and consistently instead of editing note by note. It exists to speed up and standardize complex MIDI edits.", "practical_application": "An engineer uses a transform to add a fixed amount to the velocity of every note above a chosen pitch, or to convert one controller type into another.", "category": "MIDI", "related_terms": ["MIDI sequencing", "MIDI transpose", "Modulation-wheel data", "Quantize", "Velocity", "Piano roll"], "common_mistakes": ["Applying the transform to the whole track when only a selection was intended.", "Not previewing the rule, so unwanted events get changed.", "Confusing a rule-based batch transform with simple manual editing.", "Forgetting the operation can be undone rather than editing destructively."], "scenario_contexts": ["Scaling all note velocities up by a set amount.", "Converting modulation-wheel data to a different controller number.", "Selecting and shortening every note longer than a set length."]}, "39042842-2545-4085-a545-b53a68ac56a3": {"definition": "A MIDI edit that shifts the pitch of note events up or down by a set number of semitones or octaves, without changing their timing or other data. It can be applied in real time as a playback parameter or written destructively into the recorded events.", "plain_english": "MIDI transpose moves your notes higher or lower in pitch by a set number of steps. It is like using a capo on a guitar, changing the key without replaying the part.", "purpose_function": "It lets a part move to a new key or octave instantly, so material can fit a singer's range or a new arrangement. It exists because changing pitch by data is faster and cleaner than re-performing the part.", "practical_application": "A technician transposes a bass MIDI part down an octave to suit a virtual instrument, or shifts a whole song up two semitones for a vocalist.", "category": "MIDI", "related_terms": ["MIDI sequencing", "MIDI transform", "Modulation-wheel data", "Quantize", "Velocity", "Virtual instrument"], "common_mistakes": ["Transposing so far that notes fall outside an instrument's playable range.", "Confusing MIDI transpose, which changes note data, with audio pitch-shifting, which changes recorded sound.", "Leaving a real-time transpose active and forgetting it when bouncing the mix.", "Transposing by octaves when semitones were meant, or the reverse."], "scenario_contexts": ["Moving a song up a semitone to match a singer's range.", "Dropping a synth bass part down an octave.", "Auditioning a melody in different keys while arranging."]}, "b2c49593-c351-4ff6-939a-abb8e7eb4bf5": {"definition": "A storage drive that receives a real-time duplicate copy of recorded data as it is written to the primary drive, giving redundancy against drive failure during a session. The concept follows disk mirroring (RAID 1), where identical data is written to two drives at the same time.", "plain_english": "A mirror recording drive keeps a second, live copy of everything you record. It is like writing the same notes in two notebooks at once, so if one is lost you still have the other.", "purpose_function": "It protects irreplaceable takes by holding an instant duplicate, so a single drive failure does not lose the recording. It exists because live and studio takes often cannot be re-performed.", "practical_application": "An engineer sets a multitrack recorder or system to write each take to a main drive and a mirror drive, so a failure during a concert does not lose the show.", "category": "Storage & Backup", "related_terms": ["Network-attached storage", "Off-site archive", "Offline archive", "RAID", "Backup", "Session file"], "common_mistakes": ["Assuming a mirror replaces backups; it copies deletions and corruption too.", "UNSAFE: Trusting one mirror as the only safeguard for irreplaceable live recordings with no separate archive.", "Using a slower drive as the mirror and causing recording dropouts.", "Thinking mirroring protects against accidental file deletion, which it does not."], "scenario_contexts": ["Recording a one-off live concert with a redundant mirror drive.", "Tracking an expensive session where a lost take cannot be repeated.", "Field recording where drive reliability is uncertain."]}, "979d9565-2514-4fa8-a4fc-534284942311": {"definition": "MIDI Continuous Controller number 1 (CC1) messages generated by a keyboard's modulation wheel, carrying values from 0 to 127 that an instrument maps to a modulation effect such as vibrato or filter depth. It is a stream of controller events recorded and edited alongside note data.", "plain_english": "Modulation-wheel data is the stream of values sent when you move a keyboard's mod wheel. It usually adds effects like vibrato, and the DAW records it as a line you can redraw.", "purpose_function": "It lets a player add expressive, changing effects to a sound over time, and lets the DAW store and replay those moves. It exists to give MIDI performances continuous, hands-on expression beyond note on and off.", "practical_application": "A technician records mod-wheel moves to add vibrato to a string patch, then redraws the CC1 line in the editor to smooth it.", "category": "MIDI", "related_terms": ["MIDI sequencing", "MIDI transform", "MIDI transpose", "Continuous controller", "Pitch bend", "Virtual instrument"], "common_mistakes": ["Confusing modulation (CC1) with pitch-bend, which is a separate MIDI message.", "Assuming the mod wheel always does vibrato; its effect depends on how the patch maps it.", "Leaving a stray high CC1 value at a part's start, so the sound is over-modulated.", "Forgetting mod-wheel data is editable as controller data after recording."], "scenario_contexts": ["Adding vibrato swells to a sustained synth pad.", "Editing recorded CC1 data to remove an abrupt jump.", "Mapping the mod wheel to filter cutoff on a lead sound."]}, "4d95931c-71b9-479f-baad-b04678483e44": {"definition": "A dedicated file-storage device attached to a network that provides shared storage to multiple clients over standard protocols such as SMB or NFS. In audio work it centralizes session files and media for several workstations, though throughput and latency limits usually make it better suited to backup and file sharing than to streaming an active session drive.", "plain_english": "Network-attached storage, or NAS, is a shared drive box that many computers reach over the network. Think of it as a shared filing cabinet for the studio. It is handy for backups and for moving files between rooms.", "purpose_function": "It gives a team one central, shared place to store and back up sessions and media, reachable from multiple rooms. It exists to centralize storage and simplify collaboration and backup.", "practical_application": "A studio keeps finished sessions and stems on a NAS so any room can pull them, while active recording still runs from a fast local drive.", "category": "Storage & Backup", "related_terms": ["Off-site archive", "Offline archive", "Mirror recording drive", "RAID", "Backup", "Session file"], "common_mistakes": ["Recording an active, high-track-count session directly off a NAS and hitting throughput or latency problems.", "Assuming a NAS with RAID is a backup; redundancy is not a backup.", "Ignoring network bandwidth limits when several rooms access it at once.", "Leaving the only copy of a session on one NAS with no separate archive."], "scenario_contexts": ["Centralizing a facility's session library for shared access.", "Backing up completed projects from several edit rooms.", "Sharing stems between a tracking room and a mix room."]}, "68947af1-0b29-4c4f-8291-3ce35fd7d690": {"definition": "The default, nondestructive recording mode in a DAW (notably Pro Tools) in which each new take is written as a new audio file and clip, so existing recorded material is not overwritten or erased. It contrasts with Destructive, Loop, and QuickPunch record modes.", "plain_english": "Normal record mode is the standard, safe way to record. New takes are saved as new files, so recording again does not erase what you already had.", "purpose_function": "It captures takes without destroying earlier audio, so any take can be recovered from playlists or the file pool. It exists as the safe default, so an accidental re-record does not lose data.", "practical_application": "A technician tracks vocals in Normal mode, records several passes as separate takes, then comps the best parts without any original audio being erased.", "category": "Recording", "related_terms": ["Destructive record", "Loop record", "QuickPunch", "Punch recording", "Playlist", "Take"], "common_mistakes": ["Confusing Normal (nondestructive) mode with Destructive record, which overwrites the file.", "Assuming Normal mode punches or loops automatically; it does neither.", "Recording over a clip and thinking the old audio is gone, when it remains as a file.", "Not realizing accumulated takes keep filling the drive with new files."], "scenario_contexts": ["Tracking multiple vocal takes to comp later.", "Standard overdubbing where earlier audio must be preserved.", "Recording a band's session where every take must be kept."]}, "0a3baf37-825c-4494-8ad0-349bc766ac9c": {"definition": "A stored copy of session data kept at a physically separate location from the studio, protecting against local disasters such as fire, theft, or flood. It is a core part of a 3-2-1 backup strategy: multiple copies, on two media types, with one copy off-site.", "plain_english": "An off-site archive is a copy of your work kept somewhere away from the studio. It is like leaving a spare key at a friend's house, so a fire or theft at the studio cannot destroy everything.", "purpose_function": "It ensures projects survive a disaster that destroys the studio's local copies, so work is not lost with the building. It exists to guard against site-wide risks that on-site backups cannot cover.", "practical_application": "A studio copies finished projects to a drive or cloud service held in another building, following a 3-2-1 backup plan.", "category": "Storage & Backup", "related_terms": ["Offline archive", "Network-attached storage", "Mirror recording drive", "Backup", "Cloud storage", "Session file"], "common_mistakes": ["Keeping every copy in the same room, so one disaster loses them all.", "Confusing off-site (a separate location) with offline (disconnected media).", "Never testing that the off-site copy actually restores.", "Assuming a single off-site copy is enough without verifying it."], "scenario_contexts": ["Storing project backups in a second building or the cloud.", "Protecting a facility's masters against fire or theft.", "Meeting a client's disaster-recovery requirement for deliverables."]}, "c3bd09a1-c3c9-4c87-94ca-f4ed966a0a3a": {"definition": "An archive stored on media disconnected from any computer or network (cold storage), such as LTO tape or shelved hard drives, so it cannot be altered, infected, or deleted while offline. It preserves completed projects long-term at low cost and low risk.", "plain_english": "An offline archive is a copy kept on media that is unplugged and stored away. Nothing can reach it while it is disconnected. Viruses and slips of the mouse cannot delete it, like a book locked in a safe.", "purpose_function": "It preserves finished work safely for the long term and shields it from ransomware, deletion, or drive wear that affects connected storage. It exists for durable, low-risk long-term retention.", "practical_application": "A facility writes completed albums to LTO tape and shelves the cartridges, pulling one back online only when a project must be revisited.", "category": "Storage & Backup", "related_terms": ["Off-site archive", "Network-attached storage", "Mirror recording drive", "Backup", "Session file", "Cloud storage"], "common_mistakes": ["Confusing offline (disconnected media) with off-site (a separate location).", "Leaving the archive drive connected, so it is not truly offline.", "Never verifying the archive can be read back.", "Assuming spinning hard drives last indefinitely without periodic checks."], "scenario_contexts": ["Writing completed projects to LTO tape for cold storage.", "Shelving disconnected drives that hold finished masters.", "Long-term retention of delivered projects for later recall."]}, "bb9dcefd-f4d2-4fe7-8198-bc1ccfbe2d36": {"definition": "The assignment of a track, bus, or channel's signal to a specific destination inside the DAW's mixer, such as a master fader, an auxiliary/subgroup bus, or a physical hardware output of the audio interface. Output routing determines the path each signal follows on its way to the final mix or to external gear.", "plain_english": "Output routing is how you choose where a track's sound goes next, such as the main mix, a group, or a real output jack. Think of it like picking which pipe your water flows into so it ends up in the right place.", "purpose_function": "It lets a signal be directed to the correct summing point or physical outlet so tracks can be grouped, processed together, or sent to headphones, speakers, or outboard gear. Without defined output routing a track has no path to the mix and produces no sound at the outputs.", "practical_application": "An engineer routes several drum tracks to a shared drum bus for group processing, sends a vocal to a master fader, and assigns a monitor mix to specific interface outputs feeding the performer's headphones.", "category": "Signal Routing", "related_terms": ["Input Routing", "Auxiliary send", "Bus", "Master fader", "Subgroup", "Signal flow"], "common_mistakes": ["Leaving a track routed to the wrong bus or to no output, then wondering why it is silent in the mix", "Confusing an output assignment with an auxiliary send, so a signal is duplicated or missing", "Routing multiple tracks into a bus and overloading it into clipping because the summed level was not checked"], "scenario_contexts": ["Grouping backing vocals to one bus so a single compressor treats them together", "Sending a cue mix to interface outputs 3-4 that feed the studio headphone amp", "Routing stems to separate outputs for a live multitrack recording or broadcast feed"]}, "063c1800-80df-4ee8-8a55-0183c6210346": {"definition": "A graphical MIDI editing view that displays notes as horizontal bars on a grid, with pitch shown on the vertical axis (usually beside a piano keyboard) and time on the horizontal axis. Each bar's vertical position sets its pitch, its horizontal position sets its start time, and its length sets its duration.", "plain_english": "The piano-roll editor shows MIDI notes as bars next to a picture of a piano keyboard. Higher bars are higher notes, and longer bars are longer notes, so you can draw and move music with the mouse.", "purpose_function": "It gives a clear visual way to create, move, resize, and fine-tune MIDI notes and their timing without needing to read standard notation. It exists so programmed or recorded MIDI parts can be edited precisely for pitch, timing, and length.", "practical_application": "A producer opens the piano-roll to quantize a sloppy keyboard take, drag a flat note up a semitone, shorten overlapping notes, and adjust velocities before the part triggers a virtual instrument.", "category": "MIDI Editing", "related_terms": ["MIDI", "Velocity", "Quantize", "Pitch-bend lane", "Virtual instrument", "Grid"], "common_mistakes": ["Editing note pitch in the piano-roll but forgetting it only affects MIDI, not already-recorded audio", "Leaving notes overlapping or too long, causing unwanted legato or stuck notes on the instrument", "Assuming the visible grid equals the recorded timing and quantizing away an intended groove"], "scenario_contexts": ["Cleaning up the timing of a recorded MIDI drum pattern", "Drawing a bassline note by note for a synth part", "Fixing one wrong note in an otherwise good keyboard performance"]}, "41f7e84e-4344-4c4c-8c2d-7f6d9a21e899": {"definition": "A dedicated MIDI controller lane, usually shown beneath the piano-roll, used to view and edit Pitch Bend Change messages that raise or lower the pitch of played notes smoothly. Values run from the center (no bend) to a maximum up or down, with the actual pitch range set by the receiving instrument's bend-range setting.", "plain_english": "The pitch-bend lane is a strip under the notes where you draw how much the pitch slides up or down. It works like the pitch wheel on a keyboard, letting a note glide smoothly instead of jumping.", "purpose_function": "It lets an engineer add or edit smooth pitch slides and expressive bends on a MIDI part after recording. It exists to capture and shape the continuous pitch-wheel gesture separately from the notes themselves.", "practical_application": "A technician draws a rising bend at the end of a synth lead in the pitch-bend lane, then resets stray bend data back to center so following notes play in tune.", "category": "MIDI Editing", "related_terms": ["Pitch bend", "MIDI", "Piano-roll editor", "Modulation", "Controller lane", "Virtual instrument"], "common_mistakes": ["Leaving the bend value away from center at the end of a phrase, so later notes sound out of tune", "Expecting a wide bend when the instrument's bend range is set narrow (often only two semitones)", "Confusing pitch-bend data with note pitch, and editing the wrong one"], "scenario_contexts": ["Adding a guitar-style bend to a synth lead line", "Correcting an accidental pitch-wheel nudge from a live take", "Matching a MIDI bass slide to a recorded audio part"]}, "f902b393-d587-47aa-883c-943db0a78ee1": {"definition": "Playback of a set amount of time before (pre-roll) and after (post-roll) a chosen start point, end point, or punch region, so the performer and engineer hear musical context around that spot. The pre-roll and post-roll durations are set in bars or seconds and the transport plays through them without recording over the surrounding material.", "plain_english": "Pre-roll plays a little music before the spot you want to work on, and post-roll plays a little after it. It is like a short run-up and follow-through so a player can get in the groove before recording the fix.", "purpose_function": "It gives performers time to feel the tempo and feel before a punch-in and a natural lead-out after a punch-out, making dropped-in takes tighter. It exists to add musical context around record and edit points instead of starting cold on the beat.", "practical_application": "Before punching in a single guitar phrase, the engineer sets two bars of pre-roll so the player hears the lead-in, and one bar of post-roll so the take ends cleanly.", "category": "Recording", "related_terms": ["Punch in/out", "QuickPunch", "Transport", "Loop recording", "Playhead", "Count-in"], "common_mistakes": ["Setting pre-roll so short the performer cannot lock to the tempo before the punch", "Forgetting post-roll and cutting the take off abruptly at the punch-out", "Confusing pre-roll with a metronome count-in, which is a separate feature"], "scenario_contexts": ["Punching in to fix one line of a vocal without re-singing the whole verse", "Rehearsing a difficult passage in loop mode with lead-in context", "Editing a drop-in on a bass part while keeping the surrounding groove intact"]}, "9db2fae1-a42a-41bc-9027-0f7579f44bee": {"definition": "The disk volume (drive or partition) that a DAW is configured to write new audio files to during recording, as opposed to volumes marked only for playback or transfer. It is the main storage target for a session's captured audio and must have the sustained throughput and free space to handle the track count and sample rate in use.", "plain_english": "The primary recording volume is the main hard drive the DAW saves new audio onto while you record. Think of it as the notebook the program writes in, so it must be fast and have plenty of empty pages.", "purpose_function": "It concentrates recorded audio on a drive fast enough to stream many tracks without dropouts and keeps that traffic off the busy system disk. Designating it lets the DAW know where to place new recordings and manage storage reliably.", "practical_application": "A technician sets a dedicated fast SSD or RAID array as the primary recording volume, confirms it has free space for a long multitrack session, and keeps the operating system on a separate drive.", "category": "Storage", "related_terms": ["RAID 1 storage", "RAID 5 storage", "RAID 10 storage", "Sample rate", "Buffer size", "Disk allocation"], "common_mistakes": ["Recording to the same drive as the operating system, causing disk overload and dropouts on high track counts", "Letting the volume fill up mid-session and stopping recording without warning", "Using a slow or nearly full external drive that cannot sustain the needed data rate"], "scenario_contexts": ["Assigning a session's disk allocation to a fast audio drive before a big tracking day", "Choosing a RAID array as the record target for a large film or album session", "Checking free space and drive speed before a live multitrack capture"]}, "e96d0972-390f-4e2e-89d8-2ec90c5dd716": {"definition": "An Avid Pro Tools record mode that continuously records audio in the background during playback, letting the engineer punch in and out instantly and repeatedly by triggering record while the transport rolls. Because it captures a continuous file, the audio right up to each manual punch point is preserved and can be recovered.", "plain_english": "QuickPunch lets you drop in and out of recording on the fly just by hitting record while the song plays. It quietly records the whole time in the background, so nothing you played is lost even if you punch a moment late.", "purpose_function": "It enables fast, hands-free punch recording so a performer can fix parts on the fly without stopping the transport to arm each punch. It exists to make spontaneous, repeated drop-ins reliable and to safeguard audio around the punch points.", "practical_application": "During a vocal comp, the engineer enables QuickPunch and taps record to drop in on each weak line as the song plays, redoing spots instantly without stopping.", "category": "Recording", "related_terms": ["Punch in/out", "Pre-Roll / Post-Roll (DAW)", "Loop recording", "Transport", "Track arming", "Comping"], "common_mistakes": ["Assuming QuickPunch works identically in every DAW; it is a specific Pro Tools mode and other programs name their equivalents differently", "Not track-arming the intended tracks, so punches record nothing", "Relying on it without enough disk headroom, since continuous background recording uses drive throughput"], "scenario_contexts": ["Fixing several short vocal phrases in one pass during a comp session", "Dropping in on a guitar solo mistake without halting playback", "Fast overdub sessions where the artist wants to punch by feel"]}, "ecc9318f-3c1b-42f0-b657-540575ab3e50": {"definition": "A storage configuration that mirrors identical data across two (or more) drives at the same time, so every drive holds a full copy. If one drive fails the data remains intact on its mirror, giving redundancy but no gain in usable capacity beyond a single drive.", "plain_english": "RAID 1 keeps the exact same data on two drives at once, like writing your notes in two notebooks. If one drive dies, the other still has everything, so you do not lose your work.", "purpose_function": "It protects against a single drive failure by keeping a live duplicate, so recording or editing can continue without data loss. It exists where uptime and data safety matter more than maximum storage space.", "practical_application": "A studio mirrors its active project drive with RAID 1 so a failed disk does not halt a paid session, while still keeping separate off-drive backups.", "category": "Storage", "related_terms": ["RAID 5 storage", "RAID 10 storage", "Primary recording volume", "Backup", "Redundancy", "Data striping"], "common_mistakes": ["Treating RAID 1 as a backup; it protects against drive failure but not deletion, corruption, or theft, so separate backups are still needed", "Expecting more storage space, when usable capacity equals just one drive", "Ignoring a failed mirror and running unprotected until the second drive also fails"], "scenario_contexts": ["Mirroring an active session drive for a critical recording day", "Protecting a small studio server holding current project files", "Keeping an editing workstation running through a single-disk failure"]}, "4dc8d733-aa37-4869-8725-3551d4ec79b2": {"definition": "A nested storage configuration (RAID 1+0) that combines mirroring and striping: data is striped across multiple mirrored pairs, so it spreads reads and writes for speed while each pair keeps a redundant copy. It needs at least four drives and yields usable capacity equal to about half the total drives.", "plain_english": "RAID 10 pairs drives up as mirrors and then spreads the data across those pairs. This gives both speed and safety, but you only get to use about half of the total drive space.", "purpose_function": "It delivers fast throughput plus redundancy, making it suited to high track-count recording where both speed and drive-failure protection matter. It exists as a balance between performance and data safety at the cost of usable capacity.", "practical_application": "A facility runs a four-drive RAID 10 array as its main recording volume so large sessions stream reliably and a single drive failure does not stop work.", "category": "Storage", "related_terms": ["RAID 1 storage", "RAID 5 storage", "Primary recording volume", "Data striping", "Redundancy", "Throughput"], "common_mistakes": ["Assuming RAID 10 survives any two failures, when losing both drives in the same mirrored pair still destroys the array", "Overlooking that usable capacity is only about half the raw drive total", "Treating the array as a backup rather than a redundancy layer that still needs separate backups"], "scenario_contexts": ["Serving a large multitrack film or album session that needs fast, safe storage", "A post-production bay editing many simultaneous audio and video streams", "A shared studio server balancing speed and fault tolerance"]}, "801effc7-c6df-4423-bf2e-8ddf5c5a2e2a": {"definition": "A storage configuration that stripes data across three or more drives together with distributed parity, so the array can rebuild all data if any single drive fails. Usable capacity equals the total minus one drive's worth of space, giving a mix of capacity, speed, and single-drive fault tolerance.", "plain_english": "RAID 5 spreads data across several drives and adds extra check information so it can rebuild everything if one drive dies. You lose the space of one drive to that safety net, but you keep most of your storage.", "purpose_function": "It offers larger usable capacity than mirroring while still surviving one drive failure, useful for storing many sessions or archives online. It exists as a capacity-efficient balance of storage size and redundancy.", "practical_application": "A studio keeps its shared project and sample library on a RAID 5 array so it holds a lot of data and can rebuild after one disk fails, while still keeping off-array backups.", "category": "Storage", "related_terms": ["RAID 1 storage", "RAID 10 storage", "Primary recording volume", "Parity", "Data striping", "Redundancy"], "common_mistakes": ["Assuming RAID 5 survives two simultaneous failures; a second failure during rebuild loses the whole array", "Using RAID 5 as the sole copy instead of keeping independent backups", "Choosing it for very high write loads where the parity overhead can slow performance"], "scenario_contexts": ["A shared network drive holding many project sessions and libraries", "An archive server that needs capacity plus single-drive protection", "A facility balancing storage cost against fault tolerance"]}, "198ca07f-07dd-4751-83e5-47afabef24f3": {"definition": "RAID 6 is a storage scheme that stripes data across three or more disks together with two independent sets of distributed parity, allowing the array to keep running and rebuild after up to two simultaneous drive failures.", "plain_english": "RAID 6 links several hard drives so they act like one big drive. It also stores two extra sets of repair data. Because of that, two drives can fail at the same time and you still lose nothing.", "purpose_function": "It exists to protect large media libraries from data loss, tolerating two failed drives so a rebuild can finish even if a second disk dies while the first is being restored. This matters most on big arrays where rebuilds take a long time.", "practical_application": "Studios use RAID 6 on shared media servers and archive storage where capacity is large and rebuild times are long, accepting some lost usable capacity and slower writes in exchange for higher fault tolerance.", "category": "Storage & Backup", "related_terms": ["RAID storage array", "SMART diagnostics", "Snapshot backup", "Shared project volume", "Restore verification", "Secondary recording volume"], "common_mistakes": ["Believing RAID 6 is a backup, when it protects only against drive failure and not against deletion, corruption, theft, or fire, so a separate backup is still required", "Assuming any two-drive loss is always survivable while forgetting that a third failure during a long rebuild destroys the array", "Choosing RAID 6 for a small, fast record volume where its dual-parity write penalty can hurt real-time performance"], "scenario_contexts": ["A post house keeps its shared project media on a RAID 6 server so a single drive failure never stops editing", "During a rebuild after one disk dies, a second disk also fails, but the array survives because RAID 6 holds two parity sets", "An archive unit storing finished masters uses RAID 6 to keep its large capacity as safe as possible across many high-capacity drives"]}, "84a5faf5-8b0d-42c0-973f-e009b858b766": {"definition": "A RAID (Redundant Array of Independent Disks) storage array combines multiple physical drives into one logical unit using a chosen RAID level to improve performance, redundancy, or both.", "plain_english": "A RAID array is a group of hard drives joined so they work as one drive. Depending on how it is set up, it can make storage faster, safer, or both at once.", "purpose_function": "It lets several drives act as a single volume so throughput and/or fault tolerance can exceed what one drive gives, which is essential for streaming many audio tracks at once without dropouts.", "practical_application": "Technicians set up RAID arrays as project or media volumes on studio servers and workstations, picking a RAID level that matches the needed balance of speed, capacity, and protection.", "category": "Storage & Backup", "related_terms": ["RAID 6 storage", "Shared project volume", "Secondary recording volume", "SMART diagnostics", "Snapshot backup", "Restore verification"], "common_mistakes": ["Treating a RAID array as a replacement for backups, when redundancy guards only against drive failure", "Mixing mismatched drives or ignoring a RAID level's minimum drive count, causing poor performance or a failed build", "Not monitoring drive health, so a failed drive in a redundant array goes unnoticed until a second failure causes total loss"], "scenario_contexts": ["A recording studio builds a striped-and-mirrored array as its main record volume to sustain high track counts", "An engineer replaces a failed drive and lets the array rebuild while sessions keep running", "A facility presents one large RAID volume to the network so several edit rooms share the same media"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"bcef8507-7832-4456-a106-f8606ee70486": {"definition": "Replace is a record mode in which newly recorded audio or MIDI overwrites and erases the existing material inside the record-enabled range, so the old content in that span is removed rather than kept as an alternate take or layered part.", "plain_english": "Replace is a record mode that erases the old sound as you record new sound over it. It is like recording over an old cassette tape and wiping out what was there before.", "purpose_function": "It exists to let an engineer punch fresh material directly over a flawed section, clearing the old audio in that span so the track holds only the newest performance.", "practical_application": "An engineer turns on Replace mode to overwrite a bad phrase or a wrong MIDI note in place, recording the fix over the existing region instead of stacking another take.", "category": "Recording", "related_terms": ["Snap to Grid", "Punch recording", "Overdub", "Comping", "Record enable", "Take"], "common_mistakes": ["Confusing Replace with overdub and destroying a good part of a take, because Replace erases the existing material", "Forgetting Replace is active and recording over content you meant to keep", "Assuming Replace is nondestructive, when the removed audio in that range is gone unless you can undo"], "scenario_contexts": ["A vocalist re-sings one bad line and the engineer uses Replace so only the new line remains", "A producer replaces a wrong MIDI note in a part without creating a second overlapping part", "An editor punches a corrected guitar phrase over a mistake using Replace record mode"]}, "2a8673fb-36fe-4f2e-8d4f-ac365f999c61": {"definition": "Restore verification is the practice of testing a backup by actually restoring its data and confirming the recovered files are complete, uncorrupted, and openable, proving that the backup can be relied on for recovery.", "plain_english": "Restore verification means checking that a backup really works. You bring the files back, then open them and make sure they are complete before you trust the backup.", "purpose_function": "It exists because a backup is only trustworthy once it is proven recoverable; verification catches silent corruption, incomplete jobs, or bad media before a real disaster depends on them.", "practical_application": "A technician periodically restores a sample session from backup to a scratch drive and opens it to confirm the archive is valid, instead of assuming the backup job worked.", "category": "Storage & Backup", "related_terms": ["Snapshot backup", "RAID 6 storage", "Shared project volume", "SMART diagnostics", "Secondary recording volume", "RAID storage array"], "common_mistakes": ["Trusting that a backup finished successfully without ever restoring and opening the files", "Verifying only that files exist, not that they open and play back correctly", "Testing a restore onto the same drive that holds the original, which fails to prove off-drive or off-site recovery"], "scenario_contexts": ["Before wiping a full record drive, an engineer restores the archived session elsewhere and confirms it opens", "A monthly routine restores random projects from tape to check the archive is still readable", "After a backup software update, a technician verifies that restores still produce complete sessions"]}, "c519f83d-958f-45c6-8c89-1e31b21efa0e": {"definition": "A secondary recording volume is a separate storage disk, distinct from the system or boot drive, designated to hold recorded audio so that record and playback streaming does not compete with the operating system and application for disk bandwidth.", "plain_english": "This is a second, separate drive used just for recording audio. Keeping recordings off the main system drive helps the computer run smoothly and record more tracks at once.", "purpose_function": "It exists to keep recorded media off the busy system drive, giving record and playback their own sustained bandwidth and keeping takes separate from operating system and program files.", "practical_application": "An engineer points the session's audio record path to a fast secondary drive so the boot disk stays free, which raises track count and reliability.", "category": "Storage & Backup", "related_terms": ["Shared project volume", "RAID storage array", "Snapshot backup", "Restore verification", "SMART diagnostics", "RAID 6 storage"], "common_mistakes": ["Recording to the system drive because a dedicated volume was never selected, risking dropouts and low track counts", "Assuming a secondary internal volume is backed up when it is only working storage", "Filling the record volume near capacity, which degrades write speed and can stop recording"], "scenario_contexts": ["A studio names a fast SSD as the secondary recording volume so the OS drive is never the record target", "An engineer sets each new session's audio files to save to the secondary drive by default", "On a mobile rig, tracks are recorded to an external secondary volume to keep the laptop's internal drive free"]}, "69ce84e9-973a-4492-93fe-aa0d21cd6b16": {"definition": "A shared project volume is a storage volume, typically on networked or shared-access storage, that holds a project's media and session files so that multiple workstations or users can access the same content.", "plain_english": "A shared project volume is a drive that many people or computers can reach. It lets a team work on the same session and media files instead of passing copies around.", "purpose_function": "It exists to centralize project media so a team can collaborate on one set of files, avoiding duplicate copies and keeping everyone working from the current material.", "practical_application": "In a multi-room facility, editors mount the shared project volume over the network and open the same sessions and media without copying files between machines.", "category": "Storage & Backup", "related_terms": ["Secondary recording volume", "RAID storage array", "RAID 6 storage", "Restore verification", "Snapshot backup", "SMART diagnostics"], "common_mistakes": ["Two users overwriting the same session file because file-locking or check-out rules were ignored", "Assuming shared central storage is automatically backed up, when it still needs its own backup", "Running high-track-count playback over a network too slow for the shared volume, causing dropouts"], "scenario_contexts": ["A post facility keeps all show media on a shared project volume so any suite can open any reel", "An assistant loads new dailies to the shared volume for editors across the building", "A band's overdub sessions live on a shared volume so each engineer works from the same files"]}, "495f8979-dbfc-4fcf-bfbc-24045e566b7a": {"definition": "SMART (Self-Monitoring, Analysis and Reporting Technology) is a drive-level monitoring system built into ATA/SATA and NVMe drives that tracks health attributes such as reallocated sectors, read errors, and temperature to predict impending failure.", "plain_english": "SMART is a built-in health check inside most drives. It watches for early warning signs, like bad spots or heat, so you can swap a failing drive before it dies.", "purpose_function": "It exists to give early warning of a degrading drive so it can be replaced before it fails outright and takes data with it.", "practical_application": "A technician reads SMART attributes with disk utility software to spot rising reallocated-sector or pending-sector counts and retires a suspect drive before it fails during a session.", "category": "Storage & Backup", "related_terms": ["RAID storage array", "RAID 6 storage", "Restore verification", "Snapshot backup", "Secondary recording volume", "Shared project volume"], "common_mistakes": ["Assuming a 'SMART OK' status guarantees the drive is fine, when some failures happen with no prior warning", "Ignoring rising reallocated or pending sector counts until the drive fails completely", "Relying on SMART instead of backups, though SMART only warns and cannot recover lost data"], "scenario_contexts": ["A studio's monitoring flags rising bad-sector counts on a record drive, so it is swapped before a session", "During maintenance, a technician checks SMART data across the array members and replaces a weak drive", "A drive reporting high temperature in SMART prompts better cooling before it fails"]}, "08b65d43-4f4f-430d-aa4f-5baaf97c375d": {"definition": "Snap to Grid is an editing mode that constrains the movement and placement of clips, edit points, and selections so they align to a defined grid of bars, beats, or time divisions.", "plain_english": "Snap to Grid makes clips jump to line up with the beat markers as you move them. It is like a magnet that pulls your edits neatly into place on the timeline.", "purpose_function": "It exists to keep edits musically or timing-accurate on their own, so regions land exactly on beats or frames without slow manual nudging.", "practical_application": "An editor turns on Snap to Grid to drag loops and clips so they lock to the bar or beat, keeping arrangement edits tight and in time.", "category": "Editing", "related_terms": ["Replace (record)", "Quantize", "Grid mode", "Bars and beats", "Zero crossing", "Tempo map"], "common_mistakes": ["Leaving Snap to Grid on during fine detail edits, so clips jump and will not move to the exact intended spot", "Setting the grid value too coarse, forcing edits to snap far from where they are needed", "Confusing Snap to Grid with quantize, when snapping constrains manual moves and quantize repositions events to the grid automatically"], "scenario_contexts": ["A producer arranges loops with Snap to Grid so every clip starts on a bar line", "An editor turns snapping off to slide a clip a few milliseconds for feel", "Building a beat, the user snaps drum hits to the sixteenth-note grid"]}, "86ab95bc-7f6d-4381-8da2-287302410c02": {"definition": "A snapshot backup is a point-in-time copy that captures the state of files or a volume at a specific instant, letting that exact version be preserved and restored later even as work on the live data continues.", "plain_english": "A snapshot backup is an instant picture of your files at one moment. You can go back to that exact point later if something goes wrong.", "purpose_function": "It exists to freeze a known-good state quickly so you can roll back to it after unwanted changes, corruption, or mistakes.", "practical_application": "An engineer takes a snapshot of a session or volume before a risky edit or plugin change so the earlier state can be recovered if the change goes wrong.", "category": "Storage & Backup", "related_terms": ["Restore verification", "RAID 6 storage", "Shared project volume", "SMART diagnostics", "Secondary recording volume", "RAID storage array"], "common_mistakes": ["Treating a snapshot on the same drive as a full backup, when a drive failure destroys both the data and its snapshots", "Assuming a snapshot copies all media, when it may only reference unchanged blocks on the same storage", "Never checking that a snapshot actually restores to a usable state"], "scenario_contexts": ["Before a major mix revision, an engineer snapshots the session so the earlier version can return", "A shared storage system takes hourly snapshots so a deleted file can be recovered", "A technician restores yesterday's snapshot after a corrupt save"]}, "7171a6fb-278e-45c2-ad2e-7a10468fd23b": {"definition": "Software monitoring is hearing a live input by routing it through the DAW and audio interface rather than directly through hardware, so the performer hears the signal after it passes through the computer and any active plug-ins. Because the signal is converted to digital, processed, and converted back to analog, it returns with a round-trip latency delay.", "plain_english": "This is when you listen to a mic or instrument through your computer's music software while recording. The sound goes into the computer and back out. That trip adds a tiny delay, like a faint echo of your own voice.", "purpose_function": "It lets performers hear themselves with the DAW's effects and processing applied while they play, and it avoids the need for a separate hardware monitor mixer. It exists because engineers often want to track through plug-in reverb or amp simulation.", "practical_application": "A technician lowers the buffer size to cut latency when a singer monitors through software, and switches to the interface's direct monitoring if the delay becomes distracting.", "category": "Monitoring", "related_terms": ["Direct Monitoring", "Latency", "Buffer Size", "Audio Interface", "Track Arm (Record-Enable)"], "common_mistakes": ["Using a large buffer size while software monitoring, which adds noticeable latency that throws off the performer.", "Confusing software monitoring with direct monitoring and not understanding why a delay is heard.", "Leaving both software and hardware monitoring on at once, causing a doubled or flanged sound."], "scenario_contexts": ["A vocalist wants reverb on their voice while recording, so the engineer enables software monitoring.", "A guitarist records through an amp-simulator plug-in and monitors the processed tone through the DAW.", "Latency becomes distracting during tracking, prompting a switch to the interface's direct monitoring."]}, "2c98afe2-f34f-4505-a0ec-61384609d45c": {"definition": "A storage area network (SAN) is a dedicated high-speed network that gives multiple computers block-level access to a shared pool of storage devices, so the storage appears to each host as if it were a locally attached drive. In audio and video post-production it lets several workstations edit from the same media volume at once.", "plain_english": "A storage area network is a fast, separate network just for hard drives. It lets many computers share one big pool of storage as if each one owned it. That way a whole team can work on the same recordings.", "purpose_function": "It centralizes storage so many editors can share large media files with high speed and reliability instead of copying files between separate drives. It exists to support collaborative, high-bandwidth workflows such as multi-seat post-production.", "practical_application": "In a post house, a technician connects edit suites to a SAN so several editors pull the same session media at the same time without duplicating files.", "category": "Storage", "related_terms": ["Storage health monitoring", "Tape archive", "Network-attached storage", "RAID", "Session backup"], "common_mistakes": ["Confusing a SAN, which is block-level and appears as a local disk, with NAS, which is file-level and accessed as a shared folder.", "Assuming a SAN automatically protects data, when backups and RAID are still required.", "Underestimating the network bandwidth needed, causing dropouts when many streams play at once."], "scenario_contexts": ["A film post facility runs several Pro Tools rigs off one shared SAN volume.", "An engineer troubleshoots audio dropouts traced to SAN bandwidth saturation.", "A studio expands storage by adding drives to the SAN rather than to each workstation."]}, "5c359bef-48f8-48e2-94b9-38c0237bbb71": {"definition": "Storage health monitoring is the ongoing checking of a drive's operating condition and reliability indicators, such as the S.M.A.R.T. attributes reported by ATA/SATA and NVMe devices, to detect wear, errors, and impending failure before data is lost.", "plain_english": "This means keeping an eye on the condition of your hard drives and SSDs. The drive reports warning signs, like bad sectors or high heat. You can then replace it before it dies and takes your recordings with it.", "purpose_function": "It warns technicians of a failing drive early, so data can be backed up and the drive swapped before an outage or data loss. It exists because drives wear out and often show measurable warning signs first.", "practical_application": "A technician reviews S.M.A.R.T. reports on studio drives and replaces any disk showing a rising reallocated-sector count before it fails mid-session.", "category": "Storage", "related_terms": ["Storage area network", "Tape archive", "RAID", "Session backup", "Solid-state drive"], "common_mistakes": ["Ignoring early S.M.A.R.T. warnings until the drive fails completely.", "Assuming a passing S.M.A.R.T. status guarantees the drive will not fail, when sudden failures still happen.", "Treating health monitoring as a substitute for real backups."], "scenario_contexts": ["A studio's monitoring software flags a session drive with growing bad sectors, prompting replacement.", "An engineer checks SSD wear levels before starting a long recording project.", "A drive overheats and health alerts prompt improved cooling in the machine room."]}, "5059a4bf-231e-4be0-b639-dbd11ec02b52": {"definition": "Sustain-pedal data is MIDI information from a keyboard's damper pedal, transmitted as Control Change 64 (Damper/Sustain). Following the standard's on/off convention, values of 64-127 signal pedal-down so notes sustain, and values of 0-63 signal pedal-up so notes release.", "plain_english": "This is the on/off message a keyboard sends when you press the sustain pedal. It tells the software to hold notes ringing, just like the pedal on a real piano. When you lift your foot, the notes stop.", "purpose_function": "It records and sends pedal movements separately from the notes, so held notes can be reproduced and edited later in a DAW. It exists so electronic instruments can capture expressive pedaling like an acoustic piano.", "practical_application": "When editing a MIDI piano take, a technician finds that overly long notes come from a lingering CC64 pedal-down event and edits or thins the pedal data to clean up the part.", "category": "MIDI", "related_terms": ["Velocity compression", "Time Signature", "MIDI Control Change", "Quantization", "Piano Roll"], "common_mistakes": ["Deleting notes to fix stuck sustain when the real cause is a lingering CC64 pedal-down event.", "Assuming the pedal is recorded as note length rather than as separate control-change data.", "Recording data from a half-pedal keyboard as simple on/off and losing the nuance."], "scenario_contexts": ["A recorded piano part rings on too long because a pedal-up (CC64 = 0) event is missing.", "An engineer quantizes the notes but must handle the sustain-pedal data separately.", "A MIDI file plays back with the wrong sustain because CC64 was not exported."]}, "1f3b5e3a-c78b-467f-9959-dc091201c641": {"definition": "A tape archive is a long-term store of recorded material held on magnetic tape, whether analog master tapes or modern digital data tape such as LTO. It preserves finished recordings and session media offline for years, at low cost per gigabyte and with long shelf life.", "plain_english": "This is a backup of recordings kept on magnetic tape for the long haul. Tape is cheap and lasts a long time when stored well. Studios use it to safely store finished projects they may not touch for years.", "purpose_function": "It preserves masters and session data cheaply and reliably for the long term, offline and separate from working drives. It exists because tape offers a long shelf life and low cost per gigabyte for material that must be kept but is rarely accessed.", "practical_application": "At the end of a project, a technician backs up the full session to LTO data tape and stores it off-site for long-term archival.", "category": "Storage", "related_terms": ["Storage area network", "Storage health monitoring", "Session backup", "Bounce/Export", "Session Management"], "common_mistakes": ["Storing tapes in hot or humid conditions, which speeds decay and can cause sticky-shed on older analog tape.", "Keeping only one archive copy and never verifying that it restores.", "Assuming decades-old analog tapes will play back perfectly without baking or restoration."], "scenario_contexts": ["A studio migrates completed albums to LTO tape to free up drive space.", "An archivist restores a 1970s analog master and must bake the tape before playback.", "A post facility keeps off-site tape backups of delivered projects for disaster recovery."]}, "56418beb-c6ef-43b6-a55a-f480dc964a63": {"definition": "A time signature is a musical notation that defines a bar's meter: the upper number gives the number of beats per bar and the lower number gives the note value that counts as one beat (for example, 4/4 means four quarter-note beats per bar). In a DAW it sets the bars-and-beats grid that governs the metronome, quantization, and timeline.", "plain_english": "A time signature tells you how beats are grouped into bars in a piece of music. In 4/4, for example, you count four beats over and over. In music software it sets up the grid of bars and beats that everything lines up to.", "purpose_function": "It organizes music into regular bars so performers, notation, and the DAW share one rhythmic framework. In a session it drives the click track, the grid, and beat-based editing such as quantizing.", "practical_application": "A technician sets the session's time signature to match the song so the metronome, bar ruler, and quantize grid line up with the music.", "category": "Timing", "related_terms": ["Tempo", "Quantization", "Click Track", "Bars and Beats", "Grid"], "common_mistakes": ["Confusing time signature with tempo; one sets how beats are grouped, the other sets speed.", "Leaving the DAW at the default 4/4 when the song is in another meter, so the grid and click do not match.", "Reading the lower number as a count of beats rather than as a note value."], "scenario_contexts": ["A song in 3/4 waltz time needs the session time signature changed from the default 4/4.", "A producer adds a meter change at the bridge so the grid follows the music.", "A click track sounds wrong until the time signature is corrected."]}, "648c4397-d693-4ab4-9f0f-80041ce1ac51": {"definition": "Track arming, or record-enabling, is marking a specific track to capture incoming signal when recording begins, so only armed tracks record while the others play back. Arming a track also typically routes its input to the monitor output so the performer can hear it.", "plain_english": "Arming a track means switching it on to record. Only the tracks you arm will capture sound when you hit record; the rest just play back. It is like choosing which recorders to press record on.", "purpose_function": "It selects which tracks capture new material, so an engineer can overdub onto specific tracks without recording over everything. It exists to give precise control over what gets recorded in a multitrack session.", "practical_application": "Before an overdub, a technician arms only the vocal track, checks the input level and monitoring, then records while the rest of the session plays back.", "category": "Recording", "related_terms": ["Software Monitoring", "TrackPunch", "Punch In/Out", "Input Monitoring", "Overdub"], "common_mistakes": ["Forgetting to record-enable the track, so nothing is captured on the take.", "Arming the wrong track and recording over a good take.", "Leaving several tracks armed by accident, capturing bleed or silence on them."], "scenario_contexts": ["An engineer arms a single track to punch in a corrected guitar phrase.", "During tracking, only the drum tracks are armed while a scratch guitar plays back.", "A missed take is traced to a track that was never record-enabled."]}, "36a23a51-ab50-4e26-8904-f12059216a48": {"definition": "TrackPunch is a Pro Tools record mode that lets individual audio tracks be punched in and out of recording independently, on the fly, without stopping playback, while all TrackPunch-enabled tracks stay record-armed for the whole pass. It records non-destructively, creating new audio for each punched region.", "plain_english": "TrackPunch is a Pro Tools feature that lets you drop single tracks in and out of recording while the session keeps playing. You can catch a fix on one track without stopping. It saves the new bits without erasing the old audio.", "purpose_function": "It allows fast, independent punch recording across many tracks during one continuous take, which suits live and band tracking where different parts need fixing on the fly. It exists to punch tracks in and out without stopping the transport.", "practical_application": "During a live band take, an engineer uses TrackPunch to drop the bass track in to fix a section while the rest of the take keeps rolling.", "category": "Recording", "related_terms": ["Track Arm (Record-Enable)", "Punch In/Out", "QuickPunch", "DestructivePunch", "Software Monitoring"], "common_mistakes": ["Confusing TrackPunch with DestructivePunch, which overwrites the existing audio.", "Not TrackPunch-enabling a track first, so it cannot be punched during the pass.", "Assuming it punches all tracks at once like a global punch rather than per track."], "scenario_contexts": ["A full band is tracked live and individual parts are punched in with TrackPunch as needed.", "An engineer fixes a single flubbed note on one track without stopping the take.", "A session uses TrackPunch to keep every take non-destructive while spot-fixing tracks."]}, "35c8368d-789e-41fc-8f1e-2a483654fa06": {"definition": "Velocity compression is a MIDI editing process that reduces the range between the highest and lowest note velocities in a performance, bringing loud and soft notes closer together in level. It scales velocity values toward a central value, narrowing the dynamic range without changing pitch or timing.", "plain_english": "This evens out how hard the notes in a MIDI performance were played. It pulls the loudest and softest notes closer together, so a sampled instrument plays more evenly. It is a bit like turning down only the loud parts.", "purpose_function": "It tightens the dynamic range of a MIDI part so a sampled or synth instrument sounds more even and consistent. It exists to fix uneven playing or to fit a part into a mix without re-performing it.", "practical_application": "A technician applies velocity compression to an uneven MIDI piano take so the soft notes are not lost and the loud notes do not jump out.", "category": "MIDI", "related_terms": ["Sustain-pedal data", "Time Signature", "Note Velocity", "MIDI Editing", "Quantization"], "common_mistakes": ["Confusing MIDI velocity compression with audio dynamic-range compression; velocity compression edits data, not an audio signal.", "Over-compressing velocities until the part sounds flat and lifeless.", "Assuming velocity always maps to volume, when many instruments map it to timbre or filter cutoff as well."], "scenario_contexts": ["An uneven MIDI drum performance is smoothed with velocity compression so the quiet hits are audible.", "A producer narrows the velocity range on a synth line so it sits steadily in the mix.", "A programmed piano part is velocity-compressed to reduce jarring loud notes."]}, "0e1abf8b-9c96-4629-9e3c-a00b53f8af67": {"definition": "A MIDI editing operation that multiplies the velocity values of selected note events by a factor or percentage, raising or lowering them proportionally together. A factor below 100% narrows the spread between soft and loud notes (compressing the dynamic range), while a factor above 100% widens it, in both cases preserving each note's relative dynamics rather than adding a fixed amount.", "plain_english": "MIDI velocity is a number from 1 to 127 that says how hard each note was played. It usually controls how loud the note sounds. Velocity scaling multiplies all those numbers by the same percentage at once. This makes every note softer or louder together, while the loud notes still stay louder than the soft ones. It works like a dimmer for a whole part instead of setting each note by hand.", "purpose_function": "It lets you adjust the overall dynamics of a MIDI performance in one step, either to match a part's intensity to the mix or to tighten or open up its dynamic range. It exists because editing every note's velocity by hand is slow and would not preserve the relative feel of the performance.", "practical_application": "A technician selects the notes in a MIDI part and applies a scaling function (for example Cubase's Compress/Expand ratio or a Logic velocity Scale operation) to push a too-loud programmed drum part back in the mix, or to even out an unevenly played keyboard take without re-recording it.", "category": "MIDI Editing", "related_terms": ["MIDI velocity", "Velocity curve", "Quantization", "MIDI CC", "Dynamic range", "Logical Editor"], "common_mistakes": ["Treating velocity scaling as a volume/gain change: it edits velocity data, and how that maps to loudness depends on the instrument's velocity response, not a fixed dB amount.", "Forgetting that velocity is capped at 1-127, so scaling too far clips notes to the min or max and flattens the dynamics instead of smoothly scaling them.", "Scaling velocity to fix a loudness problem that is really the instrument's velocity-to-volume mapping or the track's mix gain.", "Applying destructive scaling to the only take without keeping a copy, losing the original performance dynamics."], "scenario_contexts": ["Taming an overly aggressive programmed hi-hat or snare so it blends into the drum bus.", "Evening out a keyboard overdub where some notes were struck much harder than others.", "Compressing the velocity range of a MIDI string line so a sampled library's soft and loud layers stay in a usable range.", "Raising the velocities of a timidly played MIDI bass part to trigger a brighter, louder sample layer."]}, "4645c07b-66d3-4e07-84d6-14b7301e67c1": {"definition": "A DAW function that automatically measures the processing latency introduced by plug-ins and internal signal routing and delays the earlier-arriving tracks and buses to match, keeping every track sample-accurately time-aligned at the output.", "plain_english": "Some effects take a tiny moment to do their work, which can nudge a track slightly out of sync with the others. This feature measures that small delay and lines every track back up, so nothing ends up early or late. It is like making faster runners wait at the start so the whole group crosses the finish line together.", "purpose_function": "It exists to keep all tracks and buses time- and phase-coherent when different plug-ins and routing paths add different amounts of latency, preventing the timing smear and comb-filtering that would otherwise appear when many processed signals are mixed together.", "practical_application": "A technician leaves delay compensation on while mixing so heavily processed tracks, parallel buses, and reamped signals stay aligned, and may reduce or bypass it when tracking live because it can add noticeable monitoring latency.", "category": "DAW Feature", "related_terms": ["Latency", "Plug-in Delay", "Buffer Size", "Bus", "Phase Alignment", "Parallel Compression"], "common_mistakes": ["Assuming it removes all latency while recording; it aligns playback but can increase monitoring latency, so it is often reduced or bypassed when tracking.", "Thinking it corrects timing errors in a performance; it only offsets plug-in and routing latency, not sloppy playing or misaligned edits.", "Forgetting that some external hardware inserts need a manually measured delay offset because the DAW cannot detect their latency automatically."], "scenario_contexts": ["Mixing with a look-ahead limiter on the mix bus while keeping it aligned with the individual tracks.", "Running parallel drum compression without the processed copy drifting out of phase with the dry drums.", "Diagnosing a thin, phasey snare that turns out to be delay compensation being switched off."]}, "bf8984c9-a53d-436a-bfc9-773b00dd1527": {"definition": "A Pro Tools toggle that ties the Timeline Selection (the playback and record range shown on the timeline rulers) to the Edit Selection (the material highlighted in the Edit window), so that changing one automatically updates the other.", "plain_english": "In Pro Tools there are two kinds of highlight: the part that will play back, and the part you picked to edit. This switch joins the two, so when you select something to edit it also becomes what plays. Turning it off lets you keep playing one spot while you edit a different one.", "purpose_function": "It exists to let an editor choose whether playback follows their edit selections; linked keeps normal editing simple, while unlinked lets you loop or audition one section while selecting or editing somewhere else.", "practical_application": "Editors usually leave it linked so playback matches whatever they highlight, and unlink it when they want to loop a reference section while editing elsewhere or set punch points separate from the edited region.", "category": "DAW Feature", "related_terms": ["Timeline Selection", "Edit Selection", "Edit Window", "Loop Playback", "Punch Recording", "Link Track and Edit Selection"], "common_mistakes": ["Confusing it with 'Link Track and Edit Selection', which links selected tracks between the Mix and Edit windows rather than the timeline and edit ranges.", "Leaving it unlinked by accident, then being confused when playback starts from a different place than the highlighted region.", "Assuming the two selections are always identical; by default they can be independent of each other."], "scenario_contexts": ["Unlinking the selections to loop a chorus for reference while editing a verse elsewhere in the session.", "Keeping them linked so playback always starts from the region just selected during detailed editing.", "Setting timeline punch-in points that differ from the currently edited region."]}, "ff29436b-28d9-450d-98f3-4448b773d263": {"definition": "A track automation mode in a DAW in which the track neither writes new automation nor reads existing automation data; the automated parameter holds at its current manual setting and any recorded automation on that track is ignored during playback.", "plain_english": "This is a mode in mixing software that tells a track to ignore its saved moves. A volume slider or knob just stays where you put it, and earlier recorded changes are skipped. It is like turning off a player piano so the keys only move when you press them.", "purpose_function": "It gives an engineer a static, hands-on state for a control, so a parameter can be auditioned or set manually without triggering or overwriting recorded automation.", "practical_application": "An engineer switches a track to Automation Off to hold a fixed fader or plugin setting while checking a balance, or to silence existing automation moves temporarily without deleting the data.", "category": "Automation Modes", "related_terms": ["Automation Read", "Automation Write", "Touch Mode", "Latch Mode", "Trim Mode", "Automation Lane"], "common_mistakes": ["Assuming Off erases automation; it only suspends reading and writing, and the recorded data remains intact.", "Confusing per-track Off mode with a session-wide automation suspend, which affects all tracks at once.", "Leaving a track in Off and then wondering why recorded fader moves no longer play back."], "scenario_contexts": ["Holding a static rough-mix balance before any automation has been written.", "Auditioning a plugin or fader setting by hand without overwriting existing automation.", "Troubleshooting why automated moves are not playing back on a track."]}, "3835bc9b-7b83-4248-b1af-58cd6d2c133b": {"definition": "A metering configuration in which a channel's level meter reads the signal at a point ahead of the channel fader, so the displayed level reflects the input and gain-stage signal and does not change when the fader is moved.", "plain_english": "This shows how strong a sound is before it reaches the channel's volume slider. Because the meter sits ahead of the slider, moving the fader up or down does not change the reading. It is like checking the water pressure at the pipe before you open the tap.", "purpose_function": "It lets an engineer watch the true incoming signal level and set gain to avoid clipping, no matter where the fader happens to be set.", "practical_application": "A mixer uses pre-fader metering during soundcheck or tracking to confirm a channel's gain staging is healthy and not overloading, even when the fader is pulled down low.", "category": "Metering", "related_terms": ["Post-Fader Metering", "Gain Staging", "Clipping", "Fader", "Peak Meter", "Signal Level"], "common_mistakes": ["Confusing pre-fader with post-fader metering; pre-fader ignores the fader while post-fader follows it.", "Expecting a lower fader to fix a pre-fader meter that reads clipping, when the input gain must be reduced instead.", "Using pre-fader meters to judge final mix balance, which is actually controlled by the fader."], "scenario_contexts": ["Setting input gain during soundcheck so channels do not clip before the fader.", "Diagnosing distortion that persists even when a channel's fader is lowered.", "Confirming signal presence on a muted or pulled-down channel."]}, "624fd2d9-b53a-4ece-a80c-e1952bb83082": {"definition": "A technique in which the amplitude (level) of a carrier signal is varied in proportion to the instantaneous value of a second, modulating signal. When the modulation rate reaches the audio range, AM produces extra sideband frequencies above and below the carrier, changing the tone.", "plain_english": "Amplitude modulation means using one signal to change the loudness of another. When it happens slowly, you hear the volume wobble, like a tremolo effect. When it happens fast, it adds new tones and changes how the sound feels.", "purpose_function": "It lets one signal shape the loudness of another, creating effects from slow tremolo up to rich new sidebands. In synthesis it is used to add harmonics and reshape a sound's tone.", "practical_application": "A technician uses AM when patching a low-frequency oscillator to a signal's amplifier for tremolo, or when routing one audio-rate oscillator to another to add metallic sidebands in synth sound design.", "category": "Modulation", "related_terms": ["Ring modulation", "Frequency modulation", "Tremolo", "Low-frequency oscillator", "Sideband"], "common_mistakes": ["Confusing amplitude modulation with ring modulation; classic AM keeps the carrier present, while balanced ring modulation suppresses it and leaves only the sidebands.", "Assuming AM only makes tremolo; at audio-rate modulation it generates new sideband frequencies and changes timbre.", "Thinking AM and FM produce the same result; they create different sideband patterns."], "scenario_contexts": ["Patching an LFO to a VCA for tremolo on a synth pad", "Using audio-rate AM between two oscillators for metallic sound design", "Diagnosing unwanted amplitude modulation, such as hum riding on a signal path"]}, "d299591d-5a48-4e94-b3ee-eeba92d871a9": {"definition": "A digital oscillator designed to generate harmonically rich waveforms, such as sawtooth or square, while suppressing aliasing: the false, inharmonic frequencies that appear when harmonics exceed the Nyquist limit. It uses methods such as band-limited step functions (BLIT/BLEP), additive synthesis, or oversampled wavetables to keep the spectrum below half the sample rate.", "plain_english": "A digital oscillator that makes bright waveforms without adding harsh, wrong tones. Plain digital shapes can create ugly ghost notes called aliasing. This kind of oscillator is built to keep those ghost tones out, so the sound stays clean.", "purpose_function": "It provides classic bright analog-style waveforms in software without the aliasing artifacts that would otherwise dirty the high frequencies. This keeps synth tones clean across the whole keyboard range.", "practical_application": "When choosing or building soft-synth patches, a technician relies on anti-aliased oscillators so high notes and bright saw or pulse waves stay clean instead of developing gritty, out-of-tune overtones.", "category": "Oscillators", "related_terms": ["Band-limited oscillator", "Aliasing", "Nyquist frequency", "Wavetable synthesis", "Oversampling"], "common_mistakes": ["Believing any digital oscillator is automatically alias-free; naive digital waveforms alias badly on high notes.", "Assuming a higher sample rate alone fixes aliasing; oversampling helps but proper band-limiting is still needed.", "Confusing aliasing artifacts with normal high-frequency brightness."], "scenario_contexts": ["Choosing a soft-synth oscillator that stays clean on high notes", "A/B testing an oscillator for aliasing while sweeping pitch upward", "Building bright saw leads without digital grit"]}, "9390d684-ebfd-4449-8bbb-1877e82b0beb": {"definition": "The process of converting a continuous analog audio signal into digital form by measuring (sampling) its amplitude at regular, evenly spaced points in time, at a fixed sample rate. Per the Nyquist theorem, the sample rate must be more than twice the highest audio frequency present to capture it without aliasing.", "plain_english": "Audio sampling means turning a real sound into numbers a computer can store. The system measures the sound's level many thousands of times each second. Play those measurements back in order and you hear the sound again.", "purpose_function": "It is the basic step that lets analog sound be recorded, stored, edited, and played back digitally. Choosing a high enough sample rate makes sure the full audio range is captured accurately.", "practical_application": "A technician sets the sample rate, such as 44.1 or 48 kHz, at the audio interface or DAW before recording, balancing audio bandwidth against file size and processing load.", "category": "Digital Audio", "related_terms": ["Sample rate", "Nyquist frequency", "Aliasing", "Quantization", "Analog-to-digital converter", "Bit depth"], "common_mistakes": ["Confusing sample rate (how often amplitude is measured) with bit depth (how finely each sample's level is measured).", "Thinking a higher sample rate always sounds better; it raises file size and CPU load with limited audible benefit beyond what the material needs.", "Forgetting the Nyquist rule and recording without proper anti-alias filtering, which lets aliasing spoil the recording."], "scenario_contexts": ["Setting the sample rate in a DAW before a session", "Configuring an audio interface for a recording", "Explaining why 44.1 kHz captures the full audible range"]}, "57894ecc-012f-487d-a139-c0357d2d3fe3": {"definition": "An oscillator whose output spectrum is deliberately restricted so that it contains no energy above the Nyquist frequency (half the sample rate). By limiting the number of harmonics it generates, it avoids the aliasing that an ideal, mathematically sharp waveform would produce in a digital system.", "plain_english": "An oscillator that only makes tones up to a safe limit. In digital gear, tones above a certain point fold back and sound wrong. A band-limited oscillator stops before that point, so its sound stays clean.", "purpose_function": "It exists to reproduce bright waveforms digitally without aliasing, keeping the harmonics it makes inside the range the system can handle. This is the core idea behind alias-free digital synthesis.", "practical_application": "Sound designers pick band-limited oscillators in a synth to keep sawtooth and square waves clean, especially when playing high notes or sweeping the pitch upward.", "category": "Oscillators", "related_terms": ["Anti-aliased oscillator", "Aliasing", "Nyquist frequency", "Sawtooth wave", "Additive synthesis"], "common_mistakes": ["Assuming a mathematically perfect saw or square can be generated digitally without aliasing; its sharp edges contain harmonics above Nyquist.", "Confusing band-limiting with simply putting a low-pass filter on the output.", "Thinking band-limited oscillators sound dull; they keep every harmonic that fits below Nyquist."], "scenario_contexts": ["Selecting an alias-free oscillator for a high-register lead", "Comparing band-limited versus naive waveforms for aliasing", "Designing bright synth tones that stay clean across the keyboard"]}, "d7494023-87df-427f-8d56-7b6d48027d90": {"definition": "A collection of recorded brass-instrument samples, such as trumpet, trombone, French horn, and tuba, both solo and in sections, organized for playback in a sampler or virtual instrument. Libraries typically include multiple dynamic layers, articulations, and round-robin variations to emulate real brass performance.", "plain_english": "A brass library is a set of recorded brass sounds you play from a keyboard or computer. It holds trumpets, trombones, horns, and tubas, captured at different volumes and playing styles. This lets you build realistic brass parts without hiring live players.", "purpose_function": "It lets a producer add convincing brass parts without booking live players, by triggering recorded samples that respond to note, velocity, and articulation. It exists to make orchestral and pop brass writing practical inside a DAW.", "practical_application": "A composer loads a brass library into a sampler, then uses velocity and keyswitches to move between soft sustains, loud accents, and staccato hits while sequencing a horn section.", "category": "Sample Libraries", "related_terms": ["Choir library", "Dynamic layer", "Crossfade layer", "Round robin", "Keyswitch", "Articulation"], "common_mistakes": ["Playing every note at one velocity, so a single fixed dynamic sounds flat and unrealistic.", "Ignoring articulations and keyswitches, leaving fast passages sounding like sustained pads.", "Overlooking legato and release behavior, producing unnatural note transitions."], "scenario_contexts": ["Scoring a film cue with a sampled horn section", "Adding a punchy brass stab to a pop production", "Layering brass samples under a live horn recording for thickness"]}, "e918a5fc-51b3-49f8-9b9f-759da2074f21": {"definition": "A collection of recorded choral (vocal ensemble) samples, such as soprano, alto, tenor, and bass sections singing sustained vowels or syllables, arranged for a sampler or virtual instrument. Many choir libraries add word-building or syllable-sequencing features and multiple dynamic layers to emulate real choral singing.", "plain_english": "A choir library is a set of recorded singing voices you play from a keyboard. It usually has different voice groups singing vowels like 'ah' and 'oo'. Some let you spell out words so the choir seems to sing real lyrics.", "purpose_function": "It lets a producer add realistic choral parts without hiring a real choir, by triggering recorded voice samples that follow note and dynamics. Word-building tools exist so the sampled choir can appear to sing chosen text.", "practical_application": "A film composer loads a choir library, picks a vowel or builds syllables, and layers sustained voices under an orchestral cue for an epic, human texture.", "category": "Sample Libraries", "related_terms": ["Brass library", "Dynamic layer", "Crossfade layer", "Articulation", "Round robin"], "common_mistakes": ["Expecting any choir library to sing full words; only word-building patches support real lyrics.", "Leaving every voice on one vowel and dynamic, which sounds static and fake.", "Ignoring section balance and divisi, so the choir sounds thin or muddy."], "scenario_contexts": ["Adding an epic choir pad to a trailer cue", "Building sung syllables for a fantasy soundtrack", "Layering choir under strings for warmth in an orchestral mockup"]}, "1403ca6e-d407-463e-923e-53decb10de75": {"definition": "In a sampler, a layering setup in which two or more sample layers overlap and are smoothly blended (crossfaded) by a control source such as velocity or the mod wheel, rather than switched abruptly. As the control value moves, one layer fades out while the next fades in, avoiding audible steps between layers.", "plain_english": "A crossfade layer blends two recorded sounds smoothly instead of jumping between them. As you press harder or move a control, one layer fades down while the other fades up. This makes changes in tone sound gradual and natural.", "purpose_function": "It smooths the transition between sample layers so changes in volume or brightness sound continuous, not stepped. This is key to realistic dynamics in sampled instruments.", "practical_application": "A sound designer maps mod-wheel or velocity crossfades between soft and loud brass recordings so a held note can swell smoothly from quiet to loud.", "category": "Sample Layering", "related_terms": ["Dynamic layer", "Velocity", "Multisampling", "Modulation wheel", "Round robin"], "common_mistakes": ["Confusing a crossfade (smooth blend) with a velocity switch (a hard jump) between layers.", "Setting overlapping layers without gain compensation, so the blend gets louder in the middle.", "Crossfading two closely related recordings and hitting phase cancellation, which thins the tone."], "scenario_contexts": ["Mapping a mod-wheel crossfade for a brass swell", "Blending soft and loud layers by velocity in a sampled instrument", "Programming smooth dynamic transitions in a sustained string patch"]}, "fd6e1ce1-3d0a-467c-ba15-844920cbddb2": {"definition": "An audio oscillator whose pitch is set by a digital control system, typically a microprocessor and counter dividing a stable crystal clock, instead of an analog control voltage. The waveform itself may still be generated by analog circuitry, but the digital timing gives far better tuning stability than a traditional voltage-controlled oscillator (VCO).", "plain_english": "A digitally controlled oscillator makes a synth's basic tone, but a digital clock sets its pitch. This keeps the tuning steady and stops the drift that older analog oscillators had. You get an analog-style sound that stays in tune.", "purpose_function": "It provides analog-style oscillator tone with rock-solid tuning by locking pitch to a digital clock, solving the drift and calibration problems of pure analog VCOs. This made reliable, affordable polyphonic synths practical.", "practical_application": "A technician servicing or programming a classic DCO synth, such as a Roland Juno, can count on stable tuning across all voices without the frequent recalibration that VCO instruments need.", "category": "Oscillators", "related_terms": ["Voltage-controlled oscillator", "Anti-aliased oscillator", "Band-limited oscillator", "Crystal oscillator", "Subtractive synthesis"], "common_mistakes": ["Assuming a DCO does fully digital sound generation; the tone circuitry is often analog, and only the timing is digital.", "Treating a DCO as identical to a VCO; the DCO uses a digital clock for stable tuning.", "Blaming a DCO synth for tuning drift, when stable tuning is actually its main advantage."], "scenario_contexts": ["Servicing a Roland Juno-series synthesizer", "Choosing a DCO synth for reliable tuning on stage", "Explaining why a vintage poly stays in tune better than a VCO model"]}, "16b1f27b-b25c-4df9-be85-58005d2b2ef5": {"definition": "In a multisampled instrument, a set of samples recorded at one specific playing intensity (dynamic), such as pianissimo, mezzo-forte, or fortissimo. Multiple dynamic layers are mapped across velocity, or another controller, so that playing harder selects brighter, louder recordings, reproducing an instrument's change in tone with dynamics, not just a change in volume.", "plain_english": "A dynamic layer is a recording of an instrument played at one loudness, like soft or loud. Real instruments change their tone, not just their volume, when played harder. Stacking several layers and picking them by how hard you play makes the sampled instrument sound true to life.", "purpose_function": "It captures how an instrument's tone, not just its level, changes with playing effort, so a sampler can respond realistically to velocity. Without dynamic layers, hard and soft notes would differ only in volume.", "practical_application": "When programming a sampled instrument, a technician assigns velocity ranges to each dynamic layer so that light and heavy keystrokes trigger the correct soft or loud recordings.", "category": "Sample Layering", "related_terms": ["Crossfade layer", "Velocity", "Multisampling", "Round robin", "Brass library"], "common_mistakes": ["Confusing dynamic layers (separate recordings per intensity) with a simple volume change.", "Setting too few layers, so the tone jumps noticeably between velocity zones.", "Mismatched levels between layers, which causes uneven jumps in loudness."], "scenario_contexts": ["Programming velocity zones in a sampled piano", "Mapping pianissimo through fortissimo recordings across velocity", "Troubleshooting an audible jump between two velocity layers"]}, "9f054e39-3a8e-4acd-be02-cf86a545b1c3": {"definition": "A form of frequency modulation in which the modulating signal drives an oscillator whose frequency responds exponentially to control voltage, typically on a 1 volt-per-octave scale. Because the exponential response is asymmetric, the perceived pitch center tends to shift as modulation depth increases, so exponential FM suits vibrato, sweeps, and gritty effects rather than the stable, harmonically precise timbres for which linear FM is preferred.", "plain_english": "This changes a sound's pitch using another signal. On many older synths, pitch follows a curve, not a straight line. Because of that curve, the note can seem to slide out of tune as you add more of the effect. People use it for wobble and rough, buzzy sounds.", "purpose_function": "It lets one signal continuously vary an oscillator's pitch on synthesizers that track pitch exponentially. It exists because most analog synths use a 1 V/octave exponential pitch scale, making exponential FM the natural route to vibrato and dynamic pitch movement.", "practical_application": "A technician patches an LFO or a second oscillator into an analog synth's exponential pitch input to create vibrato or clangorous tones, and switches to a linear FM input when a stable, in-tune FM timbre is needed.", "category": "Synthesis", "related_terms": ["Frequency modulation", "Free-running oscillator", "Hard synchronization", "Voltage-controlled oscillator", "Low-frequency oscillator"], "common_mistakes": ["Assuming exponential FM keeps the note in tune; deep exponential FM shifts the average pitch sharp (upward).", "Confusing exponential FM with linear FM, then wondering why classic bell-like FM tones will not stay in tune.", "Setting modulation depth too high and treating the resulting detune as a broken oscillator."], "scenario_contexts": ["Adding vibrato to a lead patch by routing an LFO to an analog synth's exponential pitch input.", "Creating aggressive, atonal sound-effect sweeps on a modular synth.", "Troubleshooting why an oscillator drifts sharp (rises in pitch) as exponential-FM depth increases on its 1 V/octave input."]}, "89de0ef6-d679-4277-ad45-29018bd1f15f": {"definition": "A sample loop that repeatedly plays a defined section from its start point to its end point in the normal forward direction, then jumps back to the start to repeat, allowing a sampled sound to sustain for as long as a note is held.", "plain_english": "A loop is a chosen chunk of a sound that repeats. A forward loop plays that chunk from start to end, then jumps back and plays it again the same way. This lets one short recording hold a note for as long as you press the key.", "purpose_function": "It sustains a sampled sound indefinitely without needing a long recording. It exists so a short recorded segment can be held for any note length while sounding continuous.", "practical_application": "A technician sets loop start and end points inside the steady part of a sampled note so a forward loop repeats smoothly without clicks, sustaining pads, strings, or organ samples.", "category": "Sampling", "related_terms": ["Loop point", "Sustain loop", "Crossfade loop", "Keyboard mapping", "Instrument library"], "common_mistakes": ["Placing loop points where volume or tone changes, causing an audible click or pulsing.", "Confusing a forward loop with a bidirectional (alternating) loop, which reverses direction each pass.", "Looping across a transient or vibrato peak so the repeat sounds unnatural."], "scenario_contexts": ["Looping the sustain of a sampled string note so it holds while a key is pressed.", "Building an organ patch that must sustain forever from only a few seconds of recording.", "Fixing a clicking loop by moving the loop points to zero crossings."]}, "44e9a6ec-316b-4351-b78b-11dbd777d0d2": {"definition": "An oscillator that runs continuously and independently, with its phase not reset or retriggered by note-on events, so each note begins at whatever point in the waveform the oscillator happens to be at that moment.", "plain_english": "An oscillator is the part that makes the raw tone. A free-running one never stops or restarts. So each time you play a note, the wave starts at a random spot in its cycle. This gives small natural changes from note to note, like a real instrument.", "purpose_function": "It provides natural, slightly varying note starts and a lively analog character by never resetting its phase. It exists to mimic real oscillators and to allow phase differences between voices that thicken the sound.", "practical_application": "A technician chooses free-running mode when they want subtle variation and analog feel, and switches to retrigger mode when they need consistent, repeatable attacks such as a tight bass or a punchy kick.", "category": "Synthesis", "related_terms": ["Voltage-controlled oscillator", "Hard synchronization", "Frequency modulation", "Exponential frequency modulation", "Low-frequency oscillator"], "common_mistakes": ["Expecting identical attacks every time; a free-running oscillator starts at a different phase on each note.", "Blaming inconsistent bass or kick punch on a fault when it is simply free-running phase.", "Confusing free-running behavior with hard sync, which forces a phase reset."], "scenario_contexts": ["Getting a warmer, less static analog pad by leaving oscillators free-running.", "Diagnosing why a plucky bass lacks consistent punch and switching to phase retrigger.", "Layering two free-running oscillators so their drifting phase creates movement."]}, "25c467a9-8137-4691-9e99-16ece7d62909": {"definition": "A synthesis and signal-processing technique in which the instantaneous frequency of a carrier oscillator is varied by a modulating signal; when the modulator is in the audio range, this generates additional sidebands that produce complex, often inharmonic timbres.", "plain_english": "This means using one signal to change the pitch of another very fast. When the change is slow, you hear vibrato. When it is fast, it adds new tones and can make metallic, bell, or electric-piano sounds. It builds rich tones from simple ones.", "purpose_function": "It creates rich, evolving spectra from just a few oscillators by adding sidebands. It exists as an efficient way to synthesize bright, bell-like, metallic, and dynamic sounds that are hard to make with basic subtractive methods.", "practical_application": "A technician routes one oscillator (the modulator) to the frequency of another (the carrier) and adjusts modulation depth and frequency ratio to dial in bell, bass, or electric-piano tones on synths such as the Yamaha DX series.", "category": "Synthesis", "related_terms": ["Exponential frequency modulation", "Hard synchronization", "Free-running oscillator", "Voltage-controlled oscillator", "Low-frequency oscillator"], "common_mistakes": ["Confusing slow vibrato FM with audio-rate FM that changes timbre.", "Ignoring the carrier-to-modulator frequency ratio, which controls whether the result sounds harmonic or clangorous.", "Assuming FM only makes harsh sounds; gentle settings give warm electric-piano and bell tones."], "scenario_contexts": ["Programming an electric-piano patch on an FM synth.", "Adding metallic bite to a bass by increasing modulation depth.", "Using audio-rate FM in a modular system to create bell and gong textures."]}, "5096e3fb-d021-432b-9ad1-02c1a549ece0": {"definition": "An oscillator technique in which a master oscillator forcibly resets the phase of a slave oscillator at the start of each of its own cycles, locking the slave to the master's frequency and producing a characteristic bright, harmonically rich timbre as the slave's tuning is swept.", "plain_english": "Two oscillators are used together. One is the boss and restarts the other every cycle. This forces them to lock to the same base pitch. As you change the tuning of the second one, you get a sharp, tearing sound often heard in lead synth solos.", "purpose_function": "It ties a slave oscillator's pitch to a master while letting its waveform shape change, so sweeping the slave's tuning creates dramatic, vocal or tearing timbres. It exists to produce aggressive, expressive lead sounds.", "practical_application": "A technician enables hard sync, then modulates the synced oscillator's pitch with an envelope or LFO to create classic screaming sync-lead sounds, letting the master oscillator set the played pitch.", "category": "Synthesis", "related_terms": ["Free-running oscillator", "Voltage-controlled oscillator", "Frequency modulation", "Exponential frequency modulation", "Low-frequency oscillator"], "common_mistakes": ["Expecting the synced oscillator to change the played pitch; the master sets pitch while the slave changes tone.", "Not modulating the synced oscillator's frequency, so the dramatic sweeping effect never appears.", "Confusing hard sync with soft sync, which resets phase less forcefully and sounds gentler."], "scenario_contexts": ["Programming a screaming sync-lead for a solo.", "Sweeping a synced oscillator with an envelope for an aggressive attack.", "Recreating classic 1980s sync tones on a modern synth."]}, "5fcca67b-d065-4999-b42f-846641e98e65": {"definition": "A curated collection of sampled or programmed sounds for a specific instrument or group of instruments, packaged as patches or presets that load into a sampler or virtual instrument.", "plain_english": "This is a ready-made set of sounds for a software instrument. It might hold a grand piano, a full string section, or a drum kit, recorded in detail. You load it up and play those sounds from your keyboard.", "purpose_function": "It gives musicians realistic, ready-to-play instrument sounds without recording them from scratch. It exists to package professionally recorded samples and their mappings into an easily loaded product.", "practical_application": "A technician installs an instrument library, points the sampler to its sample folder, and loads its patches to play orchestral, drum, or keyboard sounds in a session.", "category": "Virtual Instruments", "related_terms": ["Instrument rack", "Keyboard mapping", "Keyswitch articulation", "Forward loop", "Velocity layer"], "common_mistakes": ["Moving or renaming the sample folder after install, so patches load with missing samples.", "Confusing an instrument library with the sampler engine that plays it; the library needs a host such as Kontakt.", "Underestimating the disk and RAM needs of large multi-gigabyte libraries."], "scenario_contexts": ["Loading a sampled string library to mock up an orchestral cue.", "Relinking a library's samples after moving them to a new drive.", "Choosing a drum library that fits a session's genre."]}, "046aa211-b702-45e0-a730-72eec92575ad": {"definition": "A container device that groups one or more instruments and their effects into parallel or layered chains under a single set of macro controls, letting several sounds be combined, split across key or velocity ranges, and played together as one instrument.", "plain_english": "This is a box that holds several instruments together and plays them as one. You can stack sounds, or split them so low keys play one and high keys play another. A few big knobs, called macros, control them all at once.", "purpose_function": "It lets a technician layer, split, and control multiple instruments as a single patch through simplified macro knobs. It exists to build rich combined sounds while keeping complex setups easy to play and automate.", "practical_application": "A technician builds an instrument rack to layer a piano under a pad, maps its key controls to macro knobs, and splits chains by key or velocity so one MIDI part triggers a full combined sound.", "category": "Virtual Instruments", "related_terms": ["Instrument library", "Keyboard mapping", "Keyswitch articulation", "Velocity layer", "Forward loop"], "common_mistakes": ["Confusing an instrument rack with an effects rack; the instrument rack must contain a sound source.", "Forgetting to map the macro knobs, so the rack's simple controls do nothing.", "Setting overlapping key or velocity zones by accident, so chains trigger together unexpectedly."], "scenario_contexts": ["Layering a piano and a pad into one playable patch.", "Splitting a keyboard so the left hand plays bass and the right plays lead.", "Assigning macro knobs to control several instruments at once during a performance."]}, "7482258a-c8c6-480b-9816-fbfeb1331afe": {"definition": "The assignment of samples or sounds to specific key (note) ranges, and often velocity ranges, across a MIDI keyboard, so that each key or zone triggers the correct sample at the correct pitch.", "plain_english": "This decides which key plays which recorded sound. A sampled note is spread across nearby keys so each one plays at the right pitch. It can also pick different recordings depending on how hard you hit the key.", "purpose_function": "It tells the sampler which sample to play for each note and velocity, spreading recordings across the keyboard. It exists so a limited number of recorded notes can cover the whole playable range convincingly.", "practical_application": "A technician creates key zones and velocity layers when building a sampled instrument, assigning each recorded note to a range of keys so the instrument sounds even and natural across the keyboard.", "category": "Sampling", "related_terms": ["Keyswitch articulation", "Instrument library", "Forward loop", "Velocity layer", "Instrument rack"], "common_mistakes": ["Stretching one sample across too many keys, causing unnatural pitch (the chipmunk effect).", "Leaving gaps between zones, so some keys make no sound.", "Confusing key mapping with keyswitching, which uses keys to change articulations rather than pitch."], "scenario_contexts": ["Building a sampled piano by mapping each recorded note to a small group of keys.", "Setting velocity layers so soft and hard hits load different samples.", "Fixing silent keys caused by a gap in the mapping."]}, "43f1dfef-86fd-4433-9ed9-26ec04e37f82": {"definition": "A technique in sampled instruments where dedicated MIDI keys, usually placed below or above the playable range, are used to switch between different performance articulations (such as legato, staccato, pizzicato, or tremolo) within a single loaded patch.", "plain_english": "Sampled instruments often include many playing styles, like short or smooth notes. Keyswitching uses special keys, usually the very low ones, to pick the style. You press one of those keys to change how the next notes sound, without loading a new patch.", "purpose_function": "It lets a player change playing styles instantly from the keyboard within one patch. It exists so realistic performances can mix articulations without reloading sounds or juggling many separate tracks.", "practical_application": "A technician plays or programs keyswitches to move a string patch between sustain, staccato, and pizzicato mid-phrase, often drawing the keyswitch notes into the MIDI track so articulations change on cue.", "category": "Sampling", "related_terms": ["Keyboard mapping", "Instrument library", "Instrument rack", "Velocity layer", "Forward loop"], "common_mistakes": ["Accidentally playing keyswitch notes as music, adding unwanted low notes to the part.", "Forgetting to set the articulation before a phrase, so it plays with the wrong style.", "Confusing keyswitches with normal mapped notes; keyswitch keys select articulations, not pitches."], "scenario_contexts": ["Switching a sampled violin between legato and staccato during a line.", "Drawing keyswitch notes into a MIDI track so articulations change automatically.", "Setting up a brass patch to jump between sustains and short stabs live."]}, "de3ae1ee-dce5-4d3a-8e8d-e3c13959fb28": {"definition": "A legato sample is a recording that captures the smooth, connected transition between two notes and is played back by a sampled instrument when notes overlap, so a melodic line sounds slurred rather than freshly re-attacked. In scripted sample libraries it is triggered by monophonic legato playing to reproduce the natural bend or crossfade from one pitch to the next.", "plain_english": "A legato sample is a recording of one note sliding smoothly into the next. Sample makers add it so a run of notes sounds joined up, like a singer gliding between words instead of stopping after each one.", "purpose_function": "It exists to reproduce the connected phrasing of a real player, where one note flows into the next without a new attack, which fixed single-note samples cannot convey. This makes sampled melodic lines sound expressive and human.", "practical_application": "A composer plays overlapping notes in a legato patch so the library engine swaps in transition samples, giving realistic slurred string or wind lines in a mockup.", "category": "Articulation", "related_terms": ["Marcato sample", "Monophonic mode", "Multi-sampled instrument", "Velocity layer", "Round robin"], "common_mistakes": ["Expecting legato transitions to sound when notes are played fully separated rather than overlapped", "Confusing a legato patch with simple synth portamento or glide", "Assuming any sustain sample will slur between notes without dedicated transition recordings"], "scenario_contexts": ["Programming a realistic solo violin melody in an orchestral mockup", "Building expressive lead lines with a sampled woodwind library", "Playing a flowing sampled-string line that must sound connected"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"72b0e103-1290-4b76-ac29-7f64fbf86eda": {"definition": "Linear frequency modulation is a form of frequency modulation in which the carrier's frequency deviation is directly proportional, in hertz, to the instantaneous amplitude of the modulating signal. Because the deviation is added linearly, the carrier-to-modulator frequency ratio and the resulting spectrum stay constant across the keyboard, giving consistent timbre at every pitch.", "plain_english": "Linear frequency modulation is a way one sound wave bends the pitch of another to build new tones. The amount of bend is a fixed step, so the sound keeps the same character all the way up and down the keyboard.", "purpose_function": "It lets one oscillator vary another's frequency to generate rich harmonic and inharmonic spectra from simple waveforms, which is the basis of FM synthesis. Keeping the modulation linear preserves the same timbre as notes move up or down the keyboard.", "practical_application": "A sound designer patches a modulator oscillator to a carrier's linear FM input on an FM or modular synth to create bell, electric-piano, or metallic tones that track evenly across the keys.", "category": "Synthesis", "related_terms": ["Frequency modulation", "Carrier", "Modulator", "Operator", "Exponential frequency modulation"], "common_mistakes": ["Confusing linear FM with exponential FM, which shifts the perceived pitch of a note as modulation is applied", "Assuming FM synthesis can only make harsh or metallic sounds rather than warm or bell-like tones", "Forgetting that the carrier-to-modulator ratio, not just the modulation amount, sets the harmonic character"], "scenario_contexts": ["Designing an electric-piano or bell patch on a DX-style FM synth", "Cross-modulating two oscillators on a modular synth for metallic timbres", "Building evolving inharmonic textures that hold their tone across the keyboard"]}, "c1bbd839-981a-4fc3-b2a6-eec472f7c23e": {"definition": "Live sampling is the practice of recording audio into a sampler or looper in real time during a performance or session and immediately making it available for playback, triggering, or manipulation. The captured audio can be replayed from pads or keys, looped, or processed on the fly rather than being prepared in advance.", "plain_english": "Live sampling means grabbing a sound as it happens and playing it back right away. A musician might record a drum hit on stage, then trigger it again from a keyboard moments later.", "purpose_function": "It exists to let performers capture and reuse sounds spontaneously, turning a live source into an instrument within the same performance. This supports improvisation, looping, and remixing without any pre-recorded material.", "practical_application": "A musician records a vocal phrase or guitar riff into a hardware looper or software sampler mid-set, then re-triggers and layers it to build an arrangement live.", "category": "Sampling technique", "related_terms": ["Sampler", "Looper", "Loop marker", "One-shot", "Overdub"], "common_mistakes": ["Not setting input levels before capture, so the live sample clips or is too quiet to use", "Failing to arm or monitor the correct input and recording silence or the wrong source", "Ignoring latency, so re-triggered samples fall out of time with the performance"], "scenario_contexts": ["Building a looped arrangement live from a vocal or guitar on stage", "Capturing a drummer's groove into a sampler to reuse during a set", "Grabbing ambient or found sounds during a session to sample instantly"]}, "6c42b005-61be-47b8-9af0-3df7f9292dc3": {"definition": "A loop marker is a point placed within a sample that defines where a repeated region begins or ends; a loop start marker and a loop end marker together set the segment that plays over and over to sustain the sound. When playback reaches the loop end it jumps back to the loop start and continues for as long as the note is held.", "plain_english": "A loop marker sets the start and end of a small chunk of sound that repeats. It lets a short recording hold a note for as long as you press the key.", "purpose_function": "Loop markers let a short recording sustain indefinitely by repeating a steady portion of it, saving memory and allowing held notes longer than the original recording. They define exactly which part of the sample cycles.", "practical_application": "An instrument builder drags the loop start and end markers into the steady sustain portion of a sampled note so held keys ring on smoothly without running out of audio.", "category": "Looping", "related_terms": ["Loop optimization", "Loop smoothing", "Sustain loop", "Zero crossing", "Sample editor"], "common_mistakes": ["Placing loop markers in the attack or decay, so the loop pumps or changes tone as it repeats", "Setting a marker off a zero crossing, causing an audible click at the loop point", "Making the loop too short, giving an unnatural buzzy or static sustain"], "scenario_contexts": ["Creating a sustaining organ or string patch from a short recorded note", "Editing a sampled pad so it holds indefinitely under a held key", "Fixing a looped instrument that clicks each time it repeats"]}, "33510e3b-a9b9-40db-9f03-77514be0ae6b": {"definition": "Loop optimization is the process of selecting and fine-tuning loop start and end points so a looped region repeats as seamlessly as possible, without clicks, level jumps, or timbral and pitch drift. It typically involves aligning the loop points to matching zero crossings and to waveform phase and amplitude that agree at the join.", "plain_english": "Loop optimization means picking the best spots to start and end a loop. Good spots make the repeat sound smooth, with no click or jump each time it comes around.", "purpose_function": "It exists to make a sustaining loop sound continuous and natural, hiding the fact that a short recording is being repeated. Careful optimization prevents the pops and pulsing that give a loop away.", "practical_application": "A sound designer nudges the loop points and searches for matching zero crossings in a sample editor until a held note loops with no audible seam.", "category": "Looping", "related_terms": ["Loop marker", "Loop smoothing", "Zero crossing", "Crossfade loop", "Sustain loop"], "common_mistakes": ["Choosing loop points by eye alone instead of listening for clicks and pulsing", "Ignoring slow amplitude or brightness changes, so the loop swells or dulls as it repeats", "Setting loop points where the waveform level or phase does not match, causing a click"], "scenario_contexts": ["Refining loop points on a sampled string note for a smooth sustain", "Preparing a memory-efficient loop for a sample-based instrument", "Troubleshooting a patch that thumps or pulses on held notes"]}, "ab270b1a-8021-4c26-b3ae-48ded6459da2": {"definition": "Loop smoothing is a technique that blends the audio around a loop's join to remove audible clicks or discontinuities, most commonly by crossfading the end of the loop into its start so the transition is inaudible. It is applied when loop points alone cannot be made to match perfectly.", "plain_english": "Loop smoothing blends the two ends of a loop so the join is not heard. It works like fading one part into the other to hide the seam.", "purpose_function": "It exists to disguise the seam of a repeated loop, producing a smooth, continuous sustain even from material that does not loop cleanly on its own. Crossfading averages out the mismatches at the join.", "practical_application": "In a sampler's loop editor, a technician applies a crossfade of a set length across the loop point to erase a click that could not be removed by moving the markers.", "category": "Looping", "related_terms": ["Crossfade loop", "Loop optimization", "Loop marker", "Zero crossing", "Sustain loop"], "common_mistakes": ["Using too long a crossfade, which blurs transients and dulls the looped tone", "Relying on smoothing to fix badly chosen loop points instead of first optimizing them", "Applying a crossfade that creates a phasey or flanged sound when the two ends are out of phase"], "scenario_contexts": ["Crossfading a loop on a sustained pad that would otherwise click", "Smoothing a looped ambient texture with slowly changing content", "Salvaging a loop in busy material where clean loop points are impossible"]}, "985f84b6-130c-4d84-812b-b36bf917f754": {"definition": "A marcato sample is a recording of a note performed with marcato articulation, meaning marked, strongly accented and somewhat detached, captured as a distinct articulation within a sampled instrument. It supplies the emphatic, sharply attacked version of a note alongside other articulations such as sustain, staccato, and legato.", "plain_english": "A marcato sample is a recording of a note played with a hard, punchy accent. Libraries include it so players can pick a strong, marked attack when the music needs it.", "purpose_function": "It exists so a sampled instrument can render forcefully accented notes, which have a harder attack and fuller body than plain or short notes. Including it lets orchestral mockups deliver marked, emphatic passages authentically.", "practical_application": "A composer switches to the marcato articulation via a keyswitch to give a brass or string line a strong, accented punch on stressed beats.", "category": "Articulation", "related_terms": ["Legato sample", "Multi-sampled instrument", "Keyswitch", "Velocity layer", "Staccato"], "common_mistakes": ["Using sustain samples with added volume instead of true marcato recordings for accented notes", "Confusing marcato with staccato, which is short and detached rather than marked and weighty", "Overusing marcato so every note is accented, which loses its emphasis"], "scenario_contexts": ["Writing an emphatic brass fanfare in an orchestral template", "Accenting strong beats in a string ostinato with marked attacks", "Programming a bold, accented film-score hit"]}, "cd08db3d-38eb-4bdb-8ccf-0546395cc926": {"definition": "Monophonic mode is a playback setting in which an instrument sounds only one note at a time; pressing a new key steals the single available voice from the note currently sounding. It is used to emulate single-voice instruments and to enable legato and glide behavior between successive notes.", "plain_english": "Monophonic mode lets an instrument play only one note at a time. Press a new key and it cuts off the old note, just like you can only whistle one pitch at once.", "purpose_function": "It exists to reproduce instruments that sound only one note at once, such as a solo wind or a classic mono synth bass, and to make note-to-note effects like portamento and legato possible. Limiting to one voice also keeps basslines and leads tight and predictable.", "practical_application": "A player selects mono mode on a synth or sample patch so overlapping notes glide or slur into each other for a smooth lead or bass line.", "category": "Playback mode", "related_terms": ["Legato sample", "Polyphony", "Portamento", "Voice", "Note priority"], "common_mistakes": ["Expecting chords to sound in mono mode, when only the last or highest-priority note plays", "Confusing monophonic mode with a single-oscillator sound; mono refers to voice count, not tone", "Not setting note priority, so held notes retrigger unexpectedly"], "scenario_contexts": ["Playing a gliding synth bassline that must not overlap", "Emulating a solo wind instrument that sounds one note at a time", "Setting up legato lead patches for expressive slurred playing"]}, "fd6685af-7a16-451e-879e-84c2213bde19": {"definition": "A multi-sampled instrument is a sampled or virtual instrument built from many individual recordings of a source instrument taken at different pitches and often different dynamic levels, mapped across the keyboard and velocity range. Using many samples rather than stretching one avoids the unnatural timbre and pitch artifacts of transposing a single recording too far.", "plain_english": "A multi-sampled instrument is built from many separate recordings of a real instrument. It uses a different clip for each note and each volume. That makes it sound far more real than stretching one recording.", "purpose_function": "It exists to reproduce a real instrument convincingly by covering its range with closely spaced recordings, so each note and dynamic sounds like the actual source rather than a pitch-shifted copy. More samples mean more realistic timbre across pitch and loudness.", "practical_application": "A producer loads a multi-sampled piano whose keys trigger recordings captured at several velocities, giving realistic tone and dynamics from soft to loud.", "category": "Sampling", "related_terms": ["Multisample", "Velocity layer", "Key mapping", "Round robin", "Sample zone"], "common_mistakes": ["Assuming one recording stretched across the keyboard sounds as real as a proper multisample", "Stretching sample zones too wide, producing a chipmunk or detuned sound at the edges", "Ignoring velocity layers, so soft and loud playing sound identical"], "scenario_contexts": ["Loading a realistic multi-sampled piano or strings for a production", "Building a sampled instrument by mapping recordings across the keys", "Choosing a detailed library with many velocity layers for expressive parts"]}, "d45e57ba-0aab-4b7d-82fc-d17dd44cdefe": {"definition": "An electronic instrument, such as a synthesizer or sampler, that can produce two or more different sounds (timbres) at the same time, each typically assigned to its own MIDI channel and voiced independently.", "plain_english": "One keyboard or sound module that can play several different sounds at once. Think of it as a small band inside one box, where each part gets its own channel.", "purpose_function": "It lets a single device behave like several instruments at once, so one unit can play bass, drums, and pads together, which is essential for building full arrangements from a MIDI sequence.", "practical_application": "A producer assigns each track in a MIDI sequence to a different channel on one multitimbral module, layering a whole arrangement without needing separate hardware for each part.", "category": "Synthesis", "related_terms": ["Polyphony", "MIDI channel", "Patch", "Sound module", "Voice allocation", "General MIDI"], "common_mistakes": ["Confusing multitimbral (many sounds at once) with polyphonic (many notes of one sound at once).", "Assuming any polyphonic synth is automatically multitimbral, when many are not.", "Running out of voices because all timbres draw from one shared voice pool."], "scenario_contexts": ["Sequencing a full song from one hardware sound module using separate MIDI channels.", "Hosting several instruments on one software sampler instance in a DAW.", "Setting up a General MIDI module so each channel plays a different patch."]}, "e4134fad-5b1b-47cb-9510-024941f95b19": {"definition": "A sound source in a synthesizer that generates noise, a signal made of a broad, random spread of frequencies (such as white or pink noise), rather than a periodic, pitched waveform.", "plain_english": "A part of a synth that makes a rushing, hiss-like sound instead of a musical note. It is like the static between radio stations, and it is useful for wind, breath, or drum sounds.", "purpose_function": "It supplies unpitched, broadband material for percussion, wind and breath effects, and for adding texture or a sharper attack to pitched sounds.", "practical_application": "A sound designer routes a short burst of the noise oscillator through a fast-decaying filter to build a snare or hi-hat, or adds a little under a pad for breathiness.", "category": "Oscillators", "related_terms": ["White noise", "Pink noise", "Oscillator", "Subtractive synthesis", "Envelope generator", "Filter cutoff"], "common_mistakes": ["Expecting a noise oscillator to track pitch, when it has no fundamental frequency to follow.", "Confusing white noise (equal energy per hertz) with pink noise (equal energy per octave).", "Leaving noise level too high, which masks the pitched oscillators."], "scenario_contexts": ["Building electronic snare and hi-hat sounds from filtered noise.", "Adding breath noise to a flute or vocal patch.", "Creating wind, ocean, or riser effects for film and game audio."]}, "8155b024-a52d-488f-8272-e31dac60b08b": {"definition": "A digital oscillator that generates a periodic waveform by repeatedly incrementing a phase accumulator with a numeric tuning value and using the accumulated phase to look up or compute each output sample; its frequency is set precisely by that number. It is the core of direct digital synthesis (DDS).", "plain_english": "A digital sound generator whose pitch is set by a number instead of a control voltage. Because a computer counts the number, the tuning stays exact and does not slip.", "purpose_function": "It produces very stable, precisely tunable tones in digital synths and radio gear, replacing the drift-prone analog voltage-controlled oscillator with exact numeric control.", "practical_application": "In a digital synthesizer or wireless system, technicians rely on the numerically controlled oscillator to hold pitch and frequency dead-on across temperature changes and over time.", "category": "Oscillators", "related_terms": ["Voltage-controlled oscillator", "Phase accumulator", "Direct digital synthesis", "Sample rate", "Wavetable", "Oscillator drift"], "common_mistakes": ["Assuming a numeric oscillator cannot alias, when its harmonics still fold back if not band-limited.", "Confusing the oscillator (frequency source) with the DAC that converts its samples to analog.", "Thinking more accumulator bits raise the pitch, when they raise tuning resolution."], "scenario_contexts": ["Setting the carrier frequency in a digital wireless microphone system.", "Generating stable, precisely tuned test tones in signal-generator instruments.", "Producing exactly tuned waveforms in a software or DSP synthesizer."]}, "47bf0269-6453-46dd-aeae-4d7666601ccb": {"definition": "The appearance of false, inharmonic frequencies when a digital oscillator produces harmonic content above the Nyquist frequency (half the sample rate); those over-range components fold back down into the audible band as tones unrelated to the intended pitch.", "plain_english": "Unwanted, out-of-tune tones that show up when a digital synth tries to make sounds too high for its sample rate. The extra highs fold back down like a mirror and sound harsh or metallic.", "purpose_function": "It is an artifact to avoid rather than a feature; understanding it lets designers use band-limited oscillators so bright digital tones stay clean instead of gaining clangy, detuned overtones.", "practical_application": "An engineer hearing a gritty, bell-like edge on the high notes of a cheap digital synth recognizes aliasing and switches to a band-limited oscillator or an oversampled plug-in.", "category": "Digital Audio", "related_terms": ["Nyquist frequency", "Sample rate", "Band-limited oscillator", "Oversampling", "Anti-aliasing filter", "Sampling theorem"], "common_mistakes": ["Confusing aliasing artifacts with normal bright harmonics.", "Believing a higher sample rate fully removes aliasing, when it only raises the fold point.", "Ignoring aliasing on high-pitched or hard-sync patches, where it is worst."], "scenario_contexts": ["Hearing metallic overtones on the top octave of a virtual analog synth.", "Choosing an oversampled soft synth to keep bright leads clean.", "Comparing band-limited versus naive digital waveforms during sound design."]}, "c7b1ba9f-981f-4668-9516-8e0ba66db001": {"definition": "A technique in which the output of one oscillator or waveform is gradually faded down while another is faded up, so the sound morphs smoothly between the two sources instead of switching abruptly.", "plain_english": "Slowly blending from one synth sound into another so the change is smooth, not a sudden jump. It works like a DJ fading between two songs so you never hear a hard cut.", "purpose_function": "It lets a synth move smoothly between two timbres, often driven by an envelope, LFO, or mod wheel, to create evolving, animated tones without clicks or steps.", "practical_application": "A sound designer maps the mod wheel to crossfade between a soft and a bright oscillator, sweeping the timbre live during a performance.", "category": "Synthesis", "related_terms": ["Oscillator", "Wavetable", "LFO", "Modulation", "Vector synthesis", "Oscillator detuning"], "common_mistakes": ["Confusing a crossfade (smooth blend) with an abrupt oscillator switch.", "Setting a fade whose midpoint dips in level when the two sources are out of phase.", "Forgetting to assign a modulation source, so the crossfade never actually moves."], "scenario_contexts": ["Blending two wavetables with the mod wheel during a solo.", "Using vector synthesis to move between four oscillators with a joystick.", "Morphing a pad slowly from dark to bright over a long envelope."]}, "db147f80-8578-42b4-84f4-5f76170b0c7e": {"definition": "Deliberately offsetting the pitch of one oscillator slightly relative to another (typically by a few cents) so the two waveforms drift in and out of phase, producing beating and a thicker, chorused sound.", "plain_english": "Setting two synth oscillators a tiny bit apart in pitch so they clash gently and sound fatter. It is the same shimmer you hear when two singers are almost, but not quite, in tune.", "purpose_function": "It fattens and animates a sound by creating slow beating between oscillators, the classic way to get big, wide, analog-style leads and pads from otherwise static tones.", "practical_application": "To thicken a lead, a player detunes the second oscillator a few cents from the first, adjusting the amount by ear for a wider or more aggressive sound.", "category": "Synthesis", "related_terms": ["Beating", "Unison", "Oscillator fine tune", "Chorus", "Cents", "Supersaw"], "common_mistakes": ["Detuning so far that the two oscillators sound like separate, out-of-tune notes.", "Confusing detune (small and musical) with a coarse pitch or interval offset.", "Forgetting that detuned unison stacks use extra voices of polyphony."], "scenario_contexts": ["Fattening a saw lead by detuning a second oscillator a few cents.", "Building a supersaw pad from many slightly detuned copies.", "Adding movement to a bass by lightly detuning a sub oscillator."]}, "bcd7730a-ef95-46c8-bd11-cbeb4b17c08a": {"definition": "Slow, small, and somewhat random variation in an oscillator's pitch over time, caused in analog circuits by temperature changes and component tolerances; many digital synths model it intentionally to add analog-style warmth and movement.", "plain_english": "The way an old analog synth's tuning wanders a little on its own. Modern synths often copy this gentle wobble because it makes the sound feel warm and alive instead of frozen.", "purpose_function": "As a fault it causes tuning instability that calls for warm-up and calibration; as a modeled effect it adds subtle, ever-changing detuning that keeps stacked oscillators from sounding sterile.", "practical_application": "A technician lets a vintage analog synth warm up and retunes it before a session, while a producer may dial a little modeled drift into a soft synth for character.", "category": "Oscillators", "related_terms": ["Oscillator detuning", "Voltage-controlled oscillator", "Tuning stability", "Analog modeling", "Oscillator fine tune", "Temperature compensation"], "common_mistakes": ["Assuming drift means the synth is broken, when a short warm-up and retune usually fixes it.", "Adding too much modeled drift, leaving the patch sounding out of tune.", "Forgetting that older analog gear needs periodic tuning before recording."], "scenario_contexts": ["Warming up and retuning a vintage analog synth before tracking.", "Adding modeled drift to a virtual analog patch for realism.", "Diagnosing pitch instability traced to a temperature-sensitive oscillator."]}, "d8d8f34b-a217-4f57-bb2b-733f05d9db06": {"definition": "A control that adjusts an oscillator's pitch in small increments, usually measured in cents (hundredths of a semitone), for precise tuning against other oscillators or instruments, as opposed to coarse tuning in semitones.", "plain_english": "A knob that shifts a synth's pitch by very small steps. You use it to tune the synth exactly to other sounds, like the fine tuner on a guitar.", "purpose_function": "It gives the small pitch resolution needed to match an oscillator precisely to another source, or to set a deliberate slight detune, separate from coarse semitone steps.", "practical_application": "A player nudges the fine tune a few cents to lock a synth to a recorded track, or to introduce a gentle detune between two oscillators.", "category": "Oscillators", "related_terms": ["Coarse tune", "Cents", "Oscillator detuning", "Concert pitch", "Unison", "Oscillator key tracking"], "common_mistakes": ["Confusing fine tune (cents) with coarse tune (semitones).", "Leaving a small offset dialed in and wondering why the synth sits slightly out of tune.", "Fine-tuning by ear against a drifting analog reference instead of a stable one."], "scenario_contexts": ["Matching a synth's pitch to a sampled or acoustic track.", "Setting a small detune between two oscillators for width.", "Zeroing fine tune to return a patch to standard concert pitch."]}, "9a42ba68-7196-423f-aff6-9864ecd2c0b6": {"definition": "A setting that makes an oscillator's pitch follow the note played on the keyboard, so higher keys raise the oscillator's frequency proportionally; at full (100%) tracking the oscillator stays in equal-tempered tune across the keyboard, and reduced tracking makes pitch change less than one semitone per key.", "plain_english": "This makes a synth oscillator change pitch to match the key you press, so it plays in tune up and down the keyboard. Turn it down and the notes get closer together, which is handy for drum or effect sounds.", "purpose_function": "It keeps oscillators musically in tune across the keyboard, and when reduced or switched off it lets a sound hold a fixed or compressed pitch range, which is useful for percussion and effects.", "practical_application": "A sound designer leaves key tracking full for melodic patches but lowers it on a noise or percussion layer so the sound barely changes pitch from key to key.", "category": "Oscillators", "related_terms": ["Keyboard tracking", "Filter key tracking", "Oscillator fine tune", "Equal temperament", "Pitch", "Envelope generator"], "common_mistakes": ["Confusing oscillator key tracking with filter key tracking, which follows pitch for the cutoff.", "Turning tracking down and then wondering why higher notes play flat.", "Assuming every oscillator tracks the keyboard, when drones and some effects deliberately do not."], "scenario_contexts": ["Keeping a lead in tune across the whole keyboard.", "Reducing tracking on a drum layer so its pitch stays nearly constant.", "Setting an oscillator to a fixed pitch for a special-effect or drone sound."]}, "5a7d3b4d-ab00-4023-9a5f-1e9e9bba42da": {"definition": "The relative level balance between two or more oscillators within a single synthesizer voice, setting how much each oscillator contributes to the combined signal before it reaches the filter and amplifier stages.", "plain_english": "A control that sets how loud each sound source is inside a synth. Like a tiny mixer, it blends two or more tone generators into one sound.", "purpose_function": "It lets a synth blend the timbres of several oscillators, so one patch can combine different waveforms or tunings into a single richer tone.", "practical_application": "A sound designer adjusts the oscillator mix to favor a bright saw over a softer sub oscillator, dialing in the body and edge of a bass or lead patch.", "category": "Oscillator control", "related_terms": ["Oscillator spread", "Oscillator octave", "Waveform", "Detune", "Filter"], "common_mistakes": ["Assuming the mix control changes tuning or pitch rather than only the level balance", "Turning one oscillator fully off and forgetting it, then blaming the filter for a thin sound", "Confusing oscillator mix with the master output level of the whole voice"], "scenario_contexts": ["Blending a saw and a square oscillator for a fuller analog-style lead", "Balancing a sub oscillator under a main oscillator for a solid bass", "Crossfading between two oscillators to morph a pad's character"]}, "eb912ce7-5d13-4897-b3b9-81d1922cc148": {"definition": "A routing grid in a synthesizer that assigns modulation sources such as LFOs, envelopes, and controllers to oscillator parameters like pitch, level, phase, and waveshape, each with an adjustable modulation depth.", "plain_english": "A grid that connects control signals to a synth's tone generators. You pick a source, pick what it changes on the oscillator, then set how strong the change is.", "purpose_function": "It gives flexible, freely assignable control over how oscillators change through time, so one synth can create motion and expression without fixed wiring.", "practical_application": "A programmer routes an envelope to oscillator pitch and an LFO to oscillator level in the matrix, building an evolving lead without touching a patch cable.", "category": "Oscillator control", "related_terms": ["Oscillator pitch envelope", "LFO", "Envelope", "Oscillator mix", "Modulation depth"], "common_mistakes": ["Leaving a modulation depth at zero and expecting to still hear the effect", "Routing several sources to the same destination and losing track of why the pitch drifts", "Confusing the modulation source with the destination when filling in a row"], "scenario_contexts": ["Assigning an LFO to oscillator pitch to add vibrato", "Routing a velocity signal to oscillator level for dynamic patches", "Stacking several oscillator modulations to build an evolving texture"]}, "5d60aa2d-e6fc-49f2-aaab-a54d1dba1fdb": {"definition": "A coarse tuning control that transposes an oscillator's pitch up or down in whole-octave steps, each step doubling or halving the frequency, without changing the note played on the keyboard.", "plain_english": "A switch that moves a synth's tone up or down by whole octaves. Each step doubles or halves the pitch, so the same key sounds higher or lower.", "purpose_function": "It lets oscillators be stacked at different octaves for a fuller sound, or shifts a patch into a usable range for bass or lead parts.", "practical_application": "A player sets one oscillator an octave below another to thicken a lead, or drops an oscillator two octaves to build a deep bass patch.", "category": "Oscillator tuning", "related_terms": ["Oscillator semitone", "Detune", "Oscillator mix", "Waveform", "Unison"], "common_mistakes": ["Confusing the octave control, which moves in whole octaves, with semitone or fine detune tuning", "Forgetting that an octave shift moves the whole keyboard range, not just one note", "Shifting so far that the sound leaves the useful audible range"], "scenario_contexts": ["Setting oscillators an octave apart for a rich stacked lead", "Dropping an oscillator an octave for a sub-heavy bass", "Matching a synth's octave to another instrument's range"]}, "bf739f74-3cc1-4614-9e9a-e180dc146d56": {"definition": "A function that forces an oscillator's waveform to restart from a fixed point in its cycle, usually at note-on, so each note begins at the same phase instead of at a free-running position.", "plain_english": "A setting that makes a synth's wave start at the same spot every time you play a note. It keeps each note's beginning steady instead of random.", "purpose_function": "It gives repeatable attacks and predictable phase relationships between oscillators, which matters for tight transients and consistent layering.", "practical_application": "A sound designer turns on phase reset so a plucky bass has the same punchy attack on every note instead of a slightly different click each time.", "category": "Oscillator control", "related_terms": ["Oscillator stereo phase", "Phase modulation", "Waveform", "Oscillator mix", "Transient"], "common_mistakes": ["Leaving phase reset off, then wondering why bass attacks sound inconsistent", "Assuming phase reset changes the timbre rather than only the start point", "Turning reset on for every oscillator and losing the natural width of free-running phase"], "scenario_contexts": ["Getting consistent punch on a plucked bass patch", "Aligning two oscillators for a tight in-phase attack", "Recording repeated notes that must sound identical"]}, "d73a075e-2b50-4ccd-8ad4-99331cfd13c0": {"definition": "An envelope generator routed to oscillator pitch that sweeps the frequency over time through its stages, such as attack and decay, to create pitched glides, blips, or drum-like transients.", "plain_english": "A control that changes a synth's pitch on its own over time. It can make a note swoop up or drop down right after you press a key.", "purpose_function": "It adds pitched motion to a sound, from a subtle attack blip to a big sweep, without the player having to move a pitch control by hand.", "practical_application": "A producer sets a fast, quickly decaying pitch envelope on an oscillator to create the classic snap of an electronic kick or a laser-like zap.", "category": "Oscillator control", "related_terms": ["Envelope", "Oscillator modulation matrix", "Oscillator semitone", "Oscillator octave", "LFO"], "common_mistakes": ["Setting the envelope depth so high that notes sound out of tune", "Confusing a pitch envelope with an amplitude envelope that controls volume", "Using a slow decay when a fast one is needed for a short percussive blip"], "scenario_contexts": ["Creating the pitch snap at the start of an electronic kick drum", "Adding a rising sweep to a synth lead's attack", "Designing sci-fi laser and zap sound effects"]}, "3e657d14-dbd0-4cfe-b9bf-b2a76b5b5440": {"definition": "A coarse tuning control that transposes an oscillator's pitch in semitone steps, the half-step increments of the equal-tempered scale, so stacked oscillators can be set to intervals such as a fifth or an octave.", "plain_english": "A control that shifts a synth's pitch by half-steps, the smallest steps on a keyboard. It lets you tune one tone generator to a musical interval above or below another.", "purpose_function": "It lets oscillators be tuned to musical intervals, so a patch can sound like a chord or a harmonized stack from a single key press.", "practical_application": "A programmer tunes a second oscillator seven semitones up to add a fifth, giving a lead an instant power-chord character.", "category": "Oscillator tuning", "related_terms": ["Oscillator octave", "Detune", "Oscillator mix", "Unison", "Waveform"], "common_mistakes": ["Confusing semitone steps with fine, cents-based detune", "Miscounting semitones and landing on a dissonant interval", "Forgetting that twelve semitones add up to one octave"], "scenario_contexts": ["Tuning a second oscillator up a fifth for a power-chord lead", "Building harmonized stabs from a single key", "Setting a minor-third interval for a specific chord color"]}, "a46ea787-d874-435f-a6d3-d78e9242e5a2": {"definition": "A control that detunes, and often pans, a set of stacked or unison oscillator voices away from a center pitch, widening the sound in both frequency and stereo image as the spread amount increases.", "plain_english": "A control that slightly retunes and spreads copies of a synth's sound. It makes one note feel wide, thick, and lush, like many players at once.", "purpose_function": "It builds a fat, wide unison sound from a single oscillator by layering slightly detuned copies, adding chorus-like richness and stereo width.", "practical_application": "A producer raises the oscillator spread on a supersaw to turn a thin lead into a huge, wide trance chord stack.", "category": "Oscillator control", "related_terms": ["Unison", "Detune", "Oscillator stereo phase", "Oscillator mix", "Chorus"], "common_mistakes": ["Adding so much spread that the pitch sounds out of tune", "Confusing spread with simple stereo panning of one voice", "Relying on heavy spread on a mono system, where the width collapses"], "scenario_contexts": ["Making a supersaw lead wide for trance and EDM", "Thickening a pad with a gentle detune spread", "Widening a bass's upper harmonics while keeping the low end mono"]}, "1aa225d3-cc6f-4eda-8fd3-a1239e748d7c": {"definition": "A parameter that offsets the starting phase of an oscillator's waveform between the left and right channels, producing a stereo width effect from what would otherwise be a mono oscillator signal.", "plain_english": "A control that starts a synth's wave at slightly different points in the left and right speakers. That small difference makes one sound feel wider.", "purpose_function": "It widens a single oscillator into a stereo image without adding extra voices, which is handy for spacious pads and leads.", "practical_application": "A sound designer offsets an oscillator's stereo phase to spread a pad across the stereo field while keeping its pitch and level unchanged.", "category": "Oscillator control", "related_terms": ["Oscillator phase reset", "Oscillator spread", "Unison", "Waveform", "Oscillator mix"], "common_mistakes": ["Adding heavy stereo phase, then losing the sound when the mix is summed to mono", "Confusing stereo phase width with panning", "Assuming it changes the timbre rather than only the stereo image"], "scenario_contexts": ["Widening a mono pad into a stereo texture", "Adding space to a lead without extra unison voices", "Checking mono compatibility after setting stereo phase"]}, "bd94f28a-ff36-4794-b01d-21f0c2e01ae0": {"definition": "A synthesis technique in which the instantaneous phase of a carrier oscillator is varied by a modulator signal, generating new harmonic sidebands; it is closely related to frequency modulation and underlies many digital FM-style synthesizers.", "plain_english": "A way to make new tones by using one wave to nudge the timing of another. This creates rich, complex sounds like bells, metal tones, and electric pianos.", "purpose_function": "It produces complex, harmonically rich timbres that are hard to make by filtering alone, and it is the core method behind classic digital FM synthesis.", "practical_application": "A sound designer builds a bell or electric-piano patch by modulating one operator's phase with another, tuning their frequency ratio for the desired harmonic character.", "category": "Synthesis technique", "related_terms": ["Frequency modulation", "Oscillator modulation matrix", "Oscillator phase reset", "Waveform", "LFO"], "common_mistakes": ["Confusing phase modulation with simple vibrato-style pitch modulation", "Assuming phase and frequency modulation are entirely unrelated", "Expecting rich FM sidebands from a slow, low-frequency modulator instead of an audio-rate one"], "scenario_contexts": ["Programming electric-piano and bell tones on an FM-style synth", "Creating metallic and clangorous percussion timbres", "Designing evolving digital textures by tuning operator ratios"]}, "7d0993c6-9afb-4b8a-98cc-7202336eb0fa": {"definition": "A curated collection of multisampled piano recordings — typically captured at many pitches and velocity layers, with released and pedal-resonance samples — packaged for playback in a sampler or dedicated virtual instrument.", "plain_english": "A piano library is a big set of recordings made from a real piano. You load it into music software so your keyboard can sound like that piano.", "purpose_function": "It lets a musician play a realistic acoustic or electric piano tone from a controller without a physical instrument, by mapping recorded notes across the keyboard. It exists because a single sampled note cannot capture the timbral changes across pitch and dynamics that real pianos produce.", "practical_application": "A technician loads the library into a sampler, sets the disk-streaming and RAM options for the machine, and adjusts velocity mapping and pedal-resonance settings to fit the mix and CPU budget.", "category": "Sampled instruments", "related_terms": ["Multisample", "Velocity layer", "Sample library", "Round-robin", "Disk streaming", "Preload buffer"], "common_mistakes": ["Assuming one recorded note can be stretched across the whole keyboard without audible artifacts, instead of using many sampled pitches", "Loading the full uncompressed library into RAM when disk streaming would use far less memory", "Ignoring velocity layers, so soft and loud playing sound identical"], "scenario_contexts": ["Producing a pop ballad that needs a convincing acoustic grand piano part", "Scoring to picture where a live piano session is not budgeted", "Live performance using a MIDI controller and laptop instead of hauling a real piano"]}, "87696b64-a201-4fa0-8b63-a1e37a262687": {"definition": "A sample loop mode that plays the looped region forward to its end, then backward to its start, alternating direction indefinitely (also called a bidirectional or alternating loop) rather than jumping straight back to the loop start.", "plain_english": "A ping-pong loop plays a short sound forward, then backward, over and over. It bounces back and forth like a ball, so a held note can keep going smoothly.", "purpose_function": "It sustains a sampled sound for as long as a key is held while avoiding the click or discontinuity that a forward-only loop can produce at its splice point. Reversing at each end can make the loop join smoother and reduce an obvious repeating pulse.", "practical_application": "When editing a sustaining sample, a technician selects ping-pong (bidirectional) loop mode in the sampler and sets loop start and end points at zero crossings so the direction changes are seamless.", "category": "Sample looping", "related_terms": ["Sustain loop", "Loop point", "Zero crossing", "Crossfade loop", "Forward loop", "Sample editor"], "common_mistakes": ["Confusing ping-pong looping with a ping-pong (stereo) delay effect, which is unrelated", "Setting loop points off a zero crossing, causing clicks at each direction change", "Using it on a sound with strong transients, where the reversed pass sounds unnatural"], "scenario_contexts": ["Building a smooth sustaining pad from a short recorded sample", "Repairing a looped instrument sample that clicks with a forward-only loop", "Creating an evolving texture where the back-and-forth motion is desirable"]}, "8953e4c5-8313-4da1-b9bf-b42b5bab6f21": {"definition": "A sampling technique in which a single recorded sample is played back faster or slower to sound higher or lower in pitch, transposing it across a range of notes rather than recording every note individually.", "plain_english": "This is a trick where one recorded note is sped up or slowed down to make other notes. Playing it faster makes it higher, and slower makes it lower.", "purpose_function": "It lets a sampler cover a full keyboard from only a few recordings, saving memory and recording effort. It exists because early samplers had limited memory, and it remains useful for spreading any sample across pitches.", "practical_application": "A technician assigns a sample to a key zone and lets the sampler transpose it for nearby keys, adding more sample zones when the shifted tone strays too far and starts to sound unnatural.", "category": "Sampling technique", "related_terms": ["Multisample", "Key zone", "Transposition", "Mickey Mouse effect", "Root key", "Time stretching"], "common_mistakes": ["Stretching one sample too far, producing the sped-up 'chipmunk' sound because playback speed and pitch change together", "Confusing simple pitch-shift sampling with formant-corrected pitch shifting, which preserves timbre", "Forgetting to set the correct root key, so notes play at the wrong pitch"], "scenario_contexts": ["Mapping a single instrument recording across a keyboard to save memory", "Detuning a drum hit up or down for variation", "Building a quick playable instrument from one field recording"]}, "1086b2e4-fb23-454e-bc0c-6e3d6d2b263e": {"definition": "A recorded sample of a string instrument note produced by plucking the string with a finger (pizzicato articulation) rather than bowing it, giving a short, percussive, quickly decaying tone.", "plain_english": "A pizzicato sample is a recording of a string being plucked with a finger instead of bowed. It gives a short, punchy note like a plucked guitar string.", "purpose_function": "It provides the plucked articulation of orchestral strings within a sampled string library so composers can switch between bowed and plucked playing. It exists because pizzicato has a distinct attack and decay that a bowed sample cannot imitate.", "practical_application": "A technician selects the pizzicato articulation via a keyswitch or separate patch in a string library, then tightens note timing since the short attack exposes any looseness.", "category": "Sampled instruments", "related_terms": ["Articulation", "Keyswitch", "Sample library", "Velocity layer", "Legato", "Round-robin"], "common_mistakes": ["Using bowed (arco) samples where pizzicato is written, losing the plucked attack", "Adding long reverb tails that blur the short, defined pizzicato notes", "Ignoring round-robin variations, so repeated plucks sound mechanically identical"], "scenario_contexts": ["Scoring a light, plucked string passage for film or games", "Layering pizzicato strings under a rhythmic pop arrangement", "Switching mid-phrase from bowed to plucked strings via a keyswitch"]}, "c3d7f6e6-94b9-41df-a545-b0e6d77a0e82": {"definition": "The maximum number of voices (simultaneous notes or sample playbacks) a sampler or synthesizer can sound at once, set by its hardware or software voice allocation; requests beyond this cap trigger voice stealing.", "plain_english": "The polyphony limit is the largest number of notes a sampler can play at the same time. Go past it and the oldest notes get cut off to make room.", "purpose_function": "It bounds the processing and memory the instrument must devote to active voices, keeping playback stable. It exists because every sounding voice consumes CPU and RAM, which are finite.", "practical_application": "A technician raises or lowers the voice limit to balance rich sustained playing against CPU load, watching for dropped notes and increasing the cap or freezing tracks when voice stealing becomes audible.", "category": "Voice management", "related_terms": ["Voice stealing", "Monophonic", "Sustain pedal", "Sample streaming", "CPU load", "Note priority"], "common_mistakes": ["Blaming a bad recording for notes that cut off, when the polyphony limit is causing voice stealing", "Forgetting that a held sustain pedal keeps voices alive and quickly exhausts the limit", "Setting the limit needlessly high and overloading the CPU"], "scenario_contexts": ["Playing dense sustained piano passages with the sustain pedal down", "Layering several sampled instruments in one project and running out of voices", "Optimizing an older hardware sampler with a low fixed voice count"]}, "ae29d43b-1477-4f15-9281-66f5df466a12": {"definition": "In a disk-streaming sampler, the initial portion of each sample held in RAM so a note can start instantly while the remainder is streamed from disk; its size trades memory use against reliable streaming under load.", "plain_english": "A preload buffer is a small first piece of each sound kept ready in memory. It lets a note start right away while the rest is read from the drive.", "purpose_function": "It hides the delay of reading from storage so notes begin without lag, letting large libraries play from disk instead of loading fully into RAM. It exists because disk access is too slow to fetch a sample's start on demand.", "practical_application": "A technician tunes the preload buffer size for the drive and project — larger for slow drives or high voice counts to prevent dropouts, smaller to save RAM when memory is tight.", "category": "Sample streaming", "related_terms": ["Disk streaming", "Sample library", "Latency", "Buffer size", "Voice stealing", "RAM"], "common_mistakes": ["Setting the preload buffer too small on a slow drive, causing audible dropouts or clicks at note starts", "Making it needlessly large and wasting RAM that other instruments need", "Confusing the sample preload buffer with the audio interface's I/O buffer, which controls monitoring latency"], "scenario_contexts": ["Streaming a large orchestral library from an SSD in a big session", "Troubleshooting note-start dropouts on a mechanical hard drive", "Balancing RAM between many streamed instruments in one project"]}, "6f8579b7-f939-42bb-9026-a82f6204c9d4": {"definition": "Recording audio into a sampler and making it immediately available for triggered playback, so a sound can be captured and performed with little or no processing delay, as opposed to pre-loading edited samples in advance.", "plain_english": "Real-time sampling means recording a sound and playing it back almost instantly. You can grab a sound and jam with it right away.", "purpose_function": "It lets a performer capture a source on the spot and play it across the keys during a session or show. It exists to support live remixing, beat-making, and improvisation where waiting to edit a sample is impractical.", "practical_application": "A technician arms the sampler's input, captures a phrase or hit from a mic or line source, and immediately triggers it from pads or keys, trimming start and end points on the fly.", "category": "Sampling technique", "related_terms": ["Sampler", "Input monitoring", "Latency", "Trigger", "Loop point", "Quantization"], "common_mistakes": ["Setting record levels too high and clipping the captured sample", "Overlooking input latency, so the captured sound sits slightly off the beat", "Not trimming the sample start, leaving a gap before the sound triggers"], "scenario_contexts": ["A live performer sampling a vocal phrase and replaying it during the set", "Beat-making by grabbing a drum hit and mapping it to pads immediately", "Capturing a found sound in the field and playing it back on the spot"]}, "450ae690-1fce-405f-9789-41219dc12b2c": {"definition": "An oscillator whose waveform phase is reset to a defined start point each time a new note is triggered, so every note begins at the same point in the cycle rather than at a free-running phase.", "plain_english": "A retriggered oscillator starts its wave over from the beginning each time you press a key. This makes every note begin the same way, so notes sound even.", "purpose_function": "Resetting phase on each note keeps attacks consistent and predictable, which matters for punchy transients and for keeping layered or stacked oscillators in phase. It exists because a free-running oscillator would start each note at a random phase, varying the attack.", "practical_application": "A technician enables oscillator retrigger (key sync) when consistent, punchy note starts are needed, and disables it for a looser, more analog-sounding attack that varies note to note.", "category": "Synthesis", "related_terms": ["Oscillator", "Phase", "Free-running oscillator", "Envelope", "LFO retrigger", "Waveform"], "common_mistakes": ["Confusing oscillator retrigger with envelope or LFO retrigger, which reset different parts of the voice", "Expecting perfectly consistent attacks with retrigger off, when free-running phase varies each note", "Leaving retrigger on when a subtly varying, more organic attack is wanted"], "scenario_contexts": ["Programming a tight bass patch that needs identical, punchy note attacks", "Phase-aligning stacked oscillators so they reinforce rather than cancel", "Designing a plucky lead where every note must start the same way"]}, "d8c8ccb0-484d-48c7-9356-60100742f223": {"definition": "An organized, stored collection of audio samples kept for backup and reuse, typically catalogued with folder structure, naming, and metadata so individual sounds can be located and recalled later.", "plain_english": "A sample archive is an organized store of your saved sound files. It works like a labeled filing cabinet so you can find and reuse sounds later.", "purpose_function": "It preserves recorded and collected sounds against loss and makes them easy to search and reload into future projects. It exists because unmanaged sample files quickly become too many to find without a system.", "practical_application": "A technician maintains an archive on a backed-up drive with consistent naming and tags, so a needed sound can be retrieved and dropped into a sampler without re-recording it.", "category": "Sample management", "related_terms": ["Sample library", "Metadata", "Backup", "File naming", "Sample rate", "Disk streaming"], "common_mistakes": ["Keeping a single unbacked-up copy, risking total loss if the drive fails", "Using inconsistent or vague file names, making sounds impossible to find later", "Confusing an organized archive with a working library that is actively streamed during playback"], "scenario_contexts": ["Backing up a studio's accumulated sound-design recordings", "Cataloguing field recordings so they can be searched by tag", "Recalling an old project's custom samples for a remix"]}, "0caf0493-7ff3-405e-a10d-c21d127fda72": {"definition": "A region of fast memory, typically RAM, into which audio samples or their initial portions are pre-loaded so a sampler's playback engine can read them with minimal latency instead of fetching every note from slower disk storage.", "plain_english": "A sample cache is fast memory that holds sounds ready to play. It keeps them close by so a note starts the instant you press a key, instead of waiting on a slow drive.", "purpose_function": "It lowers access latency and prevents dropouts by keeping the start of each sample, or frequently used sounds, in fast memory while the rest streams from disk.", "practical_application": "A technician sets the RAM preload size in a sampler like Kontakt so a large library loads its sample starts into memory and streams the tails from disk.", "category": "Playback & Memory", "related_terms": ["Sample playback engine", "Disk streaming", "Latency", "Buffer size", "Voice allocation"], "common_mistakes": ["Assuming a bigger cache improves tone, when it mainly affects loading and streaming, not sound.", "Setting the preload size so high that RAM runs out and the system slows or crashes.", "Confusing the RAM cache with permanent storage; restarting or purging empties it."], "scenario_contexts": ["Loading a large orchestral library and adjusting preload memory to avoid dropouts.", "Increasing a sampler's cache size while troubleshooting audio glitches.", "Purging unused samples from the cache to free RAM during a big session."]}, "8bd3ce4f-b852-48d2-9de9-3772ebd38e7d": {"definition": "The process of recording audio through an input and converting it to a stored digital sample via an analog-to-digital converter, producing raw material ready for editing, mapping, or playback in a sampler.", "plain_english": "Sample capture means recording a sound and saving it as a digital clip. A mic or line feeds the sound in, and the sampler turns it into a file you can play back later.", "purpose_function": "It creates the source material for a sampler by turning a real-world or line-level sound into a stored digital recording.", "practical_application": "A technician sets input gain and sample rate, then records a single note or hit into a sampler or DAW to build a new instrument.", "category": "Sample Acquisition", "related_terms": ["Sample rate", "Bit depth", "Analog-to-digital converter", "Sample editing", "Gain staging"], "common_mistakes": ["Setting input gain too high and clipping the capture, which cannot be undone later.", "Recording with background noise or at the wrong sample rate for the project.", "Leaving monitor speakers open near the mic during capture, causing feedback."], "scenario_contexts": ["Recording a drum hit to build a custom sampler instrument.", "Capturing a field recording to use as a one-shot sound.", "Sampling a synth line into a DAW for later editing."]}, "3b3f9d4b-a8fb-4561-a815-ff9b6a1a52e6": {"definition": "An organized, searchable index of stored audio samples, usually holding metadata such as name, category, tempo, key, and tags, that lets a user browse and recall sounds within a library or sampler.", "plain_english": "A sample catalog is an organized list of your sounds. Like a library index, it lets you search by name, type, or tempo so you can find the right clip fast.", "purpose_function": "It makes large collections usable by tagging and indexing sounds so they can be found and loaded quickly instead of hunting through folders.", "practical_application": "A technician tags and organizes a sample library so producers can search by instrument, key, or tempo inside the browser.", "category": "Library Management", "related_terms": ["Sample library", "Metadata", "Tagging", "Sample consolidation", "Preset browser"], "common_mistakes": ["Relying on file names alone instead of adding tags and metadata.", "Moving sample files after cataloging, which breaks the stored links.", "Not backing up the catalog database, losing all organization if it corrupts."], "scenario_contexts": ["Building a searchable library in a sampler's browser.", "Tagging loops by tempo and key for a production template.", "Recovering sample locations after a drive is remounted."]}, "cd604973-dc4f-4cac-972d-82c85d039e4e": {"definition": "The process of combining audio into a single continuous file, or gathering all sample files a project references into one folder, so the material is self-contained and easier to manage, archive, or transfer.", "plain_english": "Sample consolidation gathers your audio into one place. It can join clips into a single file. It can also copy every sound a project uses into one folder, so nothing gets lost.", "purpose_function": "It makes a project portable and reliable by turning scattered edits or file references into one file or one collected folder.", "practical_application": "A technician runs a consolidate command before archiving or moving a session so every sample travels with the project instead of staying on random drives.", "category": "Library Management", "related_terms": ["Sample editing", "Sample catalog", "Bounce", "Session archive", "Region"], "common_mistakes": ["Confusing consolidate, which gathers files, with bounce, which renders a new mix.", "Forgetting to consolidate before moving a session, leaving samples offline.", "Consolidating clips too early and losing separate edit points."], "scenario_contexts": ["Preparing a Pro Tools session for transfer to another studio.", "Merging many small edits into one clean audio file.", "Collecting all used samples into a project folder before backup."]}, "c3b92a27-e736-4bc4-9a1a-9a3cc31555d2": {"definition": "Modifying a recorded audio sample using operations such as trimming, cutting, gain change, fading, and pitch or time adjustment, to clean it up and prepare it for mapping and playback.", "plain_english": "Sample editing means cleaning up and shaping a recorded sound. You trim the ends, fix the volume, and remove noise so the clip is ready to play.", "purpose_function": "It turns raw recordings into clean, usable samples by removing unwanted parts and correcting level, timing, and tone.", "practical_application": "A technician trims silence, sets fades, and adjusts gain on a captured hit before mapping it across a keyboard.", "category": "Sample Editing", "related_terms": ["Sample capture", "Sample fade", "Sample normalization", "Zero crossing", "Trimming"], "common_mistakes": ["Cutting a sample at a non-zero crossing, which causes an audible click.", "Editing the only copy without keeping a backup of the original.", "Over-processing and adding artifacts that cannot be removed later."], "scenario_contexts": ["Trimming silence from the start of a recorded note.", "Removing a cough or noise from a vocal sample.", "Preparing a one-shot for a drum kit."]}}$j$::jsonb)) d
WHERE g.id = d.id;
COMMIT;
